window.BOOK={"key":"usul","app":"mutoon","lsk":"mutoon_usul_v1","title":"تهذيب مسار الأصول","sub":"إلى علم أصول فقه الحنفية · أ.د. صلاح محمد أبو الحاج","unitWord":"فقرة","sharhDir":"data/usul-sharh/","track":"matn","tracks":[{"k":"matn","l":"التعريفات والقواعد","kinds":["def"],"note":"الكلام الغامق بالكتاب بس (التعريفات والقواعد)، وباقي الفقرة بيضل ظاهر للقراءة."},{"k":"full","l":"الكتاب كامل","note":"كل فقرات الكتاب، كلمة كلمة."}],"chapters":[{"id":"u3","title":"المطلب الأول: تعريف علم أصول الفقه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u3_1","kind":"def","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ١","segs":[["matn","أولاً: من حيث إنَّه مركبٌ إضافيّ:"],["ctx","إنَّ لفظَ أصول الفقه قبل جعله لقباً ـ أي علماً ـ على الفن المخصوص، لفظ مركب من مضاف، وهو أصول، ومضاف إليه: وهو الفقه، وتعريف المركب يحتاج إلى تعريف أجزائه، وتعريفهما يُغني عن تعريف الإضافة التي بينهما، وهي اختصاص الأصل بالفقه باعتبار كونه أصلاً له؛ لوضوحه، وقبل ذلك نقف على معنى العلم؛ لأنَّ أصول الفقه مضافة إليه."]]},{"id":"u3_2","kind":"def","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ٢","segs":[["matn","الأول: علم:"],["matn","العلم: نقيض الجهل"],["ctx","، وهو"],["matn","معرفة الشيء على ما هو به"],["ctx","...، والمعنى الحقيقي للعلم: هو"],["matn","الإدراك."]]},{"id":"u3_3","kind":"text","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ٣","segs":[["ctx","والعلم المستفاد من تعريف الفقه ـ كما سيأتي ـ ليس الاعتقاد الجازم عن دليل؛ لأنَّ مسائل الفقه مظنونة؛ لكونه مبنياً على أخبار الآحاد والأقيسة وغيرها من المظنونات؛ إذ العلم يطلق على الظنيّات كما يطلق على القطعيّات كالطب ونحوه؛ ولأنَّ الشَّارعَ لما اعتبر غلبة الظنِّ في الأحكام صار كأنَّه قال: كلما غلب ظنّ المجتهد بالحكم يثبت الحكم؛ ولأنَّ المظنون يجب العمل به في الفروع فصار كالمقطوع."]]},{"id":"u3_4","kind":"def","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ٤","segs":[["matn","الثاني: أصول:"],["matn","لغةً"],["ctx",": جمع أصل، وهو أسفلُ كلُّ شيء، وأساسه، فمدارُ معنى الأصل لغةً فيما يُبتني عليه غيره من حيث إنَّه يُبتني عليه، سواء كان الابتناء حسياً كابتناء السَّقف على الجدار، أو عقلياً كابتناء الحكم على الدَّليل، والأصل قد يكون مُبتنياً على غيره، وأمّا الفرع فما يكون مبنياً على غيره دائماً."]]},{"id":"u3_5","kind":"def","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ٥","segs":[["matn","واصطلاحاً"],["ctx",": وله معان، وهي:"]]},{"id":"u3_6","kind":"def","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ٦","segs":[["ctx","١."],["matn","الدَّليل"],["ctx",": وهو المراد هنا، يقال: أصل هذه المسألة الكتاب: أي دليلها، ويقال: أصول الفقه: أي أدلته."]]},{"id":"u3_7","kind":"def","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ٧","segs":[["ctx","٢."],["matn","الرَّاجح"],["ctx",": كما يقال: الكتاب أصل بالنِّسبة إلى القياس: أي راجح."]]},{"id":"u3_8","kind":"def","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ٨","segs":[["ctx","٣."],["matn","المستصحب"],["ctx",": كما يقال: طهارة الماء أصل."]]},{"id":"u3_9","kind":"def","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ٩","segs":[["ctx","٤."],["matn","القاعدة"],["ctx",": كما يقال: الفاعل مرفوع أصل من أصول النَّحو."]]},{"id":"u3_10","kind":"text","label":"المطلب الأول: تعريف علم أصول الفقه · الفقرة ١٠","segs":[["ctx","فلفظ الأصل مشترك اصطلاحي في الأربعة."]]}],"sup":"المبحثُ الأوّل تعريف علم الأصول والتَّفريق بينه وبين علم الفقه"},{"id":"u3a","title":"الثَّالث: الفقه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u3a_1","kind":"def","label":"الثَّالث: الفقه · الفقرة ١","segs":[["matn","الثَّالث: الفقه:"],["matn","لغةً"],["ctx",": هو الفهم مطلقاً، قال تعالى: ﴿وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي يَفۡقَهُواْ قَوۡلِي﴾ [طه:٢٨]."]]},{"id":"u3a_2","kind":"def","label":"الثَّالث: الفقه · الفقرة ٢","segs":[["matn","واصطلاحاً:"],["ctx","إنَّ أصحاب كل علم ينظرون إلى المعنى اللغوي والشَّرعي من الجانب الذي يخدم علمهم؛ لذلك وجدنا الأصوليين والفقهاء اختلفوا في تعريف الفقه اصطلاحاً، فالأصوليون اتجهتْ عنايتهم إلى بيانِ مفهومِ الفقه في اصطلاحهم بالمعنى الوصفي: أي الحالُ التي إذا وجِدَ عليها المرءُ سمِّي فقيهاً، ولم يعرضوا لمعناه الإسمي: أي المسائل والأحكام التي يُطلقُ عليها اسم الفقه."]]},{"id":"u3a_3","kind":"text","label":"الثَّالث: الفقه · الفقرة ٣","segs":[["ctx","وقد عرَّف الأصوليون الفقه بتعاريف منها:"]]},{"id":"u3a_4","kind":"def","label":"الثَّالث: الفقه · الفقرة ٤","segs":[["ctx","١."],["matn","معرفةُ النَّفسِ ما لها وما عليها عملاً."]]},{"id":"u3a_5","kind":"text","label":"الثَّالث: الفقه · الفقرة ٥","segs":[["ctx","وهذا التَّعريف منقول عن أبي حنيفة بلا لفظ: «عملاً» الذي زاده أصحابه؛ لتخرجَ الاعتقادات والوجدانيات، فيخرج الكلام والتَّصوف."]]},{"id":"u3a_6","kind":"text","label":"الثَّالث: الفقه · الفقرة ٦","segs":[["ctx","والمعرفة: إدراكُ الجزئياتِ عن دليل."]]},{"id":"u3a_7","kind":"text","label":"الثَّالث: الفقه · الفقرة ٧","segs":[["ctx","ومعنى ما لها وما عليها: ما يجوز لها، وما يحرم عليها، فيشملان جميع الأصناف: أي الحِل والحرمة والكراهة والسُّنة وغيرها."]]},{"id":"u3a_8","kind":"def","label":"الثَّالث: الفقه · الفقرة ٨","segs":[["ctx","٢."],["matn","العلم بالأحكام الشَّرعيَّة العملية المكتسب من أدلتها التَّفصيليَّة."]]},{"id":"u3a_9","kind":"text","label":"الثَّالث: الفقه · الفقرة ٩","segs":[["ctx","وهو منقول عن أصحاب الإمام الشَّافعي."]]},{"id":"u3a_10","kind":"text","label":"الثَّالث: الفقه · الفقرة ١٠","segs":[["ctx","فالأدلة التفصيلية: هي الأدلة الجزئية التي يتعلّق كلّ دليل منها بمسألة معيّنة وينص على حكم خاص بها: كقوله تعالى: ﴿وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ﴾[الأنعام: ١٥١]، فهي دليل جزئي يتعلّق بحكم قتل النَّفس بغير حق."]]},{"id":"u3a_11","kind":"def","label":"الثَّالث: الفقه · الفقرة ١١","segs":[["ctx","وخرج"],["matn","بالأحكام"],["ctx",": العلم بالذَّوات والصِّفات والأفعال."]]},{"id":"u3a_12","kind":"def","label":"الثَّالث: الفقه · الفقرة ١٢","segs":[["matn","وبالشَّرعية"],["ctx",": العقلية، والمراد بها ما يتوقف معرفتها على الشَّرع."]]},{"id":"u3a_13","kind":"def","label":"الثَّالث: الفقه · الفقرة ١٣","segs":[["matn","وبالعملية"],["ctx",": العلمية: ككون الإجماع وخبر الواحد حجّة."]]},{"id":"u3a_14","kind":"def","label":"الثَّالث: الفقه · الفقرة ١٤","segs":[["ctx","والأحكام الشَّرعية العملية:"],["matn","هي التي تتعلّق بأفعال المكلفين في العبادات والمعاملات وغيرهما من الفرض والواجب والسُّنة والكراهة التَّحريمية والتَّنزيهية والإباحة."]]},{"id":"u3a_15","kind":"def","label":"الثَّالث: الفقه · الفقرة ١٥","segs":[["ctx","ولما كانت نظرة الفقهاء إلى بيان حكم فعل المكلف من الحلّ والحرمة بغض النَّظر عن الدَّليل اهتموا بتعريف الفقه من هذه الحيثية، فعرَّفه أبو سعيد الخادمي: بأنَّه"],["matn","علم يُبحث فيه عن أحوالِ الأعمالِ من حيث الحلِّ، والحرمةِ، والفساد، والصِّحة."]]}],"sup":"المطلب الأول: تعريف علم أصول الفقه"},{"id":"u3b","title":"ثانياً: من حيث أنَّه لقب لهذا الفن","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u3b_1","kind":"def","label":"ثانياً: من حيث أنَّه لقب لهذا الفن · الفقرة ١","segs":[["matn","ثانياً: من حيث أنَّه لقب لهذا الفن:"],["matn","بعد العرض السَّابق تبيَّن أنَّ أصل المسألة: أي دليل المسألة باعتبار كونه دليلاً عليها، فأصول الفقه ما يختص به من حيث إنَّه مبنى له ومسندٌ إليه، ثم نقل إلى المعنى العرفي اللقبي الآتي ليتناول التَّرجيح والاجتهاد أيضاً، وقد عرَّفه الأصوليّون من هذه الحيثية بتعاريف منها:"]]},{"id":"u3b_2","kind":"def","label":"ثانياً: من حيث أنَّه لقب لهذا الفن · الفقرة ٢","segs":[["ctx","١."],["matn","أدلة إجمالية للفقه يُحتاج إليها عند تطبيق الأدلة التَّفصيلية على أحكامها."]]},{"id":"u3b_3","kind":"text","label":"ثانياً: من حيث أنَّه لقب لهذا الفن · الفقرة ٣","segs":[["ctx","فمثلاً: الزَّكاة واجبة؛ لقوله تعالى: ﴿وَءَاتُواْ ٱلزَّكَوٰةَ﴾[الحج:٧٨]؛ لأنَّ الأمرَ للوجوب، فالحكم وجوب الزَّكاة، والدَّليل التَّفصيلي الآية، والدَّليل الإجمالي القاعدة الأصولية: الأمر للوجوب."]]},{"id":"u3b_4","kind":"def","label":"ثانياً: من حيث أنَّه لقب لهذا الفن · الفقرة ٤","segs":[["ctx","٢."],["matn","العلمُ بالقواعدِ التي يتوصَّل بها إلى استنباطِ الأحكام الشَّرعيّة الفرعيّة من أدلتها التَّفصيلية."]]},{"id":"u3b_5","kind":"text","label":"ثانياً: من حيث أنَّه لقب لهذا الفن · الفقرة ٥","segs":[["ctx","وفي هذا التَّعريف ثلاثة أمور: الحكم الفرعي، والقاعدة، والدَّليل، فالحكم الفرعي مثل: وجوب الصلاة، والقاعدة هي أنَّ ﴿وَأَقِيمُواْ﴾ أَمرٌ، والقاعدةُ الأصولية: هي أنَّ الأمر للوجوب، والدَّليل التَّفصيلي: هو قوله تعالى: ﴿وَأَقِيمُواْ ٱلصَّلَوٰةَ﴾ [البقرة:٤٣] ففي ضوء هاتين القاعدتين يتوصل المجتهد إلى الحكم الفرعي، وهو وجوب الصَّلاة من دليله التَّفصيلي، وهو قوله تعالى: ﴿وَأَقِيمُواْ ٱلصَّلَوٰةَ﴾."]]},{"id":"u3b_6","kind":"text","label":"ثانياً: من حيث أنَّه لقب لهذا الفن · الفقرة ٦","segs":[["ctx","وعليه فإنَّ علم أصول الفقه: هو العلم الذي يُبيِّن المناهج التي انتهجها الأئمة المجتهدون في استنباطهم وتَعرفهم للأحكام من النُّصوص والبناء عليها باستخراج العلل التي تبنى عليها الأحكام، وتلتمس المصالح التي قصد إليها الشَّرع الحكيم، وأشار إليها القرآن الكريم، وصرَّحت بها أو أومأت إليه السُّنة النَّبوية."]]},{"id":"u3b_7","kind":"text","label":"ثانياً: من حيث أنَّه لقب لهذا الفن · الفقرة ٧","segs":[["ctx","فعلم أصول الفقه على هذا: مجموعة القواعد التي تُبيِّن للفقيه طرق استخراج الأحكام من الأدلة التَّفصيلية، سواء أكانت تلك الطرق لفظية: كمعرفة دلالات الألفاظ الشَّرعية على معانيها، واستنباطها منها، وطرق التَّوفيق بينها عند تعارض ظواهرها، أو اختلاف تاريخها، أم كانت معنوية: كاستخراج العلل من النُّصوص وتعميمها، وبيان طرق استخراجها، وأسلم المناهج لتعرفها...."]]}],"sup":"المطلب الأول: تعريف علم أصول الفقه"},{"id":"u4","title":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u4_1","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ١","segs":[["ctx","فمن خلال هذه التَّعاريف للفقهاء، وبعد الاطلاع السَّابق على تعريف الفقه عند الأصوليين، تظهر الفروق التَّالية بين علم الفقه وعلم الأصول، ومنها:"]]},{"id":"u4_2","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ٢","segs":[["ctx","١. إنَّ الأصول مستمدة من علم الكلام واللغة والأحكام ـ كما سيأتي ـ، بخلاف علم الفقه، فإنَّ مباحثه مستمدة من الأدلة الشَّرعية: كالكتاب والسُّنة والقياس وأفعال المكلفين وما يصدر عنهم من تصرفات، باعتبارها المادة التي يبحث لها عن أحكام."]]},{"id":"u4_3","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ٣","segs":[["ctx","٢. إنَّ الغاية من الأصول إجمالاً هي معرفة الأحكام من أدلتها التَّفصيلية، أما الفقه فغايته الفوز بسعادة الدَّارين باتباع الأوامر واجتناب النَّواهي، والفوز برضا الله تعالى بالامتثال والعلم."]]},{"id":"u4_4","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ٤","segs":[["ctx","٣. إنَّ موضوع الأصول الأدلة والأحكام ـ كما سيأتي ـ، بينما موضوع الفقه أَفعال العباد من حيث ما ثبت لها من أحكام شرعية."]]},{"id":"u4_5","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ٥","segs":[["ctx","٤. إنَّ الفقهاء اعتنوا في الفقه من حيث بيان حكم فعل المكلف، لا من حيث دليل حكم الفعل كما هو حال اعتناء الأصوليين؛ إذ أنَّ وظيفة الفقيه بيان الحكم بغض النَّظر عن دليله، ووظيفة الأصولي بيان دليل كلِّ مسأَلة فقهية، وهذه التَّفرقة بين الفقيه والأصولي يغفل عنها كثيرٌ من النَّاس."]]},{"id":"u4_6","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ٦","segs":[["ctx","٥. إنَّ الفقه في علم الأصول: هو العلم بالأحكام من دلائلها...، فليس الفقيه إلا المجتهد عندهم، وإطلاقه على المُقلِّد الحافظ للمسائل مجاز، لكن صرَّح الأصوليون بأنَّ الحقيقة تترك بدلالة العادة، وحينئذٍ فينصرف كلام الواقف الموصي للفقهاء إلى ما هو المتعارف في زمنه؛ لأنَّه حقيقة كلامه العرفية، فتترك به الحقيقة الأصلية، ويكون حقيقة في عرف الفقهاء."]]},{"id":"u4_7","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ٧","segs":[["ctx","وتكلَّموا في المقدار الأدنى الذي يجب أن يحفظه الشَّخص حتى يطلق عليه لقب: الفقيه؛ وانتهوا إلى أنَّ هذا متروك للعرف، ونستطيع أن نقرّر أنَّ عرفنا الآن لا يطلق لقب: فقيه إلا على من يَعرف موطن الحكم من أبواب الفقه المتناثرة، بحيث يَسهل عليه الرُّجوع إليها."]]},{"id":"u4_8","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ٨","segs":[["ctx","٦. إنَّ علم الأصول يتعلّق ببيان القواعد الأصولية الكلية التي يستند إليها المجتهد في استخراج الأحكام من الأدلة التَّفصيلية، بخلاف الفقه، فإنَّه يتعلَّق بالأحكام العملية المتعلقة بالعبادات والمعاملات والمناكحات والهبات والشَّركات وغيرها."]]},{"id":"u4_9","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ٩","segs":[["ctx","٧. إنَّ الأصول هي المناهج التي تحدد وتبيِّن الطريق الذي يلتزمه الفقيه في استخراج الأحكام من أدلتها، وترتيب الأدلة من حيث قوتها، فيُقدِّم القرآن على السُّنة، والسُّنة على القياس وهكذا، أما الفقه فهو الأحكام المستخرجة مع التَّقيّد بهذه المناهج."]]},{"id":"u4_10","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ١٠","segs":[["ctx","٨. إنَّ علم الأصول يطلق على القواعد الأصولية في الاستنباط، بخلاف الفقه، فإنَّه يطلق على أصول البناء «القواعد الفقهية» في تخريج الأحكام المستجدة من قبل المجتهد في المذهب من فروع وقواعد المجتهد المستقل في المذهب، وهذه هي الطريقة التي سار عليها المتأخرون في معرفة الأحكام."]]},{"id":"u4_11","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ١١","segs":[["ctx","وبيان ذلك: أنَّ المجتهدين في المذهب كما يَصفهم الإمام الدِّهلويّ: «قومٌ توجهوا بعد المسائل المجمع عليها بين المسلمين أو بين جمهورهم إلى التَّخريج على أَصل رجل من المُتقدِّمين، وكان أكثر أمرهم حمل النَّظير على النَّظير، والرَّد إلى أصلٍ من الأُصول دون تتبع الأحاديثِ والآثارِ»."]]},{"id":"u4_12","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ١٢","segs":[["ctx","ومصدر الاجتهاد الوحيد عندهم هو: «ما نقل إليهم من كلامِ أئمةِ المذهبِ الذين يقلِّدون أهله»، قال النووي الشَّافعي والمرادي الحنبلي(ت٨٨٥هـ): «يتخذ نصوص إمامه أصولاً يستنبط منها كفعل المستقلّ بنصوص الشَّرع»."]]},{"id":"u4_13","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ١٣","segs":[["ctx","فالأمر أمر مرحلية وتدرج، وليس إهمالاً وتركاً للأدلة الشرعية؛ لأنَّ أحكام المجتهد مأخوذة من الأدلة، فهي تمثِّلها، ولكنَّها قطعت مرحلة للمجتهد في المذهب لاستخراج الأحكام التي لم يبينها المجتهد المستقل."]]},{"id":"u4_14","kind":"text","label":"المطلب الثَّاني: الفرق بين علم الأصول وعلم الفقه · الفقرة ١٤","segs":[["ctx","وتؤكد هذا ما يلاحظ في القواعد الفقهية التي استخرجت من مجموعة الأحكام الفقهية المتناثرة المتفقة فيما بينهما، ومن ثم يمكن الاعتماد على القاعدة في معرفة الأحكام غير المُبيَّنة ـ كما هو معلوم ـ."]]}],"sup":"المبحثُ الأوّل تعريف علم الأصول والتَّفريق بينه وبين علم الفقه"},{"id":"u5","title":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u5_1","kind":"def","label":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف · الفقرة ١","segs":[["matn","تمهيد:"],["ctx","بعد العرض السَّابق لمعنى أصول الفقه، فإنَّه يمكننا القول: إنَّه عبارة عن القواعد والأسس الكلية المرتكزة في الذِّهْن والتي يحتكم إليها المجتهد في استخراج الأحكام من الأدلة الجزئية."]]},{"id":"u5_2","kind":"text","label":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف · الفقرة ٢","segs":[["ctx","وهي تمثل المناهج التي سار عليها المجتهدون من الصَّحابة رضي الله عنهم والتَّابعين والأئمَّة المجتهدين في اجتهادهم: أي القواعد التي احتكموا إليها في أذهانهم عند استخراجهم للأحكام من أدلتها."]]},{"id":"u5_3","kind":"text","label":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف · الفقرة ٣","segs":[["ctx","ففي هذا المبحث سنعرض لنشأة علم الأصول والمراحل التي مَرَّ بها حتى نضج ووصل إلى ما وصل إليه الآن، مع أبرز الكتب المُؤلَّفة فيه ومناهج أصحابها فيها، وذلك من خلال المطالب الآتية:"]]}]},{"id":"u6","title":"المطلب الأوّل: أصول الفقه في العهد النَّبوي","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u6_1","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١","segs":[["ctx","إنَّ النَّشأة التَّاريخيّة لعلم الأصول تَخفى على كثير من النَّاس، فيظنُّون أنَّه وجد في نهاية القرن الثَّاني على يد الإمام الشَّافعي، ولكن مَن يدقق النَّظر في ضوء ما سبق أن ذكرناه من المراد بأصول الفقه، يلاحظ أنَّ نُواته تكونت في عهد النُّبوة، وأنَّ بعض أسسه بيَّنها رسول الله ﷺ؛ لأنَّه لا يكون اجتهاد إلا بأصول، والاجتهاد حاصل في زمن النَّبي ﷺ وأصحابه ومَن بعدهم، وتفصيل ذلك فيما يلي:"]]},{"id":"u6_2","kind":"def","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ٢","segs":[["matn","إنَّ الاجتهاد في زمن النَّبي ﷺ له صورتان، وهما:"]]},{"id":"u6_3","kind":"def","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ٣","segs":[["matn","أولاً: اجتهاد رسول الله ﷺ:"],["ctx","من المقرّر في محلِّه أنَّ النَّبي ﷺ كان مجتهداً، وهذا ما ذهب إليه عامَّة الأصوليين ومالك والشَّافعي وأحمد وعامة أهل الحديث، ومنقول عن أبي يوسف رضي الله عنه أنَّه ﷺ مأمور بالاجتهاد مطلقاً في الأحكام الشَّرعية والحروب والأمور الدِّينية من غير تقييد بشيء منها أو من غير تقييد بانتظار الوحي."]]},{"id":"u6_4","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ٤","segs":[["ctx","والمختار عند الحنفية المتأخرين: أنَّه ﷺ مأمور في حادثة لا وحي فيها بانتظار الوحي أولاً ما كان راجي الوحي إلى خوف فوت الحادثة بلا حكم، ثم بالاجتهاد ثانياً إذا مضى وقت الانتظار على حسب الحادثة ولم يوح إليه؛ لأنَّ عدم الوحي إليه فيها إذنٌ في الاجتهاد."]]},{"id":"u6_5","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ٥","segs":[["ctx","فإن أُقر ﷺ على ما أدى إليه اجتهاده عند خوف الحادثة، أَوجب إقراره عليه القطع بصحة ما أدّى إليه اجتهاده؛ لأنَّه لا يُقرّ على الخطأ، فلم يجز مخالفته كالنَّص، بخلاف غيره من المجتهدين، فإنَّه يجوز مخالفته إلى اجتهاد مجتهد آخر؛ لاحتمال الخطأ."]]},{"id":"u6_6","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ٦","segs":[["ctx","والاجتهاد في حقّه ﷺ يختصُّ بالقياس، بخلاف غيره من المجتهدين، فيكون في دلالات الألفاظ على ما هو المراد منها؛ لعروض خفاء واشتباه فيها، وفي البحث عن مخصص العام وبيان المراد من المشترك وباقي الأقسام التي في دلالتها على المراد خفاء من المجمل والمشكل والخفي والمتشابه، وفي الترجيح لأحد الدَّليلين عند التَّعارض بينهما؛ لعدم علم المتأخر."]]},{"id":"u6_7","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ٧","segs":[["ctx","وأما النَّبي ﷺ فهذا غير متأت في حقّه؛ لانتفاء تحقق التَّعارض بالنِّسبة إليه، وانتفاء عزوب تأخر المتأخر على المتقدم عن علمه على تقدير وجود صورة التَّعارض."]]},{"id":"u6_8","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ٨","segs":[["ctx","ومن اجتهادته ﷺ: إذنه بالتَّخلف عن غزة تبوك لمن ظهر نفاقه، فعوتب من الله تعالى بقوله: ﴿عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ﴾[التوبة:٤٣]، وكذلك اجتهاده بعدم قتل أسارى بدر وأخذه الفداء منهم بعد مشاورته لأبي بكر وعمر رضي الله عنهم وميله لرأي أبي بكر رضي الله عنه، فنزل قوله تعالى: ﴿مَا كَانَ لِنَبِيٍّ أَن يَكُونَ لَهُۥٓ أَسۡرَىٰ حَتَّىٰ يُثۡخِنَ فِي ٱلۡأَرۡضِۚ تُرِيدُونَ عَرَضَ ٱلدُّنۡيَا وَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ لَّوۡلَا كِتَٰبٞ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِيمَآ أَخَذۡتُمۡ عَذَابٌ عَظِيمٞ﴾[الأنفال:٦٨]."]]},{"id":"u6_9","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ٩","segs":[["ctx","وأيضاً ما روي من قضائه ﷺ بين المتخاصمين؛ فعن أم سلمة رضي الله عنها قالت: «جاء رجلان من الأنصار إلى النَّبي ﷺ في مواريث بينهما قد دَرَسَتْ ـ بادت ـ، فقال النَّبي ﷺ: إنَّما أنا بشر وإنَّكم تختصمون إليّ، وإنَّما أقضي برأيي فيما لم يَنْزل عليَّ فيه، فمَن قضيت له بشيء من حقّ أخيه فلا يأخذه، فإنَّما أقطع له قطعةً من النَّار يأتي بها يوم القيامة على عُنقه»."]]},{"id":"u6_10","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١٠","segs":[["ctx","فهذه بعض الحوادث التي وقع من النَّبي ﷺ اجتهاد فيها، مما جعل جمهور العلماء يقولون: إن النَّبي ﷺ كان مجتهداً؛ إذ أنَّ الاجتهاد منصبٌ شريفٌ فلا يُحرمه أفضل الخلق وتناله أمته، وأكثرية الثواب؛ لأكثرية المشقة."]]},{"id":"u6_11","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١١","segs":[["ctx","وطالما ثبت اجتهاده ﷺ فلا بدَّ أن يكون له أصول اعتمد عليها في ذلك، وليس هنا محل تحريرها، وإنَّما نكتفي بالإشارة إليها فحسب؛ إذ سبق أنَّ اجتهادَه ﷺ خاصٌّ بالقياس بخلاف غيره من المجتهدين، وفي حديث معاذ رضي الله عنه الآتي دلالة على ذلك، قال الزَّركشي: «وقد أشار المصطفى ﷺ في جوامع كلمه إليه ـ أي إلى علم الأصول ـ ونبَّه أرباب اللسان عليه...»."]]},{"id":"u6_12","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١٢","segs":[["ctx","وفي أصول أصحاب المذاهب المختلفة بيان لأصول النَّبي ﷺ إجمالاً في اجتهاده؛ إذ أنَّ كلاً منهم باذلٌ أَقصى جهده للوصولِ للعلَّة والقاعدةِ والأساسِ الذي مَشَى عليه رسول الله ﷺ، فأخذهم بالإجماع؛ لما ورد عنه ﷺ: «إنَّ اللهَ تعالى لا يجمع أمَّتي على ضلالة» مثلاً، وأخذهم للقياس لحديث معاذ رضي الله عنه وغيره، وهكذا، فالإجماع أشار النَّبي ﷺ إلى الأخذ به واعتماده."]]},{"id":"u6_13","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١٣","segs":[["ctx","والقياسُ طَبَّقه رسول الله ﷺ في كثيرة من الحوادث، وقد مرَّ أنَّ اجتهاد رسول الله ﷺ متعلّقٌ بالقياس؛ فعن جابر بن عبد الله رضي الله عنه، قال عمر رضي الله عنه: «هششت فقبَّلتُ وأنا صائم، فقلت: يا رسول الله، صنعت اليوم أمراً عظيماً، قَبَّلتُ وأنا صائم، قال: أرأيت لو مضمضت من الماء وأنت صائم؟ قلت: لا بأس به، قال: فَفِيمَ»، فقد قاس ﷺ القُبلة من غير إنزال على المضمضة من غير ابتلاع، وأنَّ حكم إحداهما كحكم الأخرى."]]},{"id":"u6_14","kind":"def","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١٤","segs":[["matn","ثانياً: اجتهاد الصَّحابة في عصر النَّبي ﷺ:"],["ctx","إنَّ رسولَ الله ﷺ قام بإعدادِ عددٍ من الصَّحابة رضي الله عنهم للاجتهاد، وبيَّن لهم طريقه، امتثالاً لأمر الله جل جلاله: ﴿فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ﴾[النحل:٤٣]، إذ الآية صريحة في تَمَيّز بعض النَّاس بالعلم والاجتهاد والذِّكر، وقيام بقية المسلمين بالاسترشاد برأيهم وقولهم في أمر دينهم، وتطبيقاً لهذا قام رسول الله ﷺ ببعث أصحابه رضي الله عنهم إلى خارج المدينة وأرشدهم إلى الاجتهاد، فبعث معاذاً وعلياً رضي الله عنهم إلى اليمن، وبَيَّن لهم الأصل في استنباط الأحكام، فقال لمعاذ رضي الله عنه: «بماذا تقضي إذا عرض لك القضاء؟ قال: أَقضي بكتاب الله، قال: فإن لم تجد، قال: فبسنّة رسول الله ﷺ، قال: فإن لم تجد؟ قال: أَجتهد رأيي لا آلو ـ أي لا أُقَصِّر ـ فقال رسولُ الله ﷺ: الحمدُ لله الذي وَفَّق رسولَ رسولِه بما يرضى به رسوله»."]]},{"id":"u6_15","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١٥","segs":[["ctx","وفي هذا الحديث بيانٌ لمراتب الأدلة في استخراج الأحكام، وكذلك دليلٌ على اعتماد القياس من الأدلة الشَّرعية، وهذا هو الأساس في أصول الفقه؛ لأنَّ علم الأصول يدور في مسائله حول ذلك، وبذلك يكون رسول الله ﷺ بيَّن الأدلة الإجمالية التي يجب ألا يتعداها المجتهد، وهي مصادر الأحكام الشَّرعية كالكتاب الشَّريف والسُّنة المُطهَّرة والإجماع والقياس."]]},{"id":"u6_16","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١٦","segs":[["ctx","وهنا ينبغي الانتباه أنَّ هذه الأُصول كانت راسخةً في نفوسِ الصَّحابةِ المجتهدين رضي الله عنهم بتعليم وإرشادٍ من رسول الخلق ﷺ؛ لأنَّ معاذ رضي الله عنه ذكرها وفصَّلها بمجرد سؤال النَّبي ﷺ له، بما أرضى رسول الله ﷺ عنه؛ لأنَّه لم يخالف النَّبي ﷺ فيما رسمه وعلَّمه لهم، قال الكوثري: «وقد درَّب رسول الله ﷺ الصَّحابة رضي الله عنهم على الرَّأي والاستنباطِ في أحكامِ النَّوازل غيرِ المنصوص عليها من النُّصوص، بإرجاع النَّظير إلى النَّظير، وكان المجتهدون من أَصحاب النَّبي ﷺ يقولون بالرَّأي، وكذلك الفقهاء من التَّابعين»."]]},{"id":"u6_17","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١٧","segs":[["ctx","وقد طُبِّقت هذه الأصول من الصَّحابة رضي الله عنهم بمحضر النَّبي ﷺ وفي زمنه؛ لأنَّ مجموعة من الصَّحابة رضي الله عنهم كانت تفتي في زمن النَّبي ﷺ في المدينة وخارجها، قال سهل بن أبي حثمة: «كان الذي يفتون على عهد رسول الله ﷺ ثلاثة من المهاجرين وثلاثة من الأنصار: عمر، وعثمان، وعليّ، وأُبي بن كعب، ومعاذ بن جبل، وزيد بن ثابت رضي الله عنهم»."]]},{"id":"u6_18","kind":"text","label":"المطلب الأوّل: أصول الفقه في العهد النَّبوي · الفقرة ١٨","segs":[["ctx","ولو أردنا استعراض الحوادث التي اجتهد فيها الصَّحابة رضي الله عنهم في زمنه ﷺ لطال بنا المقام، لكننا نُمثِّل بفعل عَمرو بن العاص رضي الله عنه حين قدَّم عموم القرآن واحتج به عندما أَجنب، فإنَّه «كان على سرية وأصابهم برد شديد لم يروا مثله، فخرج لصلاة الصُّبح قال: والله لقد احتلمت البارحة، فغسل مغابنه ـ الأرفاغ والآباط ـ وتوضأ وضوءه للصَّلاة، ثم صلَّى بهم، فلما قَدِمَ على رسول الله ﷺ سأل رسول الله ﷺ أصحابه فقال: كيف وجدتم عَمراً وأصحابه؟ فأثنوا عليه خيراً، وقالوا: يا رسول الله، صلَّى بنا وهو جُنب، فأرسل رسول الله ﷺ إلى عَمرو فسأله، فأخبره بذلك وبالذي لقي من البرد، وقال: يا رسول الله، إنَّ الله قال: ﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡ﴾[النساء:٢٩]، ولو اغتسلت مت، فضحك رسول الله ﷺ»."]]}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u7","title":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u7_1","kind":"text","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ١","segs":[["ctx","استمرّ الصَّحابة رضي الله عنهم بعد وفاة النَّبي ﷺ على ما بيَّنه ووضحه لهم من طريق الاجتهاد واستخراج الأحكام، وقارب عدد الصَّحابة رضي الله عنهم الذين بلغوا درجة الاجتهاد العشرين، قال الإمام ابن الهُمام: «لا تبلغ عدَّة المجتهدين الفقهاء منهم أكثر من عشرين: كالخلفاء والعبادلة وزيد بن ثابت ومعاذ بن جبل وأنس وأبي هريرة رضي الله عنهم وقليل، والباقون يرجعون إليهم ويستفتون منهم»."]]},{"id":"u7_2","kind":"text","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ٢","segs":[["ctx","وأيّده الإمام الكوثري فقال: «ومن أحاط خبراً بأدلة الجمهور من الكتاب والسُّنة وأقوال السَّلف وبأحوال الصَّحابة رضي الله عنهم، يدرك مبلغ قوة كلام ابن الهمام في عدَّة المجتهدين من الصَّحابة، وإن سعى ابن حزم في تكثير عددهم جداً في «أحكامه»، بأن حَشر في عدادهم كلّ مَن رُوي عنه مسألة أو مسألتين في الفقه، لا إجلالاً لمنْزلة الصَّحابة في العلم، بل ليتمكَّن من معاكسة الجمهور في مسائل الإجماع باشتراط النَّقل عن كلٍّ منهم، وأنَّى لمن لم يرو عنه إلا مسألة أو مسألتان في الفقه أو حديث أو حديثان في السُّنة أن يعدَّ في المجتهدين كائناً من كان، وإن كانت مَنْزلة الصَّحابة رضي الله عنهم في الصُّحبة عظيمة القدر جداً»."]]},{"id":"u7_3","kind":"text","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ٣","segs":[["ctx","هذه المبالغة من ابن حزم في تضخيم عدد المجتهدين من الصَّحابة كان محلّ انتقاد من العلماء، قال العلَّامة ابن القيم: «وما أدري بأي طريق عدَّ ابن حزم معهم الغامدية وماعزاً» أي من المجتهدين، وقال العلَّامة الحجوي: «وفي ذكر مَن تروى عنهم إلا المسألة والمسألتان نظر»."]]},{"id":"u7_4","kind":"text","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ٤","segs":[["ctx","وهذا موافقٌ لما نقل عن مسروق رضي الله عنه، قال: «شافهت أصحاب رسول الله ﷺ فوجدت علمهم انتهى إلى هؤلاءِ السِّتة: عمرُ وعليّ وعبدُ الله وأُبيّ وأَبي الدَّرداء وزيدُ بن ثابت رضي الله عنهم»."]]},{"id":"u7_5","kind":"text","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ٥","segs":[["ctx","فهؤلاء المجتهدون من الصَّحابة رضي الله عنهم كانت لهم مناهج واضحة في الاجتهاد، وهي المُسمَّاة بأصول الفقه؛ لأنَّ مِن المعروف أنَّ قواعد علم أصول الفقه ومناهجه مستقرَّة في نفس كلِّ مجتهد وإن لم يصرحوا بها ويدونونها، وكانوا يعملون بالأصول وإن لم يعلنوا ذلك، ومن الأمثلة على الأصول التي استندوا لها في اجتهاداتهم:"]]},{"id":"u7_6","kind":"def","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ٦","segs":[["ctx","١."],["matn","مراتب الأدلة في استخراج الأحكام"],["ctx","، فيُقدَّم الكتاب على السُّنة، والسُّنة على اجتهاد العلماء، واجتهاد العلماء على اجتهاد نفسه، قال ابن مسعود رضي الله عنه: «إنَّه قد أتى علينا زمان ولسنا نقضي ولسنا هنالك، ثم إنَّ الله تعالى قدَّر علينا أن بلغنا ما ترون، فمَن عَرَضَ له منكم قضاء بعد اليوم، فليقض بما في كتاب الله، فإن جاء أمرٌ ليس في كتاب الله، فليقض بما قضى به نبيُّه ﷺ، فإن جاء أمرٌ ليس في كتاب الله ولا قضى به نبيُّه ﷺ، فليقض بما قضى به الصَّالحون، فإن جاء أمر ليس في كتاب الله ولا قضى به نبيه ﷺ ولا قضى به الصَّالحون، فليجتهد رأيه ولا يقول: إنّي أخاف وإنّي أخاف، فإنَّ الحلالَ بيِّن والحرامَ بيِّن، وبين ذلك أمور مشتبهات، فدع ما يَريبك إلى ما لا يَريبك»."]]},{"id":"u7_7","kind":"def","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ٧","segs":[["ctx","٢."],["matn","التَّعارض والتَّرجيح"],["ctx","، فيعملون بالدَّليل الأقوى عند تعارض الأدلة، إذ كانوا يتحرون في قَبول السُّنة، فليس كل من نسب شيئاً لرسول الله ﷺ يأخذون به دون أن ينظروا موافقته لغيره من نصوص الشَّرع العظيم، فمثلاً: قالت فاطمة بنت قيس رضي الله عنها: «إنَّ رسول الله ﷺ لم يجعل لها سكنى ولا نفقة، فردَّ عمر رضي الله عنه: لا نترك كتاب الله وسُنَّة نبينا ﷺ لقول امرأة لا ندري لعلها حفظت أو نسيت، لها السُّكنى والنَّفقة، قال الله تعالى: ﴿لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖ﴾ [الطلاق:١])."]]},{"id":"u7_8","kind":"def","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ٨","segs":[["ctx","٣."],["matn","النَّسخ"],["ctx","، فإنَّ المتأخر من النُّصوص ناسخ للمتقدِّم منها، كما فعل ابن مسعود رضي الله عنه في قوله تعالى: ﴿وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّ﴾ [الطلاق:٤]، فقال: «مَن شاء باهلته أنَّ آية النِّساء القصرى نزلت بعد آية عدَّة الوفاة»."]]},{"id":"u7_9","kind":"def","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ٩","segs":[["ctx","٤."],["matn","الإجماع"],["ctx","، فعن الشَّعبيِّ: «أنَّ عمر رضي الله عنه كتب إلى شُريح إذا جاءك شيء في كتاب الله فاقض به ولا يغلبنك عليه الرِّجال، وإذا جاءك ما ليس في كتاب الله تعالى فانظر في سُنة رسول الله ﷺ فاقض بها، فإن كان أمر ليس في كتاب الله تعالى ولم يكن في سُنة رسول الله ﷺ، فانظر ما أَجمع عليه النَّاس فخذ به، فإن كان ممَّا ليس في كتاب الله تعالى ولا في سُنةِ رسول الله ﷺ ولم يتكلم فيه قبلك أحد، فاختر أي الأمرين شئت، إن شئت أن تجتهد رأيك وتقدم فتقدَّم، وإن شئت أن تتأخر فتأخَّر، ألا وإنَّ التَّأخير خير لك»، وهذا الأصل برز وظهر في عصر الصَّحابة رضي الله عنهم بعد أن أرشد إليه النَّبي ﷺ ـ كما سبق ـ، حتى عدَّ بعض الكُتَّاب أنَّ مصادر التَّشريع زادت مصدراً في زمن الصَّحابة رضي الله عنه وهو الإجماع."]]},{"id":"u7_10","kind":"def","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ١٠","segs":[["ctx","٥."],["matn","القياس"],["ctx","، كما في قول عمر رضي الله عنه في رسالته إلى أبي موسى الأشعري رضي الله عنه: «الفهم الفهم فيما يختلج في صدرك مما لم يبلغك في القرآنِ والسُّنة، فتعرّف الأمثال والأشباه ثم قس الأمور عند ذلك، واعمد إلى أحبّها إلى الله وأشبهها فيما ترى»، وكذلك في اجتهاد عليّ بن أبي طالب رضي الله عنه في الوصول إلى حكم عقوبة شارب الخمر، حيث قضى بجلد شارب الخمر ثمانين جلدة قياساً على عقوبة القذف، فقال: «إذا شرب هذى، وإذا هذى افترى، وعلى المفتري ثمانين جلدة»، وليس هذا إلاّ عملاً بالقياس الذي هو طريق الاجتهاد، حيث قاس شارب الخمر على القاذف."]]},{"id":"u7_11","kind":"def","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ١١","segs":[["ctx","٦."],["matn","دوران الحكم مع علَّته"],["ctx","، كما في اجتهاد عمر بن الخطاب رضي الله عنه في تعيين العلَّة عندما أراد أن يُطبِّق النَّص المتعلق بمصارف الزَّكاة: ﴿إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ﴾ [التوبة:٦٠]، إذ لاحظ ضرورة التَّعرّف على العلَّة التي لأجلها شُرِع الحكم، وجعل الحكم يتبع العلَّة وجوداً وعدماً ويرتبه عليها، فقال: «إنَّ اللهَ أَعَزَّ الإسلام» فلم يعط للمؤلَّفة قلوبهم؛ لعدم توفّر شرط التَّأليف، كما أنَّه إذا لم يتوفر شرط الفقر في إنسان فلا يستحق الزَّكاة، ومتى توفر شرط التَّأليف فيمن يستحقّ أَخَذَ من الزَّكاة، وهكذا."]]},{"id":"u7_12","kind":"text","label":"المطلب الثَّاني: أصول الفقه في عصر الصَّحابة رضي الله عنه · الفقرة ١٢","segs":[["ctx","قال بلتاجي: «إنَّ أحكامَ الصَّحابة رضي الله عنهم لم تكن قائمة على مجرد الهوى، وإنَّما قامت على أصول وقواعد قيَّدوا بها أنفسهم فلم يخرجوا عن حدودها، بدليل اتحاد أحكام المسائل عند تساويها في المناط أو الحكمة، وليس يلزم من عدم نقل تلك الأصول والقواعد أنَّها لم تكن مستقرة في نفوسهم ملحوظة عند استنباطهم»."]]}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u8","title":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u8_1","kind":"text","label":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم · الفقرة ١","segs":[["ctx","إنَّ ما تلقاه الصَّحابة رضي الله عنهم من مِشكاة النُّبوة من فقه وحديث وأصول وغيرها نقلوه إلى التَّابعين، فاستمر صرح الفقه وأصوله بالاكتمال والظُّهور حتى صار إلى ما صار إليه، وما ذاك إلا لأنَّ القاعدة المتينة فيه أَسَّسَها رسول الله ﷺ وقوَّاها أصحابه رضي الله عنهم وشيَّدها التَّابعون وأكمل بناءها مَن جاء بعدهم من أئمة الدِّين، فما بين أيدينا من علم للدِّين نقله خلفنا عن سلفنا عن رسولنا ﷺ، والعلماء فيه أهل اتباع لَمن سبقهم، لا أهل ابتداع، وإنَّما إبداع في إظهار علم النُّبوة ونقله."]]},{"id":"u8_2","kind":"text","label":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم · الفقرة ٢","segs":[["ctx","قال الدِّهلوي: «سَمِعَ التَّابعون قضاءَ الصَّحابة وفتاويهم، وسألوهم عن المسائل، واجتهدوا في ذلك كلّه، ثم صاروا كبار قوم، ووسِّد إليهم الأمر، فنسجوا على منوال شيوخهم، ولم يألوا في تتبع الإيماءات والاقتضاءات، فقضوا، وأفتوا، ورووا، وعلموا، وكان صنيعهم في هذه الطَّبقة متشابهاً، وحاصل صنيعهم أن يتمسك بالمسند من حديث رسول الله ﷺ والمرسل جميعاً، ويستدل بأقوال الصَّحابة والتَّابعين علماً منهم أنَّها إما أحاديث منقولة عن رسول الله ﷺ فجعلوها موقوفة»."]]},{"id":"u8_3","kind":"text","label":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم · الفقرة ٣","segs":[["ctx","فصحابة رسول الله ﷺ فتحوا البلاد شرقاً وغرباً وحلوا فيها معلمين لأهلها ما ورثوه عن النَّبي ﷺ، وصارت الأمصار الرئيسية يدور فقهها على فقه من سَكنها من كبار مجتهدي الصَّحابة رضي الله عنهم، فالكوفة حلَّ فيها ابن مسعود رضي الله عنه يُعَلِّمَ أهلها، وتلقى على يديه كبار التَّابعين فيها مثل علقمة، وهكذا الحال في مكة والبصرة والشَّام والمدينة وغيرها."]]},{"id":"u8_4","kind":"text","label":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم · الفقرة ٤","segs":[["ctx","وما يهمنا هنا من ذلك أنَّ هذه المدن صُبِغَت فقهاً وأصولاً بفقه مَن حلَّ فيها من الصَّحابة رضي الله عنهم ومَن تلقى على يديهم من التَّابعين، فتميز فقه كل مِصر؛ لتميز أصوله التي بُني عليها فقهه كما هو معلوم، فلاحظنا أنَّ أهل كل بلد يفتخرون بعلمائهم وعلمهم ولا يجاوزونه إلى غيره إلا نادراً، قال ولي الله الدِّهلوي: «إذا اختلفت مذاهب الصَّحابة والتَّابعين رضي الله عنهم في مسألة، فالمختار عند كلّ عالم مذهب أهل بلده وشيوخه؛ لأنَّه أعرف بصحيح أقاويله من السَّقيم، وأوعى للأصول المناسبة لها، وقلبه أَميلُ إلى فضلهم وتبحرهم»، فمثلاً أهلُ المدينة اعتمدوا من أُصولهم إجماع أَهل المدينة، وهو ما توارثه علماء المدينة جيلاً بعد جيل عن رسول الله ﷺ، وقدَّموه على حديث الآحاد، فعن فقيه المدينة ربيعة الرَّأي: «ألف عن ألف خير من واحد عن واحد»."]]},{"id":"u8_5","kind":"text","label":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم · الفقرة ٥","segs":[["ctx","ومثل ما حصل في المدينة كان حاصلاً في الكوفة ـ وهما يومئذ حاضرة الإسلام ـ فأهل الكوفة كانوا يعتدون ويعتمدون على فقه الصَّحابة رضي الله عنهم الذين سكنوا الكوفة، ويُقدِّمونه على غيره، قال الإمامُ السَّرَخسيُّ في مسألة استدل فيها الإمام أبو حنيفة رضي الله عنه بقول إبراهيم النَّخعي: «وما ذكر هذا على سبيل الاحتجاج بقول إبراهيم؛ لأنَّ أبا حنيفة كان لا يرى تقليد التَّابعين، وكان يقول هم رجال ونحن رجال، ولكن ظهر عنده أنَّ إبراهيم فيما كان يفتي به يعتمد قول عليّ وابن مسعود رضي الله عنهم، فإنَّ فقه أهل الكوفة دار عليهما، وكان إبراهيم أعرف النَّاس بقولهما، فما صَحَّ عنه فهو كالمنقول عنهما، فلهذا حشا الكتاب من أقاويل إبراهيم»."]]},{"id":"u8_6","kind":"def","label":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم · الفقرة ٦","segs":[["ctx","فحاصل ما سبق: أنَّ أبرز مدرستين فقهيتين تَكَوَنتا في عصر التَّابعين في المدينة والكوفة كان من أصولهما:"],["matn","الاعتماد على الفقه الموروث عن مشايخهم من كبار التَّابعين والصَّحابة"],["ctx","رضي الله عنهم، وهذا الأصل كان له التَّأثير الكبير في الفقه الحنفي والمالكي فيما بعد، قال الدِّهلوي: «كان أبو حنيفة رضي الله عنه أَلزمهم بمذهب إبراهيم وأقرانه لا يجاوزه إلا ما شاء الله، وكان عظيم الشَّأن في التَّخريج على مذهبه، دقيق النَّظر في وجوه التَّخريجات، مقبلاً على الفروع أتم إقبال، وإن شئت أن تعلم حقيقة ما قلنا فَلَخِّص أقوال إبراهيم وأقرانه من كتاب الآثار لمحمد وجامع عبد الرَّزاق ومُصنَّف أبي بكر بن أبي شيبة، ثم قايسه بمذهبه تجده لا يفارق تلك المحجة إلا في مواضع يسيرة، وهو في تلك اليسيرة أيضاً لا يخرج عما ذهب إليه فقهاء الكوفة»."]]},{"id":"u8_7","kind":"def","label":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم · الفقرة ٧","segs":[["ctx","ومن الأصول التي عوِّل عليها في عصر التَّابعين"],["matn","الاعتماد على الحديث المرسل"],["ctx","، إذ قبلوا الخبر المرسل كالخبر المسند إذا كان مُرسله ثقة، وعليه جرت جمهرة فقهاء الأُمَّة من الصَّحابة والتَّابعين وتابعيهم إلى رأس المئتين؛ قال العلَّامة ظفر أحمد التَّهانوي: «لأنَّ من أسند فقد أحال على غيره، ومن أرسل فقد تكفَّل لصحَّة الخبر؛ لأنَّ العدل الثِّقة إذا قال: قال رسولُ الله ﷺ كذا جازماً بذلك، فالظَّاهرُ من حاله أنَّه لا يستجيز ذلك إلا وهو عالمٌ أو ظانٌّ أنَّ النَّبي ﷺ قاله، فإنَّه لو كان ظاناً أنَّ النَّبي ﷺ لم يقله أو كان شاكاً فيه لما استجاز في دينه النَّقل الجازم عنه؛ لما فيه من الكذب والتَّدليس على المستعمرين، وذلك يستلزم تعديل من روى عنه»."]]},{"id":"u8_8","kind":"text","label":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم · الفقرة ٨","segs":[["ctx","وقال الطَّبري: «لم يزل النَّاس على العمل بالمرسل وقَبوله، حتى حدث بعد المئتين القول برده». وفي كلام ابن عبد البرّ ما يقتضي أنَّ ذلك إجماع."]]},{"id":"u8_9","kind":"text","label":"المطلب الثَّالث: أصول الفقه في عصر التَّابعين رضي الله عنهم · الفقرة ٩","segs":[["ctx","وبهذا يتبيَّن لنا: أنَّ عصر التَّابعين ظهر فيه الفقه المدرسي، فكل أهل بلدة بينهم اتفاق كبير في المسائل الفقهية التي تلقوها عن مشايخهم من كبار التَّابعين والصَّحابة رضي الله عنهم مما جعل اشتراكاً بينهم في بعض الأصول، كأخذهم بالمرسل وتلقيهم لفقه الصَّحابة وكبار التَّابعين رضي الله عنهم بالقَبول، وهذا لا ينافي اختصاص كل واحد منهم بأصول خاصة به تتوافق مع نظرته واجتهاده في الأحكام."]]}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u9","title":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين»","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u9_1","kind":"text","label":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين» · الفقرة ١","segs":[["ctx","لا بُدَّ أن ينشأ مع الفقه أصول وضوابط وقواعد له، وهي مقدمات علم الأصول وقواعده الأساسية، ولا يوجد الفقه إلا بعلم الأصول، وقد دُوِّنَ الفقه الإسلامي وَهُذِّبت أبوابه قبل أن يُدَوَّن علم الأصول."]]},{"id":"u9_2","kind":"text","label":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين» · الفقرة ٢","segs":[["ctx","والأئمةُ المجتهدون أصحاب المذاهب المعتبرة كان لهم أصولهم وقواعدهم التي استندوا لها في استنباط المسائل الفرعية؛ إذ أنَّ ما عهِد عنهم من مسائل تنتظم في سلك واحد لأصول معيّنة لا تخرج عنها، فكلّ الفروع المتشابهة ترجع لقاعدة واحدة، الأمر الذي جعل مَن بعدهم يُقرّ لهم بالأحقية في التَّقليد والاتباع."]]},{"id":"u9_3","kind":"text","label":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين» · الفقرة ٣","segs":[["ctx","فهؤلاء الأئمة لا شكّ في اعتمادهم في استنباطهم على أصول وقواعد وإن لم تُدَوَّن في زمنهم، وقد نُسب أول تدوين في أصول الفقه إلى أبي يوسف رضي الله عنه؛ إذ ألَّف في أصول أبي حنيفة رضي الله عنه، وعيسى بن أَبان يكثر في كتبه من نقل نتف في الأصول عن محمد بن الحسن رضي الله عنه، وأبو بكر الرَّازيّ كثير النَّقل من كتب عيسى في كتابه: «الفصول في الأصول»."]]},{"id":"u9_4","kind":"text","label":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين» · الفقرة ٤","segs":[["ctx","ويرجع السَّبب في تأخُّر تدوين علم أصول الفقه إلى أنَّه لم يكن قد ابتدأ بَعْدُ عصر تقعيد قواعد العلوم الشَّرعية، وتأصيل أصول منهجية لها، وتدوينها بطريقة علمية منظمة، بل إنَّ مجرد تدوين العلوم العربية كلها نشأ في القرن الثَّاني، ولم يزدهر ويأخذ صورة جماعية إلا في النِّصف الثَّاني منه، فأول كتاب مستقل في الأصول يصل إلينا هو كتاب الشَّافعيّ المسمَّى بـ: «الرِّسالة»؛ لأنَّ تدوين وتأصيل العلوم كلها قد ظهر في عهده، فابتدأ تأصيل قواعد النَّحو، ووضع الخليل بن أحمد أصول العروض، وكان معاصراً للشَّافعي، والجاحظ قد ابتدأ يتكلم ويكتب في موازين النَّقد الأدبي، وهكذا نجد ذلك العصر قد ابتدأت فيه مناهج العلوم."]]},{"id":"u9_5","kind":"text","label":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين» · الفقرة ٥","segs":[["ctx","ولا غرابة في تأخير تدوين الأصول عن تدوين الفقه؛ لأنَّ الذي دفع إلى إعلان أحكام الفروع الفقهية هو السُّؤال عنها، والحاجة إلى إعلانها؛ ليعرف النَّاس أحكام دينهم، وما كان العامَّة الذين يستفتون في حاجة إلى تَعرُّف مناهج الاستنباط، وإنَّما كانوا في حاجة إلى معرفة حكم الدِّين فيما يقع لهم من حوادث، وما يُبتلون به من أمور تحتاج إلى أحكام تكون على وفق أحكام الإسلام."]]},{"id":"u9_6","kind":"text","label":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين» · الفقرة ٦","segs":[["ctx","ومن الطبيعي إذن في تاريخ العلوم كلِّها أن يكون وضعُ القواعد والأصول متأخراً في النَّشأة ولاحقاً لوجود موضوع هذه العلوم ذاتها."]]},{"id":"u9_7","kind":"text","label":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين» · الفقرة ٧","segs":[["ctx","فحاصلُ الكلام في هذه المرحلة: أنَّ الأئمة المجتهدين المستقلين أحكموا الأصول وسبروا النُّصوص ودقَّقوا في وضع القواعد وأكثروا من التَّفريع عليها بعد أن استفادوا ممَّن سبقهم حتى تكوَّنت لديهم مذاهب فقهيّة مستقلّة."]]},{"id":"u9_8","kind":"text","label":"المطلب الرَّابع: أصول الفقه في عصر الأئمة «المجتهدين المستقلين» · الفقرة ٨","segs":[["ctx","وفي عصرِهم ظهرت حركة تدوين العلوم المختلفة فابتدؤوا بتدوين الفقه، وبرزت الموسوعات الفقهية الضَّخمة على يد محمد بن الحسن الشَّيباني ككتابه المبسوط."]]}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u10","title":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب»","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u10_1","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١","segs":[["ctx","في هذا العصر ظهر علم الأصول في كتب مستقلة، وحُققت مسائله، ودُقِّقت قواعده، وفُصِّلت أصوله، ودُلِّل عليها، بعد أن كانت هذه الأصول مرتكزة في الأذهان والعقول إلا ما كان من التَّدوين الذي قام بها الشَّافعي رضي الله عنه لها، وسلك العلماء في التَّأليف في الأصول مسالك، وأُلِّفت في كلِّ منها المئات من الكتب الأصولية، نقتصر هاهنا على بيان خمسة اتجاهات مع ذكر أبرز الكتب فيها فيما يلي:"]]},{"id":"u10_2","kind":"def","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ٢","segs":[["matn","المسلك الأول: طريقة الفقهاء:"],["ctx","وامتازت هذه الطَّريقة بأَنَّ علماء الحنفية وَجَّهوا عنايتهم إلى تقرير القواعد الأصولية وتحقيقها على ضوء ما نقل عن أئمتهم من الفروع الفقهية، ومعنى ذلك أنَّهم استمدوا أصول فقههم من الفروع والمسائل الفقهية المنقولة عن أئمة المذهب الحنفي؛ لذلك كثرت الفروع الفقهية في كتب أصول الحنفية، وإن كانوا يذكرونها على سبيل التَّفريع على القواعد، وممكن تلخيص صفات هذه الطَّريقة فيما يلي:"]]},{"id":"u10_3","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ٣","segs":[["ctx","١. القواعد الأصولية مستخرجة من الفروع الفقهية، فإذا تعارضت القاعدة الأصولية مع الفرع الفقهي عُدِّلت القاعدة بما يتفق مع الفرع الفقهي؛ لأنَّ الفرع منقول عن المجتهد المطلق، والقاعدة مستفادة من الفرع، فيكون الفرع أقوى."]]},{"id":"u10_4","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ٤","segs":[["ctx","٢. الإكثار من ذكر الفروع الفقهية؛ لإثبات صحة القواعد التي استخرجت منها."]]},{"id":"u10_5","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ٥","segs":[["ctx","٣. الابتعاد عن الخوض في القضايا الكلامية؛ لبعدها عن الفقه."]]},{"id":"u10_6","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ٦","segs":[["ctx","٤. تقسيمهم للألفاظ كالآتي:"]]},{"id":"u10_7","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ٧","segs":[["ctx","أ. من حيث الوضوح إلى: الظَّاهر، والنَّص، والمفسَّر، والمحكم."]]},{"id":"u10_8","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ٨","segs":[["ctx","ب. من حيث الإبهام إلى: الخفي، والمشكل، والمجمل، والمتشابه."]]},{"id":"u10_9","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ٩","segs":[["ctx","ج. من حيث الدلالة على المعنى إلى: دلالة العبارة، ودلالة النَّص، ودلالة الإشارة، ودلالة الاقتضاء."]]},{"id":"u10_10","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١٠","segs":[["ctx","٥. من القواعد الأصولية التي اعتمدوها:"]]},{"id":"u10_11","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١١","segs":[["ctx","أ. عدمُ الاحتجاج بمفهوم المخالفة."]]},{"id":"u10_12","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١٢","segs":[["ctx","ب. دلالةُ العام على أفراده قطعية."]]},{"id":"u10_13","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١٣","segs":[["ctx","ج. عدمُ حمل المطلق على المقيد إذا اتحدا في سبب الحكم والموضوع."]]},{"id":"u10_14","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١٤","segs":[["ctx","د. الاحتجاج بالحديث المرسل."]]},{"id":"u10_15","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١٥","segs":[["ctx","هـ. عدم الأخذ بخبر الواحد فيما تعم به البلوى."]]},{"id":"u10_16","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١٦","segs":[["ctx","قال ابنُ خلدون: «إنَّ كتابةَ الفقهاء فيها أمس بالفقه وأليق بالفروع؛ لكثرة الأمثلة منها والشَّواهد وبناء المسائل فيها على النُّكت الفقهية، والمتكلِّمون يُجرِّدون صورة تلك المسائل على الفقه ويَميلون إلى الاستدلال العقلي ما أَمكن؛ لأنَّه غالبُ فنونهم ومقتضى طريقتهم، فكان لفقهاء الحنفيةِ فيها اليدُ الطولى من الغوصِ على النُّكت الفقهيّة والتقاط هذه القوانين من مسائل الفقه ما أمكن."]]},{"id":"u10_17","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١٧","segs":[["ctx","وجاء أبو زيد الدَّبوسيّ من أئمة الحنفية فكتب في القياس بأوسع من جميعهم وتمَّمَ الأبحاث والشُّروط التي يُحتاج إليها فيه، وكَمُلَت صناعة أُصوله الفقه بكمالِه وتهذيب مسائله وتمهدت قواعدُه..."]]},{"id":"u10_18","kind":"text","label":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب» · الفقرة ١٨","segs":[["ctx","وأما طريقة الحنفية فكتبوا فيها كثيراً، وكان أحسن كتابة فيها للمتقدمين تأليف أبي زيد الدَّبوسي، وأحسن كتابة المتأخرين فيها تأليف فخر الإسلام البزدوي من أئمتهم، وهو مستوعب»."]]}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u10a","title":"وأبرز المؤلفات على هذه الطريقة هي","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u10a_1","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١","segs":[["matn","وأبرز المؤلفات على هذه الطريقة هي:"],["ctx","١."],["matn","الأصول"],["ctx",": لأبي الحسن عبيد الله بن الحسن الكرخي (ت٣٤٠هـ)، وقد انتهت إليه رئاسة الحنفية، وله رسالة صغيرة في الأصول التي عليها مدار مسائل الحنفية، وممن شرحها أبو حفص عمر النَّسفي، وعامَّة ما تحويه هذه الرِّسالة هي أصول بناء «قواعد فقهية»، وليس أصول استنباط، ويُكثر الأصوليون النَّقل عن الكرخي في الأصول، فلا شك انه له كتاباً موسعاً في الأصول، والله أعلم."]]},{"id":"u10a_2","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٢","segs":[["ctx","٢."],["matn","أصول الشاشي"],["ctx",": لأبي عليّ حمد بن محمد بن إسحاق الشَّاشي (ت٣٤٤هـ)، والكتاب مشهور متداول، وفي نسبته إلى الشاشي نظر، والأولى في نسبته للقرن السَّادس، وعليه شروح عديدة، منها: فصول الحواشي لأصول الشَّاشي، وتسهيل أصول الشَّاشي لمحمد أنور البدخشاني، وحُسن الحواشي لمحمد بركة الله."]]},{"id":"u10a_3","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٣","segs":[["ctx","٣."],["matn","الفصول في الأصول"],["ctx",": لأحمد بن عليّ، أبي بكر الرَّازي، المعروف بالجصاص، وقد انتهت إليه رئاسة الحنفية (ت٣٧٠هـ)."]]},{"id":"u10a_4","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٤","segs":[["ctx","٤."],["matn","تقويم الأدلة والأسرار في الأصول والفروع"],["ctx",": لعبيد الله بن عمر بن عيسى، أبي زيد الدَّبوسي، وهو أول من وضع علم الخلاف، وكان ممن يضرب به المثل في النَّظر واستخراج الحجج، وهو من كبار الفقهاء الحنفية، (ت٤٣٠هـ)، وشرح التَّقويم: فخر الإسلام البزدوي الحنفي، وهو شرح حَسَنٌ اعتبره علماء الحنفية، واختصره: أبو جعفر محمد بن الحسين الحنفي."]]},{"id":"u10a_5","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٥","segs":[["ctx","٦."],["matn","أصول البزدويّ «كنز الوصول إلى معرفة الأصول»"],["ctx",": لعليّ بن محمد بن الحسين، أبي الحسن، فخر الإسلام البزدويّ، قال الكفويّ: «الإمام الكبير الجامع بين أشتات العلوم، إمام الدُّنيا في الفروع والأصول، له تصانيف كثيرة معتبرة»، (ت٤٨٢هـ)، وهو كتاب عظيم الشأن، جليل البرهان، محتو على لطائف الاعتبارات بأوجز العبارات، تأبى على الطلبة مرامه، واستعصى على العلماء زمامه، قد انغلقت ألفاظه وخفيت رموزه وألحاظه، فقام جمع من الفحول بأعباء توضيحه وكشف خباياه وتلميحه، ومن شروحه: كشف الأسرار لعبد العزيز بن أحمد البخاري، وهو أحسنها وأشهرها، والكافي لحسين بن علي الصغناقي، والتَّقرير لأكمل الدِّين البابرتي، والتَّحرير لمصنفك، وشرح أحمد بن حسن الجاربردي، وشرح قوام الدِّين الأتراري، وشرح محمد بن أحمد بن الضياء المكي، وشرح عمر بن عبد المحسن الأرزنجاني، وشرح حميد الدِّين عليّ بن محمد الضرير، وشرح ملا خسرو، وغيرها من الشُّروح."]]},{"id":"u10a_6","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٦","segs":[["ctx","٧."],["matn","أصول السَّرخسي"],["ctx",": لمحمد بن أحمد، أبي بكر السَّرخسي، شمس الأئمة، قال الكفوي: «كان إماماً علَّامة حجَّة متكلماً مناظراً أصولياً مجتهداً، وقد أملى «المبسوط» من غير مراجعة شيء من الكتب، وهو في الجبّ محبوس بسبب كلمة نصح بها الأمراء، وكان تلامذته يجتمعون على أعلى الجبّ يكتبون»، (ت نحو ٥٠٠هـ)."]]},{"id":"u10a_7","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٧","segs":[["ctx","٨."],["matn","كفاية الفحول في علم الأصول"],["ctx",": لأبي محمد عبد العزيز بن عثمان العقيلي الحنفي، المعروف بالقاضي النَّسفي، (ت٥٣٣هـ)."]]},{"id":"u10a_8","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٨","segs":[["ctx","٩."],["matn","ميزان الأصول في نتائج العقول في أصول الفقه"],["ctx",": لعلاء الدِّين أبي بكر محمد بن أحمد السَّمرقندي (ت٥٣٩هـ)."]]},{"id":"u10a_9","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٩","segs":[["ctx","١٠."],["matn","بذل النَّظر في الأصول"],["ctx",": لمحمد بن عبد الحميد الأسمندي (ت٥٥٢هـ)."]]},{"id":"u10a_10","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٠","segs":[["ctx","١١."],["matn","الفصول في علم الأصول"],["ctx",": لأبي المؤيد موفق بن محمد الخاصي الخوارزمي الحنفي (ت٦٣٤هـ)."]]},{"id":"u10a_11","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١١","segs":[["ctx","١٢."],["matn","المنتخب في أصول المذهب"],["ctx",": لمحمد بن محمد بن عمر الاخسيكثي، حسام الدِّين، قال الكفوي: «كان شيخاً فاضلاً إماماً في الفروع والأصول»، (ت٦٤٤هـ)، وهو محذوف الفضول، ومبين الفصول، متداخل النقوض والنَّظائر، منسرد اللآلئ والجواهر، فتهالك النَّاس في تعلّمه وتعليمه، مكبين في تحديثه وتنقيره، ومن شروحه: التحقيق لعبد العزيز البخاري، والوافي للصغناقي، والتَّبيين لقوام الدِّين أمير كاتب بن أمير عمر الإتقاني، وشرح حافظ الدِّين النَّسفي، والنِّظامي لمحمد نظام الدين الكيرانوي وغيرها من الشُّروح."]]},{"id":"u10a_12","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٢","segs":[["ctx","١٣."],["matn","المجتبى في أصول الفقه"],["ctx",": لأبي الرَّجا مختار بن محمود الزَّاهدي القزويني الحنفي، نجم الدِّين، (ت٦٥٨هـ)."]]},{"id":"u10a_13","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٣","segs":[["ctx","١٤."],["matn","المغني"],["ctx",": لعمر بن محمد بن عمر الخبازي، جلال الدِّين، (ت٦٩١هـ)، ومن شروحه: شرح منصور القاآني، وشرح سراج الدِّين الهندي."]]},{"id":"u10a_14","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٤","segs":[["ctx","١٥."],["matn","منار الأنوار"],["ctx",": لعبد الله بن أحمد بن محمد النَّسفي، حافظ الدِّين، قال اللكنوي: «وكل تصانيفه نافعةٌ مُعتبرةٌ عند الفقهاءِ مطروحةٌ لأنظار العلماءِ»، (ت٧٠١هـ)، وهو متن متين جامع مختصر نافع، ومن أكثر كتب الأصول تداولاً وأقربها تناولاً مع صغر حجمه ووجازة نظمه، بحرٌ محيطٌ بدرر الحقائق، وكنزٌ أودع فيه نقود الدَّقائق، ومن شروحه: كشف الأسرار للمؤلف، وجامع الأسرار للكاكي، ونور الأنوار لملا جيون، وإفاضة الأنوار في إضاءة أصول المنار لسعد الدِّين محمود الدِّهلوي، وشرح ابن ملك، وشرح ابن العيني، وشرح ناصر الدِّين ابن الربوة، و تبصرة الأسرار لهبة الله بن أحمد التركستاني، والأنوار للبابرتي، واقتباس الأنوار ليوسف بن قوماري العنقري، وفتح الغفار لابن نجيم المصري، ونتائج الأفكار لعزمي زاده، وغيرها من الشُّروح التي لا تحصى."]]},{"id":"u10a_15","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٥","segs":[["ctx","١٦."],["matn","مجامع الحقائق"],["ctx",": لأبي سعيد محمد بن محمد بن مصطفى الخادمي(ت بعد ١١٦٨هـ)، وقد شرحه مصطفى كُوْزَل حَصاري (ت١٢١٥هـ) في منافع الدَّقائق، وشرح الخاتمة سليمان الفرق أغاجي."]]},{"id":"u10a_16","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٦","segs":[["ctx","١٧."],["matn","تسهيل الوصول إلى علم الأصول"],["ctx",": لمحمد عبد الرَّحمن عيد المحلاوي الحنفي."]]}],"sup":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب»"},{"id":"u10b","title":"المسلك الثَّاني: طريقة المتكلمين","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u10b_1","kind":"def","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١","segs":[["matn","المسلك الثَّاني: طريقة المتكلمين:"],["ctx","وتميَّزت هذه الطَّريقة بتحقيق المسائل تحقيقاً منطقياً نظرياً، وتمحيص الخلافات مع الميل إلى الاستدلال العقلي وعدم التَّعقيد في الجدل، فهم يثبتون ما أثبته الدَّليل، وينفون ما نفاه الدَّليل، وكلُّ هدفهم الوصول إلى أقوى القواعد وأضبطها، فلم يجعلوا همّهم أخذ القواعد من الفروع الفقهية، ولم يربطوها ببعضها، بل كانوا بعد تقريرهم القاعدة الأصولية يثبتونها وإن خالفت الأصول التي دوَّنها أئمتهم."]]},{"id":"u10b_2","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ٢","segs":[["ctx","وكان يميل إلى هذه الطَّريقة علماء المالكية والشَّافعية وعلماء الكلام، ولم تقتصر هذه الطَّريقة على قواعد استنباط الأحكام الفقهيّة، بل بحثت في بعض المسائل الكلاميّة العقلية، فقد تكلّموا عن عصمة الأنبياء قبل النُّبوة، وعن التحسين والتقبيح العقليين، وبعض المباحث المنطقية الفلسفية؛ لذلك سُمِّيت هذه الطَّريقة بطريقة المتكلمين، وعلى الجملة فالأصول عندهم فنّ مستقل يبنى عليه الفقه، فلا حاجة للمزج بين الفنين، والجمع بين العلمين، ويمكن تلخيص صفات هذه الطريقة فيما يلي:"]]},{"id":"u10b_3","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ٣","segs":[["ctx","١. الفصل بين الأصول والفقه، بمعنى أنَّ الأصول فن مستقل عن الفقه."]]},{"id":"u10b_4","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ٤","segs":[["ctx","٢. أسلوبهم في معالجة القضايا الأصولية فيه صعوبة بسبب المنهج الذي اتبعوه في استخراج القواعد."]]},{"id":"u10b_5","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ٥","segs":[["ctx","٣. الإكثار من الجدل والمناظرة، فهم يستعملون أسلوب الفنقلة: أي فإن قيل: كذا، قلنا: كذا."]]},{"id":"u10b_6","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ٦","segs":[["ctx","٤. الخوض في مسائل لا صلة لها بأصول الفقه، كعصمة الأنبياء قبل النُّبوة، وأصل اللغات، وتكليف المعدوم."]]},{"id":"u10b_7","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ٧","segs":[["ctx","٥. تقسيمهم للألفاظ كالآتي:"]]},{"id":"u10b_8","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ٨","segs":[["ctx","أ. من حيث الوضوح إلى: نص وظاهر."]]},{"id":"u10b_9","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ٩","segs":[["ctx","ب. من حيث الخفاء إلى: مجمل ومتشابه."]]},{"id":"u10b_10","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١٠","segs":[["ctx","ج. من حيث الدلالة على الحكم إلى: دلالة منطوق ودلالة مفهوم."]]},{"id":"u10b_11","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١١","segs":[["ctx","٦. من القواعد الأصولية التي اعتمدوها:"]]},{"id":"u10b_12","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١٢","segs":[["ctx","أ. الأخذ بمفهوم المخالفة."]]},{"id":"u10b_13","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١٣","segs":[["ctx","ب. دلالة العام على أفراده دلالة ظنية."]]},{"id":"u10b_14","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١٤","segs":[["ctx","ج. قَبول خبر الواحد فيما تعم به البلوى."]]},{"id":"u10b_15","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١٥","segs":[["ctx","قال ابن خلدون: «وعُني النَّاس بطريقة المتكلمين فيه، وكان من أحسن ما كَتب فيه المتكلمون كتاب: «البرهان» لإمام الحرمين، و«المستصفى» للغزالي، وهما من الأشعرية، وكتاب: «العمد» لعبد الجبار، و«المعتمد» لأبي الحسين البصري، وهما من المعتزلة، وكانت الأربعة قواعد هذا الفن وأركانه، ثم لخصَّ هذه الكتب الأربعة فحلان من المتكلمين المتأخرين، وهما الإمام فخر الدِّين بن الخطيب في كتاب: «المحصول»، وسيف الدِّين الآمدي في كتاب: «الإحكام»، واختلفت طرائقهما في الفنّ بين التحقيق والحجاج، فابن الخطيب أميل إلى الاستكثار من الأدلة والاحتجاج، والآمدي مولع بتحقيق المذاهب وتفريع المسائل."]]},{"id":"u10b_16","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١٦","segs":[["ctx","وأما كتاب المحصول، فاختصره تلميذه الإمام سراج الدِّين الأموري في كتاب: «التحصيل»، وتاج الدِّين الأموري في كتاب: «الحاصل»، واقتطف شهاب الدِّين القرافي منهما مقدمات وقواعد في كتاب صغير سمّاه: «التَّنقيحات»، وكذلك فعل البيضاوي في كتاب: «المنهاج»، وعني المتبدؤون بهذين الكتابين، وشرحهما كثير من النَّاس."]]},{"id":"u10b_17","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١٧","segs":[["ctx","وأما كتاب: «الإحكام» للآمدي وهو أكثرها تحقيقاً في المسائل، فلخصه أبو عمر بن الحاجب في كتابه المعروف بـ: «المختصر الكبير»، ثم اختصره في كتاب آخر تدواله طلبة العلم وعني أهل المشرق والمغرب به وبمطالعته وشرحه وحصلت زبدة طريقة المتكلمين في هذا الفن في هذه المختصرات»."]]},{"id":"u10b_18","kind":"text","label":"المسلك الثَّاني: طريقة المتكلمين · الفقرة ١٨","segs":[["ctx","والظاهر أنَّ هذه الطريقة ألصق بعلم الكلام من الفقه؛ لذلك كانت أُمّهات كتب هذه الطريقة راجعةٌ لأبرز علماء الكلام من الأشاعرة والمعتزلة، واهتمام أصحابها بتقعيد القواعد بدون التفات للفروع يدلّ على ذلك."]]}],"sup":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب»"},{"id":"u10c","title":"وأبرز المؤلفات على هذه الطريقة هي","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u10c_1","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١","segs":[["matn","وأبرز المؤلفات على هذه الطريقة هي:"],["ctx","١."],["matn","الرِّسالة:"],["ctx","للإمام محمد بن إدريس الشَّافعي (ت٢٠٤هـ)، ومن شروحها: شرح لأبي بكر محمد الصيرفي (ت٣٣٠هـ)، وشرح أبي الوليد حسام بن محمد النيسابوري (ت٣٤٩هـ)، وشرح أبي محمد القفال الشاشي (ت٣٦٥هـ)، وشرح أبي بكر محمد بن عبد الله الشيباني (ت٣٨٨هـ)، وشرح عبد الله بن يوسف الجويني (ت٤٣٨هـ)."]]},{"id":"u10c_2","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٢","segs":[["ctx","٢."],["matn","التَّعريف والإرشاد في ترتيب طرق الاجتهاد:"],["ctx","للقاضي أبي بكر الباقلاني المالكي (ت٤٠٣هـ)، وقد اختصره في كتب الإرشاد المتوسط، والإرشاد الصغير: قال السُّبكي: «وهو من أَجَّل كتب الأصول، والذي بين أيدينا منه هو المختصر الصغير، ويبلغ أربعة مجلدات، ويحكى أنَّ أصله كان في اثني عشر مجلداً، ولم نطلع عليه، وكذلك اختصره إمام الحرمين وسمّاه التَّلخيص."]]},{"id":"u10c_3","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٣","segs":[["ctx","٣."],["matn","العمد:"],["ctx","للقاضي عبد الجبار بن أحمد الهمداني المعتزلي (ت٤١٥هـ)."]]},{"id":"u10c_4","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٤","segs":[["ctx","٤."],["matn","الفصل في أصول الفقه، والتَّحصيل في أصول الفقه:"],["ctx","لأبي منصور عبد القادر ابن طاهر البغدادي (ت٤٢٩هـ)."]]},{"id":"u10c_5","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٥","segs":[["ctx","٥."],["matn","العدة والكفاية:"],["ctx","للقاضي أبي يعلى محمد بن الحسين الفراء الحنبلي (ت٤٥٨هـ)."]]},{"id":"u10c_6","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٦","segs":[["ctx","٦."],["matn","المعتمد في أصول الفقه:"],["ctx","لأبي الحسين البصري المعتزلي (ت٤٦٣هـ)."]]},{"id":"u10c_7","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٧","segs":[["ctx","٧."],["matn","إحكام الفصول في أحكام الأصول:"],["ctx","لأبي الوليد سليمان بن خلف الباجي (ت٤٧٤هـ)."]]},{"id":"u10c_8","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٨","segs":[["ctx","٨."],["matn","اللمع وشرح اللمع والتبصرة:"],["ctx","لأبي إسحاق إبراهيم بن علي الشيرازي (ت٤٧٦هـ)."]]},{"id":"u10c_9","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ٩","segs":[["ctx","٩."],["matn","البرهان والورقات:"],["ctx","لإمام الحرمين عبد الملك الجويني (ت٤٧٨هـ)، ومن شروح البرهان: إيضاح المحصول من برهان الأصول لأبي عبد الله المازري المالكي (ت٥٣٦هـ)، وشرح أبي يحيى زكريا الحسني المغربي، وشرح لأبي الحسن بن الأبياري المالكي(ت٦١٤هـ)، وأما شروح الورقات فلا تعد ولا تحصى لكثرتها، وهي مشهورة متداولة إلى يومنا هذا."]]},{"id":"u10c_10","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٠","segs":[["ctx","١٠."],["matn","القواطع في أصول الفقه:"],["ctx","لأبي المظفر منصور بن محمد السمعاني (ت٤٨٩هـ)."]]},{"id":"u10c_11","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١١","segs":[["ctx","١١."],["matn","المستصفى في أصول الفقه والمنخول من تعليقات علم الأصول:"],["ctx","لحجة الإسلام أبي حامد محمد بن محمد الغزالي (ت ٥٠٥هـ)، ورتب المستصفى على مقدمة وأربعة أقطاب: المقدمة: للتوطئة والتمهيد، والأقطاب: هي المشتملة على لباب المقصود، القطب الأول: في الأحكام، والثاني: في الأدلة، والثَّالث: في طريق الاستثمار، والرابع: في المستثمر. وقد اعتنى به العلماء عناية كبيرة فاختصره أحمد بن محمد الإشبيلي، والسهوردي الحكيم، وعبد الكريم المدرس، وشرحه: حسين بن عبد العزيز الفهري البلنسي، وعليه تعاليق: لسليمان بن محمد الغرناطي."]]},{"id":"u10c_12","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٢","segs":[["ctx","١٢."],["matn","إحكام الأحكام في أصول الأحكام:"],["ctx","لسيف الدِّين علي بن محمد الآمدي، قال الأسنوي:«صاحب التَّصانيف النافعة، والعلوم الكثيرة المحقَّقة»،(ت٦٣١هـ)، رتب على أربع قواعد: في مفهوم أصول الفقه، وفي الأدلة السَّمعية، وفي أحكام المجتهدين، وفي التَّرجيح، نقل عن الشِّيرازي: أنَّ ابن الحاجب اختصر منه كتابه المسمّى: بالمنتهى."]]},{"id":"u10c_13","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٣","segs":[["ctx","١٣."],["matn","منتهى السول والأمل في علمي الأصول والجدل:"],["ctx","لعثمان بن عمر، المعروف بابن الحاجب المالكي (ت٦٤٦هـ)، وهو مشهور متداول بمختصر المنتهى، ومختصر ابن الحاجب، وهو مختصر غريب في صنعه بديع في فنه لغاية إيجازه يضاهي الألغاز، وبحسن إيراده يحاكي الإعجاز، واعتنى بشأنه الفضلاء، فمن شروحه شرح الشيرازي، وشرح ركن الدين الموصلي، وشرح جمال الدين الحلي، وشرح المولى زين الدين الخنجي، وشرح شمس الدين الأصبهاني، وشرح بدر الدين التستري، وشرح شمس الدين الخطيبي، وشرح عضد الملة والدين، وهو أشهر شروحه لحسن اختصاره مع اشتماله على تدقيقات وتحقيقات لا توجد في غيره، ولهذا كتبوا على ذلك حواشي شريفة، مثال حاشية سيف الدين الأبهري، وحاشية شمس الدين الكرماني، وحاشية المولى سعد الدين التفتازاني، وحاشية المولى السيد الشريف الجرجاني."]]},{"id":"u10c_14","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٤","segs":[["ctx","١٣."],["matn","المحصول في أصول الفقه:"],["ctx","لفخر الدِّين محمد بن عمر الرَّازي (ت٦٠٦هـ)، ومن شروحه: شرح شمس الدِّين الأصبهاني، وشرح أحمد بن إدريس القرافي المالكي."]]},{"id":"u10c_15","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٥","segs":[["ctx","١٤."],["matn","التحصيل:"],["ctx","لسراج الدِّين محمود بن أبي بكر الأرموي (ت٦٨٢هـ)، وهو مختصر من المحصول للرَّازي، ومشهور متداول، ومن شروحه: الحاصل لمحمد بن محمد الجزري."]]},{"id":"u10c_16","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٦","segs":[["ctx","١٥."],["matn","منهاج الوصول إلى علم الأصول:"],["ctx","للقاضي عبد الله بن عمر البيضاوي (ت٦٨٥هـ)، وهو كتاب نفيس على مذهب الشَّافعي مرتب على مقدمة وسبعة كتب، وعليه شروح: شرح السَّيد العبري، وهو أحسنها، والسِّراج الوهاج للتبريزي، وشرح محمود بن عبد الرحمن الأصفهاني، ونهاية السول لعبد الرحيم بن حسن الأسنوي، وشرح غياث الدين محمد بن محمد الواسطي، وشرح تاج الدين السبكي، ونهاية السول لفرج بن محمد الأردبيلي، وشرح أحمد بن حسين الرملي، وشرح زكريا الأنصاري، وسراج العقول لمحمد بن طاهر القزويني، والأسرار للخنجي، والتحرير لأبي زرعة العراقي، ومعراج الوصول لمجد الدين الأيكي، وغيرها من الشروح."]]},{"id":"u10c_17","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٧","segs":[["ctx","١٦."],["matn","البحر المحيط في أصول الفقه:"],["ctx","لبدر الدِّين محمد بن بهادر بن عبد الله الزركشي الشافعي (ت٧٩٤هـ)، أراد المؤلِّف لكتابه أن يكون مؤلَّفاً موسوعياً في مدونة واحدة يجمع فيه أقوال علماء الأصول الذين عاصروه، أو سبقوه، فعرض في كل مسألة أقوال أهل العلم، وذكر المذاهب فيها، وحقق ووازن بين الأقوال، وذكر الأدلة وانتقدها، وذكر أسباب الاختلاف."]]},{"id":"u10c_18","kind":"def","label":"وأبرز المؤلفات على هذه الطريقة هي · الفقرة ١٨","segs":[["ctx","١٧."],["matn","جمع الجوامع:"],["ctx","لتاج الدِّين عبد الوهاب بن علي بن السُّبكي الشَّافعي، (ت٧٧١هـ)، وهو مختصر مشهور، جمعه من زهاء مئة مصنف مشتمل على زبدة ما في شرحيه على مختصر ابن الحاجب والمنهاج مع زيادات وبلاغة في الاختصار، ورتب على مقدمات وسبعة كتب، ومن شروحه: منع الموانع للمصنف، والدرر اللوامع في تحرير الجامع لابن أبي الشريف المقدسي، وتشنيف المسامع لبدر الدين محمد بن عبد الله الزركشي، وتشنيف المسامع أيضاً للأسدي الغزي، وشرح أبي زرعة العراقي، وشرح ابن جماعة، وشرح ابن رسلان الرملي، وشرح برهان الدين القبقابي، وشرح عبد الوهاب الشعراني، وشرح البقاعي، وشرح جلال الدين المحلي، وهو أحسن في غاية التحرير والتنقيح؛ ولذلك اعتنى العلماء بتدريسه وتحشيته، ومن حواشيه: حاشية محمد ابن داود البازلي، وحاشية ناصر الدين القاني، وحاشية بدر الدين محمد بن محمد بن خطيب، وحاشية زكريا الأنصاري، وحاشية قطب الدين الصفوي الإيجي."]]}],"sup":"المطلب الخامس: أصول الفقه في عصر الأئمة «المجتهدين في المذاهب»"},{"id":"u11","title":"المسلك الثَّالث: طريقة المتأخرين","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u11_1","kind":"text","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ١","segs":[["ctx","تقوم هذه الطَّريقة على الجمع بين طريقة المتكلمين التي تقوم على تحقيق القواعد الأصولية تحقيقاً نظرياً منفصلاً عن الفقه، وعلى طريقة الفقهاء التي تقوم على تحقيق القواعد الأصولية تحقيقاً مرتبطاً بالفقه ومعتمداً عليه، وقد سار على هذه الطريقة علماء من مختلف المذاهب الفقهية، وسُمِّيَت هذه الطريقة بطريقة المتأخرين؛ لأنَّها ظهرت في وقت متأخر عن طريقة الفقهاء والمتكلمين."]]},{"id":"u11_2","kind":"text","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ٢","segs":[["ctx","وصفة هذه الطَّريقة أنَّها تحقق القواعد الأصولية تحقيقاً نظرياً، وتقيم البراهين عليها مع العناية بتطبيق هذه القواعد على الفروع الفقهية وربطها بها."]]},{"id":"u11_3","kind":"text","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ٣","segs":[["ctx","قال ابن خلدون: «وجاء ابن السَّاعاتي من فقهاء الحنفية فجمع بين «كتاب الأحكام» و«كتاب البزدوي» في الطريقتين، وسمى كتابه بـ: «البدائع» فجاء من أحسن الأوضاع وأبدعها، وأئمة العلماء لهذا العهد يتداولونها قراءة وبحثاً، وولع كثير من علماء العجم بشرحه»."]]},{"id":"u11_4","kind":"text","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ٤","segs":[["ctx","والظاهر أنَّ المشتغلين في هذه الطريقة هم علماء الحنفية أعادوا ترتيب كتب أصولهم على طريقة المتكلمين؛ لأنَّها كانت أفضل تأليفاً من طريقة الفقهاء، وتكلَّموا فيها في المباحث التي ناقشتها طريقة المتكلمين ولم تناقشها طريقة الفقهاء، فهي تأليف من علماء الحنفية على منهج طريقة المتكلمين."]]},{"id":"u11_5","kind":"def","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ٥","segs":[["matn","وأبرز المؤلفات على هذه الطريقة هي:"],["ctx","١."],["matn","بدائع النِّظام الجامع بين كتابي البزدوي والإحكام:"],["ctx","لأحمد بن علي بن ثعلب البغدادي البعلبكي الحنفي، مظفر الدين، المعروف بابن السَّاعاتي، قال الكفوي: «كان إمام العصر في العلوم الشرعية، كان ثقة حافظاً متقناً، أقرّ له شيوخ زمانه بأنَّه فارس جواد في ميدانه»، (ت٦٩٤هـ)، ولاشتراك ذلك الكتاب بين الأصوليين تصدَّى لشرحه جماعة من الحنفية والشَّافعية منهم: ابن أمير الحاج التبريزي في الرفيع في شرح البديع، وعثمان بن عبد الملك الكردي المصري، ومحمود بن عبد الرحمن الأصفهاني في بيان معاني البديع، وابن الشيخ عونية الموصلي، وسراج الدين عمر بن إسحاق الهندي في كاشف معاني البديع وبيان مشكلة المنيع، وكمال الدين محمد بن عبد الواحد بن الهمام، وابن خطيب جربن الحلبي، غيرهم من الشراح."]]},{"id":"u11_6","kind":"def","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ٦","segs":[["ctx","٢."],["matn","تنقيح الأصول:"],["ctx","لعبيد الله بن مسعود المحبوبي الحنفي، صدر الشَّريعة، وهو عالم محقق، وحبر مدقق، له تصانيف مفيدة، (ت٧٤٧هـ)، جمع فيه بين كلام البَزْدَويّ وكلام ابن الحاجب، ورتَّبه ترتيباً حسناً، ومن شروحه: التَّوضيح للمصنف، وشرح عبد الله بن محمد الحسيني، وقد لقي شرحه التوضيح عناية فائقة من العلماء حفظاً وتدريساً وشرحاً وتحشيةً وتعليقاً، قال المرجاني: «إنَّ كتاب «التنقيح» وشرحه «التوضيح» هو المعوّل عند الطلبة عليه والرُّجوع في تحصيل الأصول إليه. انتهى؛ لذا أقبل الطلاب على متنه بالحفظ، والعلماء على شرحه بالتَّدريس والتَّوضيح لِما أشكل من عباراته وغمض من ألفاظه»، ومن الحواشي والشروح عليه: حاشية عبد القادر الأنصاري، وحزامة الحواشي لإزاحة الغواشي للمرجاني، والتلويح في كشف حقائق التنقيح، والترجيح لبرهان الدين أحمد السيواسي، وحاشية العلامة السيد الشريف الجرجاني، وحاشية مصنفك، وحاشية حسن بن محمد شاه الفناري، وغيرها."]]},{"id":"u11_7","kind":"def","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ٧","segs":[["ctx","٣."],["matn","فصول البدائع في أصول الشَّرائع:"],["ctx","لمحمد بن حمزة الفناري الحنفي، شمس الدِّين، قال الكفوي: «إمام كبير، علامة نحرير، أوحد زمانه في العلوم النقلية وأغلب أقرانه في العلوم العقلية، شيخ دهره في العلم والأدب»، (ت٨٣٤هـ)، رتبه على فاتحة والمطلب فيه: مقدمتان ومقصدان وخاتمة، والخاتمة: في الاجتهاد وما يتبعه جمع فيها: المنار، وأصول البزدوي، ومحصول الرَّازي، ومختصر ابن الحاجب، وغير ذلك، وأقام في تأليفه ثلاثين سنة، قال الشَّوكاني: «وهو من أجل الكتب الأصولية وأنفعها وأكثرها فوائد». وكتب ابنه محمد شاه: حاشية عليه، وسماها: تلخيص الفصول وترصيص الأصول، واختصره الشيخ يوسف بن إبراهيم المغربي الدانوعي الحنبلي في غاية التَّحرير الجامع، ثم شرحه وسمَّاه كشف الشوارد والموانع."]]},{"id":"u11_8","kind":"def","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ٨","segs":[["ctx","٤."],["matn","مرقاة الوصول إلى علم الأصول:"],["ctx","لمحمد بن فراموز الحنفي، المشهور بملا خسرو، قال الكفوي: «كان بحراً زاخراً عالماً بالمعقول والمنقول، وحبراً فاخراً جامعاً للفروع والأصول»، (ت٨٨٥هـ)، ومن شروحه: المرآة للمصنف، وهو شرح لطيف جامع للفوائد المنقولة عن المتقدمين مع زوائد أبدعها خاطره الشَّريف؛ لذلك أقبل عليه العلماء تدريساً وتحشية وتعليقاً ومن الحواشي عليه: حاشية حامد أفندي، وحاشية مصطفى أفندي، وحاشية الطرطوسي، وحاشية سليمان الإزميري، وغيرها."]]},{"id":"u11_9","kind":"def","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ٩","segs":[["ctx","٥."],["matn","تحرير الأصول:"],["ctx","لكمال الدين محمد بن عبد الواحد الحنفي، الشهير بابن همام (ت٨٦١هـ)، جمع فيه علماً جماً بعبارات منقحة، وبالغ في الإيجاز حتى كاد يعد من الألغاز، ومن شروحه: التقرير والتحبير لمحمد بن محمد بن أمير الحاج، وتيسير التحرير لأمير بادشاه البخاري، واختصر التحرير ابن نجيم في لب الأصول."]]},{"id":"u11_10","kind":"def","label":"المسلك الثَّالث: طريقة المتأخرين · الفقرة ١٠","segs":[["ctx","٦."],["matn","مُسَلَّمُ الثُّبوت:"],["ctx","لمحبّ الدِّين بن عبد الشكور الحنفي (ت١١١٩هـ)، وهو أشهر كتب الأصول المتداولة، ومن شروحه: فواتح الرحموت لعبد العلي اللكنوي، وكشف المبهم لمحمد بشير الدين العثماني القنوجي، وشرح غلام رسول رضوي، ومفاتح البيوت لمحمد فيض الحسن اللكنوي."]]}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u12","title":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u12_1","kind":"text","label":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول · الفقرة ١","segs":[["ctx","إنَّ التَّأليف على هذه الطَّريقة لا يعتبر تأليفاً في الأصول المحضة، ولا في الفروع المحضة، وإنَّما هو مزيج من الأصول والفروع لبيان أثر الأصول في الفروع، وتمتاز هذه الطَّريقة بما فيها من ربط الصلة بين الأصول والفروع المختلفة، وتوضيح أنَّ الخلاف بين العلماء في الفروع الفقهية كان قائماً على اختلافهم في الأصول، وليس اتباعاً للهوى، وبيان لجهد العلماء السابقين في وضع هذه القواعد الأصولية التي بنيت عليها الفروع، وتنمية للملكة الفقهية للطلبة، وطريق للعلماء ليُلحقوا ما جد من المسائل بناء على هذه القواعد."]]},{"id":"u12_2","kind":"text","label":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول · الفقرة ٢","segs":[["ctx","والظَّاهر أنَّ عامَّة مَن ألَّف فيها من المالكية والشَّافعية والحنابلة، أرادوا فيها محاكاة طريقة الفقهاء من تفريع الفروع على الأصول، بحيث يذكر تحت كلّ أصل الفروع التي تخرج عليه، وهذا له شَبه بطريقة الفقهاء وإن وجد فيه نوع اختلاف."]]},{"id":"u12_3","kind":"def","label":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول · الفقرة ٣","segs":[["matn","وأبرز المؤلفات على هذه الطَّريقة هي:"],["ctx","١."],["matn","تأسيس الأدلة في اختلاف الأئمة:"],["ctx","لأبي زيد عبيد الله بن عمر الدبوسي الحنفي (ت٤٣٠هـ)، ويعتبر أول كتاب أشار إلى جمل يسيرة من القواعد الأصولية التي يرجع إليها في الخلاف بين أئمة المذهب الحنفي فيما بينهم وبين الإمام الشافعي، وبينهم وبين الإمام مالك."]]},{"id":"u12_4","kind":"def","label":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول · الفقرة ٤","segs":[["ctx","٢."],["matn","تخريج الفروع على الأصول:"],["ctx","لشهاب الدين محمود بن أحمد الزنجاني الشافعي(ت٦٥٦هـ)، وبيَّن فيه العلاقة بين الأصول والفروع في المذهبين الشافعي والحنفي، وبيان أن الاختلاف في الفروع قائم على الأسس التي بنيت عليها هذه الفروع."]]},{"id":"u12_5","kind":"def","label":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول · الفقرة ٥","segs":[["ctx","٣."],["matn","مفتاح الوصول إلى بناء الفروع على الأصول:"],["ctx","لأبي عبد الله محمد بن أحمد التلمساني (ت٧٧١هـ)، وقد بيَّن فيه أثر الأصول في الفروع على المذاهب الثلاثة المالكي والحنفي والشافعي."]]},{"id":"u12_6","kind":"def","label":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول · الفقرة ٦","segs":[["ctx","٤."],["matn","التَّمهيد في تخريج الفروع على الأصول:"],["ctx","لعبد الرَّحيم بن الحسن الإسنوي الشافعي (ت٧٢٧هـ)، وقد اقتصر فيه على تخريج الفروع على أصول مذهب الشافعي."]]},{"id":"u12_7","kind":"def","label":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول · الفقرة ٧","segs":[["ctx","٥."],["matn","القواعد والفوائد الأصولية:"],["ctx","لعلي بن محمد الحنبلي، المشهور بابن اللَّحام، (ت٨٠٣هـ)، واقتصر فيه على تخريج الفروع على أصول المذهب الحنبلي."]]},{"id":"u12_8","kind":"def","label":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول · الفقرة ٨","segs":[["ctx","٦."],["matn","الوصول إلى قواعد الأصول:"],["ctx","لمحمد بن عبد الله بن الخطيب التمرتاشي الحنفي، (١٠٠٤هـ)، ذكر فيه تخريج الفروع على أصول المذهب الحنفي مع الإشارة إلى مذهب الشافعي أحياناً."]]},{"id":"u12_9","kind":"def","label":"المسلك الرَّابع: طريقة تخريج الفروع على الأصول · الفقرة ٩","segs":[["ctx","٧."],["matn","أثر الاختلاف في القواعد الأصولية في اختلاف الفقهاء:"],["ctx","للدكتور مصطفى سعيد الخن، وقد جعل أسباب الخلاف بين الفقهاء ثمانية أسباب، ومثَّل لكل منها، ولم يستوعب كل القواعد الأصولية، ويذكر خلاف العلماء في القاعدة الأصولية وحججهم وردهم على بعضهم البعض ويكثر من الأمثلة من مختلف الأبواب الفقهية."]]}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u13","title":"المسلك الخامس: طريقة المعاصرين","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u13_1","kind":"text","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ١","segs":[["ctx","وهذه الطَّريقة ظهرت نتيجة ظهور المدرسة الإصلاحية في مصر فتأثر بها كثير من المعاصرين، وتقوم على الجمع والتَّلفيق في الأصول والفروع بين جميع المذاهب الفقهيّة دون اتباع منهج صحيح واضح؛ إذ نَقلت علم الأصول من العلميّة إلى الثَّقافية."]]},{"id":"u13_2","kind":"text","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ٢","segs":[["ctx","فالدَّارس على هذه الطَّريقة لا يتمكن من ضبطِ الأُصول ودركها، وإنَّما يصبح لديه ثقافةٌ عامّةٌ عنها، ويلاحظ النَّاظر في مؤلَّفات المعاصرين التَّخبط الشَّديد في تشييد الأُصول وبيان علاقةِ الفروع بها، فتراهم في كثير من الأحيان يجمعون بين المتناقضات؛ لذكرهم أُصولاً متناقضة بين المذاهب وفروعاً متعارضة، مما يُربك الدَّارس لها كثيراً."]]},{"id":"u13_3","kind":"text","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ٣","segs":[["ctx","ومعلومٌ أنَّ للعلماء مناهج ومدارس في العلم والتَّأليف والتَّدريس، فعسى هؤلاء المعاصرين أن يعودوا إلى منهج سادتنا العلماء في كتابة الأصول وتدريسه؛ لأنَّ أثر هذه الطَّريقة انعكس سلبياً على الدَّارسين في الجرأة على الفتوى، والاضطراب في المسائل، وعدم ربط الفروع بالأصول، والاستخفاف بالأئمة والفقهاء، وغير ذلك مما يطول ذكره."]]},{"id":"u13_4","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ٤","segs":[["matn","ومن المؤلفات على هذه الطَّريقة:"],["ctx","١."],["matn","علم أصول الفقه:"],["ctx","لعبد الوهاب خلَّاف."]]},{"id":"u13_5","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ٥","segs":[["ctx","٢."],["matn","أصول الفقه:"],["ctx","لمحمد الخضري بك."]]},{"id":"u13_6","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ٦","segs":[["ctx","٣."],["matn","أصول الفقه:"],["ctx","لمحمد أبو زهرة."]]},{"id":"u13_7","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ٧","segs":[["ctx","٤."],["matn","الواضح في أصول الفقه:"],["ctx","لمحمد حسين عبد الله."]]},{"id":"u13_8","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ٨","segs":[["ctx","٥."],["matn","أصول الفقه الإسلامي:"],["ctx","لبدران أبو العينين."]]},{"id":"u13_9","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ٩","segs":[["ctx","٦."],["matn","الوجيز في أصول الفقه:"],["ctx","للدكتور عبد الكريم زيدان."]]},{"id":"u13_10","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ١٠","segs":[["ctx","٧."],["matn","تيسير الأصول:"],["ctx","لحافظ ثناء الله الزَّاهدي."]]},{"id":"u13_11","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ١١","segs":[["ctx","٨."],["matn","الواضح في أصول الفقه للمبتدئين:"],["ctx","للدكتور محمد الأشقر."]]},{"id":"u13_12","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ١٢","segs":[["ctx","٩."],["matn","أصول الفقه الإسلامي:"],["ctx","للدكتور وهبة الزُّحيلي، وهو من أوسعها، ويشتمل على علم كثير."]]},{"id":"u13_13","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ١٣","segs":[["ctx","١٠."],["matn","أصول الفقه للمبتدئين:"],["ctx","لمحمد أنور بدخشاني، وهو نافع سهل للطلبة."]]},{"id":"u13_14","kind":"def","label":"المسلك الخامس: طريقة المعاصرين · الفقرة ١٤","segs":[["ctx","١١."],["matn","أصول الفقه الإسلامي:"],["ctx","لشاكر بك الحنبلي، وهو من أنفع كتب المعاصرين."]]}],"sup":"المبحث الثَّاني تاريخ علم الأصول وتطوّره وأهم المؤلفات فيه وطرق التأليف"},{"id":"u14","title":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u14_1","kind":"text","label":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره · الفقرة ١","segs":[["ctx","بعد أن تَعَرَّفنا في المبحثين السَّابقين على معنى أصول الفقه في اللغة والاصطلاح، والفرق بينه وبين الفقه، والنَّشأة التَّاريخية التي مرَّ بها، وطرق التَّأليف فيه، وأهم المؤلفات فيه، فإننا في هذه الوحدة سنتعرف على موضوعه واستمداده وفائدته وغايته ومصادره في المطالب الآتية:"]]}]},{"id":"u15","title":"المطلب الأول: موضوع علم أصول الفقه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u15_1","kind":"text","label":"المطلب الأول: موضوع علم أصول الفقه · الفقرة ١","segs":[["ctx","الدَّليل السَّمعي الكلي من حيث يوصل العلم بأحواله إلى قدرة إثبات الأحكام لأفعال المكلفين أخذاً من مشخصاته؛ إذ يبحث في الكتاب والسُّنة والإجماع والقياس من حيث استناد الأحكام الشَّرعية إليها، واستنباطها منها، وبيان ذلك أنَّ موضوعه:"]]},{"id":"u15_2","kind":"text","label":"المطلب الأول: موضوع علم أصول الفقه · الفقرة ٢","segs":[["ctx","١. الأدلة الشَّرعية من حيث ذاتها: أي من حيث كونها حجة قطعاً أو ظنَّاً، وغير حجة."]]},{"id":"u15_3","kind":"text","label":"المطلب الأول: موضوع علم أصول الفقه · الفقرة ٣","segs":[["ctx","٢. ما يثبت من الأدلة الشَّرعية من الأحكام: كالوجوب، والتَّحريم، والنَّدب، والكراهة، وغيرها."]]},{"id":"u15_4","kind":"text","label":"المطلب الأول: موضوع علم أصول الفقه · الفقرة ٤","segs":[["ctx","٣. طرق الاستنباط من الأدلة الشَّرعية: كالبحث عن دلالة العام، والأمر، والنَّهي، وغيرها."]]},{"id":"u15_5","kind":"text","label":"المطلب الأول: موضوع علم أصول الفقه · الفقرة ٥","segs":[["ctx","٤. المُستَنْبِط من الأدلة الشَّرعية: أي المجتهد."]]},{"id":"u15_6","kind":"text","label":"المطلب الأول: موضوع علم أصول الفقه · الفقرة ٦","segs":[["ctx","وبذلك يتبيَّن أنَّ موضوعه هو الأدلة الشَّرعية والأحكام."]]}],"sup":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره"},{"id":"u16","title":"المطلب الثَّاني: استمداد علم أصول الفقه ومصادره","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u16_1","kind":"text","label":"المطلب الثَّاني: استمداد علم أصول الفقه ومصادره · الفقرة ١","segs":[["ctx","يستمد علم الأصول من الكلام والعربية والأحكام الشرعية من جهة تصورها لا من جهة العلم بثبوتها، وبيان ذلك أن مصدره:"]]},{"id":"u16_2","kind":"def","label":"المطلب الثَّاني: استمداد علم أصول الفقه ومصادره · الفقرة ٢","segs":[["ctx","١."],["matn","علم الكلام:"],["ctx","وهو علم يتضمن الحجاج عن العقائد الإيمانية بالأدلة العقلية، ووجه استمداد الأصول منه كون معرفة الباري تعالى، وصدق المبلغ عنه متوقفاً عليه، وهما مبينان في علم الكلام، وغالب مباحث الحاكم مستمد من هذا العلم."]]},{"id":"u16_3","kind":"def","label":"المطلب الثَّاني: استمداد علم أصول الفقه ومصادره · الفقرة ٣","segs":[["ctx","٢."],["matn","علوم اللغة:"],["ctx","لأن فهم الكتاب والسنة متوقف على معرفتها؛ إذ هما عربيان، ووجوه الاستدلال من غالبها تعتمد على علوم اللغة من العموم والخصوص والتباين والترادف والحقيقة والمجاز."]]},{"id":"u16_4","kind":"def","label":"المطلب الثَّاني: استمداد علم أصول الفقه ومصادره · الفقرة ٤","segs":[["ctx","٣."],["matn","الأحكام الشرعية:"],["ctx","كالوجوب والتحريم من حيث تصورها؛ لأن مقصود الأصولي من الأصول إثبات الأحكام أو نفيها من حيث أنها مدلولة للأدلة الشرعية، ومستفادة منها كما أن مقصود الفقيه من الفقه إثباتها أو نفيها من حيث تعلقها بفعل المكلف، فالفقه يذكر في الأصول من حيث الجملة، فيذكر الواجب بما هو واجب، والمندوب بما هو مندوب؛ لأن هذا القدر مبين حقيقة الأصول."]]},{"id":"u16_5","kind":"text","label":"المطلب الثَّاني: استمداد علم أصول الفقه ومصادره · الفقرة ٥","segs":[["ctx","أما بالنِّسبة لقول السُّبكي: «إنَّ علم الأصول ليس علماً برأسه، بل هو أبعاض علوم جمعت من الكلام والفقه واللغة والحديث والجدل» ليس بحق، وَذِكر تفاصيل مباحث السُّنة: كالأحوال الرَّاجعة إلى متن الحديث أو طريقه، وعدالة الرَّاوي وجرحه في علم الأصول كما في علم الحديث لا يوجب استمداده إياها من علم الحديث، بل هي من مباحثه بالأصالة أيضاً، والجدال المذكور فيه ـ أعني كيفية الإيراد على الأقيسة الفقهية ذوات العلل الجعلية ـ حادث بحدوثه، فإن أفرد هذا الجدل فكالفرائض بالنِّسبة إلى الفقه."]]},{"id":"u16_6","kind":"text","label":"المطلب الثَّاني: استمداد علم أصول الفقه ومصادره · الفقرة ٦","segs":[["ctx","ومباحث الإجماع والقياس ظاهر كونها مختصة به، ولا يعلم علم من العلوم المدونة كفيل بها سواه، وأما الكلام فليس في الأصول منه إلا مسألة الحاكم، فإنَّها من العقائد الدِّينية، وما يتعلق بها من مباحث الحسن والقبح؛ لكون ذلك وسيلة إلى ما هو من العقائد الدِّينية فتلحق بها؛ لأنَّها من المُقدِّمات لهذا العلم لا منه، وأما الفقه فليس في الأصول منه إلا ما هو إيضاح لقواعده في صورة جزئية، فظهر أنَّ هذا العلم مستقل برأسه غير مستمد من علم مدون قبله."]]}],"sup":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره"},{"id":"u17","title":"المطلب الثَّالث: فائدة علم أصول الفقه وغايته","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u17_1","kind":"text","label":"المطلب الثَّالث: فائدة علم أصول الفقه وغايته · الفقرة ١","segs":[["ctx","١. القدرة على معرفة الأحكام الشَّرعيّة من أدلتها التي يترتَّب عليها الفوز بالسَّعادة الدُّنيوية والأخروية، فالمجتهد بهذا الفنّ يستنبط الأحكام الشَّرعية من أدلتها، والعالم الذي يبلغ درجة الاجتهاد يلزمه معرفة مأخذ المجتهدين؛ حتى إذا عُرضت عليه حادثةٌ لم يَنصّ عليها إمامُه، أمكنه معرفة حكمها تخريجاً على القواعد التي دُوِّنت في علم الأصول، وإذا روي عن الإمام رأيان أمكنه اختيار الرَّأي الذي ينطبق على قواعده، فكل عالم ومفت محتاج إلى هذا الفن، قال البابرتي: «بأنَّ التَّحقيق أنَّ غايتَه معرفة استنباط الأحكام»."]]},{"id":"u17_2","kind":"text","label":"المطلب الثَّالث: فائدة علم أصول الفقه وغايته · الفقرة ٢","segs":[["ctx","فلا بُدّ من علم الأصول لنستفيد الحكم الشَّرعي من الدَّليل التَّفصيلي؛ لأنَّ الدَّليل التَّفصيلي وحده لا يفيد، فلا بد من الدَّليل الإجمالي لِنصل إلى النَّتيجة، كما في قوله تعالى: ﴿وَأَقِيمُوا۟ ٱلصَّلَوٰةَ﴾ [يونس:٨٧] أمر بإقامتها، إلا أننا لا نعرف ما المراد بالأمر، هل هو الوجوب أو غيره."]]},{"id":"u17_3","kind":"text","label":"المطلب الثَّالث: فائدة علم أصول الفقه وغايته · الفقرة ٣","segs":[["ctx","وبسبب الجهل في الأصول ضلَّ كثير من النَّاس، فأحلُّوا الحرام، وحرَّموا الحلال، ظناً منهم بأنَّ معرفة الدَّليل التَّفصيلي كافية جهلاً وغروراً، فلو أنَّهم عرفوا أصول الفقه لأعرضوا عن كثير مما افتروا به على شرع الله تعالى بجهلهم، ولأمسكوا كثيراً من سهامهم التي يرمونها لأئمة هذا الدِّين بغرورهم."]]},{"id":"u17_4","kind":"text","label":"المطلب الثَّالث: فائدة علم أصول الفقه وغايته · الفقرة ٤","segs":[["ctx","٢. إنَّ للأصول أثراً في تكوين العقلية الفقهيّة القادرة على الدَّرس والفحص والاستنباط السَّليم، فبه نستطيع أن نفهم ما ورثناه من ثروة فقهية حافلة."]]},{"id":"u17_5","kind":"text","label":"المطلب الثَّالث: فائدة علم أصول الفقه وغايته · الفقرة ٥","segs":[["ctx","٣. إنَّه من أكثر وسائل حفظ الدِّين وصون أدلته وحججه من شُبه المتحلِّلين وتضليل الملحدين، فبواسطته نستطيع أن نردّ على قول بعض المعتزلة من أنَّه لا حجّة في أخبار الآحاد، وقول بعض النِّظامية والرَّافضة: إنَّ الإجماع والقياس ليسا من الأدلة الشَّرعيّة."]]},{"id":"u17_6","kind":"text","label":"المطلب الثَّالث: فائدة علم أصول الفقه وغايته · الفقرة ٦","segs":[["ctx","٤. إننا نتعرَّف بواسطة قواعد الأصول مدارك الفقهاء المجتهدين وطرق استنباطهم، ونتوصل بها إلى معرفة الأحكام الشَّرعيّة معرفةً دقيقةً مرتكزةً على الفهم واطمئنان النَّفس."]]}],"sup":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره"},{"id":"u18","title":"المطلب الرَّابع: حكم تعلم علم أصول الفقه","group":"الباب الأول مقدمات في أصول الفقه","units":[{"id":"u18_1","kind":"text","label":"المطلب الرَّابع: حكم تعلم علم أصول الفقه · الفقرة ١","segs":[["ctx","إنَّ تعلم علم الأصول كأغلب العلوم النَّافعة الشَّرعية وغير الشَّرعية واجبٌ على الكفاية، فإن قامَ به البعض سقط عن الباقين؛ لأنَّه لا بُدّ من حفظها وتوصيلها للمسلمين حتى لا يضيع هذا العلم الذي فيه حفظ علم الفقه، قال جل جلاله: ﴿إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ﴾ [الحجر:٩]، ومعلومٌ أنَّ حفظ الله تعالى لها يكون على أيدي المسلمين ممن يتخصّصون في تعلمه وتعليمه."]]},{"id":"u18_2","kind":"text","label":"المطلب الرَّابع: حكم تعلم علم أصول الفقه · الفقرة ٢","segs":[["ctx","وقال تعالى: ﴿۞ وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةً ۚ فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَآئِفَةٌ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ﴾ [التوبة:١٢٢]، فالآية دالَّة على أننا مأمورون بأن يتفرَّغَ منا البعض لتعلم أحكام الشَّريعة؛ ليعلِّموها للنَّاس، قال تعالى: ﴿۞ يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ۖ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ﴾ [المائدة:٦٧]، وقال تعالى: ﴿فَٱصْدَعْ بِمَا تُؤْمَرُ﴾ [الحجر:٩٤]، وقال ﷺ: «رحم الله امرأً سمع منّي حديثاً فحفظه حتى يُبَلِّغه غيره، فرب حامل فقه إلى مَن هو أفقه منه، ورب حامل فقه ليس بفقيه»."]]},{"id":"u18_3","kind":"text","label":"المطلب الرَّابع: حكم تعلم علم أصول الفقه · الفقرة ٣","segs":[["ctx","ولم يكن واجباً عينياً؛ لأنَّه ليس كلُّ فردٍ من المسلمين بحاجة إليه، بل يحتاج إليه أُولي العلم والفقه والذين نصبوا أنفسهم للفتوى أو نُصّبوا للقضاء والحكم بين النَّاس، فإذا قام به بعضهم فإنَّ سائر النَّاس يمكنهم الاستغناء عن دراسته."]]},{"id":"u18_4","kind":"text","label":"المطلب الرَّابع: حكم تعلم علم أصول الفقه · الفقرة ٤","segs":[["ctx","ويستحبُّ تَعَلُّمه للمسلمين كباقي العلوم وإن قام به بعضهم؛ لأنَّ تَعَلُّم الزَّائد على ما يُحتاج إليه إلى من يَحتاج إليه أفضل من نفل العبادة، قال تعالى: ﴿يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍ﴾ [المجادلة:١١]، وعن أبي هريرة رضي الله عنه قال ﷺ: «أفضل الصَّدقة أن يتعلّم المرء المسلم علماً، ثم يعلمه أخاه المسلم»."]]},{"id":"u18_5","kind":"text","label":"المطلب الرَّابع: حكم تعلم علم أصول الفقه · الفقرة ٥","segs":[["ctx","أمّا إن تَعَلَّمه للزِّينة والكمال فهو مباحٌ؛ لأنَّه كلما يزداد علم العالم يزداد زينته، ويحرم تَعَلُّمه إن كان ليباهي به العلماء، ويماري ـ أي يجادل ـ به السُّفهاء، ويأكل به أموال الأغنياء، ويستخدم به الفقراء؛ لأنَّه سبب يتوصل به إلى ما هو حرام، فيكون حراماً؛ فعن كعب بن مالك رضي الله عنه، قال ﷺ: «مَن طلب العلم؛ ليجاري به العلماء أو ليماري به السُّفهاء أو يصرف به وجوه النَّاس إليه أدخله الله النَّار»، وعن أبي هريرة رضي الله عنه، قال ﷺ: «مَن تعلَّم علماً مِمَّا يبتغى به وجه الله تعالى لا يتعلَّمه إلا لِيُصيب به عرضاً من الدُّنيا لم يجد عرف ـ ريح ـ الجنَّة يوم القيامة»."]]}],"sup":"المبحث الثَّالث موضوع علم الأصول واستمداده وفائدته وغايته ومصادره"},{"id":"u21","title":"أولاً: معنى الدَّليل","group":"الباب الثَّاني الكتاب","units":[{"id":"u21_1","kind":"def","label":"أولاً: معنى الدَّليل · الفقرة ١","segs":[["matn","أهداف الباب:"],["matn","فالدَّليل لغةً: ما يستدلُّ به"],["ctx","، وأيضاً:"],["matn","الدَّالّ"],["ctx","، وقيل: الدَّليل: هو"],["matn","المُرشد."]]},{"id":"u21_2","kind":"def","label":"أولاً: معنى الدَّليل · الفقرة ٢","segs":[["matn","واصطلاحاً: ما يمكن التَّوصل بصحيح النَّظر فيه إلى مطلوب خبري."]]},{"id":"u21_3","kind":"text","label":"أولاً: معنى الدَّليل · الفقرة ٣","segs":[["ctx","فإنَّ ﴿أَقِيمُوا۟ ٱلصَّلَوٰةَ﴾ [الأنعام:٧٢] دليل شرعي يمكن الوصول إلى وجوب الصَّلاة بعد النَّظر الصَّحيح فيه."]]},{"id":"u21_4","kind":"text","label":"أولاً: معنى الدَّليل · الفقرة ٤","segs":[["ctx","والمراد بصحيح النَّظر: أن يكون النَّظر فيه من الجِّهة التي من شأنها انتقال الذِّهْن بسببها إلى المطلوب، وهي وجه الدَّلالة."]]},{"id":"u21_5","kind":"text","label":"أولاً: معنى الدَّليل · الفقرة ٥","segs":[["ctx","والمراد بالنَّظر: الفكر، وهو حركة النَّفس في المعقولات، بخلاف حركتها في المحسوسات، فَتُسَمَّى تخيلاً."]]},{"id":"u21_6","kind":"text","label":"أولاً: معنى الدَّليل · الفقرة ٦","segs":[["ctx","والمراد بالمطلوب الخبري: ما يخبر به، وهو التَّصديق المحتمل للصِّدق والكذب، واحترز به عما يمكن التَّوصل بصحيح النَّظر فيه إلى مطلوب تصوري، فإنَّه لا يسمى دليلاً، بل يسمى حداً، بأن يتصور الحيوان النَّاطق حداً للإنسان."]]},{"id":"u21_7","kind":"def","label":"أولاً: معنى الدَّليل · الفقرة ٧","segs":[["matn","وأقسام الأدلة باعتبار قطعيتها وظنيتها:"],["ctx","١."],["matn","قطعية الثُّبوت:"],["ctx","وهي الأدلَّة التي وصلتنا من طريق يقطع بصحّته من غير زيادة ولا نقصان، ولا يكون ذلك إلا في المتواتر: كالقرآن الكريم، والسُّنة المتواترة، والسُّنة المشهورة، والإجماع المنقول نقلاً متواتراً."]]},{"id":"u21_8","kind":"def","label":"أولاً: معنى الدَّليل · الفقرة ٨","segs":[["ctx","٢."],["matn","قطعية الدَّلالة:"],["ctx","وهي الأدلة على المطلوب بما لا يقبل الاحتمال بوجه ما: أي لا يحتمل إلا معنى واحداً: كنصوص القرآن المفسَّرة أو المحكمة، والسُّنة المتواترة والآحاد التي مفهومها قطعي، مثل دلالة آيات الحدود: ﴿فَٱجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةً﴾ [النور:٤] على أنَّ عددَ الجَّلدات ثمانين، وآيات المواريث: ﴿يُوصِيكُمُ ٱللَّهُ فِىٓ أَوْلَٰدِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ﴾ [النساء:١١]، وآيات الكفَّارات: ﴿ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم﴾ [المجادلة:٢]."]]},{"id":"u21_9","kind":"def","label":"أولاً: معنى الدَّليل · الفقرة ٩","segs":[["ctx","٣."],["matn","ظنيّة الثُّبوت:"],["ctx","وهي الأدلة التي من طريق لا يقطع بصحته؛ لاحتمال كذب الرَّاوي، أو عدم ضبطه، أو غير ذلك: كسُنَّة الآحاد."]]},{"id":"u21_10","kind":"def","label":"أولاً: معنى الدَّليل · الفقرة ١٠","segs":[["ctx","٤."],["matn","ظنيّة الدَّلالة:"],["ctx","وهي الأدلّة على المطلوب بما يقبل الاحتمال بوجه ما: أي يحتمل أكثر من معنى واحد: كالآيات المؤولة، والسُّنة التي مفهومها ظني، مثل اللفظ المشترك في قوله تعالى: ﴿وَٱلْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٍ﴾ [البقرة:٢٢٨]، فلفظ القرء في اللغة مشترك بين المعنيين: الطُّهر والحيض، فيحتمل أن يراد ثلاثة أطهار أو ثلاث حيضات، وتكون الدَّلالة على أحد المعنيين ظنية."]]},{"id":"u21_11","kind":"def","label":"أولاً: معنى الدَّليل · الفقرة ١١","segs":[["matn","والأحكام التي تفيدها هذه الأدلَّة السَّميعة باعتبار ظنيتها وقطعيتها هي:"],["ctx","١. قطعي الثُّبوت والدَّلالة يثبت به الافتراض والتَّحريم."]]},{"id":"u21_12","kind":"text","label":"أولاً: معنى الدَّليل · الفقرة ١٢","segs":[["ctx","٢. قطعي الثُّبوت وظني الدَّلالة أو ظني الثُّبوت وقطعي الدَّلالة يثبت به الإيجاب وكراهة التَّحريم."]]},{"id":"u21_13","kind":"text","label":"أولاً: معنى الدَّليل · الفقرة ١٣","segs":[["ctx","٣. ظني الثُّبوت وظني الدَّلالة يثبت به السُّنية والاستحباب."]]}],"sup":"المبحث التَّمهدي"},{"id":"u22","title":"ثانياً: تعريف القرآن الكريم","group":"الباب الثَّاني الكتاب","units":[{"id":"u22_1","kind":"text","label":"ثانياً: تعريف القرآن الكريم · الفقرة ١","segs":[["ctx","إنَّ القرآن الكريم هو المصدر الأول لاستقاء الأحكام الشَّرعية."]]},{"id":"u22_2","kind":"text","label":"ثانياً: تعريف القرآن الكريم · الفقرة ٢","segs":[["ctx","وقبل الشروع في مباحث القرآن الكريم نعرض لمعنى أشهر أسمائه في اللغة وهي: القرآن، والكتاب، والذِّكر، والفرقان، والمصحف:"]]},{"id":"u22_3","kind":"def","label":"ثانياً: تعريف القرآن الكريم · الفقرة ٣","segs":[["matn","القرآن:"],["ctx","مصدر قرأ، فقرأت الكتاب قراءةً وقُرآناً، ومنه سُمِّيَ القرآن، قال ابن الأثير: «الأصل في هذه اللفظة: الجمع، وكل شيء جمعته فقد قرأته، وسُمِّي القرآن؛ لأنَّه جمع القَصص، والأمر، والنَّهي، والوعد، والوعيد، والآيات والسُّور بعضها إلى بعض، وهو مصدر كالغُفران والكُفران»، وقد ورد لفظ القرآن في آيات عديدة منها: ﴿أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ﴾ [النساء:٨٢]، ﴿وَإِذَا قُرِئَ ٱلْقُرْءَانُ﴾ [الأعراف:٢٠٤]."]]},{"id":"u22_4","kind":"def","label":"ثانياً: تعريف القرآن الكريم · الفقرة ٤","segs":[["ctx","ويُسَمَّى أيضاً:"],["matn","الكتاب"],["ctx","، وهو مصدر بمعنى المكتوب: أي كُلّ ما يكتب، ويطلق على الكتاب المُنَزَّل، وَكَتَبَ بمعنى جمع وضم كما في قرأ، ومن الآيات التي ورد فيها: ﴿ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ ۛ فِيهِ﴾ [البقرة:٢]، ﴿هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَٰبَ﴾ [آل عمران:٧]."]]},{"id":"u22_5","kind":"def","label":"ثانياً: تعريف القرآن الكريم · الفقرة ٥","segs":[["ctx","ويُسمّى أيضاً:"],["matn","الذِّكر"],["ctx","، وهو مصدر، تقول: ذكرت، أذكر، ذكراً، ووجه تسمية القرآن ذكراً؛ لما فيه من المواعظ والزَّواجر والموقظات التي تُذَكِّر قارئه، وتوقظ قلبه، وتصله بالله، وتزجره عن المعاصي، ومن الآيات التي ورد فيها: ﴿إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ﴾ [الحجر:٩]، ﴿وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ﴾ [النحل:٤٤]."]]},{"id":"u22_6","kind":"def","label":"ثانياً: تعريف القرآن الكريم · الفقرة ٦","segs":[["ctx","ويسمّى أيضاً:"],["matn","الفرقان"],["ctx","، وهو مصدر، تقول: فرق، يفرق، فرقاً، وفرقاناً، وسُمِّيَ القرآن فرقاناً؛ لأنَّ الله فرَّق به بين الحق والباطل، والهدى والضَّلال، والإيمان والكفر، والمؤمن والكافر، قال تعالى: ﴿تَبَارَكَ ٱلَّذِى نَزَّلَ ٱلْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَٰلَمِينَ نَذِيرًا﴾ [الفرقان:١]."]]},{"id":"u22_7","kind":"def","label":"ثانياً: تعريف القرآن الكريم · الفقرة ٧","segs":[["ctx","ويسمّى أيضاً:"],["matn","المصحف"],["ctx","، والمصحف حقيقته مجمع الصُّحف، وسمّوا القرآن مصحفاً؛ لأنَّه كان متفرقاً في صحائف أولاً فجمعوه بين الدَّفتين وسمّوه به، ويجوز أن يسمى غيره بهذا الاسم إذا وجد هذا المعنى."]]},{"id":"u22_8","kind":"def","label":"ثانياً: تعريف القرآن الكريم · الفقرة ٨","segs":[["matn","واصطلاحاً، له تعاريف عديدة يتحقق المقصود بها:"],["ctx","١."],["matn","المُنزل على رسول الله ﷺ، المكتوب في المصاحف، المنقول عن النَّبيّ ﷺ، نقلاً متواتراً بلا شُبهة."]]},{"id":"u22_9","kind":"text","label":"ثانياً: تعريف القرآن الكريم · الفقرة ٩","segs":[["ctx","واحترز بقوله: المُنزل؛ عن غير الكتب السَّماوية، وعن الوحي الذي ليس بمتلو؛ لأنَّ المراد من المُنزل ما أنزل نظمه ومعناه، والوحي الذي ليس بمتلو لم ينزل إلا معناه."]]},{"id":"u22_10","kind":"text","label":"ثانياً: تعريف القرآن الكريم · الفقرة ١٠","segs":[["ctx","وبقوله: على رسول الله ﷺ؛ عما أُنزل على غيره من الأنبياء عليهم السَّلام من التَّوراة والإنجيل والزَّبور أو نحوها."]]},{"id":"u22_11","kind":"text","label":"ثانياً: تعريف القرآن الكريم · الفقرة ١١","segs":[["ctx","وبقوله: المكتوب في المصاحف؛ عما نُسِخت تلاوته وبقيت أحكامه: كآية الرَّجم، فعن عمر رضي الله عنه: «لولا أن يقول النَّاس زاد عمر في كتاب الله لكتبت آية الرَّجم بيدي»."]]},{"id":"u22_12","kind":"text","label":"ثانياً: تعريف القرآن الكريم · الفقرة ١٢","segs":[["ctx","وبقوله: المنقول عنه نقلاً متواتراً؛ عمّا اختصّ بمثل مصحف أُبيّ وغيره مما نقل بطريق الآحاد، نحو قوله: فَعِدَّة من أيام أخر متتابعات."]]},{"id":"u22_13","kind":"text","label":"ثانياً: تعريف القرآن الكريم · الفقرة ١٣","segs":[["ctx","وبقوله: بلا شبهة؛ عما اختص بمثل مصحف ابن مسعود رضي الله عنه مما نقل بطريق الشُّهرة، وهذا على قول الجصَّاص ظاهر، فإنَّه جعل المشهور أحد قسمي المتواتر، وعلى قول غيره يكون قوله: نقلاً متواتراً، احترازاً عن المشهور والآحاد، وقوله: بلا شبهة؛ تأكيداً، وهذا الموضع صالح للتأكيد؛ لقوة شبه المشهور بالمتواتر."]]},{"id":"u22_14","kind":"def","label":"ثانياً: تعريف القرآن الكريم · الفقرة ١٤","segs":[["ctx","٢."],["matn","ما نقل إلينا بين دفتي المصاحف تواتراً."]]},{"id":"u22_15","kind":"text","label":"ثانياً: تعريف القرآن الكريم · الفقرة ١٥","segs":[["ctx","فخرج سائر الكتب والأحاديث الإلهية والنَّبوية والقراءة الشَّاذة."]]},{"id":"u22_16","kind":"def","label":"ثانياً: تعريف القرآن الكريم · الفقرة ١٦","segs":[["ctx","٣."],["matn","النَّظم المُنزل على رسولنا محمد ﷺ المنقول عنه تواتراً."]]},{"id":"u22_17","kind":"text","label":"ثانياً: تعريف القرآن الكريم · الفقرة ١٧","segs":[["ctx","والنَّظم: هو الموضوع لمعنى مفرداً كان أو مركباً."]]}],"sup":"المبحث التَّمهدي"},{"id":"u23","title":"ثالثاً: الفرق بين القرآن والحديث القدسي","group":"الباب الثَّاني الكتاب","units":[{"id":"u23_1","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ١","segs":[["ctx","وَيُفَرَّق بين القرآن والحديث القدسي بما يلي:"]]},{"id":"u23_2","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ٢","segs":[["ctx","١. إنَّ القرآن نزل به جبريل عليه السلام إلى النَّبي ﷺ لفظاً ومعنى، أما الحديث القدسي فقد نزل روح القدس ـ وهو جبريل عليه السلام ـ إلى النَّبي ﷺ بمعناه؛ ولهذا سُمِّي قدسياً، وصياغة ألفاظه عن الله تعالى من رسول الله ﷺ؛ لذا سُمِّي حديثاً."]]},{"id":"u23_3","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ٣","segs":[["ctx","٢. إنَّه نُقل القرآن تواتراً، وأما الحديث القدسي فليس متواتر."]]},{"id":"u23_4","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ٤","segs":[["ctx","٣. إنَّه تصحّ الصَّلاة بالقرآن، ولا تصح بالحديث القدسي."]]},{"id":"u23_5","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ٥","segs":[["ctx","٤. إنَّ القرآن مُعجز، بخلاف الحديث القدسي."]]},{"id":"u23_6","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ٦","segs":[["ctx","٥. إنَّه لا يجوز ترجمة القرآن نصاً، وفي الحديث القدسي يجوز."]]},{"id":"u23_7","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ٧","segs":[["ctx","٦. إنَّ القرآن لا يمس إلا على طهارة، بخلاف القدسي."]]},{"id":"u23_8","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ٨","segs":[["ctx","٧. إنَّ القرآن يتعبّد بتلاوته، ولا يتعبّد بألفاظ الحديث القدسي."]]},{"id":"u23_9","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ٩","segs":[["ctx","٨. إنَّ جاحد القرآن كافر، بخلاف جحود القدسي."]]},{"id":"u23_10","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ١٠","segs":[["ctx","٩. إنَّه لا يجوز رواية القرآن بالمعنى، وفي القدسي يجوز على الرَّاجح."]]},{"id":"u23_11","kind":"text","label":"ثالثاً: الفرق بين القرآن والحديث القدسي · الفقرة ١١","segs":[["ctx","١٠. إنَّ القرآن مُقَسَّم إلى سور وآيات وأجزاء وأحزاب، ولا توجد هذه الأمور في القدسي."]]}],"sup":"المبحث التَّمهدي"},{"id":"u24","title":"رابعاً: إنَّ القرآن هو النَّظم والمعنى جميعاً","group":"الباب الثَّاني الكتاب","units":[{"id":"u24_1","kind":"text","label":"رابعاً: إنَّ القرآن هو النَّظم والمعنى جميعاً · الفقرة ١","segs":[["ctx","أراد بالنَّظم: العبارات، وبالمعنى: مدلولات العبارات، وَعَدَلَ النَّسفي عن ذِكر اللفظ الذي معناه الرمي بدل النَّظم رعاية للأدب؛ لأنَّ النَّظم حقيقةً: جمع اللآلئ في السِّلك بحسن التَّرتيب، وتعظيماً لعبارات القرآن."]]},{"id":"u24_2","kind":"text","label":"رابعاً: إنَّ القرآن هو النَّظم والمعنى جميعاً · الفقرة ٢","segs":[["ctx","وفي ذكر الحنفية بأنَّ القرآن نظمٌ ومعنى ردٌّ على مَن زعم أنَّ القرآن هو المعنى دون النَّظم عند أبي حنيفة رضي الله عنه بدليل جواز القراءة بالفارسية عنده في الصَّلاة بغير عذر، مع أنَّ قراءة القرآن في الصَّلاة فرضٌ مقطوعٌ به، ويجاب عن هذا الدَّليل:"]]},{"id":"u24_3","kind":"text","label":"رابعاً: إنَّ القرآن هو النَّظم والمعنى جميعاً · الفقرة ٣","segs":[["ctx","١. إنَّه لم يَجعل النَّظم ركناً لازماً؛ لأنَّه قال: مبنى النَّظم على التَّوسعة؛ لأنَّه غير مقصود خصوصاً في حالة الصَّلاة إذ هي حالة المناجاة، وكذا مبنى فرضية القراءة في الصَّلاة على التَّيسير قال تعالى: ﴿فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ ۚ﴾ [المزمل:٢٠]؛ ولهذا تسقط القراءة عن المقتدي بتحمّل الإمام عند الحنفية، وبخوف فوت الركعة عند غير الحنفية بخلاف سائر الأركان."]]},{"id":"u24_4","kind":"text","label":"رابعاً: إنَّ القرآن هو النَّظم والمعنى جميعاً · الفقرة ٤","segs":[["ctx","٢. إنَّه صحَّ رجوع الإمام أبي حنيفة رضي الله عنه عن جواز القراءة بالفارسية مع القدرة على العربية، ورواه نوح بن أبي مريم، وهو اختيار القاضي الإمام أبي زيد وعامَّة المحققين وعليه الفتوى."]]}],"sup":"المبحث التَّمهدي"},{"id":"u25","title":"خامساً: هل البسملة آية من القرآن؟","group":"الباب الثَّاني الكتاب","units":[{"id":"u25_1","kind":"text","label":"خامساً: هل البسملة آية من القرآن؟ · الفقرة ١","segs":[["ctx","الصَّحيح أنَّها آية فذَّة من القرآن، ليست من الفاتحة، ولا من سورة أخرى، أُنزلت لبيان مبادئها وخواتيها؛ للفصل بينها، وهو مختار متأخري الحنفية، ولهذا كُره للجنب قراءة التَّسمية على قصد قراءة القرآن، وإنَّما لم يتأدّ فرض القراءة بها عند أبي حنيفة؛ لاختلاف العلماء في كونها آيةً منه، وأدنى درجات الاختلاف المعتبر إيراث الشُّبهة، وما كان فرضاً لا يتأدّى بما فيه شبهة."]]}],"sup":"المبحث التَّمهدي"},{"id":"u26","title":"سادساً: حكم الاحتجاج بالقراءة الشَّاذة في الأحكام","group":"الباب الثَّاني الكتاب","units":[{"id":"u26_1","kind":"text","label":"سادساً: حكم الاحتجاج بالقراءة الشَّاذة في الأحكام · الفقرة ١","segs":[["ctx","الشَّاذ لُغةً: المنفرد، وفي الاصطلاح: عكس المتواتر، والمتواتر قراءة ساعدها خطّ المصحف، مع صحّة النَّقل فيها، ومجيئها على الفصيح من لغة العرب، قال الشَّيخ أبو شامة: «فمتى اختل أحد هذه الأركان الثَّلاثة أطلق على تلك القراءة أنَّها شاذة»."]]},{"id":"u26_2","kind":"text","label":"سادساً: حكم الاحتجاج بالقراءة الشَّاذة في الأحكام · الفقرة ٢","segs":[["ctx","ويشترط الشُّهرة في القراءة الشَّاذة عند السَّلف للعمل بها؛ ولهذا لم يعملوا بقراءة أُبي بن كعب رضي الله عنه: (فَعِدَّة من أيام أخر متتابعة)؛ لأنَّها قراءة شاذة غير مشهورة، وبمثلها لا يثبت الزِّيادة على النَّص، فأما قراءة ابن مسعود رضي الله عنه فقد كانت مشهورة في زمن أبي حنيفة، حتى كان الأعمش يقرأ ختماً على حرف ابن مسعود رضي الله عنه، وختماً من مصحف عثمان رضي الله عنه، والزِّيادة عندنا تثبت بالخبر المشهور."]]},{"id":"u26_3","kind":"text","label":"سادساً: حكم الاحتجاج بالقراءة الشَّاذة في الأحكام · الفقرة ٣","segs":[["ctx","قال الجصَّاص: «لم يكن حرف عبد الله بن مسعود رضي الله عنه عندهم وارداً من طريق الآحاد؛ لأنَّ أهل الكوفة في ذلك الوقت كانوا يقرءون بحرف عبد الله رضي الله عنه كما يقرءون بحرف زيد، وقال إبراهيم النَّخعي: كانوا يعلمونا ونحن في الكتّاب حرف عبد الله كما يعلمونا حرف زيد، وكان سعيد بن جبير رضي الله عنه يصلِّي بهم في شهر رمضان فيقرأ ليلة بحرف عبد الله، وليلة بحرف زيد، فإنَّما أثبتوا هذه الزِّيادة بحرف عبد الله؛ لاستفاضته وشهرته عندهم في ذلك العصر، وإن كان إنَّما نقل إلينا الآن من طريق الآحاد؛ لأنَّ النَّاس تركوا القراءة به، واقتصروا على غيره، وإنَّما كلامنا على أصول القوم، وهذا صحيح على أصلهم»."]]},{"id":"u26_4","kind":"text","label":"سادساً: حكم الاحتجاج بالقراءة الشَّاذة في الأحكام · الفقرة ٤","segs":[["ctx","وهذا الكلام من الجصَّاص في غاية الدِّقة بأنَّ المعتبر حال الدَّليل في وقت المجتهد، لا حال من جاء بعده لا سيما في الأزمنة المتأخرة، ففي زمن أبي حنيفة كانت قراءة ابن مسعود رضي الله عنه مشهورةً ومعمولاً بها، فصحَّ الاعتماد عليها من قِبَلِ أبي حنيفة في استخراج الأحكام كما في كفَّارة اليمين، حيث اشترط التَّتابع في الصِّيام، وكان لقراءة ابن مسعود رضي الله عنه أثراً ظاهراً في المذهب في العديد من المسائل، وحجتهم بالاعتماد على هذه القراءة صحيحة على هذا الأصل، فليتنبه."]]}],"sup":"المبحث التَّمهدي"},{"id":"u30","title":"المبحث الأول الخاصّ","group":"الباب الثَّاني الكتاب","units":[{"id":"u30_1","kind":"def","label":"المبحث الأول الخاصّ · الفقرة ١","segs":[["matn","وهو ما وُضِع لمعنى واحد معلوم على الانفراد، جنساً:"],["ctx","كإنسان،"],["matn","أَو نوعاً:"],["ctx","كرجل،"],["matn","أَو عيناً:"],["ctx","كزيد، أو لفظ وضع لمعنى واحد منفرد عن ملاحظة الأفراد، سواء كانت واحداً حقيقاً كالأعلام الشَّخصية كزيد، أو اعتبارياً كالواحد بالجنس كإنسان، وبالنَّوع كرجل وثلاثة."]]},{"id":"u30_2","kind":"def","label":"المبحث الأول الخاصّ · الفقرة ٢","segs":[["matn","وحكمُ الخاصّ:"],["matn","تناولُ المخصوص قطعاً بلا احتمال بيان"],["ctx",": أي لا يحتمل البيان؛ لكونه بيِّناً في نفسه."]]},{"id":"u30_3","kind":"text","label":"المبحث الأول الخاصّ · الفقرة ٣","segs":[["ctx","فمثلاً: الرُّكوع والسُّجود في قوله تعالى: ﴿ٱرْكَعُوا۟ وَٱسْجُدُوا۟﴾ [الحج:٧٧] خاصّ، فهو بيِّن في نفسه فلا يحتاج إلى البيان؛ لأنَّ الرُّكوع بمعنى الانحاء عن القيام، والسُّجود مماسسة الجبهة الأرض، فيكون كلٌّ من الإنحاء ومماسّة الجبهة هو الفرض، ولا يلحقه البيان من حديث المسيء صلاته، فلا تكون الطَّمأنينة فرضاً فيهما، وإنَّما واجب؛ لعدم احتمال الخاصّ البيان؛ لأنَّه بَيِّنٌ في نفسه."]]}]},{"id":"u32","title":"المطلب الأول: إفادة الأمر، ولها ثلاثة جوانب","group":"الباب الثَّاني الكتاب","units":[{"id":"u32_1","kind":"def","label":"المطلب الأول: إفادة الأمر، ولها ثلاثة جوانب · الفقرة ١","segs":[["matn","والخاصُّ على نوعين:"],["ctx","أ."],["matn","يختصُّ بصيغة لازمة فلا يكون الفعل موجباً"],["ctx","؛ لأنَّ الوجوب بالأمر، والأمر مختصّ بصيغته، وهي افعل، فيستفاد الإيجاب منها."]]},{"id":"u32_2","kind":"def","label":"المطلب الأول: إفادة الأمر، ولها ثلاثة جوانب · الفقرة ٢","segs":[["matn","ب. الأمرُ المطلق يفيد الوجوب بعد الحظر أو قبله"],["ctx","؛ لأنَّ المقتضي للوجوب، وهو صيغةُ الأمر، وهي قائمةٌ في الحالين: أي ما قبل الحظر وبعده."]]},{"id":"u32_3","kind":"text","label":"المطلب الأول: إفادة الأمر، ولها ثلاثة جوانب · الفقرة ٣","segs":[["ctx","وبعض الآيات والأحاديث التي جاءت للإباحةِ بعد الحظر، فلوجود دليل آخر أفاد ذلك غير الصِّيغة."]]},{"id":"u32_4","kind":"def","label":"المطلب الأول: إفادة الأمر، ولها ثلاثة جوانب · الفقرة ٤","segs":[["matn","جـ. الأمرُ المطلق لا يقتضي تكرار المأمور به"],["ctx","، وهو أن يفعلَه ثمّ يعود إليه،"],["matn","ولا"],["ctx","يكون التِّكرار محتملاً من محتملات الأمر؛ لأنَّ مدلولَ صيغة الأمر طلب حقيقة الفعل، والمرّةُ والتِّكرارُ بالنِّسبة إلى حقيقة الفعل أمرٌ خارجي، ويتحقَّق الخروجُ عن عهدة المأمور به بالمرَّة بحصول حقيقة الفعل، لا أنَّ المرَّة والتِّكرار من مدلولِ صيغة الأمر، وإنَّما يحمل المأمور به على التِّكرار؛ لوجود قرائن أُخر أفادت هذا الحكم."]]},{"id":"u32_5","kind":"def","label":"المطلب الأول: إفادة الأمر، ولها ثلاثة جوانب · الفقرة ٥","segs":[["ctx","ولا يفيد الأمر التِّكرار سواء"],["matn","تعلّق"],["ctx","الأمر"],["matn","بشرط"],["ctx","نحو: قوله تعالى: ﴿وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْ﴾ [المائدة: ٦]،"],["matn","أو اختص بوصف"],["ctx","نحو: قوله تعالى: ﴿ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ﴾ [النور: ٢]."]]},{"id":"u32_6","kind":"text","label":"المطلب الأول: إفادة الأمر، ولها ثلاثة جوانب · الفقرة ٦","segs":[["ctx","وليس سبب تكرُّر العبادات هو أنَّ الأمر يقتضي التِّكرار، وإنَّما لتكرّر أسبابها عند الجمهور، مثل تكرار سبب وجوب الصَّلاة وهو الوقت سببٌ لتكرُّر الصَّلاة، وقال بعضٌ: بتكرُّرِ المأمورات كالصيام بتكرُّر الأَوامر؛ بأن يتحقَّق الأمر مرّةً بعد مرّة، بحصول الأمر بالصِّيام كلِّ سَنة في رمضان."]]},{"id":"u32_7","kind":"def","label":"المطلب الأول: إفادة الأمر، ولها ثلاثة جوانب · الفقرة ٧","segs":[["ctx","وإذا لم يقتض الأمر التِّكرار ولا يحتمله،"],["matn","فيقع"],["ctx","الأمر فيما للمأمور به أفراد"],["matn","على"],["ctx","أَقلّ جنس المأمور، وهو الفرد الحقيقي: كالطَّلقة الواحدة،"],["matn","ويحتمل"],["ctx","كلّ الجنس باعتبار معنى الفرديّة: كالطَّلاقات الثَّلاث، لا باعتبار معنى العدد، بل من حيث إنَّه فردٌ، فصار من حيث هو جنساً واحداً، وإن كان له أَفرادٌ، وهذا في قول الرَّجل لزوجته: طلِّقي نفسك، فيمكن للزَّوجة أن توقع على نفسها واحداً أو ثلاثاً إن نَوَى الرَّجل ذلك."]]}],"sup":"المبحث الأول الخاصّ"},{"id":"u33","title":"المطلب الثَّاني: حكم الأمر على صورتين","group":"الباب الثَّاني الكتاب","units":[{"id":"u33_1","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ١","segs":[["matn","أ. أداءٌ: وهو إقامةُ الواجب"],["ctx",": أي إخراجُه إلى الوجود على حسب الصُّورة التي وجبت بالأمر ابتداءً، أو تسليم عين ما عُلِمَ ثبوتُه من الأمر، وهو أفعال الجوارح في الوقت المعيّن له، والتَّسليم هو إخراجُه من العدم إلى الوجودِ كالصَّلاة، فإنَّها وقت دخول الوقت معدومة، فأداؤها فيه إخراجُها من العدم إلى الوجود."]]},{"id":"u33_2","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ٢","segs":[["matn","ب. قضاءٌ: وهو تسليم"],["ctx","مثل الواجب بالسَّبب، وهو ما في الذمة، وإنَّما ثبت بنفس الوجوب بالأمر لأفعال الجوارح في الأداء له لا بالسَّبب، أو فِعْل المأمور به بعد وقته، ففعل صلاة الظهر مثلاً في وقتها أداء، وفِعلُها بعد مضي وقتها قضاء."]]},{"id":"u33_3","kind":"text","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ٣","segs":[["ctx","وأمَّا الإعادة فهي فِعلُ ما فُعِلَ أوّلاً مع نوع من الخلل ثانياً إن كانت واجبة؛ بأن وقع الأَوّل فاسداً بأن تركَ القراءة مثلاً أو ركناً من أركانها كركوع وسجود ونحو ذلك."]]},{"id":"u33_4","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ٤","segs":[["matn","وللأداء والقضاء الأحكام الآتية:"],["ctx","١. يُطلق كلُّ واحدٍ منهما على الآخر، فيتبادلان الأداء والقضاء، فيُقال هذا مكان هذا"],["matn","مجازاً"],["ctx","، ونحتاج إلى قرينةٍ إن أُطلق أحدُهما على الآخر؛ لتمييزه، كما يُقال: أدَّى ما عليه من الدَّين، فقوله: من الدَّين؛ قرينةٌ يُفهمُ منها القضاء؛ لأنَّ أداءَ حقيقة الدَّين مُحالٌ؛ لأنَّ كونه ديناً يعني حقّ ثابت في الذِّمّة، فيكون أداؤه قضاءً له، والمعنى الجامعُ في كلّ من الأداء والقضاء هو التَّسليم؛ لذلك صَحَّ إطلاق كلّ واحدٍ منهما على الآخر."]]},{"id":"u33_5","kind":"text","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ٥","segs":[["ctx","٢. يؤدّي كلٌّ من الأداء والقضاء بنية الآخر منهما، فيؤدي القضاء بنية الأداء والأداء بنية القضاء، ونحتاج إلى القرينة التي تبيّن أنَّ هذا أداء مثلاً على رغم أنَّني نويته قضاء، كما يُقال: نويت أن أؤدي ظهر الأمس، أو نويت أن أقضي ظهر اليوم."]]},{"id":"u33_6","kind":"text","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ٦","segs":[["ctx","٣. يجب الأداءُ والقضاءُ بسببٍ واحدٍ، وهو الأمرُ الذي وَجَبَ به الأداء عند الجمهور؛ لأنَّ المستَحَقَّ ـ وهي الصَّلاة مثلاً ـ لا يسقط عن المستَحَّقّ عليه ـ وهو المكلَّف ـ إلا بإسقاط مَن له الحقّ ـ وهو الله تعالى ـ أو بتسليم المستَحقّ، ولم يوجد الإسقاط من الله تعالى، ولا التَّسليم للصَّلاة من المكلَّف، فبقيت الصَّلاة ديناً عليه، ويُمكنه أداؤها في وقتٍ آخر؛ لعجزه عن أدائها في نفس الوقت؛ لخروج الوقت، فيفوته فضل الوقت."]]},{"id":"u33_7","kind":"text","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ٧","segs":[["ctx","ولا يكون القضاء بسبب جديد كما قال العراقيون من الحنفية، وهو النُّصوص الواردة في القضاء، ففي الصَّوم وجب القضاء بقوله تعالى: ﴿فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَ﴾ [البقرة: ١٨٤]، وفي الصَّلاة وجب بقوله ﷺ: «مَن نَسِيَ صلاةً فليصلها إذا ذكرها»، و«إذا رقد أحدُكم عن الصَّلاة أو غَفِلَ عنها فليصلها إذا ذكرها»؛ لأنَّ هذه النُّصوص في القضاء لطلب تفريغ الذمَّة عمَّا وَجَبَ بالأمر وتعريفِ أنَّ الواجبَ لم يسقط."]]},{"id":"u33_8","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ٨","segs":[["matn","٤. أَنواع الأداء ثلاثةٌ:"]]},{"id":"u33_9","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ٩","segs":[["matn","أـ أداء كامل: وهو ما يُؤَدَّى كما شُرِع"],["ctx",": أَي مع توفير حقّه من الواجبات والسُّنن والآداب: كأداء الصَّلاة في الجماعة من المكتوبات، والوتر في رمضان."]]},{"id":"u33_10","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ١٠","segs":[["matn","ب ـ أداء قاصر: وهو النَّاقص عن صفته"],["ctx","التي قدَّمناها، فيتمكن النُّقصان في وصفه: كالصَّلاة منفرداً ـ أي أداء كلها أو بعضها منفرداً كالمسبوق ـ، فإنَّه أداءٌ محضٌ فيه قصور؛ لعدم الوصف المرغوب فيه، وهو الجماعة."]]},{"id":"u33_11","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ١١","segs":[["matn","ج ـ أداء شبيه بالقضاء"],["ctx",": كفعل اللاحق، وهو الذي فاته بعض الصَّلاة بعد إدراك بعضها بعد فراغ الإمام من الصَّلاة، ففعلُهُ باعتبار الوقت أداءٌ، وباعتبار أنَّه يتدارك ما التزم أداؤه مع الإمام قضاءٌ، فهو أَداءٌ شبيهٌ بالقضاء، فسُمِّي شبيهاً بالقضاء؛ لأنَّه أداءٌ لبقاء الوقت وشبيهٌ بالقضاء؛ لأنَّ مَن أدرك أوَّل الصَّلاة قد التزم الصَّلاة كاملة مع الإمام وقد فات بعض أفعال الصَّلاة بسبب النَّوم مثلاً، وكان التزم أداءها كاملةً مع الإمام، ففعل بقية أفعال الصَّلاة بعد الإمام شبيهٌ بالقضاء."]]},{"id":"u33_12","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ١٢","segs":[["matn","٥. أنواع القضاء ثلاثة:"]]},{"id":"u33_13","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ١٣","segs":[["ctx","أ. قضاء"],["matn","بمثل معقول:"],["ctx","كالصَّلاة للصَّلاة والصَّوم للصَّوم، فيكون قضاء للفعل بمثل الهيئة التي وجبت على المكلّف."]]},{"id":"u33_14","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ١٤","segs":[["matn","ب. قضاء بمثل غير معقول:"],["ctx","أي يقصر العقل عن إدراك المماثلة فيه؛ لأنَّ العقلَ ينفي التَّشابه بين ما كان واجباً كالصِّيام وبين ما يؤدى بدل عنه كالفدية للصَّوم عند العجز المستدام، كما في حَقّ الشَّيخ الفاني، فإنَّه لا مماثلة تدرك بين الصَّوم والفدية، فالصَّومُ وصف، والفدية عين؛ لأنَّ الصَّومَ إتعابُ النَّفس بالكفّ عن شهوتَي البطن والفرج، والفديةُ تنقيص المال، فحيث عدمنا إدراكَ المماثلة عقلاً أَثبتناه بالنَّصّ الوارد في حقِّه من آية أو حديث: كقوله تعالى: ﴿وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖ﴾ [البقرة: ١٨٤]."]]},{"id":"u33_15","kind":"def","label":"المطلب الثَّاني: حكم الأمر على صورتين · الفقرة ١٥","segs":[["matn","جـ. قضاءٌ بمعنى الأداء"],["ctx",": كتكبير مَن أدرك الإمام في العيد راكعاً في الرُّكوع، فمِن حيث إنَّه فات عن موضعه ـ وهو القيام ـ كان قضاءً، ومن حيث إنَّ الفرق بين القائم والقاعد انتصاب النِّصف الأسفل كان الركوع شبيه القيام، فالإتيان بالتَّكبير فيه قضاء بمعنى الأداء."]]}],"sup":"المبحث الأول الخاصّ"},{"id":"u34","title":"المطلب الثَّالث: حسن الأمر","group":"الباب الثَّاني الكتاب","units":[{"id":"u34_1","kind":"text","label":"المطلب الثَّالث: حسن الأمر · الفقرة ١","segs":[["ctx","إذا أمر الله تعالى بشيء عُلِم أنَّه حسنٌ بلا خلاف، سواء كان موجَب الأمر أو مدلوله؛ لأنَّ الشَّارع تعالى حكيم على الإطلاق لا يأمر بالفحشاء، ولا يليق بالحكمة طلب ما هو القبيح؛ لقوله تعالى: ﴿إِنَّ ٱللَّهَ لَا يَأۡمُرُ بِٱلۡفَحۡشَآءِ﴾ [الأعراف: ٢٨]."]]},{"id":"u34_2","kind":"def","label":"المطلب الثَّالث: حسن الأمر · الفقرة ٢","segs":[["matn","فالحسنُ لازمٌ للمأمور به"],["ctx","؛ لأنَّ الآمر حكيم، فلا يأمر بشيء إلا لحسنه، والعقل آلة يدرك بها حسن بعض الأشياء وقُبحها؛ لأنَّ الحُسن والقُبح لا يُعرفان إلا بالأمر والنَّهي لا بالعقل نفسه؛ لأنَّ العقل غير مهتد إليهما، وغير موجب عندنا، وإن كان له حظٌّ في معرفة بعض المشروعات: كالإيمان وأصل العبادات."]]},{"id":"u34_3","kind":"text","label":"المطلب الثَّالث: حسن الأمر · الفقرة ٣","segs":[["ctx","وقالت المعتزلة: الحُسن والقُبح عقليان لا شرعيان، يعني يستقلّ العقل في معرفتِهما من غير توقف على الشَّرع: أي الأمر والنَّهي."]]},{"id":"u34_4","kind":"def","label":"المطلب الثَّالث: حسن الأمر · الفقرة ٤","segs":[["matn","والحُسن على قسمين:"],["ctx","الأول: حسن"],["matn","لمعنى"],["ctx","حاصل"],["matn","في عين الأمر، وهذا الحسن"],["ctx","بالنَّظر إلى حكم الأمر"],["matn","نوعان:"]]},{"id":"u34_5","kind":"def","label":"المطلب الثَّالث: حسن الأمر · الفقرة ٥","segs":[["ctx","١. حسن"],["matn","لمعنى في وصف الأمر، وله صورتان:"]]},{"id":"u34_6","kind":"text","label":"المطلب الثَّالث: حسن الأمر · الفقرة ٦","segs":[["ctx","أ. ما لا يقبل السُّقوط أَصلاً لا بعذر الإكراه ولا بغير عذر الإكراه: كالإيمان بمعنى التَّصديق، حَسنٌ بمعنى في وصفه، وهو شُكرُ المُنعم، وهذا حاصلٌ في ذاتِ التَّصديق، فالإيمانُ بالله تعالى هو شكرُه على نِعَمِّهِ الظَّاهرةِ والباطنة علينا."]]},{"id":"u34_7","kind":"text","label":"المطلب الثَّالث: حسن الأمر · الفقرة ٧","segs":[["ctx","ب. ما يقبل السُّقوط في بعض الأحوال: كالصَّلاة حسنت للتَّعظيم، والتَّعظيمُ حاصلٌ في ذاتها، فقيام العبد بالصَّلاة لله تعالى يتحقّق فيها معنى تعظيم المعبود."]]},{"id":"u34_8","kind":"def","label":"المطلب الثَّالث: حسن الأمر · الفقرة ٨","segs":[["ctx","٢. حسن لمعنى في عين الأمر"],["matn","مشابهٌ للحسن لمعنى في غير الأمر"],["ctx",": كالزَّكاة فإنَّها في عينها تنقيص المال، حَسُنت لمعنى في غيرها، وهو دفعُ حاجة الفقير، فبهذا المعنى صارت مشابهةً للذي حسن لمعنى في غيره، إلا أنَّ حاجةَ الفقير لما كانت بِخَلق الله تعالى لا صنع للعبد فيها، صارت كلا واسطة؛ لأنَّ الأمرَ بالزَّكاة وحاجة الفقير كلاهما من الله تعالى، فلم يعد فعل للعبد فيها، فأضيفت الحاجة للفقير إلى الزَّكاة مباشرة، وأُلحقت بالقسم الأوّل."]]},{"id":"u34_9","kind":"def","label":"المطلب الثَّالث: حسن الأمر · الفقرة ٩","segs":[["matn","وحكم ما وجب في عين الأمر بِصُوره: أنَّه"],["ctx","لا يسقط إلا بالأداء أو باعتراض ما يُسقطه كالحيض في الصَّلاة، فإنَّه يسقط الصَّلاة عن المرأة."]]},{"id":"u34_10","kind":"def","label":"المطلب الثَّالث: حسن الأمر · الفقرة ١٠","segs":[["matn","الثّاني:"],["ctx","حسن"],["matn","لمعنى في غير"],["ctx","المأمور به، وذلك المعنى الخارج الذي حسن المأمور به لأجله على نوعين:"]]},{"id":"u34_11","kind":"def","label":"المطلب الثَّالث: حسن الأمر · الفقرة ١١","segs":[["matn","١. أن لا يؤدَّى المعنى الخارج: كالصَّلاة بالمأمور به"],["ctx","كالوضوء، فإنَّ الوضوء حسن للتمكُّن من الصَّلاة به، والصَّلاةُ لا تتأدّى بالوضوء، وإنَّما تتأدّى بأركانها المعلومة."]]},{"id":"u34_12","kind":"def","label":"المطلب الثَّالث: حسن الأمر · الفقرة ١٢","segs":[["matn","٢. أن يؤدَّى المعنى الخارج الذي"],["ctx","حسن المأمور به لأجله به:"],["matn","كإعلاء كلمة الله بالمأمور به وهو الجهاد،"],["ctx","فالجهاد حسن لإعلاء كلمة الله تعالى، وإعلاء كلمة الله تتأدَّى بالجهاد."]]},{"id":"u34_13","kind":"def","label":"المطلب الثَّالث: حسن الأمر · الفقرة ١٣","segs":[["matn","وحكم ما حسن لغيره بِصُوره:"],["ctx","هو بقاءُ الوجوب ببقاء غيره الذي حسن لأجله، وسقوطه بسقوطه: كوجوب الوضوء بوجوب الصَّلاة، وسقوط الوضوء بسقوط الصَّلاة."]]}],"sup":"المبحث الأول الخاصّ"},{"id":"u35","title":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت","group":"الباب الثَّاني الكتاب","units":[{"id":"u35_1","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١","segs":[["matn","الأول: مطلق عن الوقت"],["ctx","؛ بأن لا يُذكر له وقتٌ محدودٌ على وجهٍ يفوت الأداء بفواته، بحيث لا يكون المأمورُ به محدداً بوقتٍ: كالأمر بالزَّكاةِ وصدقةِ الفطر، فلا يجب الأداءُ على الفور، وهو الإتيانُ بالمأمور به عَقِيب ورود الأمر؛ لأنَّ الأمرَ لطلب الفعل فقط، والأزمنةُ في صلاحيةِ حصول الفعل فيه على حدّ سواء، فتجب الزَّكاة وصدقة الفطر على التَّراخي، ويؤديها في أي وقت شاء، ولا يكون قضاء؛ لعدم اختصاصها بوقت معيّن."]]},{"id":"u35_2","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٢","segs":[["matn","الثاني: مقيّدٌ"],["ctx","بالوقت؛ بحيث يفوت الأداء بفوات الوقت؛ لاختصاصه بوقت محدّد،"],["matn","وهو أَربعة أَقسام:"]]},{"id":"u35_3","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٣","segs":[["matn","١. أن يكون الوقت ظرفاً وشرطاً وسبباً، بأن يكون ظرفاً للمؤدّى،"],["ctx","وهو الواجب،"],["matn","وشرطاً لأداء الواجب"],["ctx","، وهو إخراج الواجب وهو الصَّلاة إلى الوجود،"],["matn","وسبباً للوجوب"],["ctx",": فيثبت الوجوب بهذا السَّبب، وتتحقَّق هذه المعاني الثَّلاثة: ظرفاً وشرطاً وسبباً في"],["matn","وقت الصَّلاة."]]},{"id":"u35_4","kind":"text","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٤","segs":[["ctx","فوقتُ الصَّلاة ظرفٌ؛ لأنَّ الظَّرف ما يفضل عن أداء الواجب بحيث لا يستوعب الواجب كلّ الوقت، وإنَّما يستغرق جزءاً من الوقت، فإن صَلَّى فاكتفى بمقدار الفرض انقضى المؤدَّى قبل فراغ الوقت، وكلُّ ما يفضلُ من الأوقاتِ عن أداءِ الواجب يُسمّى ظرفاً؛ لأنَّ المرادَ بالظَّرفِ أن لا يكون الفعلُ مُقدَّراً بالوقت، بحيث يستغرق الواجب كلّ الوقت."]]},{"id":"u35_5","kind":"text","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٥","segs":[["ctx","ووقت الصَّلاة شرطٌ؛ لأنَّ الشَّرطَ ما يفوت أداء الواجب بفوته، بحيث لا يتحقَّق أداء الواجب بزوال الشَّرط؛ لأنَّ الوقتَ إذا خرج كان الإتيانُ بالواجب قضاءً، فالصَّلاةُ المكتوبة بعد انتهاء وقتها تصبح قضاءً لا أداءً؛ لفوات شرطها وهو الوقت، وكلُّ ما يفوت الأداء بفوته شرطٌ كما في سائر شروط الصَّلاة: كالطَّهارة وستر العورة واستقبال القِبلة والنيّة، فلا تصحّ الصَّلاة بفقد واحد من هذه الشُّروط."]]},{"id":"u35_6","kind":"text","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٦","segs":[["ctx","ووقتُ الصَّلاة سبب؛ لأنَّ السَّببَ ما يختلف أداء الواجب باختلاف صفته، فاختلافُ صفة الواجب من فجر إلى ظهر إلى عصر يختلف به الواجب من صلاة فجر إلى صلاة ظهر إلى صلاة عصر، وكلُّ ما يتغيّر الواجبُ بتغيُّره فهو سببٌ؛ لأنَّ المُسبَّبَ كالصَّلاة يثبت على وفق سببه وهو الوقت."]]},{"id":"u35_7","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٧","segs":[["matn","ومن أحكام الصَّلاة بسبب وجود هذه المعاني الثَّلاثة فيها:"],["matn","اشتراط نيّة"],["ctx","تعيين فرض الوقت؛ بأن ينوي صلاة الظُّهر في وقتِ الظُّهر مثلاً؛ لأنَّ الوقتَ لّما كان ظَرفاً كان المشروعُ فيه متعدِّداً، بحيث يُمكنه أن يؤدِّي في الوقتِ عدّة صلوات، فيشترط تمييز أي صلاة يؤدّي في الوقت، وذلك بنية التعيين."]]},{"id":"u35_8","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٨","segs":[["matn","ولا تسقط نيّة تعيين الصَّلاة إذا"],["ctx","ضاق الوقت؛ بحيث لا يسع غير هذه الصَّلاة الواجبة، بل لا بُدّ أن يعيِّنها؛ لأنَّ المعتبرَ أنَّ الوقتَ في نفسه ظرفٌ، لا أنَّه في هذه الصُّورةِ محددٌ بهذه الصَّلاة."]]},{"id":"u35_9","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٩","segs":[["matn","ولا يتعيَّن"],["ctx","بعضُ أَجزاء الوقت للسَّببية بشيءٍ من القصد ولا من القول، بأن يكون بداية الوقت أو وسطه أو آخره سبباً للصَّلاة إن قصد المكلَّف ذلك أو حدّد المكلَّف ذلك بلسانه، كأن ينوي أنَّ هذا الجزء هو السَّبب، أو يقول: عيّنتُ هذا الجزء للسَّبب؛ لأنَّ الصَّلاة لا تتعيّن في الوجوب إلا في اللَّحظة التي يشرع فيها، فإن لم يشرع في جزءٍ من الوقت تَعيّن آخر الوقت سبباً للوجوب."]]},{"id":"u35_10","kind":"text","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١٠","segs":[["ctx","وهذا يشبه الحانث في اليمين، فهو مخيّرٌ في الكفَّارة بين الإعتاق أو الكسوة أو الإطعام، ولو عَيَّن المكلّف أَحدَ هذه الثَّلاثة بقصد أو قول فإنَّه لا يتعيّن، وله أن يفعل غيره ما لم يفعل التَّكفير، فإن كَفَّرَ بأحدها تَعيَّن."]]},{"id":"u35_11","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١١","segs":[["matn","٢. أن يكون الوقت معياراً وشرطاً وسبباً"],["ctx","، بأن يكون معياراً ـ أي مقداراً ـ للمؤدَّى، وهو الواجب،"],["matn","وشرطاً لأداء الواجب"],["ctx","، وهو إخراج الواجب وهو الصِّيام إلى الوجود،"],["matn","وسبباً للوجوب"],["ctx","فيثبت الوجوب به، وتتحقَّق هذه المعاني الثَّلاثة: معياراً وشرطاً وسبباً في"],["matn","وقت شهر رمضان."]]},{"id":"u35_12","kind":"text","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١٢","segs":[["ctx","فوقت شهر رمضان معياراً؛ لأنَّ صوم رمضان قُدِّر بأيّام شهر رمضان، حتى ازداد الصِّيام بزيادة أيّام شهر رمضان، وانتقص الصِّيام بنقصان أيّام شهر رمضان."]]},{"id":"u35_13","kind":"text","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١٣","segs":[["ctx","ووقت شهر رمضان شرطاً؛ لأنَّ صيام رمضان يفوت بفوات أيّام شهر رمضان، ويكون قضاءً بعده لا أداءً."]]},{"id":"u35_14","kind":"text","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١٤","segs":[["ctx","ووقت شهر رمضان سبباً؛ لأنَّ الصِّيام يُضاف إلى شهر رمضان، والإضافةُ تدلُّ على الاختصاص، وأقوى وجوه الاختصاص السَّببية، فيكون شهرُ رمضان سبباً للصِّيام."]]},{"id":"u35_15","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١٥","segs":[["matn","ومن أحكام صيام رمضان بسبب وجود هذه المعاني الثَّلاثة فيه:"],["ctx","عدم صحّة أي صيام غير صيام رمضان في شهر رمضان؛ لأنَّ الوقتَ معيارٌ لصِّيام رمضان، فلا يتسع لغيره من الصِّيامات، وإذا لم يتسع شهر رمضان لغير صيام رمضان، فيتأدّى صيام رمضان"],["matn","بمطلق الاسم"],["ctx","، وهو الصَّوم، بأن يقول: نويتُ أن أصوم."]]},{"id":"u35_16","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١٦","segs":[["ctx","ويتأدّى"],["matn","مع الخطأ"],["ctx","في وصف الصَّوم، بأن ينوي صوم القضاء أو النَّذر أو النَّفل؛ لأنَّ الوقت لا يقبل أي وصف للصيام غير رمضان، فَلَغت نيّتُه وبقيت نيّةُ أَصل الصَّوم، وبها يتأدّى صوم رمضان،"],["matn","إلا في المسافر ينوي واجباً آخر"],["ctx","؛ لأنَّه لم يبق صيام رمضان في حقِّه متعيِّناً، فيصحّ نيّة غير رمضان."]]},{"id":"u35_17","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١٧","segs":[["matn","٣. أن يكون"],["ctx","الوقت"],["matn","معياراً فقط؛ بأن يكون صيام قضاء رمضان"],["ctx","مُقَدَّراً؛ لأنَّه بعد تعيين اليوم للقضاء لا يتسع لغير القضاء، فكان معياراً للقضاء فقط."]]},{"id":"u35_18","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١٨","segs":[["matn","ولا يكون وقت القضاء سبباً"],["ctx","لوجوب"],["matn","قضاء رمضان"],["ctx","؛ لأنَّ سبب القضاء هو سبب الأداء، وهو شهود شهر رمضان ـ على ما عُلِم ـ، فلم يكن زمن القضاء سبباً."]]},{"id":"u35_19","kind":"text","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ١٩","segs":[["ctx","ولا يكون وقت القضاء شرطاً لصيام قضاء رمضان؛ لأنَّه لا يفوت القضاء بفوات هذا الوقت المعيّن للقضاء؛ لأنَّه يُمكنه أن يقضيه في أيّ وقت آخر، ولا يختلف حال الوقت الذي يقضيه فيه عن مثل هذا الوقت المُعَيَّن للقضاء؛ لأنَّ وقتَ القضاء العمر، بخلاف الصَّلاة وصيام رمضان؛ لأنَّ وقتَهما محدودٌ بحدّ يفوت الأداء بفوته."]]},{"id":"u35_20","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٢٠","segs":[["matn","ومن أحكام صيام قضاء رمضان بسبب أنَّه معيار فقط:"],["matn","اشتراط تعيين أنَّه قضاء لرمضان"],["ctx","؛ لأنَّ هذا الصَّوم ليس بوظيفةِ الوقت، ولا هو متعيّنٌ فيه، فيصير له مزاحماً من الصِّيامات الأخرى، فيُمكن نيّة أي صيام، وإذا ازدحمت العبادات في وقتٍ واحدٍ فلا بُدَّ من التَّعيين؛ لتمييز أي صيام نريد منها، والتَّعيين إنَّما يحصل بنيّة صيام قضاء رمضان."]]},{"id":"u35_21","kind":"text","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٢١","segs":[["ctx","واشتراط أن يكون نيّة صيام القضاء من الليل؛ لينعقد الإمساك من أوّل النَّهار؛ لأنَّ الوقتَ يحتمل القضاء وغيره."]]},{"id":"u35_22","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٢٢","segs":[["matn","٤. أن يكون"],["ctx","الوقت"],["matn","مشكلاً"],["ctx","يشبه المعيار ويشبه الظَّرفَ،"],["matn","فإنَّ الحجَّ"],["ctx","يشبه وقته المعيار من حيث إنَّه لا يصحّ منه في عامّ واحد إلا حجّة واحدة، فكان وقت الحجّ كالنَّهار في الصَّوم، ويشبه الظَّرف من حيث إنَّ أركانَ الحجّ لا تستغرق جميع الوقت، فكان وقت الحج كوقت الصَّلاة."]]},{"id":"u35_23","kind":"def","label":"المطلبُ الرَّابع: أنواع الأمر من حيث الوقت · الفقرة ٢٣","segs":[["matn","ومن حكم الحجّ بسببِ كونه مشكلاً:"],["ctx","أنَّه يلزم"],["matn","أدائه في أشهر الحجّ"],["ctx","من أوَّل سني الإمكان، بأن توفرت فيه شروط وجوب الحجّ، فيكون وجوب الحج على الفور لا على التَّراخي."]]}],"sup":"المبحث الأول الخاصّ"},{"id":"u36","title":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة","group":"الباب الثَّاني الكتاب","units":[{"id":"u36_1","kind":"text","label":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة · الفقرة ١","segs":[["ctx","ويتعلق بالأمر مخاطبة الكُفَّار بالأحكام الشَّرعية:"]]},{"id":"u36_2","kind":"def","label":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة · الفقرة ٢","segs":[["matn","فالكفَّارُ مخاطبون بالإيمان بإجماع الفقهاء، قال الله تعالى:"],["ctx","﴿قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡ جَمِيعًا ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِ﴾ [الأعراف: ١٥٨]."]]},{"id":"u36_3","kind":"text","label":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة · الفقرة ٣","segs":[["ctx","ومخاطبون بالمشروع من العقوبات فيما اعتقدوا حرمته، ولهذا تقام عليهم الحدود بطريق الجزاء والزَّجر عن الإقدام على أسبابها، ولا يُحدون حدّ شرب الخمر والسَّكر؛ لعدم اعتقادهم حرمته."]]},{"id":"u36_4","kind":"text","label":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة · الفقرة ٤","segs":[["ctx","ومخطابون بالمعاملات: كالبيع؛ لوجود التزامهم."]]},{"id":"u36_5","kind":"text","label":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة · الفقرة ٥","segs":[["ctx","والكافرُ إذا أسلم لا شيء عليه من قضاء ما مضى من العبادات في حالة الكُفر."]]},{"id":"u36_6","kind":"text","label":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة · الفقرة ٦","segs":[["ctx","واختلفوا في مخاطبتهم في الصَّوم والصَّلاة والحجّ والزَّكاة في حال الكفر:"]]},{"id":"u36_7","kind":"text","label":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة · الفقرة ٧","segs":[["ctx","قال العراقيون: إنَّهم مخاطبون بالفروع اعتقاداً وأداءً: أي يعذبون في النَّار على اعتقادهم بعدم الفرضية وعلى عدم أدائهم؛ لأنَّهم يخاطبون بجميع أوامر الله تعالى ونواهيه من حيث الاعتقاد والأداء في حَقِّ المؤاخذة في الآخرة، فيعاقبون على ترك ذلك؛ لقوله تعالى: ﴿مَا سَلَكَكُمۡ فِي سَقَرَ قَالُواْ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّينَ﴾ [المدثر: ٤٣]، فأخبروا أنَّهم استحقوا ذلك بترك الصَّلاة، ولم يُرَدَّ عليهم."]]},{"id":"u36_8","kind":"text","label":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة · الفقرة ٨","segs":[["ctx","وقال جماعة من مشايخ ما وراء النَّهر: إنَّهم مخاطبون اعتقاداً لا أداءً، فلا يعذبون في جهنم إلا على عدم اعتقادهم الفرضية."]]},{"id":"u36_9","kind":"text","label":"المطلب الخامس: مخاطبة الكُفَّار بالشَّريعة · الفقرة ٩","segs":[["ctx","وقال جماعة أخرى من مشايخ ما وراء النَّهر: إنَّهم ليسوا بمخاطبين اعتقاداً وأداءً فلا يعذبون؛ لأنَّ الكفّارَ ليسوا بأهل لأداء العبادات؛ لأنَّ أداءَها سبب لاستحقاق الثَّواب."]]}],"sup":"المبحث الأول الخاصّ"},{"id":"u37","title":"النَّوع الثَّاني: النَّهي","group":"الباب الثَّاني الكتاب","units":[{"id":"u37_1","kind":"text","label":"النَّوع الثَّاني: النَّهي · الفقرة ١","segs":[["ctx","وهو قول القائل لغيره على سبيل الاستعلاء: لا تفعل."]]}],"sup":"المبحث الأول الخاصّ"},{"id":"u38","title":"المطلب الأوّل: القبح للنَّهي","group":"الباب الثَّاني الكتاب","units":[{"id":"u38_1","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١","segs":[["matn","ونتكلَّم عليه في مطلبين:"],["ctx","فالنَّهي كالأمر في كونه من الخاصّ؛ لأنَّه لفظٌ وُضِع لمعنى معلوم، وهو التَّحريم."]]},{"id":"u38_2","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ٢","segs":[["matn","ويقتضي النَّهي صفة القُبح للمنهي عنه كالأمر في اقتضائه لصفة الحُسن"],["ctx","للمأمور به؛ لأنَّ النَّاهي حكيم، والحكيم إنَّما ينهى عن الفحشاء والمنكر."]]},{"id":"u38_3","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ٣","segs":[["matn","وينقسم القُبح للنَّهي إلى نوعين:"],["matn","١. القبيح لمعنى في عين المنهي عنه، وهو على صورتين:"]]},{"id":"u38_4","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ٤","segs":[["matn","أ. وضعاً"],["ctx",": أي وضع للقبيح العقلي بقطع النَّظر عن ورود الشَّرع: كالكفر وُضِع لمعنى قبيح في ذاته، وهو كفران النِّعم، فإنَّ كلَّ مَن يُنكر نعم مَن أنعم عليه، فهو يفعل فعلاً قبيح، وهذا أمر مرده للعقل."]]},{"id":"u38_5","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ٥","segs":[["matn","ب. شرعاً"],["ctx",": أي إنَّ الشَّرع ورد بهذا القبح، وإلا فالعقل يُجوِّزه: كبيع الحرّ عُلِمَ من الشَّرع قُبحُه لا من العقل؛ لأنَّ العقل لا يرى فرقاً بين بيع العبد والحرّ، فكما جاز بيع العبد جاز بيع الحرّ، لكنَّ الشَّرع منع بيع الحرّ، وليس بلازم أن يكون مقصوداً بالشَّرع الشَّريعة الإسلامية، وإنَّما يقصد بالشَّرع مطلق النِّظام أو القانون عند المسلمين وغير المسلمين."]]},{"id":"u38_6","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ٦","segs":[["ctx","ويندرج تحت القَبيح لعينه بصورتيه:"]]},{"id":"u38_7","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ٧","segs":[["ctx","النَّهي عن"],["matn","الأفعال الحسية"],["ctx","، وهي التي تُعرف بالحسّ، ولا يتوقّف وجودها على الشَّرع ـ أي النِّظام ـ: كالقتل والزِّنا وشرب الخمر؛ لأنَّها تتحقق بنفسها بدون توقف على أمر آخر، بخلاف البيع، فإنَّه يتوقف انتقال الملك من البائع والمشتري على وجود نظام يرتب أنَّ التَّلفظ بهذا اللفظ بهيئة مخصوصة يفيد الانتقال للملك، والتَّلفظ بنفسه بدون وجود نظام لا يستفاد منه هذا الحكم."]]},{"id":"u38_8","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ٨","segs":[["ctx","والقتل مثال للقبيح لعينه وضعاً؛ لأنَّ العقل يرفضه ويُقَبحه، بدليل أنَّه محظور في كافة دول العالم بدون حقّ."]]},{"id":"u38_9","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ٩","segs":[["ctx","والزِّنا وشربُ الخمر قبيح لعينه شرعاً؛ لأنَّ العقل لا يمنع منها بدليل أنَّها مشروعةٌ في عامّة دول العالم، وإنَّما القبح من النِّظام، فالتِّشريعات الإسلامية تمنع منه؛ لكثرت ضررها."]]},{"id":"u38_10","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١٠","segs":[["ctx","وحكم ما قَبح لعينه: أنَّ المنهيَ عنه غيرُ مشروع أصلاً."]]},{"id":"u38_11","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١١","segs":[["matn","٢. القبيح لمعنى في"],["ctx","غير المنهي عنه على صورتين:"]]},{"id":"u38_12","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١٢","segs":[["ctx","أـ"],["matn","وصفاً، وهو ما يكون القبيحُ"],["ctx","قائماً بالمنهي عنه لا يقبل الانفكاك: كوصف صيام يوم النَّحر، فإنَّه إمساكٌ لله تعالى، فلم يقبح باعتبار الإمساك لله تعالى، بل باعتبار وصفه، وهو الإعراضُ عن ضيافةِ الله تعالى في هذا اليوم."]]},{"id":"u38_13","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١٣","segs":[["ctx","وحكم القبيح لغيره للوصف:"]]},{"id":"u38_14","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١٤","segs":[["ctx","أنَّ المنهيَّ عنه بعد النَّهي مشروعٌ بأصلِه غير مشروع بوصفه، فيصحّ النَّذر بصيام يوم النَّحر، فإن صام يوم النَّحر يصحّ صيامه مع الكراهة ويخرج عن العهدة."]]},{"id":"u38_15","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١٥","segs":[["matn","ب ـ مجاوراً: وهو ما يكون القبيح"],["ctx","مصاحباً ومقارناً في الجملة؛ بأن يوجد في بعض الأحيان وينفك في أحيان أخرى: كالبيع وقت النِّداء، قَبُحَ للاشتغال بالبيع عن السَّعي، وهو مجاورٌ للبيع قابلٌ للانفكاك عنه، كما إذا باع في حالةِ السَّعي في الطَّريق فلا يكره."]]},{"id":"u38_16","kind":"def","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١٦","segs":[["matn","ويندرج تحت القبيح لغيره بصورتيه:"],["matn","النَّهي عن الأمور الشَّرعية"],["ctx","، وهي التي يتوقَّف تحقيقها على الشَّرع: كالصَّلاة والصَّوم والبيع والإجارة، فإنَّ هذه الأفعال عُرفت من قبل النِّظام، وهي بدون نظام يُحددها ويَبني عليها أحكاماً تكون عبثاً، فأيُّ معنى لأفعال الصَّلاة إن لم تكن عبادة أُمرنا بها بهيئةٍ خاصّةٍ، وأيُّ معنى للبيع إن لم نرتب عليه انتقال الملك إلا العبث بقول هذه الكلمة."]]},{"id":"u38_17","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١٧","segs":[["ctx","وطالما أنَّها عُرفت ابتداءً من قبل الشَّرع «النِّظام»، فإن لم يكن النِّظام يريدها لا يشرعها أصلاً، فإن نُهِيَ عنها في النِّظام عُرِف أنَّه يريد المنع من صورةٍ من صورها لا غير؛ لأنَّه طالما أنَّه شرعها فهو يريدُها، والمنعُ يُحمل على وصفِ مُعيّن لها."]]},{"id":"u38_18","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١٨","segs":[["ctx","وهذا معنى أنَّ النَّهي في الأفعال الشَّرعيَّة يدلُّ على جواز أصلها، والمنع في وصف خاصّ لها؛ لأنَّ أصلها عُرف من قِبَلِ النِّظام، فإن كان لا يريده فلا يشرعه أصلاً، وبالتالي لا نعرفه."]]},{"id":"u38_19","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ١٩","segs":[["ctx","وإن أردنا بالنَّهي بطلان أصلها، فهذا يؤدي إلى بطلان النَّهي نفسه؛ لأنَّه سيكون نهياً لشيءٍ غير موجود؛ لكونها أفعالاً شرعيةً عُرفت من قبل الشَّرع، فبطلانها يقتضي عدم وجودها أصلاً، فكان النَّهي لغواً لوقوعه في محلّ معدوم؛ لأنَّ النَّهي تصرُّف من الشَّرع بالمنع عن الفعل، فلا بُدَّ أن يكون الفعلُ متصوّراً للمكلَّف، وتصوُّرُه هذا موقوفٌ على إيجاد الشَّرع له."]]},{"id":"u38_20","kind":"text","label":"المطلب الأوّل: القبح للنَّهي · الفقرة ٢٠","segs":[["ctx","وحكم القبيح لغيره: أنَّه مشروعٌ بأَصلِهِ غيرَ مشروع بوصفِه، ففي العباداتِ يصحُّ التزامها، كما في نذر صيام يوم النَّحر، وفي المعاملاتِ تفيد الملك عند اتصال القبض، كما في البيع الفاسد فإنَّه يملك بالقبض."]]}],"sup":"المبحث الأول الخاصّ"},{"id":"u39","title":"المطلب الثَّاني: الأمر والنَّهي في حقّ الضدّ","group":"الباب الثَّاني الكتاب","units":[{"id":"u39_1","kind":"text","label":"المطلب الثَّاني: الأمر والنَّهي في حقّ الضدّ · الفقرة ١","segs":[["ctx","الأمرُ بالشَّيء يقتضي كراهة ضدِّه، والنَّهي عن الشَّيء يقتضي أن يكون ضدُّه في معنى سُنّة مؤكّدة؛ لأنَّ الشَّيءَ في نفسِه لا يدلّ على ضدّه، وإنَّما يلزم الحكم في الضدّ ضرورة الامتثال، فتكفي الدَّرجة الأدنى في ذلك، وهي الكراهة في الأمر؛ لأنَّها دُون التَّحريم، والسُّنَّةُ المؤكدة في النَّهي؛ لأنَّها دون الواجب."]]},{"id":"u39_2","kind":"text","label":"المطلب الثَّاني: الأمر والنَّهي في حقّ الضدّ · الفقرة ٢","segs":[["ctx","فالتَّحريم لّما لم يكن مقصوداً بالأمر لم يعتبر إلا من حيث يفوِّت الأمر بالكليّة، فإذا لم يفوِّته كان مكروهاً: كالأمر بالقيام إلى الرّكعة الثَّانية بعد فراغ الأولى أو الثَّالثة بعد فراغ التَّشهد، ليس بنهي عن القعودِ قصداً، حتى إذا قَعَدَ أثناء قيامه في الصَّلاة ثمّ قام لا تفسد صلاتُه بنفس القعود، ولكنَّه يُكره؛ لأنَّ نفسَ القعود وهو قعودُ مقدارُ تسبيحة لا يُفوِّت القيام فيُكره، وإن مَكَثَ كثيراً بحيث ذهب أوان القيام تفسد الصَّلاة."]]},{"id":"u39_3","kind":"text","label":"المطلب الثَّاني: الأمر والنَّهي في حقّ الضدّ · الفقرة ٣","segs":[["ctx","والوجوب لما لم يكن مقصوداً بالنَّهي، أفاد النَّهي السُّنة المؤكَّدة: كنهِي المُحْرِم عن لُبْسِ المخيطِ، فلا بُدّ له أن يَلبسَ شيئاً يستر به العورة، وأدنى ما تكون به الكفاية هو الإزارُ والرِّداء، فكان من السُّنّةِ لُبْس الإزار والرِّداء."]]}],"sup":"المبحث الأول الخاصّ"},{"id":"u40","title":"المبحث الثَّاني العام","group":"الباب الثَّاني الكتاب","units":[{"id":"u40_1","kind":"def","label":"المبحث الثَّاني العام · الفقرة ١","segs":[["matn","وهو ما تناول أفراداً متفقة الحدود على سبيل الشُّمول"],["ctx",": أي يضمّ مجموعة أفراد متشابة مع بعضها البعض في آن واحدٍ، فيُمكن الجمع بينها بحرفِ الواو: أي هذا وهذا وهذا، بخلاف اسم الجنس نحو: رجل، فإنَّه يتناول أَفراداً متفقةَ الحدود لكن على سبيل البدل: أي هذا أو هذا أو هذا."]]},{"id":"u40_2","kind":"def","label":"المبحث الثَّاني العام · الفقرة ٢","segs":[["matn","وحكم العام:"],["matn","إيجابُ الحكم فيما يتناوله قطعاً"],["ctx",": كقوله تعالى: ﴿فَٱقۡتُلُواْ ٱلۡمُشۡرِكِينَ﴾ [التوبة: ٥]، ﴿وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَيۡهِ﴾ [الأنعام: ١٢١]، فالحكم هو الوجوب المستفاد من ﴿فَٱقۡتُلُواْ﴾ يثبت في مدلول العام، وهو المشركون حكماً له."]]},{"id":"u40_3","kind":"def","label":"المبحث الثَّاني العام · الفقرة ٣","segs":[["ctx","وطالما أنَّ العام يشمل أفراده قطعاً ويفيد الوجوب فيها فيكون في مرتبة الخاصّ،"],["matn","فيجوز نسخُ الخاصّ"],["ctx","بالعامّ، فمثلاً عن أنس رضي الله عنه: «إنَّ النَّبيَّ ﷺ أمر العُرنيين بشرب أبوال الإبل»، وهذا خاصٌّ، وعن أبي هريرة رضي الله عنه، قال ﷺ: «استنزهوا من البول»، وهذا عامٌّ، فلمَّا شارك الخاصَّ في حكمِه المتعلّق بطهارةِ ونجاسةِ البول، فكان الخاصّ مبيحاً: أي مفيداً لطهارة البول، وكان العامُّ مُحرِّماً: أي مفيداً نجاسة البول، والقاعدةُ الأصوليّةُ تقول: إن تعارض المحرِّم والمبيح قُدِّم المحرِّم وجُعِل ناسخاً، فيُقدَّم نجاسة البول على طهارته، ولو لم يكن العامّ مثل الخاصّ في القطع لما صحّ النَّسخ."]]},{"id":"u40_4","kind":"text","label":"المبحث الثَّاني العام · الفقرة ٤","segs":[["ctx","وهذا حكم العام قبل التَّخصيص، فأمّا بعده فيكون ظنيّاً، كما روي: أنَّ فاطمة رضي الله عنها احتجت على أبي بكر رضي الله عنه في ميراثها بعموم قوله تعالى: ﴿يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡ﴾ [النساء: ١١]، مع أنَّ القاتل والكافر خُصّا منه، فلم ينكر أحدٌ احتجاجها من الصَّحابة، وعَدَل أبو بكر رضي الله عنه في حرمانها إلى الاحتجاج بقوله ﷺ: «لا نورث، ما تركناه صدقة»، فلما كان العامّ بعد التَّخصيص ظنيّاً، فإنَّه ساوى أحاديث الآحاد الظَّنيَّة، فقد احتج أبو بكر رضي الله عنه في معارضته بدليل ظنيّ."]]},{"id":"u40_5","kind":"text","label":"المبحث الثَّاني العام · الفقرة ٥","segs":[["ctx","ومن المواضع العامة التي لم تخصّ في القرآن: قوله تعالى: ﴿حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ﴾ [النساء: ٢٣]، فكلُّ ما سميت أمّاً من نسبٍ أو رضاع وإن عَلَت حرامٌ، وقوله تعالى: ﴿كُلُّ مَنۡ عَلَيۡهَا فَانٖ﴾ [الرحمن: ٢٦]، وقوله تعالى: ﴿كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِ﴾ [آل عمران: ١٨٥]، وقوله تعالى: ﴿وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ﴾ [النساء: ١٧٦]، وقوله تعالى: ﴿۞ وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا﴾ [هود: ٦]، وقوله: ﴿ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ﴾ [إبراهيم: ٢]."]]},{"id":"u40_6","kind":"def","label":"المبحث الثَّاني العام · الفقرة ٦","segs":[["matn","وألفاظ العموم قسمان:"],["ctx","١. عام بصيغته ومعناه: فهو صيغة كلُّ جمع مثل: الرِّجال والنِّساء والمسلمين والمسلمات والمشركين والمشركات وما أشبه ذلك."]]},{"id":"u40_7","kind":"text","label":"المبحث الثَّاني العام · الفقرة ٧","segs":[["ctx","أما صيغته فموضوعة للجمع، وأما معناه فكذلك، وذلك شامل لكل ما ينطلق عليه وأدنى الجمع ثلاثة."]]},{"id":"u40_8","kind":"text","label":"المبحث الثَّاني العام · الفقرة ٨","segs":[["ctx","والمراد أن يكون هذا اللفظ موضوعاً لمطلق الجمع من غير تعرض لعدد معلوم بل يتناول الثَّلاثة فصاعداً، وله صيغة تثنية وفرد من لفظه: كرجال، أو من غير لفظه: كنساء."]]},{"id":"u40_9","kind":"text","label":"المبحث الثَّاني العام · الفقرة ٩","segs":[["ctx","٢. عام بمعناه دون صيغته، ولا يتصور أن يكون العام عاماً بصيغته فقط؛ إذ لا بد من تعدد المعنى، والعام بالمعنى أنواع:"]]},{"id":"u40_10","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١٠","segs":[["ctx","أ. ما هو فرد وضع للجمع، مثل: الرَّهط والقوم والطَّائفة والجماعة، فإنَّه يتناول أَفراداً بمعناه دون صيغته، فَيُثَنَّى ويجمع فيقال: رهط ورهطان وأرهط وأرهاط، وقوم وقومان وأقوام، ولكنَّه وضع للجمع، والرَّهط اسم لما دون العَشرة من الرِّجال لا يكون فيهم امرأة، والقوم اسم لجماعة الرِّجال خاصة، والطَّائفة اسم للواحد فصاعداً، قال تعالى: ﴿فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ﴾ [التوبة: ١٢٢] أنَّه يقع على الواحد فصاعداً؛ لأنَّه نعتٌ فردٌ صار جنساً بعلامة الجماعة."]]},{"id":"u40_11","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١١","segs":[["ctx","ب. كلمة: «كل»، وهي للإحاطة على سبيل الإفراد قال الله تعالى: ﴿كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِ﴾ [الأنبياء: ٣٥]، ومعنى الإفراد أن يعتبر كلَّ مُسمَّى منفرداً ليس معه غيره، يعني أثر عمومه يظهر في المضاف إليه، فلو قال: كلُّ امرأةٍ أتزوَّجها فهي طالقٌ، يوجب العموم في المرأةِ لا في التَّزوُّج، حتى لو تزوَّج امرأةً مرَّتين لا تطلق في المرَّة الثَّانية."]]},{"id":"u40_12","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١٢","segs":[["ctx","ج. كلمة: «الجميع»، وهي عامّة مثل «كلّ»، إلا أنَّها تُوجب الاجتماع دون الانفراد، كما لو قال الإمام: جميع مَن دخل هذا الحصن أوّلاً فله رأس، فدخله عشرة معاً، فيستحق العشرة رأساً واحداً، بخلاف استخدام الإمام كلمة: «كل» تقتضي الإحاطة على سبيل الإفراد، فيجعل باعتبارها كأنَّ كلّ واحدٍ من الدَّاخلين تناوله الإيجاب خاصة."]]},{"id":"u40_13","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١٣","segs":[["ctx","د. أسماء الشَّرط: كمن وما وأي: كقوله تعالى: ﴿فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُ﴾ [البقرة: ١٨٥]، وقوله تعالى: ﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ﴾ [البقرة: ٢٧٢]، وقوله: ﴿أَيّٗا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ﴾ [الإسراء: ١١٠]."]]},{"id":"u40_14","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١٤","segs":[["ctx","فكلمة: «من»، وهي تحتمل الخصوص والعموم، وهي مختصة بأولي العقول، وتستعمل في الواحد والاثنين والجمع والمُذكَّر والمُؤنَّث، وأصلها العموم، قال ﷺ: «ومن دخل دار أبي سفيان فهو آمن»."]]},{"id":"u40_15","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١٥","segs":[["ctx","وكلمة: «ما»، وهي عامَّةٌ في ذوات ما لا يعقل وصفات مَن يعقل، تقول ما في الدَّار؟ جوابه: شاة أو فرس، وتقول: ما زيد؟ وجوابه: عاقل أو عالم."]]},{"id":"u40_16","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١٦","segs":[["ctx","هـ. أسماء الاستفهام: كمن ومتى وأين: كقوله تعالى: ﴿مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗا﴾ [المدثر: ٣١]، وقوله تعالى: ﴿مَتَىٰ نَصۡرُ ٱللَّهِ﴾ [البقرة: ٢١٤]، وقوله تعالى: ﴿أَيۡنَ مَا كُنتُمۡ تَدۡعُونَ مِن دُونِ ٱللَّهِ﴾ [الأعراف: ٣٧]."]]},{"id":"u40_17","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١٧","segs":[["ctx","و. كلمة: «الذي»، وهي عامة فيما يعقل وفيما لا يعقل."]]},{"id":"u40_18","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١٨","segs":[["ctx","س. النَّكرةُ إذا اتصل بها دليل العموم؛ لأنَّ النَّكرة تحتمل ذلك إذا اتصل بها دليله، فالنَّكرة في النَّفي تعمّ، وفي الإثبات تخصّ؛ لأنَّ النَّفي دليل العموم، وذلك ضروري لا لمعنى في صيغة الاسم، كقولك: ما جاءني رجلٌ، فقد نفيت مجيء رجل واحد نكرة، ومن ضرورة نفيه نفي غيره فتعم، بخلاف الإثبات؛ لأنَّ مجيء رجل واحد لا يوجب مجيء غيره فتخصّ."]]},{"id":"u40_19","kind":"text","label":"المبحث الثَّاني العام · الفقرة ١٩","segs":[["ctx","ح. أسماء الأجناس المُعَرَّفة بتعريف اللام الاستغراقية أو بتعريف الإضافة للاستغراق، فلام التَّعريف فيما لا يحتمل التَّعريف بعينه لمعنى العهد تفيد العموم، مثل قول تعالى: ﴿وَٱلۡعَصۡرِ إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ﴾ [العصر: ٢]: أي هذا الجنس، وقول تعالى: ﴿وَٱلسَّارِقُ وَٱلسَّارِقَةُ﴾ [المائدة: ٣٨]، ﴿ٱلزَّانِيَةُ وَٱلزَّانِي﴾ [النور: ٢]، وقال ﷺ: «مَطلُ الغني ظلم»."]]},{"id":"u40_20","kind":"text","label":"المبحث الثَّاني العام · الفقرة ٢٠","segs":[["ctx","ط. النَّكرة إذا اتصل بها وصف عام، فيصحُّ أن يوصف بها كلُّ فردٍ من أفراد نوع الموصوف ولا يختصّ بواحد، مثل قول الرَّجل: والله لا أكلم أحداً إلا رجلاً كوفياً، ولا أتزوج امرأةً إلا امرأةً كوفية، فإذا وُصفت النَّكرة بمثل هذا الوصف تعمم ضرورة عموم الوصف وإن كانت في نفسها خاصَّة."]]},{"id":"u40_21","kind":"text","label":"المبحث الثَّاني العام · الفقرة ٢١","segs":[["ctx","ومن جنس النَّكرة التي تعم بدليل العموم كلمة «أي»، قال تعالى: ﴿أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا﴾ [النمل: ٣٨]."]]},{"id":"u40_22","kind":"text","label":"المبحث الثَّاني العام · الفقرة ٢٢","segs":[["ctx","ي. الجمع المُعرَّف بغير اللام، نحو: زوجاتي طوالق إلا ليلى عام؛ لصحَّة الاستثناء."]]}]},{"id":"u41","title":"المبحثُ الثَّالث المشترك","group":"الباب الثَّاني الكتاب","units":[{"id":"u41_1","kind":"def","label":"المبحثُ الثَّالث المشترك · الفقرة ١","segs":[["matn","وهو ما تناول أَفراداً مختلفة الحدود بالبدل: أي هذا أو هذا، أو هو لفظ وضع وَضْعاً شخصياً لمعنين فأكثر بأوضاع متعددة ابتداءً بلا نَقْل من معنى إلى آخر، سواء كان بينهما مناسبة أم لا."]]},{"id":"u41_2","kind":"text","label":"المبحثُ الثَّالث المشترك · الفقرة ٢","segs":[["ctx","فمثلاً: القَرْء في قوله تعالى: ﴿وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖ﴾ [البقرة: ٢٢٨]، فإنَّه لفظ مشترك يتناول الحيض والطُّهر بالبدل، وعندنا يحمل على الحيض لقرائن ستأتي."]]},{"id":"u41_3","kind":"def","label":"المبحثُ الثَّالث المشترك · الفقرة ٣","segs":[["matn","وحكمُ المشترك:"],["matn","التَّوقف فيه من غير اعتقاد حكم معلوم سوى أنَّ الثابت به حقّ حتى يقوم مُرَجِّح للمعنى المراد، فيتأَمّل فيه ليترجَّح بعضُ وجوهِهِ للعمل به"],["ctx","، كما تؤمّل لفظ القَرْء، فوجد أَصل التَّركيب دالاً على الجمع، يُقال: قرأت الشَّيء: أي جمعتُه، وعلى الانتقال يُقال: قرأ النَّجمَ إذا انتقل، والاجتماعُ للدَّم والانتقال للحيض، فترجَّح الحيض على الطُّهر؛ لشهادة اللغة له، ولقوله تعالى: ﴿وَٱلَّٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ﴾ [الطلاق: ٤]؛ لأنَّه تعَرَّض عند ذكر الخلف لليأس عن الحيض دون الطُّهر، فعُلِمَ أنَّ المراد في الأصل هو الحيض."]]},{"id":"u41_4","kind":"def","label":"المبحثُ الثَّالث المشترك · الفقرة ٤","segs":[["matn","ولا عموم"],["ctx","للمشترك عندنا، فلا يستعمل في أكثر من معنى واحد؛ لأنَّ المتبادرَ إلى الفهم إرادة المتكلَّم أحد معاني المشترك؛ ليستقيم الكلام، ويتوضح المراد، فلزم ترجيح المعنى المطلوب المُعيَّن، وهذا يفيد أنَّ شرط استعمال المشترك بأن يكون في أحد المعاني لا غير."]]}]},{"id":"u42","title":"المبحث الرَّابع المؤوّل","group":"الباب الثَّاني الكتاب","units":[{"id":"u42_1","kind":"def","label":"المبحث الرَّابع المؤوّل · الفقرة ١","segs":[["matn","وهو ما ترجَّح من المشترك بعض وجوهِهِ بغالبِ الرَّأي."]]},{"id":"u42_2","kind":"text","label":"المبحث الرَّابع المؤوّل · الفقرة ٢","segs":[["ctx","والمرادُ بغالب الرَّأي الظنِّي، والتَّأويل ليس خاصاً بترجيح أحد معاني المشترك، بل يشمل كلَّ لفظ ترجّح بعض محتملاته بدليل فيه شبهة؛ لأنَّك إذا تأمّلت ما وضع اللفظ له وصرفته إلى وجهٍ معيّن فقد أَوّلته إليه."]]},{"id":"u42_3","kind":"def","label":"المبحث الرَّابع المؤوّل · الفقرة ٣","segs":[["matn","وحكم المؤول:"],["ctx","وجوبُ العمل به؛ لأنَّه دليلٌ ظنيّ"],["matn","على احتمال الغلط"],["ctx","؛ لأنَّ تعيينَه بدليل ظنيّ، فإنَّ المجتهدَ يُخطئ ويُصيب عندنا."]]},{"id":"u42_4","kind":"text","label":"المبحث الرَّابع المؤوّل · الفقرة ٤","segs":[["ctx","وظاهر ما سبق أنَّ المؤولَ ليس نوعاً رابعاً حقيقة، إنَّما هو مرحلةٌ ثانيةٌ من المشترك بعد اختيار أحد معانيه، وإنَّما ذُكِر نوعاً مستقلاً تسهيلاً على الدَّارس من وجود أربعة أنواع تحت كلّ قسم من وجوه دلالات الألفاظ."]]}]},{"id":"u45","title":"أولاً: مراتب الظُّهور أربعة","group":"الباب الثَّاني الكتاب","units":[{"id":"u45_1","kind":"def","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ١","segs":[["matn","الأوّل: الظَّاهر:"],["ctx","وهو كلام وضح المعنى الوضعي بنفس صيغته من غير نظر إلى أمر آخر، أو اسم عُرف المراد به للسَّامع إذا كان من أهل اللسان بمجرد سماع صيغته بلا قرينة، ويكون محتملاً للتأويل إن كان خاصاً والتَّخصيص إن كان عاماً، نحو قوله تعالى: ﴿وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْ﴾ [البقرة: ٢٧٥]، فإنَّ المعنى الوضعي وهو الإحلالُ والتَّحريمُ ظاهرٌ منه للعالم باللسان."]]},{"id":"u45_2","kind":"def","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ٢","segs":[["matn","وحكمُ الظَّاهر:"],["matn","وجوبُ العمل بما ظَهَر منه على سبيل القطع"],["ctx","؛ لعدم اعتبار احتمال لا ينشأ عن دليل من التَّأويل والتَّخصيص، حتى صَحَّ إثبات الحدود والكفَّارات بالظَّواهر."]]},{"id":"u45_3","kind":"def","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ٣","segs":[["matn","الثَّاني: النَّصُّ:"],["matn","وهو ما زاد المرادُ به وضوحاً على الظَّاهر بمعنى من المتكلِّم، وهو سوقُ الكلام له"],["ctx",": أي تكلَّم المتكلِّم من أجل هذا الأمر، فساق الكلام لبيانه، فإنَّ المسوقَ له أَجْلَى من غيره: كقوله تعالى: ﴿وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْ﴾ [البقرة: ٢٧٥]، فإنَّه ظاهرٌ في التَّحليل والتَّحريم، نصٌّ في الفَصْل والتَّفريق بين البيع والرِّبا؛ لأنَّه سيق الكلام لأجل الفَصْل، فإنَّهم ادعوا التَّسوية بينهما بقولهم: إنَّما البيعُ مثل الرِّبا على طريق المبايعة بجعل الرِّبا شبيهاً به في الحلّ، فردّ الله تعالى تسويتهم بقوله: ﴿وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْ﴾، فازداد وُضُوحاً بمعنى من المتكلِّم لا في نفس الصِّيغة بأن ساق الكلام لهذا."]]},{"id":"u45_4","kind":"def","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ٤","segs":[["matn","وحكم النَّص:"],["matn","وجوب العمل بما اتضح قطعاً على احتمال تأويل"],["ctx","من حمل الكلام على خلاف ظاهره مجازاً، أو تخصيص إن كان عاماً، وهذا الاحتمال لا يُخرج النَّصَّ عن كونه قطعيّاً، كما أنَّ احتمالَ الحقيقة أن تكون مجازاً لا يخرجها عن كونها قطعيّة."]]},{"id":"u45_5","kind":"def","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ٥","segs":[["matn","الثَّالث: المُفَسَّر:"],["matn","وهو ما ازداد وضوحاً على النَّصِّ من غير"],["ctx","احتمال"],["matn","تأويل"],["ctx","إن كان خاصّاً، أو تخصيص إن كان عامّاً."]]},{"id":"u45_6","kind":"text","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ٦","segs":[["ctx","ويحصل الازدياد في الوضوح إن كان مجملاً؛ بأن يلحقه بيان تفسير بقطعي لا شُبهة فيه يزيل خفاء المجمل والمشترك، وإن كان عاماً؛ بأن يلحقه بيان تقرير، بأن يؤكد الكلام بما يقطع احتمال المجاز أو الخصوص: كقوله تعالى: ﴿فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ﴾ [الحجر: ٣٠]، فإنَّه نصّ لسوق الكلام لبيان سجود الملائكة، ولكنَّه يحتمل التَّخصيص بإرادة البعض، فانقطع ذلك بقوله: ﴿كُلُّهُمۡ﴾، وبقي احتمال التَّأويل، وهو الحمل على التَّفريق، فانقطع هذا الاحتمال بقوله: ﴿أَجۡمَعُونَ﴾."]]},{"id":"u45_7","kind":"def","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ٧","segs":[["matn","وحكمُ المُفَسَّر:"],["matn","وجوبُ العمل به على احتمال النَّسخ"],["ctx","في نفسه في زمن التَّشريع بورود نصّ متأخر ينسخه، وبعد وفاة النَّبي ﷺ انسدّ باب النَّسخ في ذاته، وبقي اجتهاد العلماء في أنَّ هذا النَّصّ منسوخٌ بهذا النَّصّ."]]},{"id":"u45_8","kind":"def","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ٨","segs":[["matn","الرَّابع: المُحكم:"],["matn","وهو ما أُحكم المرادُ به عن احتمال النَّسخ."]]},{"id":"u45_9","kind":"text","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ٩","segs":[["ctx","وانقطاع احتمال النَّسخ قد يكون لمعنى في ذاته: كالآيات الدَّالَّة على وجود الصَّانع وصفاته، فإنَّها لا تحتمل النَّسخ عقلاً، ويُسمّى هذا «مُحكماً لعينه»، وقد يكون لانقطاع الوحي بوفاةِ النَّبيِّ ﷺ ويُسَمَّى «مُحكماً لغيره»."]]},{"id":"u45_10","kind":"def","label":"أولاً: مراتب الظُّهور أربعة · الفقرة ١٠","segs":[["matn","وحكم المُحكم:"],["ctx","وجوب العمل"],["matn","من غير احتمال"],["ctx","للتَّأويل ولا للنَّسخ."]]}],"sup":"الوجه الأول: الظُّهور"},{"id":"u46","title":"ثانياً: التَّرجيح بين مراتب الظُّهور","group":"الباب الثَّاني الكتاب","units":[{"id":"u46_1","kind":"text","label":"ثانياً: التَّرجيح بين مراتب الظُّهور · الفقرة ١","segs":[["ctx","يظهر التَّفاوت بين هذه الأربعة عند التَّعارض؛ لأنَّه لا تفاوت بينها في إيجاب الحُكم قطعاً، فيصير الظَّاهر متروكاً عند معارضة النَّصّ، والظَّاهر والنَّصّ عند معارضة المُفسَّر، والمُفسَّر عند معارضة المُحكم، ومن أمثلتها:"]]},{"id":"u46_2","kind":"def","label":"ثانياً: التَّرجيح بين مراتب الظُّهور · الفقرة ٢","segs":[["matn","أ. تعارض الظَّاهر مع النَّص"],["ctx",": في قوله تعالى: ﴿وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ﴾ [النساء: ٢٤]، فإنَّه ظاهر في جواز التَّزوج من النِّساء بلا حصر بعدد، مع قوله تعالى: ﴿فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَ﴾ [النساء: ٣]، فإنَّه نَصٌّ في بيان العدد، فيُقدَّم عليه، ولا يحل الجمع بين أكثر من أربع نساء."]]},{"id":"u46_3","kind":"text","label":"ثانياً: التَّرجيح بين مراتب الظُّهور · الفقرة ٣","segs":[["ctx","وقوله تعالى: ﴿وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًا﴾ [الأحقاف: ١٥]، فإنَّه ظاهرٌ في أنَّ الإرضاع سنتين ونصف إن فُسِّر الحمل بالحمل في اليد وليس في البطن، مع قوله تعالى: ﴿۞ وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ﴾ [البقرة: ٢٣٣]، فإنَّه نَصٌّ في بيان مدّة الحمل، وهي سنتين لا غير، فيُقدَّم على الظَّاهر."]]},{"id":"u46_4","kind":"def","label":"ثانياً: التَّرجيح بين مراتب الظُّهور · الفقرة ٤","segs":[["matn","ب. تعارض النَّصّ مع المُفسَّر"],["ctx",": في قوله ﷺ: «المستحاضة تدع الصَّلاة أيّام أقرائها، ثمّ تغتسل وتتوضَّأ لكلِّ صلاةٍ وتصوم وتُصلي»، فإنَّه نصّ في وجوب الوضوء على المستحاضة لكل صلاة على حدة، مع قوله ﷺ: «المستحاضة تتوضأ لوقت كل صلاة»، فإنَّه مفسَّرٌ بوجوب الوضوء لوقت كلِّ صلاة، فيُقَدَّمُ على الوجوب لكلِّ صلاةٍ."]]},{"id":"u46_5","kind":"def","label":"ثانياً: التَّرجيح بين مراتب الظُّهور · الفقرة ٥","segs":[["matn","ج. تعارض المُفسَّر مع المُحكم"],["ctx",": في قوله تعالى: ﴿وَأَقِيمُواْ ٱلصَّلَوٰةَ﴾ [النساء: ٧٧]، فإنَّه مُفَسَّرٌ بأحاديث متواترة في كيفية الصَّلاة المطلوبة، ولم تحدد الآية أنَّه لا بد من صلوات متكررة في أوقات مختلفة، مع قوله تعالى: ﴿إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا﴾ [النساء: ١٠٣]، فإنَّه محكمٌ في لزوم الصَّلاة متكررة في أوقات، فيُقَدَّم على المُفسَّر."]]}],"sup":"الوجه الأول: الظُّهور"},{"id":"u47","title":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع","group":"الباب الثَّاني الكتاب","units":[{"id":"u47_1","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١","segs":[["matn","الأول: الخفي:"],["matn","هو اسم لكلام استتر معناه بسبب عارض نشأ من غير الصِّيغة، أو هو كلام خفي المراد به"],["ctx","بسببٍ عارضٍ، يعني أنَّ صيغة الكلام ظاهرة بالنَّظر إلى موضوعها اللغوي، لكن خفي بالنِّسبة إلى المحلّ بسببٍ عارضٍ في ذلك المحلّ."]]},{"id":"u47_2","kind":"text","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٢","segs":[["ctx","فاللفظ في نفسه واضحٌ لا خفاء فيه، لكنَّه خفيٌّ بتطبيقه على غير ما وُضِع له: كلفظ السَّارق، فهو نفسه واضحٌ في أخذ المال سرّاً، وخَفيٌّ في تطبيقه على غيره: كالنَّباّش الذي ينبش القبر ويأخذ الكفن."]]},{"id":"u47_3","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٣","segs":[["ctx","وعلامةُ كون اللفظ خفياً: أنَّه"],["matn","يحتاجُ إلى الطَّلب"],["ctx",": أي قليل تأمّل؛ لنتوصل هل يعتبر ما كان فيه خفياً من أفراده، فيطبق عليه حكمه أم لا؟"]]},{"id":"u47_4","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٤","segs":[["matn","وحكم الخفي:"],["matn","النَّظر فيما خَفي فيه لإظهار هل خفاؤه لزيادة فيه فيأخذ حكم الأصل، أو خفاؤه لنقصان فيه فلا يأخذ حكم الأصل."]]},{"id":"u47_5","kind":"text","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٥","segs":[["ctx","فيتفكر في الخفاء؛ ليظهر سبب خفائه، هل هو خفاء لأجل زيادة المعنى فيه أو لأجل نقصان المعنى فيه: كآية السَّرقة، فإنَّها ظاهرةٌ في إيجابِ قطع كلِّ سارق أَخَذَ المال سِرّاً من حرز، خَفيةٌ في حَقّ الطَّرّار: وهو الذي يطرّ الهَمايين: أي يَشقُّ حزام النَّفقة ويقطعها ويأخذ ما فيها من المال سِرّاً وبسرعةٍ، وفي حقِّ النَّبَّاش: وهو الذي ينبش القبور ويأخذ أَكفان الموتى."]]},{"id":"u47_6","kind":"text","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٦","segs":[["ctx","فعندما نتأمّل نجد أنَّ الخفاء لعارضٍ في غيرِ صيغةِ الآية، وهو اختصاص الطَّرَّار والنَّبّاش باسم آخر يُعرفان به، وتغاير الأسماء يَدلُّ على تغاير المُسَمّيات، فتؤمُّل في هذا الاختصاص لكلّ من الطَّرّار والنَّبّاش مع أصل السَّرقة، وهو أنَّ الطَّرَّار يُسارق عين اليقظان فعُدِّي حكم السَّرقة من الحدّ إلى الطَّرَّار؛ لوجود معنى السَّارق مع زيادة، وهي الأخذ بسرعة."]]},{"id":"u47_7","kind":"text","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٧","segs":[["ctx","وفي النَّبَّاش لم يوجد معنى السَّارق؛ لقصور معنى النَّبَّاش عن السَّارق؛ لأنَّ النَّبَّاش إنَّما يُسارق مَن عساه يهجم عليه القبر، وهذا لا يُعَدُّ من الأخذِ خفيةً من حرزٍ، فلم يُعَدَّ حكم السَّارق من الحدّ إلى النَّبَّاش."]]},{"id":"u47_8","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٨","segs":[["matn","الثَّاني: المشكل:"],["matn","وهو اسم لكلام يحتمل المعاني المتعددة، ويكون المراد واحداً منها"],["ctx","، فالإشكالُ في نفس اللفظ باعتبار صيغته لا لأمر خارجيّ؛ لاحتوائه على عدّة معاني،"],["matn","وهو فوقُ الخفي"],["ctx","في خفاء المراد؛ لاحتياجه لمرحلتين:"]]},{"id":"u47_9","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٩","segs":[["matn","أ. الطَّلب"],["ctx",": وهو تحصيلُ المعنى التي يشتمل عليها اللفظ."]]},{"id":"u47_10","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١٠","segs":[["ctx","ب."],["matn","التَّأمّل"],["ctx",": وهو التكلُّفُ والاجتهادُ في الفكر بعد ذلك؛ ليتميّز المراد من بين هذه المعاني."]]},{"id":"u47_11","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١١","segs":[["matn","وحكم المشكل:"],["matn","اعتقاد حَقيّةِ المرادِ إلى أن يتبيّن بالطَّلب والتَّأمّل"],["ctx","، ومثاله:"]]},{"id":"u47_12","kind":"text","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١٢","segs":[["ctx","كلمة: ﴿أَنَّىٰ﴾ في قوله تعالى: ﴿فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡ﴾ [البقرة: ٢٢٣]، جاءت في القرآن بعدّة معاني، فطلبتُ معاني: ﴿أَنَّىٰ﴾ حيث استعملت بمعنى: «أين» في قوله تعالى: ﴿أَنَّىٰ لَكِ هَٰذَا﴾ [آل عمران: ٣٧]: أي من أين لك هذا؟ وبمعنى «كيف» في قوله تعالى: ﴿أَنَّىٰ يَكُونُ لِي غُلَٰمٞ﴾ [آل عمران: ٤٠]."]]},{"id":"u47_13","kind":"text","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١٣","segs":[["ctx","ثم تؤمل ونظر هل يجوز إتيان المرأة في القُبل والدُّبر باعتبار معنى «أين»، أو يجوز إتيان المرأة في القُبل فقط باعتبار معنى «كيف» الدَّالة على الأوصاف لا على المواضع: أي كيف شئتم، سواء كانت قاعدةً أو مضطجعةً أو على أي جهةٍ بعد أن يكون المأتى واحداً، وهو القُبُل، فَتَرجُح «كيف»؛ لأنَّ سياق الآية سَمّاهنّ حرثاً: أي مواضع حرثكم، لما يلقى في أرحامهنّ من النُّطف التّي هي بمنزلة البذر للنَّسل، فيكون الإتيان في الموضع الذي يتعلّق به هذا الغرض، وهو القُبُل."]]},{"id":"u47_14","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١٤","segs":[["matn","الثَّالث: المُجْمَل:"],["ctx","ما خفي المراد منه خفاء لا يدركُ إلا ببيان من المُجْمِل، أو"],["matn","هو"],["ctx","كلامٌ"],["matn","اشتبه"],["ctx","المراد منه؛ لتزاحم المعاني فيه من غيرِ رجحان لأحدها إلا ببيان من الشَّارع الحكيم، وهو أكثر خفاء من المشكل؛ لاحتياجه إلى ثلاثة مراحل:"]]},{"id":"u47_15","kind":"text","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١٥","segs":[["ctx","أ. الطلب: بأن يطلب المعاني التي يشتملها اللفظ: كلفظ الصَّلاة فيجمع معانيه من دعاء وإِليَتين وغيرها."]]},{"id":"u47_16","kind":"text","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١٦","segs":[["ctx","ب. التَّأمل: بأن يجتهد في التَّرجيح بينها، ولا يستطيع لذلك سبيلا."]]},{"id":"u47_17","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١٧","segs":[["matn","ج. الاستفسار"],["ctx","من المُجْمِل حيث لم يدرك من نفس العبارة، فيخبره الشَّارع أنَّ المقصود بالصَّلاة هيئات مخصوصات بأوقات مخصوصة."]]},{"id":"u47_18","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١٨","segs":[["matn","وحكمُ المُجْمَل:"],["matn","التَّوقُّفُ فيه إلى أن يَتَبيَّنَ مُرادُه من المُجْمِل"],["ctx",": كالصَّلاة فإنَّها في اللُّغة الدُّعاء وذلك غير مراد، وقد بيَّنَها النَّبيُّ ﷺ بالهيئات المخصوصة في الشَّريعة."]]},{"id":"u47_19","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ١٩","segs":[["matn","الرَّابع: المتشابه:"],["ctx","وهو اسم لما انقطع رجاء معرفة المراد منه للأُمَّة في الدُّنيا، أو"],["matn","هو"],["ctx","كلامٌ"],["matn","لم يُرْجَ"],["ctx","في الدُّنيا"],["matn","بيانُ"],["ctx","المراد منه"],["matn","لشدّةِ خفائه؛ لأنَّه يصير معلوماً في الآخرة لابتلاء الرَّاسخين بعدم"],["matn","الوصول إليه"],["ctx",": كالحروف المُقطَّعة في أوائل السُّور، وآيات الصِّفات مثل قوله تعالى: ﴿ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ﴾ [طه: ٥]."]]},{"id":"u47_20","kind":"def","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٢٠","segs":[["matn","وحكم المتشابه:"],["matn","التَّوقُّف فيه أبداً بعدم جواز العمل به مع اعتقاد حَقيَّة المراد به"],["ctx",": أَي اعتقاد أنَّ مرادَ الله تعالى لذلك حقّ، ﴿وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُ﴾ [آل عمران: ٧]."]]},{"id":"u47_21","kind":"text","label":"الوجهُ الثَّاني: مراتب الخفاء، وهي أربع · الفقرة ٢١","segs":[["ctx","وسبب عدم جواز العمل به قصور أفهام البشر عن العلم بمعناه، وعن الاطلاع على مراد الله تعالى منه."]]}]},{"id":"u48","title":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة","group":"الباب الثَّاني الكتاب","units":[{"id":"u48_1","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١","segs":[["matn","الأَوَّل: الحقيقة:"],["matn","وهي اسم"],["ctx","للفظ"],["matn","أُريد به"],["ctx","معنى"],["matn","وُضِع له"],["ctx","ذلك اللَّفظ."]]},{"id":"u48_2","kind":"text","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٢","segs":[["ctx","والمرادُ بالوضعِ: تعيينه للمعنى بحيث يدلّ عليه من غيرِ قرينة، فإن كان ذلك التَّعيينُ من جهةِ واضعِ اللغة فوضعٌ لغويّ، وإن كان من الشَّارعِ فوضعٌ شرعيّ، وإن كان من قومٍ مخصوصٍ فوضعٌ عرفيٌّ خاصّ، وإن كان من قوم غير مخصوصين فوضعٌ عرفيٌّ عامّ."]]},{"id":"u48_3","kind":"text","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٣","segs":[["ctx","والمعتبرُ في الحقيقة: هو الوضعُ بشيءٍ من الأوضاعِ المذكورة، وفي المجازِ عدمه."]]},{"id":"u48_4","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٤","segs":[["matn","الثَّاني: المجازُ:"],["matn","وهو اسم"],["ctx","للفظ"],["matn","أُريد به غير ما وُضِع له"],["ctx","لعلاقةٍ بينهما: أي اسم لكلّ لفظٍ أريد به غير ما وُضِع له لأجلِ مناسبةٍ بين المعنى الموضوع له وغيرِ الموضوع له: كتسمية الشُّجاع أسداً."]]},{"id":"u48_5","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٥","segs":[["matn","ومن أحكام الحقيقة والمجاز:"],["matn","١. استحالةُ اجتماع الحقيقة والمجاز مرادين بلفظٍ واحدٍ"],["ctx","في وقتٍ واحدٍ؛ بأن يكون كلٌّ منهما متعلِّقُ الحكم، نحو: «لا تقتل الأسد»، وتريد الحيوان المفترس والرَّجل الشُّجاع؛ لأنَّ الأصلَ إرادةُ الحقيقة، فإن لم تنافها إرادةُ المجاز لم ينصرف الكلام إلى المجاز، وشَرْطُ أن يحمل الكلام على المجاز هو إرادتُه للمجاز، فإن نافت الحقيقة المجاز؛ بأن كانت الحقيقة مرادةً، يمتنع اجتماع الحقيقة والمجاز."]]},{"id":"u48_6","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٦","segs":[["matn","٢. متى أَمكن العمل بالحقيقةِ سَقَطَ المجاز"],["ctx","؛ لأنَّ المستعار ـ وهو المجاز ـ خلفٌ عن الحقيقة، فلا يزاحم المستعار الأصل."]]},{"id":"u48_7","kind":"text","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٧","segs":[["ctx","فلو كان للفظ حقيقة مستعملة ومجاز متعارف، فالعمل بالحقيقة عند أبي حنيفة وبالمجاز عند أبي يوسف ومحمّد، كما إذا حلف لا يأكل حنطة، فاليمينُ عنده على عينها، وعندهما على ما يتخذ منها."]]},{"id":"u48_8","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٨","segs":[["matn","٣. الحالات التي تُترك فيه الحقيقة إلى المجاز كثيرة، ومنها:"]]},{"id":"u48_9","kind":"text","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٩","segs":[["ctx","أ. إن كانت الحقيقةُ متعذِّرةً ـ وهي ما لا يُصاب به إلا بمشقّة ـ تحوَّل القولُ إلى المجاز، كما إذا حَلَف لا يأكل من هذه النَّخلةِ ولا نِيّة له، تحوَّلت اليمين إلى ما يخرج منها بلا صنعةٍ: كالجُمَّار والطَّلع والرَّامخ والبُسر والرُّطب وصفره والتَّمر والنَّبيذ والخلّ المتخذ منه."]]},{"id":"u48_10","kind":"text","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١٠","segs":[["ctx","ب. إن كانت الحقيقة مهجورةً: وهي ما يُمكن الوصولُ إليها إلاّ أنَّ النَّاسَ هجروها ـ أي تركوها ـ كما إذا حَلَفَ لا يضع قدمَه في دارِ فلان؛ لأنَّ حقيقةَ وضع قدمه حافياً وإن لم يدخل مهجورٌ عرفاً، فلا أحد يذهب لدار آخر ويضع قدمه في بيته ثم يخرج، والمهجورُ عرفاً كالمتعذِّر تحقُّقُه، فينصرف اليمينُ إلى دخول الدَّار، وهو المجاز المتعارف، فيحنث إن دخل الحالف الدَّار مطلقاً."]]},{"id":"u48_11","kind":"text","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١١","segs":[["ctx","ومَن حَلَفَ لا يأكل رأساً، فالحقيقةُ ما يُسمَّى رأساً من أيِّ حيوانٍ مأكول، ولكنَّه متروك عادةً، فيقع يمين الحالف على ما يُباع في الأسواق بعد كبسه في التَّنانير وسلقه؛ بدلالة العادة، فإنَّه هو المقصود بالرَّأس عند الإطلاق."]]},{"id":"u48_12","kind":"text","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١٢","segs":[["ctx","والمهجورُ شرعاً كالمهجور عادة: كالخصومةِ مهجورةٌ شرعاً؛ لقوله تعالى: ﴿وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ﴾ [الأنفال: ٤٦]، فإذا وَكَّل عمرو زيداً في خصومةٍ مع رجلٍ بأن يدفع ما يدّعيه هذا الرَّجل على عمرو، وتَبَيَّن لزيدٍ أنَّ الحقّ مع هذا الرَّجل، فله أن يُقِرَّ بذلك على عمرو، ويقول: الحقُّ للرَّجل، وإن تبيَّن لزيدٍ أنَّ الحقَّ مع عمرو فعليه أن يدفعَ عنه ويقول: الحقّ مع عمرو، فكان زيدٌ بهذا التَّوكيل له الحقّ في الإجابة بنعم: أي الحقّ مع عمرو، أو لا: أي لا حقّ مع عمرو، لا أنَّ زيداً يُصِرُّ على الباطل ودائماً يدَّعي الحقّ مع عمرو؛ لأنَّ هذا شرعاً لا يجوز، فلا ينصرف التَّوكيل له، ويكون مهجوراً شرعاً."]]},{"id":"u48_13","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١٣","segs":[["ctx","ج. إن كان الكلام على حقيقته لا يستقيم إلا بتقدير محذوف، فيحمل على المجاز بعد هذا التَّقدير، ويُسمّى بـ: «"],["matn","دلالةٍ في محلِّ الكلام"],["ctx","»: أي يدلُّ محلُّ الكلام على أنَّ الحقيقةَ تُرِكَت فلم تكن مرادةً، كـ: «إنَّما الأعمال بالنِّيات» دلَّ وجود الأعمال بغير نيّة على أنَّه صرف عن وجود الأعمال إلى حكم الأعمال، فيكون التَّقدير: إنَّما ثواب أو حكم الأعمال بالنيات؛ لأنَّ الأفعال توجد بدون الثَّواب أو الحكم، فدلَّ على عدم استقامة الكلام بدون هذا التَّقدير."]]},{"id":"u48_14","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١٤","segs":[["ctx","د. إن كان حال المتكلّم يصرف الكلام عن حقيقته، ويُسمَّى بـ: «"],["matn","دلالة معنى يرجع إلى المتكلِّم"],["ctx","» كما في يمين الفور، وهي المنع عن الفعل حالاً لا مستقبلاً: كمَن أرادت امرأتُه أن تخرج في الغضب ونحوه، فقال: والله ما تخرجين أو إن خرجتِ فأنتِ طالق، فمكثت ساعةً ثم خرجت لم يحنث، فالحقيقةُ عدمُ الخروج أبداً، تُرك هذا وحُمل على الخروج المُعيَّن، وهو هذه السَّاعة، وهو ما مَنَعَ منه الزَّوج للزَّوجة بدلالةِ حال المتكلِّم، وهو إرادةُ المنع الخاصّ لا المنع أَبداً."]]},{"id":"u48_15","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١٥","segs":[["ctx","هـ. إن كان سياق الكلام يصرفه عن الحقيقية، ويُسمَّى بـ: «"],["matn","دلالةِ سياق النَّظم"],["ctx","»، والمقصود بسياق النَّظم قرينةٌ لفظيّةٌ التحقت بالكلام تمنع حمله على حقيقته، مثل قول الرَّجل لآخر: طَلِّق امرأتي إن كنت رجلاً، فإنَّ زيادة «إن كنت رجلاً»، أخرجت الكلام عن حقيقته، وهي التَّوكيل إلى المجاز وهو التَّوبيخ."]]},{"id":"u48_16","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١٦","segs":[["ctx","و. إن كان تركيب اللفظ لغةً يصرفه عن حقيقته، ويُسمّى بـ: «"],["matn","دلالةِ اللفظ في نفسِه"],["ctx","»، فهل يراعى الأصل الذي اشتق منه أم يبقى على إطلاقه، فمَن حَلَفَ لا يأكل لحماً لا يَقَعُ على لحم السَّمك؛ لأنَّ اللَّحمَ ينبئ عن الشِّدَّة بدلالة التحام الحرب والجرح، والملحمة وهي بالدَّم، ولا دم في السَّمك؛ ولذا يعيش في الماء ويَحِلّ بلا ذكاة، فعندما راعينا أصل اشتقاق اللَّحم خرج السَّمك، ولم يعد مقصوداً مجازاً؛ لأنَّ اللَّحم مطلقاً ينصرفُ إلى الكامل في الحقيقةِ، وهو اللَّحم بالدَّم، فدلالةُ الاشتقاق والإطلاق صَرَفَت اليمين عن السَّمك."]]},{"id":"u48_17","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١٧","segs":[["matn","الثَّالث: الصَّريح:"],["matn","وهو"],["ctx","لفظ"],["matn","ظَهَرَ"],["ctx","المرادُ منه ظُهوراً تامّاً بكثرةِ الاستعمال، احترز به عن الظَّاهر، فإنَّ الظُّهور فيه ليس بتام؛ لبقاء الاحتمال، وبكثرة الاستعمال يخرج النَّصُّ والمُفسَّر؛ لأنَّ ظهورَهما بالبيانِ والقرائن لا بكثرةِ الاستعمال: كقوله: أنت حرٌّ، وأنتِ طالق."]]},{"id":"u48_18","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١٨","segs":[["matn","وحكم الصَّريح:"],["matn","ثبوت"],["ctx","ما يوجبه اللفظ الصَّريح من الحريةِ في المثال الأوّل، والطَّلاق في الثّاني حال كونه"],["matn","مستغنياً عن العزيمة"],["ctx",": أي النِّيَّة، فيقع العتق والطَّلاق المتقدِّمان نَوَى أو لم يَنو."]]},{"id":"u48_19","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ١٩","segs":[["matn","الرَّابعُ: الكنايةُ:"],["matn","وهو ما استتر المراد منه واحتمل أكثر من معنى، أو هو لفظ لم يظهر المراد به إلاّ بقرينة"],["ctx",": كهو يفعل، فإنَّ الضمير «هو» لا يُميز مَن المقصود من النَّاس زيد أو عمرو إلا بقرينةٍ تنضمُّ إلى ذلك كسبق زيد في الذِّكر، فيكون المقصود هو لا غيره."]]},{"id":"u48_20","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٢٠","segs":[["matn","وحكم الكناية:"],["matn","عدمُ العمل بالكناية بدون نيّة"],["ctx","؛ لأنَّه لا يثبت الحكم الشَّرعيّ بها إلا بنيّة المتكلّم، كما في كنايات الطَّلاق، نحو: خليّة، فإن نوى بها الطَّلاق وقعت، وإلا فلا يقع الطلاق."]]},{"id":"u48_21","kind":"def","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٢١","segs":[["matn","والأصلُ في الكلام هو الصَّريح"],["ctx","؛ لأنَّ الكلامَ للإفهام والإفادة، والصَّريحُ هو التَّامُّ في هذا المعنى،"],["matn","وفي الكناية قصورٌ"],["ctx","عن البيان؛"],["matn","لاشتباه المراد"],["ctx","فيتوقّف في إفادة المقصود على قرينةٍ."]]},{"id":"u48_22","kind":"text","label":"القسمُ الثَّالث: في وجوه استعمال ذلك النَّظم، وهو أربعة · الفقرة ٢٢","segs":[["ctx","ويظهر هذا التَّفاوت الحاصل بين الصَّريح والكناية فيما يُدرأ بالشُّبهات، حيث جاز إثباتها بالصَّريح دون الكناية، حتى لو قال لآخر: جامعتَ فلانةً، لا يجب عليه حَدّ القذف؛ لأنَّه لم يُصَرِّح بالزِّنا، ويجب إذا قال: زنيت بها، فلفظ: جامعتَ كناية وليس صريحاً في الزِّنا المُحَرَّم، بخلاف «زنيتَ»، فإنَّه صريحٌ في الفعل المُحَرَّم، فترتَّب عليه حكم الحدّ، بخلاف جامعت فلم يترتب عليه حكم الحدّ."]]}]},{"id":"u49","title":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى)","group":"الباب الثَّاني الكتاب","units":[{"id":"u49_1","kind":"text","label":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى) · الفقرة ١","segs":[["ctx","وهي أربعة أقسام؛ لأنَّه إمّا أن يدلَّ على الحكم بعبارته، أو إشارته، أو دلالته، أو اقتضائه؛ لأنَّ الحكمَ المستفاد من اللفظ إمّا أن يكون ثابتاً بنفس اللفظ أو لا."]]},{"id":"u49_2","kind":"text","label":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى) · الفقرة ٢","segs":[["ctx","فإن كان اللفظ مسوقاً فهو العبارة، وإلا فهو الإشارة."]]},{"id":"u49_3","kind":"text","label":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى) · الفقرة ٣","segs":[["ctx","وإن كان الحكم مفهوماً منه لغةً فهي الدَّلالة، أو شرعاً فهو الاقتضاء، وبيان هذه الوجوه على النَّحو الآتي:"]]},{"id":"u49_4","kind":"def","label":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى) · الفقرة ٤","segs":[["matn","الأول: الاستدلال بعبارة النَّصِّ:"],["matn","وهو اللفظ الدَّالّ على معنى سيق اللفظ له بلا تأمّل، أو هو العمل بظاهر ما سيق الكلام له."]]},{"id":"u49_5","kind":"text","label":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى) · الفقرة ٥","segs":[["ctx","فهو إثباتُ الحكم بشيءٍ ظاهر لا يحتاج إلى مَزيد تأمُّل؛ لأنَّ ظاهر الكلام يدلُّ عليه وأوتي بالكلام من أجل بيانه، فكانت دلالته على الحكم بَيِّنة وواضحة."]]},{"id":"u49_6","kind":"text","label":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى) · الفقرة ٦","segs":[["ctx","مثاله: الحكم بإيجاب سهم من الغنيمةِ للفقراءِ في قوله تعالى: ﴿مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ ۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ لِلْفُقَرَآءِ ٱلْمُهَٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ﴾ [الحشر:٨]، فدلالة الآية واضحة على استحقاق الفقراء المهاجرين بشيء من الفيء؛ لأنَّهم منهم اليتامى والمساكين وابن السَّبيل، والكلُّ متوفرٌ فيه صفة الفقر الآن، فيستحقّ الإعانة بسهم من الفيء، والآية أُوتي بها؛ لإفادة هذا الحكم."]]}]},{"id":"u49a","title":"الثَّاني: الاستدلالُ بإشارةِ النَّصِّ","group":"الباب الثَّاني الكتاب","units":[{"id":"u49a_1","kind":"def","label":"الثَّاني: الاستدلالُ بإشارةِ النَّصِّ · الفقرة ١","segs":[["matn","الثَّاني: الاستدلالُ بإشارةِ النَّصِّ:"],["matn","وهو العملُ"],["ctx","بحكم"],["matn","ثبت بنظمه"],["ctx","ـ أي بتركيبه من غير زيادة ولا نقصان؛ لأنَّه ثابتٌ بمعنىً في النَّظم ـ"],["matn","لغةً"],["ctx",": أي غير مسوق له، أو دلالة اللفظ على حكم لا يظهر ظهوراً أَولياً، ولا يكون مقصوداً ولا مسوقاً لأجله الكلام، فهو يُفهم من اللفظ مع خفاء فيه؛ لعدم ظُهوره البيِّن."]]},{"id":"u49a_2","kind":"text","label":"الثَّاني: الاستدلالُ بإشارةِ النَّصِّ · الفقرة ٢","segs":[["ctx","ومثاله: قوله تعالى: ﴿وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ﴾ [البقرة:٢٣٣]، فإنَّ الكلام سيق لإثبات النَّفقة والكسوة على الأب؛ لأنَّه المولود له، فهذا عبارة النَّصّ."]]},{"id":"u49a_3","kind":"text","label":"الثَّاني: الاستدلالُ بإشارةِ النَّصِّ · الفقرة ٣","segs":[["ctx","وفي الآيةِ إشارةٌ إلى أنَّ النَّسبَ إلى الآباء؛ لأنَّ اللام في كلمة «له»؛ للاختصاص، والأب لا يختص بالابن من حيث الملك، فيختصّ من حيث النَّسب، والآية لم تُسق لإثبات النَّسب، ولكنَّه أُفيد منها عرضاً لا قصداً."]]},{"id":"u49a_4","kind":"def","label":"الثَّاني: الاستدلالُ بإشارةِ النَّصِّ · الفقرة ٤","segs":[["matn","والعبارةُ والإشارةُ سواء في إيجاب الحكم"],["ctx","؛ لأنَّ كلاً منهما يُفيدُ الحكم بظاهره،"],["matn","ولكنَّ العبارةُ أرجح عند التَّعارض من الإشارة"],["ctx","؛ لأنَّ العبارةَ منظومٌ مسوقٌ له، والإشارة منظومٌ غيرُ مسوق."]]},{"id":"u49a_5","kind":"text","label":"الثَّاني: الاستدلالُ بإشارةِ النَّصِّ · الفقرة ٥","segs":[["ctx","مثال التَّعارض: ما أورده الشَّافعية في كتبهم من حديث: «ما رأيت من ناقصات عقل ودين... قيل: ما نقصان دينهن؟ قال: تقعد إحداهن شطر عمرها لا تصوم ولا تُصلِّ» سيق الكلام لبيانِ نقصانِ دينهنّ، وفي الحديث إشارةٌ إلى أنَّ أكثرَ الحيض خمسة عشر يوماً، أفيدت من لفظ: «شطر»: أي فهي نصف وقتها لا تصوم ولا تصلّي، وهو نصف شهر، وتعارض مع قوله ﷺ: «أقل الحيض ثلاثة أيام، وأكثرُه عشرة أيام»، وهذا عبارةُ النَّصِّ؛ لأنَّه سيق الكلام لإثبات أقلّ وأكثر الحيض، وظاهر اللفظ واضحٌ في الدَّلالة عليه، فيكون مُقدَّماً على إشارة النَّصِّ."]]},{"id":"u49a_6","kind":"def","label":"الثَّاني: الاستدلالُ بإشارةِ النَّصِّ · الفقرة ٦","segs":[["matn","وللإشارة عموم كالعبارة؛"],["ctx","لأنَّ كلاً منهما ثابتٌ بنفسِ النَّظم، فيحتمل أن يكونَ كلٌّ منهما خاصّاً وأن يكون عامّاً مخصوصَ البعض، والعموم باعتبار الصِّيغة."]]}],"sup":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى)"},{"id":"u49b","title":"الثَّالث: الاستدلال الثَّابت بدلالة النَّصِّ","group":"الباب الثَّاني الكتاب","units":[{"id":"u49b_1","kind":"def","label":"الثَّالث: الاستدلال الثَّابت بدلالة النَّصِّ · الفقرة ١","segs":[["matn","الثَّالث: الاستدلال الثَّابت بدلالة النَّصِّ:"],["matn","هو حكمٌ ثبت بسبب معنى النَّصِّ لغةً"],["ctx","لا بعين النَّصِّ، أو دلالة اللفظ على ثبوت حكم الصُّورة المذكورة للصُّورة المسكوت عنها؛ لاشتراكهما في معنىً ووصف يَعرف كُلُّ عارفٍ باللُّغة أنَّ ذلك المعنى هو علَّةُ الحكم المذكور. والمرادُ المعنى الذي يعرفه كُلُّ سامع يعرف اللُّغة من غير استنباط."]]},{"id":"u49b_2","kind":"text","label":"الثَّالث: الاستدلال الثَّابت بدلالة النَّصِّ · الفقرة ٢","segs":[["ctx","مثاله: قوله تعالى: ﴿فَلَا تَقُل لَّهُمَآ أُفٍّ﴾ [الإسراء:٢٣]، فالنَّهي عن التَّأفيف يُعلم به حرمة الضَّرب من غير اجتهاد، فحرمةُ الضَّرب حكم استفيد من معنى التَّأفيف ـ الذي هو الأذى ـ بكلمة التَّضجر."]]},{"id":"u49b_3","kind":"def","label":"الثَّالث: الاستدلال الثَّابت بدلالة النَّصِّ · الفقرة ٣","segs":[["matn","والثَّابتُ بدلالةِ النَّصِّ كالثَّابت بعبارته وإشارته"],["ctx","من حيث إنَّ كلاً منهما يوجب الحكم قطعاً؛ لاستناده إلى المعنى المفهوم من اللفظ لغةً، لكن"],["matn","عند التَّعارض"],["ctx","، فإنَّ الإشارةَ تُقَدَّمُ على الدَّلالة، وإذا قُدِّمت الإشارةُ، فالعبارةُ أَولى؛ لأنَّ في الإشارة وُجِد النَّظمُ والمعنى اللغوي، وفي الدَّلالةِ لم يوجد إلاّ المعنى اللغوي، فتَرَجَّحَت الإشارة."]]},{"id":"u49b_4","kind":"text","label":"الثَّالث: الاستدلال الثَّابت بدلالة النَّصِّ · الفقرة ٤","segs":[["ctx","ومثال تعارضهما: ما قاله الشَّافعيُّ: تجب الكفَّارة في القتل العمد؛ لأنَّها لَّما وَجَبَتْ في القتل الخطأ مع قيام عذر الخطأ، كما في قوله تعالى: ﴿وَمَن قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ﴾ [النساء:٩٢]، فلأن تجب في العمد مع انتفاء العذر فهو أَولى وأحقّ."]]},{"id":"u49b_5","kind":"text","label":"الثَّالث: الاستدلال الثَّابت بدلالة النَّصِّ · الفقرة ٥","segs":[["ctx","ولكن هذه الدَّلالة للنَّصِّ عارضها إشارة للنَّصِّ كما في قوله تعالى: ﴿وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهُۥ جَهَنَّمُ﴾ [النساء:٩٣]، فإنَّه يشير إلى عدم وجوب الكفَّارة في العمد؛ لأنَّ لفظ الجزاءَ اسمٌ للكامل التَّامّ، فلو وَجَبَت الكفَّارة لكان جهنم بعض الجزاء لا كُلَّ الجزاء، وهذا يخالف إشارة النَّصِّ، فرجِّحت الإشارة على الدَّلالة، فلم تجب كفارة في القتل العمد عند الحنفية."]]},{"id":"u49b_6","kind":"def","label":"الثَّالث: الاستدلال الثَّابت بدلالة النَّصِّ · الفقرة ٦","segs":[["matn","والثَّابتُ بدلالة النَّصِّ لا يحتمل التَّخصيص؛ إذ لا عموم للدَّلالة؛"],["ctx","لأنَّ العمومَ من أوصاف اللفظ، ولا لفظ في الدَّلالة؛ لأنَّها مستفادةٌ من المعنى."]]}],"sup":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى)"},{"id":"u49c","title":"الرَّابع: الثَّابتُ باقتضاء النَّصِّ","group":"الباب الثَّاني الكتاب","units":[{"id":"u49c_1","kind":"def","label":"الرَّابع: الثَّابتُ باقتضاء النَّصِّ · الفقرة ١","segs":[["matn","الرَّابع: الثَّابتُ باقتضاء النَّصِّ:"],["matn","وهو"],["ctx","حكمٌ"],["matn","لم يَعمل النَّصِّ إلاّ بشرط"],["ctx","تقدُّمه على النَّصِّ، أو دلالة اللفظ على معنى خارج عن منطوق الكلام يتوقَّف عليه صدقه أو صحّتُه الشَّرعيّة أو العقليّة. فيكون المقصود باقتضاء النَّصِّ: هو تقدير محذوف حتى يستقيم الكلام صدقاً أو شرعاً أو عقلاً، كما في الأمثلة الآتية:"]]},{"id":"u49c_2","kind":"def","label":"الرَّابع: الثَّابتُ باقتضاء النَّصِّ · الفقرة ٢","segs":[["matn","مثال صدقُ الكلام:"],["ctx","حديث: «إنَّ اللهَ تعالى وضع عن أُمتي الخطأُ والنِّسيان وما استكرهوا عليه»، فيقدَّر «إثم»؛ لأنَّ الكلام لا يصدق بدون تقدير محذوف فيه، وهو «الإثم»؛ لأنَّ الخطأ والنِّسيان يقعان بلا محالة من كل شخص، فكيف وُضعا عن النَّاس، فلزم التَّقدير للمحذوف."]]},{"id":"u49c_3","kind":"def","label":"الرَّابع: الثَّابتُ باقتضاء النَّصِّ · الفقرة ٣","segs":[["matn","ومثال صحَّة الكلام شرعاً:"],["ctx","قوله تعالى: ﴿فَتَحْرِيرُ رَقَبَةٍ﴾ [المجادلة:٣]، فيقدَّرُ «مملوكةً»؛ لأنَّه لا تصحّ الكفَّارة إلا بتحرير عبدٍ يملكه، فيكون في الكلام تقدير لمحذوف، حتى يصحّ الكلام شرعاً."]]},{"id":"u49c_4","kind":"def","label":"الرَّابع: الثَّابتُ باقتضاء النَّصِّ · الفقرة ٤","segs":[["matn","ومثال صحَّة الكلام عقلاً:"],["ctx","قوله تعالى: ﴿وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا﴾ [يوسف:٨٢]، فَيُقَدَّر «أهل»؛ لأنَّ القرية بنفسها لا تُسأل لكونها جماداً، وإنَّما يسأل مَن يعيش فيها من النَّاس، فيلزم تقدير محذوف للكلام حتى يستقيم من جهة العقل."]]},{"id":"u49c_5","kind":"text","label":"الرَّابع: الثَّابتُ باقتضاء النَّصِّ · الفقرة ٥","segs":[["ctx","والثَّابتُ بالاقتضاء كالثّابت بدلالة النَّصِّ في إفادته وجوب الحكم قطعاً، ولكن عند تعارض الاقتضاء مع الدَّلالة ترجَّح الدَّلالة على الاقتضاء."]]},{"id":"u49c_6","kind":"text","label":"الرَّابع: الثَّابتُ باقتضاء النَّصِّ · الفقرة ٦","segs":[["ctx","مثالُه: عن أسماء ابنة أبي بكر رضي الله عنهم أنَّ امرأة سألت النَّبي ﷺ عن الثَّوب يصيبه الدَّم من الحيضة؟ فقال ﷺ: «حُتيه ثمّ أُقرصيه بالماء ثمّ انضحيه»، فإنَّه يدلّ باقتضاءِ النَّصِّ على أنَّه لا يجوز غسلُ النَّجَس بغيرِ الماءِ من المائعات؛ لأنَّه لَّما أوجب الغَسل بالماء فمقتضى صحّته أن لا يجوز بغير الماء، ولكنَّه بعينِهِ يدلّ بدلالةِ النَّصِّ على أنَّه يجوز غسله بالمائعات؛ وذلك لأنَّ المعنى المأخوذ منه الذي يعرفه كُلُّ أحدٍ هو التَّطهيرُ، وذلك يحصلُ بالماء والمائعات جميعاً؛ لأنَّ المقصودَ وهو إزالةُ النجاسة، وهو حاصلٌ على كلِّ حالٍ، فرُجِّحت الدَّلالةُ على الاقتضاء."]]},{"id":"u49c_7","kind":"def","label":"الرَّابع: الثَّابتُ باقتضاء النَّصِّ · الفقرة ٧","segs":[["matn","والثَّابتُ بالاقتضاء لا يحتمل التَّخصيص؛ إذ لا عموم له"],["ctx","؛ لعدم وجودِ اللَّفظ فيه، والعمومُ من خصائصِ الألفاظ."]]}],"sup":"القسم الرَّابع: في وجوه الاستدلال: «الوقوف على أحكام النَّظم» (فهم المعنى)"},{"id":"u50","title":"الفصل الثاني الوجوه الفاسدة في الاستدلال على الأحكام عند الحنفية","group":"الباب الثَّاني الكتاب","units":[{"id":"u50_1","kind":"text","label":"الفصل الثاني الوجوه الفاسدة في الاستدلال على الأحكام عند الحنفية · الفقرة ١","segs":[["ctx","وما عدا هذه الوجوه الأربعة في الاستدلال على الأحكام، فهي فاسدةٌ عند الحنفيّة؛ لأنَّ الوجوه الصَّحيحة منحصرة في الأربع ـ أعني العبارة والإشارة والدَّلالة والاقتضاء ـ، وتمسَّكَ غيرُ الحنفية بوجوه أُخر في الاستدلال، فنذكر بعضها؛ لتحقيقها وبيان وجه فسادها عند الحنفيّة:"]]}]},{"id":"u51","title":"المطلب الأول: الاحتجاج بمفهوم المخالفة","group":"الباب الثَّاني الكتاب","units":[{"id":"u51_1","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ١","segs":[["matn","ويُسمّى عند الحنفية «التَّنصيصُ لا يدلُّ على التَّخصيص»:"],["matn","فالتَّنصيصُ"],["ctx","على الشَّيء باسم يدلّ على الذَّات دون الصِّفة، سواءٌ كان علماً أو اسم جنس،"],["matn","لا يدلُّ على"],["ctx","تخصيص الحكم بذلك الشَّيء؛ لأنَّه يلزم الكُفر بقوله تعالى: ﴿مُّحَمَّدٌ رَّسُولُ ٱللَّهِ﴾ [الفتح:٢٩] على قول مَن يحتج به؛ لأنَّ مفهوم المخالفة يقتضي نفي رسالة سائر الرُّسل، فلم يصلح أن يكون حجّةً."]]},{"id":"u51_2","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ٢","segs":[["matn","وبيان ذلك أنَّ المنطوق:"],["ctx","هو ما يدلّ عليه لفظ من ألفاظ العبارة، ويشمل عبارة النَّصِّ وإشارة النَّصِّ عند الحنفية."]]},{"id":"u51_3","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ٣","segs":[["matn","والمفهوم:"],["ctx","هو ما دلَّ عليه مباشرة غير اللفظ المذكور في تلك العبارة، وهو قسمان:"]]},{"id":"u51_4","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ٤","segs":[["matn","١. مفهوم الموافقة:"],["ctx","وهو دلالةُ العبارة على ثبوت حكم المنطوق للمسكوت بمجرد فهم اللغة: أي بلا توقف على رأي واجتهاد: كدلالة قوله تعالى: ﴿فَلَا تَقُل لَّهُمَآ أُفٍّ﴾ [الإسراء:٢٣] على تحريم الضَّرب والشَّتم، ويسمّى عند الحنفية «دلالة النَّصِّ»."]]},{"id":"u51_5","kind":"text","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ٥","segs":[["ctx","وهو معتبرٌ في نصوص القرآن والسُّنَّة وعبارات الفقهاء."]]},{"id":"u51_6","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ٦","segs":[["matn","٢. مفهوم المخالفة:"],["ctx","وهو دلالة العبارة على ثبوت نقيض الحكم المنطوق للمسكوت: كقوله ﷺ: «في الإبل السَّائمة زكاة»، فمفهومه المخالف عدم وجوب زكاة على الإبل المعلوفة، وهو أنواع:"]]},{"id":"u51_7","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ٧","segs":[["matn","أ. مفهوم الصِّفة؛"],["ctx","وهو ما دلَّ عليه لفظ وقع صفة لموصوف: كقوله ﷺ: «في الإبل السَّائمة زكاة»."]]},{"id":"u51_8","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ٨","segs":[["matn","ب. مفهوم الشَّرط؛"],["ctx","وهو ما دلَّ على انتفاء الحكم عند انتفاء الشَّرط: كقوله تعالى: ﴿وَإِن كُنَّ أُو۟لَٰتِ حَمْلٍ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ﴾ [الطلاق:٦]، فمفهومه المخالف أنَّ الإنفاقَ لا يجب على المطلّقة المبتوتة التي ليست حاملة."]]},{"id":"u51_9","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ٩","segs":[["matn","ج. مفهوم الغاية:"],["ctx","وهو ما دلَّ على أنَّ حكمَ المنطوق منتف فيما بعد الغاية: كقوله تعالى: ﴿وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ﴾ [المائدة:٦]، فإنَّ مفهومَه أنَّ ما وراء الكعبين لا يجب غَسله."]]},{"id":"u51_10","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ١٠","segs":[["matn","د. مفهوم العدد؛"],["ctx","وهو ما دلَّ على أنَّ حكم المنطوق مقتصر على العدد الملفوظ، ويثبت نقيض ذلك الحكم على ما وراء ذلك العدد، نحو قوله تعالى: ﴿فَٱجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةً﴾"],["matn","[النور:٤]"],["ctx","، فإنَّ مفهومه أن لا يجلد فوق ثمانين."]]},{"id":"u51_11","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ١١","segs":[["matn","هـ. مفهوم اللَّقب؛"],["ctx","وهو ما دلَّ على أنَّ حكم المنطوق مقتصر على الاسم الجامد المذكور في العبارة، وأنَّ نقيضه ثابت لغير ذلك الاسم الجامد، مثل قوله ﷺ: «الحنطة بالحنطة ....»، فتنصيصه على الأعيان السِّتة في الرِّبا يمنع جريانه في غيرها."]]},{"id":"u51_12","kind":"text","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ١٢","segs":[["ctx","وهذه الأنواع لمفهوم المخالفة معتبرةٌ عند الشَّافعيّة في نصوص القرآن والسُّنة سوى الأخير، وهو مفهوم اللقب، فغير معتمد عندهم، وعند الحنفية غير معتبر مطلقاً، بمعنى أنَّ النَّصِّ لا يدلّ على نقيض الحكم لغير المنطوق، فيبقى المفهوم مسكوتاً عنه، فإن دلَّ دليل على أنَّ حكمه حكم المنطوق عمل به، وإن دلَّ دليل على أنَّ حكمه مناقض لحكم المنطوق عُمل به."]]},{"id":"u51_13","kind":"text","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ١٣","segs":[["ctx","ومفهومُ المخالفة معتبرٌ في كتب الفقه عند الحنفيّة، وكذلك في مخاطبات النَّاس."]]},{"id":"u51_14","kind":"def","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ١٤","segs":[["matn","ووجه الفرق بين النُّصوص الشَّرعية والعبارات الفقهية:"],["ctx","إنَّ نصوص القرآن والسُّنة تحتوي على عباراتٍ بليغةٍ حكيمةٍ، فربّما تذكر فيها ألفاظ للتَّأكيد والتَّوبيخ والتَّشنيع والوعظ والتَّذكير ولا تكون قيداً لما سبق: كقوله تعالى: ﴿وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا﴾ [البقرة:٤١]، فإنَّما أضيف لفظ القليل؛ للتَّشنيع على العمل ولا يدلّ على أنَّ الاشتراءَ بالثَّمن الكثير جائزٌ، وكذلك قوله تعالى: ﴿لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَٰفًا مُّضَٰعَفَةً﴾ [آل عمران:١٣٠]، فإنَّه يدلّ على أنَّ الرِّبا جائزٌ إذا لم يكن أضعاف الأصل."]]},{"id":"u51_15","kind":"text","label":"المطلب الأول: الاحتجاج بمفهوم المخالفة · الفقرة ١٥","segs":[["ctx","أما كتب الفقه فإنَّ مقصودها تدوين الأحكام على طريقة قانونية وليس فيها شيء من التَّأكيد والتَّشنيع وغير ذلك، فلا بُدّ من اعتبار مفهوم المخالفة فيها."]]}],"sup":"الفصل الثاني الوجوه الفاسدة في الاستدلال على الأحكام عند الحنفية"},{"id":"u52","title":"المطلب الثاني: حمل المطلق على المُقَيَّد","group":"الباب الثَّاني الكتاب","units":[{"id":"u52_1","kind":"def","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ١","segs":[["matn","المطلق:"],["ctx","وهو ما دلَّ على بعض أفراد شائع لا قيد معه نحو: رقبة، أو خاصّ يدلّ على معناه الحقيقي بدون زيادة قيد."]]},{"id":"u52_2","kind":"def","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ٢","segs":[["matn","والمُقَيَّدُ:"],["ctx","وهو الدَّالُّ على مدلول المطلق بصفة زائدة، أو خاصّ يدلُّ على معناه الحقيقي بزيادة قيد."]]},{"id":"u52_3","kind":"text","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ٣","segs":[["ctx","والقيود التي تزاد في المقيد على ما يكون عليه المطلق، هي كل ما لم يبق معه المطلق على إطلاقه، سواء كان صفةً أو حالاً أو شرطاً أو عدداً أو زماناً أو مكاناً."]]},{"id":"u52_4","kind":"def","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ٤","segs":[["matn","أ. اتحاد الحادثة:"],["ctx","فيُحمل المُطلق على المُقيَّد في المحكوم به في حادثةٍ واحدةٍ في هذه الحالة فقط؛ للضَّرورة في استحالة أنّ يكون لحادثة واحدة حكمان."]]},{"id":"u52_5","kind":"text","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ٥","segs":[["ctx","مثاله: في المطلق قوله تعالى في صوم كفَّارة اليمين: ﴿ثَلَٰثَةِ أَيَّامٍ ۚ﴾ [المائدة:٨٩]؛ إذ أوجب صيام ثلاثة أيام مطلقة، سواء كانت متتابعة أو غير متتابعة، مع المقيَّد في القراءة المشهورة لابن مسعود رضي الله عنه: «ثلاثة أيّام متتابعات»؛ إذ أوجب صيام ثلاثة أيّام مقيَّدة بالتتابع، فحمل فيها المطلق على المقيّد؛ لاستحالة أن يكون لهذا الحادثة حكمان؛ بأن يصوم متتابعاً أو غير متتابع."]]},{"id":"u52_6","kind":"def","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ٦","segs":[["matn","ب. اختلاف الحادثة:"],["ctx","فلا يُحمل المُطلق على المُقيَّد في المحكوم به في حادثتين."]]},{"id":"u52_7","kind":"text","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ٧","segs":[["ctx","مثاله: المطلق في قوله تعالى في كفّارة الظِّهار: ﴿فَتَحْرِيرُ رَقَبَةٍ﴾ [المجادلة:٣]؛ إذ أوجب في الكفَّارة رقبة مطلقة مسلمة أو غير مسلمة، مع المقيَّد في قوله تعالى في كفَّارة القتل: ﴿فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ﴾ [النساء:٩٢]؛ إذ أوجب في الكفَّارة رقبةً مُقيَّدةً بأن تكون مسلمةً، فلا يحمل المطلق على المقيّد فيها، فيعمل في كفَّارة الظِّهار بمطلق رقبةٍ، ويُعمل في كفَّارة القتل برقبةٍ مقيّدةٍ بالإيمان."]]},{"id":"u52_8","kind":"def","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ٨","segs":[["matn","أ. اتحاد الحادثة:"],["ctx","فلا يُحمل فيها المُطلق على المُقيَّد في سبب الحكم في حادثة واحدة:"]]},{"id":"u52_9","kind":"text","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ٩","segs":[["ctx","مثاله: في المطلق قوله ﷺ: «أدّوا صاعاً من قمح بين اثنين أو صاعاً من تمر، أو صاعاً من شعير، عن كلِّ حرٍّ وعبدٍ، صغيرٍ أو كبيرٍ»؛ إذ بيَّن أنَّ سبب الفطرة كونه عبداً مطلقاً، مسلماً أو غير مسلم، مع المُقيَّد: وهو قول ابن عمر رضي الله عنه: «فَرَضَ رسولُ الله ﷺ زكاة الفطر من رمضان، صاعاً من تمر أو صاعاً من شعير، على العبد والحرِّ، والذَّكر والأُنثى، والصَّغير والكبير من المسلمين»؛ إذ بيَّن أنَّ سبب الفطرة كونه العبد مسلماً، فلا يحمل فيها المطلق على المقيد، بل يعمل في المطلق على إطلاقه، فيجب أن يخرج صدقة الفطر عن عبده المسلم وغير المسلم، ويعمل في المقيَّد بتقييده، فيخرج عن عبده المسلم، فيكون نتيجة الحديثين أنَّه يخرج عن العبدِ المسلم والكافر."]]},{"id":"u52_10","kind":"text","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ١٠","segs":[["ctx","وهذا يُعَدُّ من السَّببِ للفطرةِ لكونه بهذه الأوصاف، فيترتب نتيجة هذه العلَّة للمسألة الحكم لها، وهو وجوب الإخراج لصدقة الفطر عنهم؛ إذ أنَّ سبب الفطرة عند الحنفية هو رأسٌ يمونه: أي يجب نفقتُه عليه، ويلي عليه ولاية كاملة: أي ينفذ قوله عليه رضي أم لم يرض، فالعبدُ نفقتُه على سيدِه وينفذ قول السَّيد عليه مطلقاً، وكذلك الابن الصَّغير نفقتُه واجبةٌ على والدِه، وينفذ قوله عليه مطلقاً، وهكذا."]]},{"id":"u52_11","kind":"def","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ١١","segs":[["matn","ب. اختلاف الحادثة:"],["ctx","فلا يُحمل المُطلق على المُقيَّد في سبب الحكم في اختلاف الحادثة، مثاله: في المطلق في قوله تعالى: ﴿وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا﴾ [المائدة:٣٨]؛ إذ اليد مطلقة فلم يبيِّن مقدار القطع فيها، مع المقيد في قوله تعالى: ﴿فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ﴾ [المائدة:٦]؛ إذ بيَّن أنَّ الغَسل في الوضوء إلى المرافق، فلا يُحمل المُطلق على المُقيَّد، فيلزم منها القطع إلى المرافق، بل يعمل بكلّ واحدة منها على حدة، لكن ثبت في الأحاديث المشهورة أنَّ النبي ﷺ قطع من الزَّند، فيكون التَّقييد جاء من تلك الأحاديث؛ لكونها في حادثة واحدة في المحكوم به؛ لاستحالة اجتماع حكمين لمسألة واحدة."]]},{"id":"u52_12","kind":"text","label":"المطلب الثاني: حمل المطلق على المُقَيَّد · الفقرة ١٢","segs":[["ctx","وإنَّما لا يُحمل المُطلق على المُقيَّد في غير الصُّورة الأُولى التي سبقت؛ لإمكان العمل بالدَّليلين في المطلق على إطلاقه، وفي المقيَّد على تقييده، وكلُّ ما أَمكن إعمال الدَّليلين وَجَبَ بالعمل بهما، وهو أولى من إهمال أحدهما."]]}],"sup":"الفصل الثاني الوجوه الفاسدة في الاستدلال على الأحكام عند الحنفية"},{"id":"u53","title":"المطلب الثالث: القِران في النَّظم يُوجبُ القِران في الحكم","group":"الباب الثَّاني الكتاب","units":[{"id":"u53_1","kind":"def","label":"المطلب الثالث: القِران في النَّظم يُوجبُ القِران في الحكم · الفقرة ١","segs":[["matn","فمعنى القِران في النَّظم:"],["ctx","أي الجمع بين كلامين بحرفِ العطف، نحو قوله تعالى: ﴿وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ﴾ [البقرة:٨٣]، فإنَّه"],["matn","لا يوجب القِران في الحكم"],["ctx",": أي لا يَلزم منه الاتفاق في الحكم بين المقترنين."]]},{"id":"u53_2","kind":"text","label":"المطلب الثالث: القِران في النَّظم يُوجبُ القِران في الحكم · الفقرة ٢","segs":[["ctx","واستدل بعضُهم بأنَّ الزَّكاةَ لا تجب على الصَّغير؛ لأنَّ الصَّلاة لا تجب على الصَّغير؛ لاقترانهما معاً في قوله تعالى: ﴿وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ﴾؛ لأنَّ العطفَ موجبٌ الاشتراك، وهما جملتان كاملتان عُطِفَت إحداهما على الأُخرى بالواو، فيقتضي التَّسويةَ بينهما في الحكم."]]},{"id":"u53_3","kind":"text","label":"المطلب الثالث: القِران في النَّظم يُوجبُ القِران في الحكم · الفقرة ٣","segs":[["ctx","وعند الحنفية: لا تجب الزَّكاة على الصَّبيّ، لكن لا لأجل العطف الوارد في الآية؛ لأنَّهم لم يعتبروا أنَّ الاقترانَ في النَّظم موجبٌ الاقتران في الحكم، بل لأنَّها عبادةٌ، وهي واجبةٌ على المكلّفين، والصَّغيرُ ليس مكلّفاً بالعبادات، فلا تجب عليه."]]},{"id":"u53_4","kind":"def","label":"المطلب الثالث: القِران في النَّظم يُوجبُ القِران في الحكم · الفقرة ٤","segs":[["matn","والعطف في الجملة على الجملة لا يوجب الشَّركة؛ لأنَّ الشَّركةَ إنَّما وجبت في الجملة النَّاقصة لافتقارها إلى ما تتمّ به"],["ctx","وهو الخبر، مثال: هند وزينب طالق، فإنَّ هنداً كانت محتاجة إلى الخبر وهو طالق، فحصلت الشَّركة، كما في قوله تعالى: ﴿مُّحَمَّدٌ رَّسُولُ ٱللَّهِ ۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ﴾ [الفتح:٢٩]، فإنَّ جملة «محمد رسول الله» مفتقرة إلى الخبر: «أشداء على الكفار»، فاشتركت مع جملة «والذين معه» في هذا الخبر وحكمه."]]},{"id":"u53_5","kind":"def","label":"المطلب الثالث: القِران في النَّظم يُوجبُ القِران في الحكم · الفقرة ٥","segs":[["matn","فإذا تمَّت الجملة بنفسِها فلا تجب الشَّركة"],["ctx","كالتَّعليق في قوله: إن دخلت الدَّار فأنت طالق وعبدي حر، فإنَّ الجملة الأخيرة وإن كانت تامّةً إيقاعاً لكنَّها ناقصةً تعلقاً، فصارت مشتركةً معها في التَّعليق، بخلاف قوله: إن دخلت الدار فأنت طالق وزينب طالق، فإنَّه لا يعلِّق طلاق زينب؛ إذ لو كان غرضه التَّعليق لقال: وزينب بدون ذكر الخبر؛ لأنَّ خبرَ كلتا الجملتين واحدٌ، فإذا أعاده عُلِم أنَّ غرضَه التَّنجيز."]]}],"sup":"الفصل الثاني الوجوه الفاسدة في الاستدلال على الأحكام عند الحنفية"},{"id":"u55","title":"المطلب الأول: حروف العطف","group":"الباب الثَّاني الكتاب","units":[{"id":"u55_1","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١","segs":[["matn","أولاً: الواو:"],["matn","فهي لِمطلق الجمع، فلا يستفاد منها أنَّ المقارنة في النَّظم توجب المقارنة في الحكم ـ كما سبق ـ، ولا تفيد التَّرتيب بين المعطوفات، فلم يجب التَّرتيب بين أركان الوضوء:"],["ctx","﴿فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ﴾ [المائدة:٦]؛ لعدم إفادة الواو التَّرتيب."]]},{"id":"u55_2","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ٢","segs":[["matn","وقد تستعار الواو للحال"],["ctx","، وهذا يناسب معنى الواو؛ لأنَّ الإطلاقَ يحتمله، قال الله تعالى: ﴿حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا﴾ [الزمر:٧٣]: أي إذا جاءوها وأبوابها مفتوحة."]]},{"id":"u55_3","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ٣","segs":[["matn","ثانياً: الفاء:"],["matn","فهي للتَّعقيب، فيتراخى المعطوف عن المعطوف عليه لزمان وإن لطف"],["ctx","ـ أي قلَّ ذلك الزَّمان بحيث لا يدرك ـ؛ إذ لو لم يكن الزَّمان فاصلاً أصلاً كان مقارناً تستعمل فيه كلمة: «مع»، فإذا قال: إن دخلت هذه الدَّار فهذه الدَّار فأنت طالق، فالشَّرط أن تدخل الثَّانية بعد الأولى بلا تراخ، فإن دخلت الثَّانية بعد الأولى بتراخ لا تَطلُق؛ لأنَّه لم يوجد الشَّرط."]]},{"id":"u55_4","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ٤","segs":[["matn","وتستعمل الفاء في أحكام العلل"],["ctx","على سبيل الحقيقة؛ لأنَّ الفاءَ للتَّعقيب، والأحكام تعقبُ العلل، وتترتب عليها بالذَّات، وإن كانت مقارنةً لها بالزَّمان، فإذا قال: بعتُ منك هذه السِّيارة بكذا، وقال الآخر: فهي صدقة، يكون قَبولاً للبيع ـ أي قبلت فتصَّدقت ـ؛ لأنَّه رتَّب الصَّدقة على الإيجاب، ولا يترتَّب عليه إلا بعد ثبوت القَبول بطريق الاقتضاء."]]},{"id":"u55_5","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ٥","segs":[["matn","وتستعار الفاء لمعنى الواو في قوله: لهُ عليَّ درهم فدرهم حتى لزمه درهمان، وهذا معنى مجازي للفاء؛"],["ctx","إذ التَّعقيب إنَّما يكون في الأعراض دون الأعيان، والدِّرهمُ عينٌ لا يتصوّر فيه التَّعقيب إلاّ بسبب الوجوب في الذِّمَّة، والحال أنَّه لم يباشر سبباً آخر بعد التَّكلّم بالدِّرهم الأوّل حتى يكون وجوب هذا عقيب الأوّل، فلا بُدّ أن يكون بمعنى الواو، فيلزمه درهمان."]]},{"id":"u55_6","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ٦","segs":[["matn","ثالثاً: ثُمَّ:"],["matn","وهي للتَّرتيب مع التَّراخي بمنزلة ما لو سكت ثُمَّ استأنف"],["ctx","، فإذا قال: أنت طالق ثُمَّ طالق، فكأنَّه سكت على قوله: أنت طالق وبعد ذلك قال: ثُمَّ طالق، وهذا هو الكامل في التَّراخي: أي في التَّكلّم والحكم جميعاً."]]},{"id":"u55_7","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ٧","segs":[["ctx","فلو"],["matn","قال لزوجته غير المدخول بها: أنت طالق، ثُمَّ طالق، ثُمَّ طالق إن دخلت الدَّار، فيقع الطَّلاق الأوّل ويلغو الثَّاني والثَّالث"],["ctx","؛ لأنَّ التَّراخي لَّما كان في التَّكلُّم فكأنَّه قال: أنت طالق وسكت على هذا القدر، فوقع هذا الطَّلاق ولم يبق محلاً لما بعده؛ لأنَّها غيرُ موطوءة فيلغو."]]},{"id":"u55_8","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ٨","segs":[["matn","رابعاً: بل:"],["matn","وهي لإثبات ما بعد «بل» والإعراض عمّا قبل «بل» على سبيل تدارك الغلط"],["ctx","، بمعنى أَنَّا غلطنا في تكلّم ما قبل بل؛ إذ لم يكن مقصوداً لنا، وإنَّما المقصود ما بعده، فإذا قلت: جاءني زيدٌ بل عمروٌ، كان معناه: أنَّ المقصودَ إثباتُ المجيءِ لعمرو لا لزيد."]]},{"id":"u55_9","kind":"text","label":"المطلب الأول: حروف العطف · الفقرة ٩","segs":[["ctx","فلو قال رجل لزوجته المدخول بها: أنت طالق واحدة بل ثنتين يقع ثلاثاً؛ لأنَّه أراد أن يضربَ عن الواحدة إلى الاثنتين، فالقياسُ يقتضي أن لا يقع الأوّل بل الآخر، ولكن لَّما لم يصحّ الإعراض عن الطَّلاق فيعمل الأوّل والآخر معاً فيقع الثَّلاث؛ لأنَّ الإعراضَ عمّا قبله إنَّما يصحّ إذا كان ما قبله صالحاً للإعراض، كما في الأخبار، أمّا في الإنشاءات، فلا يُمكن ذلك، فيقع الأول والثَّاني جميعاً."]]},{"id":"u55_10","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١٠","segs":[["matn","خامساً: لكن:"],["matn","وهي للاستدراك بعد النَّفي"],["ctx",": أي دفع توهم ناشئ من الكلام السَّابق كقولك: ما جاءني زيد، فأوهم أنَّ عَمراً أيضاً لم يجء لمناسبة وملازمة بينهما، فاستدركت بقولك: لكن عمرو."]]},{"id":"u55_11","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١١","segs":[["matn","وإن كان عطف مفرد على مفرد يشترط وقوعها بعد النَّفي، وإن كان عطف جملة على جملة يقع بعد النَّفي والإثبات."]]},{"id":"u55_12","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١٢","segs":[["ctx","و"],["matn","يصحّ العطف عند اتساق الكلام وإلا فهو مستأنف"],["ctx","، ونعني بالاتساق: أن يكون «لكن» موصولاً بالكلام السَّابق، ولا يكون نفي فعل وإثباته بعينه، بل يكون النَّفي راجعاً إلى شيء، والإثبات إلى شيء آخر، وإن فُقِد أحد الشَّرطين فحينئذٍ يكون الكلام مستأنفاً مبتدأ لا معطوفاً كقوله: حضر محمد لكن عليٌّ قويٌّ، فيكون مستأنفاً؛ لعدم الاتساق، ولا يوجد فيه نفي لشيءٍ وإثبات لآخر."]]},{"id":"u55_13","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١٣","segs":[["matn","سادساً: أو:"],["matn","وهو لأحد المذكورين"],["ctx","كما في قول الزَّوج لزوجته: هذه طالق أو هذه، فمعناه كقول الزَّوج: إحداهما طالق."]]},{"id":"u55_14","kind":"text","label":"المطلب الأول: حروف العطف · الفقرة ١٤","segs":[["ctx","يعني أنَّ قولَه: هذه طالق أو هذه إنشاءٌ من حيث الشَّرع؛ لأنَّ الشَّرعَ وضعه لإيجادِ الطَّلاق بهذا اللفظ، ولكنَّه يحتمل أن يكون إخباراً عن طلاق سابق على هذا الكلام؛ لأجل كونه خبراً من حيث اللغة، ولما كان ذا جهتين فأوجب التَّخيير: أي تخيير المتكلّم من حيث كونه إنشاءً بعد ذلك؛ بأن يوقع الطَّلاق في أيّتهما شاء، ويُعيِّن أنَّ هذا كان مراداً لي على احتمال أن يكون هذا التَّعيين بياناً للخبر المجهول الصَّادر عنه من حيث كونه خبراً."]]},{"id":"u55_15","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١٥","segs":[["matn","وتُستعارُ «أو» للعموم فتصير بمعنى «واو» العطف لا عينها"],["ctx","، يعني كما أنَّ الواوَ تدلُّ على إثبات الحكم للمعطوف والمعطوف عليه كليهما، فكذلك: أو؛ فتكون بمعنى الواو، لكن الواو تدلُّ على الاجتماع والشُّمول، و«أو» تدلُّ على انفرادِ كلٍّ منهما عن الآخر، فلا تكون عينها."]]},{"id":"u55_16","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١٦","segs":[["matn","ومثاله: قوله: والله لا أُكلم فلاناً أو فلاناً، حتى إذا كلَّم أحدَهما يحنث، ولو كلَّمهما لم يحنث إلاّ مرّةً"],["ctx","؛ لأنَّها لم تكن عين الواو، فلو كلَّمهما جميعاً لم يحنث إلا مرةً، ولم يجب عليه إلا كفَّارة يمين واحدة؛ إذ هتك حرمة اسم الله تعالى لم يوجد إلا مرّةً واحدة، ولو كانت عين الواو لصار بمنزلة اليمينين، فتجب الكفَّارة لكلّ واحدٍ منهما على حدة."]]},{"id":"u55_17","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١٧","segs":[["matn","سابعاً: حتى:"],["matn","وهي للغاية؛"],["ctx","لأنَّ الأصلَ فيها معنى الغاية كـ«إلى»، بأنْ يكونَ ما بعدها جزءٌ لما قبلها كما في المثال: أكلت السَّمكةَ حتى رأسَها."]]},{"id":"u55_18","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١٨","segs":[["matn","وتجيء للعطف"],["ctx","، فيَتبع ما بعدها لما قبلها في الإعراب، وشرطها أن يكون المعطوف جزءاً من المعطوفِ عليه، فيكون المعطوف إما أفضل أو أخس، مثل قولك: مات النَّاس حتى الأنبياء، وَقَدِمَ الحجاج حتى المشاة، ولا يجوز جاء الرِّجال حتى هند، ويشترط أن يكون حكم ما قبلها مما ينقضي شيئاً فشيئاً إلى الأعلى أو الأدنى."]]},{"id":"u55_19","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ١٩","segs":[["matn","وتدخل على الأفعال بأن تجعلَ غايةً، ويحتملَ صدر الكلام الامتداد، وأن يصلحَ الآخرُ دلالةً على الانتهاء:"],["ctx","كقوله: سرت حتى أدخلها، فالسير يحتمل الامتداد إلى مدّةٍ مديدةٍ، والدُّخولُ يصلح للانتهاءِ إليه."]]},{"id":"u55_20","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ٢٠","segs":[["matn","وإن صلح الأوّل أن يكون سبباً للثَّاني تكون بمعنى «كي»"],["ctx","، مثل: أسلمت حتى أُدخل الجنَّة: أي كي أُدخل الجنَّة."]]},{"id":"u55_21","kind":"def","label":"المطلب الأول: حروف العطف · الفقرة ٢١","segs":[["matn","وإن تكن للغاية أو السَّببية فتدل على العطف المجرد، فتكون دالةً على التَّعقيب كالفاء"],["ctx","، كقوله: إن لم آتك حتى أتغدى عندك فزوجتي طالق، لعدم استقامة المجاز، فإنَّ التَّغديةَ في هذا المثال فعلُ المتكلِّم كالإتيان، والإنسانُ لا يُجازي نفسَه في العادة."]]}],"sup":"الفصل الثَّالث حروف المعاني"},{"id":"u56","title":"المطلب الثَّاني: حروف الجرّ","group":"الباب الثَّاني الكتاب","units":[{"id":"u56_1","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ١","segs":[["matn","أَوَّلاً: حرفُ «الباء»:"],["matn","وهي للإلصاق"],["ctx","، فتدخل على الوسائل، كما في مسح الرَّأس، قال تعالى: ﴿وَٱمْسَحُوا۟ بِرُءُوسِكُمْ﴾ [المائدة:٦]: أي امسحوا روؤسكم ملصقين فيها أيديكم، فوجب مقدار اليد، وهو الرُّبع."]]},{"id":"u56_2","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ٢","segs":[["matn","وتصحب الباء الأثمان"],["ctx","، فلو قال المشتري: اشتريتُ منك الدَّفتر بكيلو سكر، كان السُّكر هو الثَّمن، فيجوز استبداله بغيره، بحيث يتفقان أن يدفع رزاً مثلاً بدل السُّكر، وجاز التَّأجيل في السُّكر؛ لأنَّه ثمنٌ، بخلاف الدَّفتر فلا يجوز الاستبدال والتَّأجيل فيه؛ لأنَّه مبيعٌ."]]},{"id":"u56_3","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ٣","segs":[["matn","ثانياً: حرف «على»:"],["matn","وهي للاستعلاء"],["ctx","، ويراد به الوجوب «الإلزام» نحو: له عليَّ ألف، إلا أن يقصد به الوديعة نحو: له عليَّ ألف وديعة، فيكون وديعةً لا ديناً."]]},{"id":"u56_4","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ٤","segs":[["matn","وتستعمل للشَّرط"],["ctx",": أي ما بعدها شرط لما قبلها، مثل قوله تعالى: ﴿يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًٔا﴾ [الممتحنة:١٢]: أي بشرط عدم الإشراك بالله تعالى."]]},{"id":"u56_5","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ٥","segs":[["matn","ويستعار في المعاوضات المحضة ـ"],["ctx","الخالية عن معنى الإسقاط، مثل: البيع والإجارة"],["matn","ـ بمعنى الباء"],["ctx","، فإذا استعملت «على» في المعاوضات المحضة كانت بمعنى الباء بلا خلاف، مثل قولك: بعتُ هذا على ألف، كان المعنى بألف."]]},{"id":"u56_6","kind":"text","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ٦","segs":[["ctx","أمّا غير المحضة ـ وهي التي فيها معنى الإسقاط، مثل: الطَّلاق على مال، والخلع ـ، فهي للشَّرط في الطَّلاق عند أبي حنيفة رضي الله عنه، وعند الصَّاحبين: للمعاوضة، فلو قالت: طلقني ثلاثاً على ألفٍ، فطلَّقها واحدةً، كانت بمعنى الباء عند الصَّاحبين، ويجب ثلث الألف؛ لأنَّ الطَّلاق على مال معاوضة من جانب المرأة، وعند أبي حنيفة رضي الله عنه: لا يجب ثلث الألف؛ لأنَّ الطَّلاق يحتمل التَّعليق بالشَّرط، فيُحمل على الشَّرط."]]},{"id":"u56_7","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ٧","segs":[["matn","ثالثاً: حرف «في»:"],["matn","وهي للظَّرفيّة"],["ctx","، بأن يشتمل المجرور على ما قبلها اشتمالاً مكانياً أو زمانياً، وقد تكون الظَّرفية حقيقة مثل قولهم: محمد في الأردن، وقد تكون مجازية مثل: خالد في نعمة الله تعالى: أي أنَّ النِّعمةَ محيطةٌ به إحاطة الظَّرف بالمظروف."]]},{"id":"u56_8","kind":"text","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ٨","segs":[["ctx","وتكون ظاهرةً مثل: صمتُ في هذا الشَّهر، وتكون مضمرةً مثل: صمتُ شهراً، والفرق بينهما: أنَّه في حالة الإضمار يقتضي الاستيعاب للكل، أما في حالة الإظهار فلا يقتضي الاستيعاب."]]},{"id":"u56_9","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ٩","segs":[["matn","وتستعار للمقارنة إذا لم تصلح للظَّرفية"],["ctx","، بأن كان دخولها على الأفعال، مثل: أنت طالق في دخولك الدَّار: أي لحظة دخولك الدَّار يقع الطَّلاق."]]},{"id":"u56_10","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ١٠","segs":[["matn","رابعاً: حرف «من»:"],["matn","وهي للتَّبعيض"],["ctx","، هذا أصلُ وضعها، وباقي المعاني مجازٌ فيها، مثل: أخذت من الدَّراهم: أي أخذت بعضهم."]]},{"id":"u56_11","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ١١","segs":[["matn","وتكون للبيان"],["ctx","، كما في قوله تعالى: ﴿فَٱجْتَنِبُوا۟ ٱلرِّجْسَ مِنَ ٱلْأَوْثَٰنِ﴾ [الحج:٣٠]، وخاتم من فضة: أي خاتم مصنوع من فضّة."]]},{"id":"u56_12","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ١٢","segs":[["matn","وتكون زائدة"],["ctx","، مثل: ما جاءني من أحد، فلو حذفت وقيل: ما جاءني أحدٌ، لا يتغيّر المعنى، فعُلِم أنَّها زائدةٌ."]]},{"id":"u56_13","kind":"def","label":"المطلب الثَّاني: حروف الجرّ · الفقرة ١٣","segs":[["matn","خامساً: حرف «إلى»:"],["matn","وهي لانتهاء الغاية"],["ctx","، بالدَّلالة على أنَّ ما بعدها نهايةُ حكم ما قبلها، مثل قوله تعالى: ﴿ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ﴾ [البقرة:١٨٧]، فإنَّه يدلُّ على انتهاءِ امتدادِ الصَّوم إلى الغاية الزَّمانيّة، وهي اللَّيل."]]}],"sup":"الفصل الثَّالث حروف المعاني"},{"id":"u57","title":"المطلب الثَّالث: أسماء الظُّروف","group":"الباب الثَّاني الكتاب","units":[{"id":"u57_1","kind":"def","label":"المطلب الثَّالث: أسماء الظُّروف · الفقرة ١","segs":[["matn","أولاً: «مع»:"],["matn","وهي للمقارنة"],["ctx","، فيقع اثنتان إن قال لغير المدخول بها: أنتِ طالقٌ واحدةً مع واحدةٍ؛ لوقوعهما في وقتٍ واحدٍ بسببِ المقارنة."]]},{"id":"u57_2","kind":"def","label":"المطلب الثَّالث: أسماء الظُّروف · الفقرة ٢","segs":[["matn","ثانياً: «قبل»:"],["matn","وهي للتَّقدُّم في الزَّمان على الزَّمان التي أُضيفت له"],["ctx","، فيقع واحدةً في قوله لغير المدخول بها: أنت طالقٌ واحدةً قبل واحدةٍ، ويقع ثنتان في قوله: أنت طالقٌ واحدةً قبلها واحدة؛ لأنَّ الطَّلاقَ المذكور أَوَّلاً واقعٌ في الحال، والذي وُصف بأنَّه قبل هذا الطَّلاق الواقع في الحال يقع أيضاً في الحال."]]},{"id":"u57_3","kind":"def","label":"المطلب الثَّالث: أسماء الظُّروف · الفقرة ٣","segs":[["matn","ثالثاً: «بعد»:"],["matn","وهي للتَّأخر الزَّماني عن زمان ما أُضيفت إليه"],["ctx","، فلو قال لغير المدخول بها: أنت طالقٌ واحدةً بعد واحدةٍ، فإنَّها تطلق طلقتان، وذلك كما قلنا في قوله: واحدةً قبلها واحدةٍ."]]},{"id":"u57_4","kind":"text","label":"المطلب الثَّالث: أسماء الظُّروف · الفقرة ٤","segs":[["ctx","ولو قال: واحدةً بعدها واحدةً، طَلُقت واحدةً، كما في واحدةٍ قبل واحدة."]]},{"id":"u57_5","kind":"def","label":"المطلب الثَّالث: أسماء الظُّروف · الفقرة ٥","segs":[["matn","رابعاً: «عند»:"],["matn","وهي للحضرة"],["ctx","، فقوله: لفلان عندي ألف درهم، إقرارٌ بالوديعة لا بالدَّين؛ لأنَّ الحضرةَ تدلّ على الحفظ، فمَن قال: وضعت الشَّيء عندك، يُفهم منه الاستحفاظ، ولا تدلُّ على اللزوم في الذِّمة حتى تكون ديناً، لكن لو صَرَّح بكونها ديناً، فإنَّها تُحمل على الدَّين."]]}],"sup":"الفصل الثَّالث حروف المعاني"},{"id":"u58","title":"المطلب الرَّابع: حروف الشَّرط","group":"الباب الثَّاني الكتاب","units":[{"id":"u58_1","kind":"def","label":"المطلب الرَّابع: حروف الشَّرط · الفقرة ١","segs":[["matn","أَوَّلاً: حرف «إن»:"],["matn","وهي في الأصل للشَّرط؛"],["ctx","لاختصاصه بها، فتدخل في أمر على خطر الوجود: أي مدخولها، وهو الشَّرط يكون معدوماً على خطر الوجود: أي متردِّدٍ بين أن يكون وأن لا يكون."]]},{"id":"u58_2","kind":"text","label":"المطلب الرَّابع: حروف الشَّرط · الفقرة ٢","segs":[["ctx","وقد تفرَّع على هذا: أنَّه لو قال قائل لامرأته: إن لم أطلقك فأنت طالق، فالحكم أنَّه إن لم يطلقها لا يقع الطَّلاق إلا في آخر جزء من حياته أو حياتها؛ لأنَّه علَّق وقوع الطَّلاق بعدم تطليقه إيَّاها، وهذا لا يتحقَّق إلا عند الموت، فيقع الطَّلاق في آخر جزءٍ من الحياة."]]},{"id":"u58_3","kind":"def","label":"المطلب الرَّابع: حروف الشَّرط · الفقرة ٣","segs":[["matn","ثانياً: حرف «إذا»:"],["matn","وهي"],["ctx","عند الكوفيين:"],["matn","للظَّرفِ وللشَّرطِ"],["ctx",": أي للظَّرفِ المجردِ عن الشَّرط، فتفيد زمان حصول ما بعدها، فلا تجزم الفعل، ويكون استعماله فيما هو قطعيّ الوجود، وللشَّرط المجرد عن الظَّرف، فإذا استعملت في الشَّرط لم يبق فيها معنى الوقت، وصارت بمعنى «إن»، وإليه ذهب أبو حنيفة."]]},{"id":"u58_4","kind":"text","label":"المطلب الرَّابع: حروف الشَّرط · الفقرة ٤","segs":[["ctx","وعند البصريين: حقيقة في الظَّرف، وقد تجيء للشَّرط بلا سقوط معنى الظَّرف كـ«متى»، وإليه ذهب الصَّاحبان رضي الله عنهم، ودخوله في أمر كائن أو منتظر لا محالة: أي أمر يقطع بتحقّقه في المستقبل، مثل قوله تعالى: ﴿إِذَا ٱلشَّمْسُ كُوِّرَتْ﴾ [التكوير:١]، فهي تقلب الماضي إلى المستقبل؛ لأنَّها حقيقةٌ في الاستقبال."]]},{"id":"u58_5","kind":"def","label":"المطلب الرَّابع: حروف الشَّرط · الفقرة ٥","segs":[["matn","ثالثاً: حرف «كيف»:"],["matn","وهي للسُّؤال عن الحال، وتُستعمل مجازاً بمعنى الحال إذا تعذَّر حملُها على الاستفهام"],["ctx","، كقول الرَّجل لزوجته: أنت طالق كيف شئت: أي على الحال التي تشائيها من الرَّجعة أو البينونة الصُّغرى أو الكبرى، فكيف هنا لم تستعمل في حقيقتها؛ لتعذر الاستفهام."]]}],"sup":"الفصل الثَّالث حروف المعاني"},{"id":"u59","title":"الفصل الرَّابع البيان","group":"الباب الثَّاني الكتاب","units":[{"id":"u59_1","kind":"text","label":"الفصل الرَّابع البيان · الفقرة ١","segs":[["ctx","والحجج من الكتاب والسُّنة بأَقسامهما تحتمل البيان بإظهار المراد منها."]]},{"id":"u59_2","kind":"def","label":"الفصل الرَّابع البيان · الفقرة ٢","segs":[["matn","وهو تأكيدُ الكلام بما يَقْطَعُ احتمال ما يلي:"],["matn","أ. المجاز:"],["ctx","كقوله تعالى: ﴿وَلَا طَٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ﴾ [الأنعام:٣٨]، فبجناحيه قطع الاحتمال أن يرادَ المُسرع ونحوه، ومثلُه قوله لها: أنت طالق، وقال: عنيت المعنى الشَّرعي."]]},{"id":"u59_3","kind":"def","label":"الفصل الرَّابع البيان · الفقرة ٣","segs":[["matn","ب. الخصوص:"],["ctx","كقوله تعالى: ﴿فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ﴾ [الحجر:٣٠] فـ﴿كُلُّهُمْ﴾ قطع احتمال البعض."]]},{"id":"u59_4","kind":"def","label":"الفصل الرَّابع البيان · الفقرة ٤","segs":[["matn","ويصحُّ موصولاً ومفصولاً."]]},{"id":"u59_5","kind":"def","label":"الفصل الرَّابع البيان · الفقرة ٥","segs":[["matn","وهو بيان ما فيه خفاء مما يلي:"],["matn","أ. المُجْمَل:"],["ctx","كقوله تعالى: ﴿وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ﴾ [البقرة:٨٣]، فالصَّلاةُ والزَّكاةُ مجملٌ لحقه البيانُ بالسُّنة."]]},{"id":"u59_6","kind":"def","label":"الفصل الرَّابع البيان · الفقرة ٦","segs":[["matn","ب. المشترك:"],["ctx","نحو قوله تعالى: ﴿وَٱلْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٍ﴾ [البقرة:٢٢٨]، فالقرءُ مُشْتَرَكٌ بين الطُّهر والحيض، لحِقَه البيانُ بقوله ﷺ: «طلاقُ الأمةِ ثنتان، وعدّتها حيضتان»."]]},{"id":"u59_7","kind":"def","label":"الفصل الرَّابع البيان · الفقرة ٧","segs":[["matn","وهذا القسم يصحُّ موصولاً ومفصولاً."]]}]},{"id":"u59a","title":"وهو إخراج الكلام عما كان عليه بما يلي","group":"الباب الثَّاني الكتاب","units":[{"id":"u59a_1","kind":"def","label":"وهو إخراج الكلام عما كان عليه بما يلي · الفقرة ١","segs":[["matn","وهو إخراج الكلام عما كان عليه بما يلي:"],["matn","أ. التَّعليقُ بالشَّرط:"],["ctx","كأنتِ طالق إنْ دخلتِ الدَّار؛ لأنَّه أَبطل الإيقاع وَصَيَّره يَميناً في الشَّرط."]]},{"id":"u59a_2","kind":"def","label":"وهو إخراج الكلام عما كان عليه بما يلي · الفقرة ٢","segs":[["matn","ب. الاستثناء:"],["ctx","كلَهُ عليَّ ألفٌ إلا مئةً؛ لأنَّه أَبطل الكلام في حَقّ المئة في الاستثناء. ولكنَّه بيانٌ مجازاً من حيث إنَّه بيَّن أنَّه حلفٌ لا تطليق، وأنَّه عليه تسعمئة لا أَلف."]]},{"id":"u59a_3","kind":"def","label":"وهو إخراج الكلام عما كان عليه بما يلي · الفقرة ٣","segs":[["matn","ويصحُّ موصولاً فقط"],["ctx","بالإجماع، إلاّ ما يروى عن ابن عباس رضي الله عنه."]]},{"id":"u59a_4","kind":"text","label":"وهو إخراج الكلام عما كان عليه بما يلي · الفقرة ٤","segs":[["ctx","والاستثناءُ تكلَّم بالباقي بعد الثنيا."]]},{"id":"u59a_5","kind":"text","label":"وهو إخراج الكلام عما كان عليه بما يلي · الفقرة ٥","segs":[["ctx","وإذا تعقب الاستثناء جُملاً متعاطفةً صُرِف إلى الأخيرةِ؛ لظهور ذلك، وتأييده في قوله تعالى: ﴿وَٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ثُمَّ لَمْ يَأْتُوا۟ بِأَرْبَعَةِ شُهَدَآءَ فَٱجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةً وَلَا تَقْبَلُوا۟ لَهُمْ شَهَٰدَةً أَبَدًا ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ﴾ [النور:٥] الآية الأخيرة اسمية: ﴿وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ﴾، فلا تعلّق لها بالحكام ولا بالحدّ، وما قبلها فعلية إنشائية خوطب بها الحكام للحد، إلى غير ذلك ممّا ذكر في المطولات."]]},{"id":"u59a_6","kind":"text","label":"وهو إخراج الكلام عما كان عليه بما يلي · الفقرة ٦","segs":[["ctx","وتخصيص العام ابتداء مثل هذا النَّوع، يصحّ موصولاً فقط، حتى عُرِّف بأنَّه: قصر العام على بعض أَفراده بالمستقل المتصل حقيقة أو حكماً للجهل بالتَّاريخ."]]}],"sup":"الفصل الرَّابع البيان"},{"id":"u59b","title":"٤. للضَّرورة","group":"الباب الثَّاني الكتاب","units":[{"id":"u59b_1","kind":"def","label":"٤. للضَّرورة · الفقرة ١","segs":[["matn","٤. للضَّرورة:"],["matn","وهو نوعُ بيان يقع بما لم يوضع"],["ctx","للبيان بالنُّطق، وهو البيان بالسكوت، وهو أقسام:"]]},{"id":"u59b_2","kind":"text","label":"٤. للضَّرورة · الفقرة ٢","segs":[["ctx","أ. قسم يكون في حكم المنطوق: كقوله تعالى: ﴿وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ﴾ [النساء:١١] صدر الكلام أوجب الشَّركة المطلقة، من جهة أنَّ الميراثَ أُضيف إليهما من غير بيان نصيب كلٍّ منهما، ثمّ تخصيص الأمّ بالثُّلث صار بياناً لكون الأب يستحقُّ الباقي ضرورة."]]},{"id":"u59b_3","kind":"text","label":"٤. للضَّرورة · الفقرة ٣","segs":[["ctx","ب. يثبت بدلالة حال المتكلّم: كسكوت صاحب الشَّرع عند أَمر يُعاينه: كرؤية النَّبيّ ﷺ لمضاربات الصَّحابة رضي الله عنهم وشركاتهم وما يبيعون في السَّوم ولم ينكر عليهم، فعُلِم أَنَّه مُباح، فسكوتُه أُقيم مقام الأَمر بالإباحة."]]},{"id":"u59b_4","kind":"text","label":"٤. للضَّرورة · الفقرة ٤","segs":[["ctx","ج. يثبت ضرورةَ دفع الغرور عن النَّاس: كسكوت الأب حين رأى ابنه الصغير يبيع ويشتري، فيُجعل إذناً في التِّجارة؛ دَفعاً للغرور عَمَّن يُعامل الصغير."]]},{"id":"u59b_5","kind":"text","label":"٤. للضَّرورة · الفقرة ٥","segs":[["ctx","د. يثبت ضرورة دفع طول الكلام فيما يكثر استعماله كقوله: عليَّ مئةٌ ودرهم، جُعِل العطفُ بيان أنَّ المئةَ من جنسِ المعطوف."]]},{"id":"u59b_6","kind":"def","label":"٤. للضَّرورة · الفقرة ٦","segs":[["matn","٥. للتَّبديل:"],["matn","وهو النَّسخُ"],["ctx","، قال الله تعالى: ﴿وَإِذَا بَدَّلْنَآ ءَايَةً مَّكَانَ ءَايَةٍ﴾ [النحل:١٠١]."]]},{"id":"u59b_7","kind":"def","label":"٤. للضَّرورة · الفقرة ٧","segs":[["matn","وهو اصطلاحاً: أن يَدُلَّ على خلافِ حكمِ شرعيٍّ دليلٌ شرعيٌّ متراخٍ، وهذا في حَقّ البَشَر."]]},{"id":"u59b_8","kind":"def","label":"٤. للضَّرورة · الفقرة ٨","segs":[["matn","ويُجْعَلُ في حَقِّ الشَّارع بياناً لانتهاء مدّة"],["ctx","الحكم"],["matn","المطلق"],["ctx","عن تأبيدٍ أو تأقيت"],["matn","المعلوم عند الله"],["ctx","تعالى أنَّه ينتهي في وقتِ كذا."]]},{"id":"u59b_9","kind":"text","label":"٤. للضَّرورة · الفقرة ٩","segs":[["ctx","وشَرْطُ جواز النَّسخ: التَّمكّنُ من عقدِ القلبِ عندنا، يعني لا بُدّ بعد وصول الأَمر إلى المكلَّفِ من زمانٍ قليل يَتَمَكَّن فيه من اعتقادِ ذلك الأَمر حتى يقْبَل النَّسخ بعده، ولا يشترط فيه فصلُ زمان يتمكن فيه من فعل ذلك الأمر، خلافاً للمعتزلة، فإنَّ عندهم لا بُدّ من زمان التَّمكّن من الفعل حتى يقبل النَّسخ."]]},{"id":"u59b_10","kind":"text","label":"٤. للضَّرورة · الفقرة ١٠","segs":[["ctx","ومحَلُّه: حكمٌ يحتملُ الوجودَ والعدمَ في نفسِه."]]},{"id":"u59b_11","kind":"def","label":"٤. للضَّرورة · الفقرة ١١","segs":[["matn","والقياسُ لا يصلح ناسخاً"],["ctx","للكتاب والسُّنة؛ لأنَّ الصَّحابةَ رضي الله عنهم أَجْمَعوا على تركِ الرَّأي بالكتاب والسُّنّة؛ ولأنَّ الرَّأيَّ لا مجال له في معرفة انتهاء وقتِ الحكم."]]},{"id":"u59b_12","kind":"def","label":"٤. للضَّرورة · الفقرة ١٢","segs":[["matn","والإجماعُ"],["ctx","لا يصلح ناسخاً"],["matn","عند الجمهور"],["ctx","، خلافاً لبعض المشايخ؛ لأنَّ الإجماعَ بعد عهد الرَّسول ﷺ؛ إذ لا إجماع دون رأيه وهو منفرد، ولا نسخ بعده."]]}],"sup":"الفصل الرَّابع البيان"},{"id":"u59c","title":"وأقسام النَّاسخ","group":"الباب الثَّاني الكتاب","units":[{"id":"u59c_1","kind":"def","label":"وأقسام النَّاسخ · الفقرة ١","segs":[["matn","وأقسام النَّاسخ:"],["ctx","الكتاب بالكتاب، والسُّنة بالسُّنة، والكتاب بالسُّنة، والسُّنة بالكتاب،"],["matn","فيجوز نسخُ كلٍّ من الكتابِ والسُّنَّةِ بالآخر"],["ctx","، نصَّ عليه؛ لأنَّه موضعُ الخلاف."]]},{"id":"u59c_2","kind":"text","label":"وأقسام النَّاسخ · الفقرة ٢","segs":[["ctx","مثال نسخ السُّنة بالكتاب: التَّوجُّه إلى بيتِ المقدس فعَلَه ﷺ سبعةَ عشرَ شَهْراً بالمدينة، ثمّ نُسِخَ بقوله تعالى: ﴿فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ﴾ [البقرة:١٤٤]."]]},{"id":"u59c_3","kind":"text","label":"وأقسام النَّاسخ · الفقرة ٣","segs":[["ctx","ومثال نسخ الكتاب بالسُّنة: ما روت عائشة رضي الله عنها إنَّ النَّبي ﷺ أَخبرها بأنَّ الله تعالى أَباح له من النِّساء ما يشاء، نسخ قوله تعالى: ﴿لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعْدُ﴾ [الأحزاب:٥٢]."]]},{"id":"u59c_4","kind":"def","label":"وأقسام النَّاسخ · الفقرة ٤","segs":[["matn","وأقسام المنسوخ:"],["ctx","١."],["matn","نسخُ الحكم والتِّلاوة جميعاً"],["ctx","، فعن عائشة رضي الله عنها أنَّها قالت: «كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثُمَّ نسخن بخمس معلومات، فتوفي رسول الله ﷺ وهنّ فيما يقرأ من القرآن»."]]},{"id":"u59c_5","kind":"def","label":"وأقسام النَّاسخ · الفقرة ٥","segs":[["ctx","٢."],["matn","نسخ التِّلاوة مع بقاء الحكم"],["ctx","، فعن زر رضي الله عنه قال: قال لي أُبَيّ بن كعب رضي الله عنه: «كأين تقرأ سورة الأحزاب أو كأين تعدُّها؟ قال: قلت له: ثلاثاً وسبعين آية، فقال: قط، لقد رأيتها وإنَّها لتعادل سورة البقرة، ولقد قرأنا فيها الشَّيخ والشَّيخة إذا زنيا فارجموهما البتة نكالاً من الله، والله عليم حكيم»."]]},{"id":"u59c_6","kind":"def","label":"وأقسام النَّاسخ · الفقرة ٦","segs":[["ctx","٣."],["matn","نسخُ الحكم وبقاءُ التِّلاوة"],["ctx",": كآيات المسالمة."]]},{"id":"u59c_7","kind":"def","label":"وأقسام النَّاسخ · الفقرة ٧","segs":[["ctx","٤."],["matn","نسخ وصفِ الحكم"],["ctx","مع بقاءِ أصلِه؛ بأن ينسخ عمومه وإطلاقه ويبقى أصله، كالزِّيادة على النَّصِّ؛ لأنَّ الزِّيادةَ تدفع إجزاء الأصل: كزيادة مسح الخفين على غَسل الرِّجلين."]]}],"sup":"الفصل الرَّابع البيان"},{"id":"u60","title":"الفصل الخامس شرائع من قبلنا","group":"الباب الثَّاني الكتاب","units":[{"id":"u60_1","kind":"text","label":"الفصل الخامس شرائع من قبلنا · الفقرة ١","segs":[["ctx","المراد به الأحكام الفرعيّة التي شُرعت على الأُمم السَّابقة ونزلت على أنبيائهم من عبادة وغيرها، بِدأً بسيدنا آدم عليه السلام وانتهاءً بسيدنا عيسى عليه السلام، وهي تنقسم إلى قسمين:"]]},{"id":"u60_2","kind":"def","label":"الفصل الخامس شرائع من قبلنا · الفقرة ٢","segs":[["matn","١. إن لم يصل إلينا أو وصل على لسان واحدٍ من أفرادِ تلك الأُمم"],["ctx","، فهذا النَّوع لا يلزمنا اتفاقاً؛ لأنَّهم متهمون بصحّة وروده بكتبهم؛ لثبوت تحريفهم بعضه عندنا، قال تعالى: ﴿يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ﴾ [النساء:٤٦]، ولا يقبل أيضاً بقول مَن أسلم منهم؛ لأنَّه عرف ذلك بظاهر الكتاب أو بقول جماعتهم، ولا حجّة في ذلك؛ لما سبق."]]},{"id":"u60_3","kind":"def","label":"الفصل الخامس شرائع من قبلنا · الفقرة ٣","segs":[["matn","٢. إن ورد إلينا بنصّ القرآن أو بقول رسولنا"],["ctx","، فله ثلاثة أقسام من حيث القَبول أو الرَّد:"]]},{"id":"u60_4","kind":"def","label":"الفصل الخامس شرائع من قبلنا · الفقرة ٤","segs":[["matn","أ. إن ورد منسوخاً في شريعتنا، أو على سبيل الإنكار"],["ctx","، فإنَّه لا يلزمنا العمل به وليس شرعاً لنا اتفاقاً، مثل: التَّوبة لا تقبل إلا بقتل المذنب نفسه، والنَّجاسة لا تطهر إلا بقطعها مع موضعها من الثَّوب، وتحريم كلّ ذي ظفر وبعض شحوم البقر والغنم؛ قال تعالى: ﴿وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ ۖ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ﴾ [الأنعام:١٤٦]، ثم قال: ﴿ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْ﴾ [الأنعام:١٤٦] فَعُلِمَ أنَّه لم يكن حراماً علينا، وكذا تحريم الغنائم عليهم؛ لقوله ﷺ: «وأُحلت لي الغنائم ولم تحلّ لأحدٍ قبلي»."]]},{"id":"u60_5","kind":"def","label":"الفصل الخامس شرائع من قبلنا · الفقرة ٥","segs":[["matn","ب. إن ورد إلينا وقد دلَّ الدَّليل على أننا مُكَلَّفون به"],["ctx","، وملزمون بالأخذ به، فهو شرعٌ لنا، وملزمون به اتفاقاً، مثل: وجوب الصَّوم في قوله تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ﴾ [البقرة:١٨٣]، ومشروعية الأضحية التي هي سُنَّة إبراهيم عليه السلام؛ لقول الصَّحابة رضي الله عنهم للنَّبي ﷺ: «يا رسول الله، ما هذه الأضاحي؟ قال: سُنَّة أبيكم إبراهيم»."]]},{"id":"u60_6","kind":"def","label":"الفصل الخامس شرائع من قبلنا · الفقرة ٦","segs":[["matn","ج. إن قَصَّه القرآن أو السُّنّة ولم يقترن به ما يدلُّ على نسخِهِ وإنكاره أو على لزوم فعله علينا"],["ctx","، ولم يرد في شرعنا ما يخالفه،"],["matn","فإنَّه يلزمُنا على أنَّه شريعة رسولنا ﷺ"],["ctx","لا أنَّه يلزمنا على أنَّه شريعة مَن قبلنا من الأنبياء عليهم السلام، كما في سائر ما تجدَّدَ من شريعتنا يلزمنا على أنَّه شريعةُ نبيِّنا ﷺ؛ لأنَّ النَّبي ﷺ بُعِثَ لحفظ ما أُنزل إليه من الله تعالى وتبليغه إلى الخلق، قال تعالى: ﴿سَنُقْرِئُكَ فَلَا تَنسَىٰٓ إِلَّا مَا شَآءَ ٱللَّهُ﴾ [الأعلى:٧]، وقال تعالى: ﴿يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ﴾ [المائدة:٦٧]، وما بُعث ﷺ بحفظ شرائع مَن قبله من الأنبياء وتبليغ ذلك إلى أُمَّته؛ لأنَّه لو بعث لذلك يصير كواحدٍ من دعاتهم وواحدٍ من علمائهم وخلفائهم دون أن يكون مبعوثاً ليكون رسول الله ﷺ إلى خلقه لتبليغ شريعته إليهم، فلا نكون ملزمين بشريعة الأنبياء السَّابقين مطلقاً، وقال تعالى: ﴿أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ ۖ فَبِهُدَىٰهُمُ ٱقْتَدِهْ﴾ [الأنعام:٩٠]، وقال تعالى: ﴿ثُمَّ أَوْحَيْنَآ إِلَيْكَ أَنِ ٱتَّبِعْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ﴾ [النحل:١٢٣]، وقال تعالى: ﴿شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًا﴾ [الشورى:١٣]."]]},{"id":"u60_7","kind":"def","label":"الفصل الخامس شرائع من قبلنا · الفقرة ٧","segs":[["matn","وهذا أصلٌ كبيرٌ يتفرَّعُ عليه كثيرٌ من الأحكام الفقهية، ومنها:"],["ctx","ـ قال تعالى: ﴿وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌ﴾ [المائدة:٤٥]، فالقرآن ذكر في هذه الآية وجوب القصاص بالأنفس والأطراف والأعضاء دون بيان لنسخها أو إنكارها علينا."]]},{"id":"u60_8","kind":"text","label":"الفصل الخامس شرائع من قبلنا · الفقرة ٨","segs":[["ctx","ـ قال تعالى في قصة ناقة صالح عليه السلام: ﴿لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ﴾ [الشعراء:١٥٥]، فلمّا قصَّها تعالى من غير إنكار، وجعل لناقة صالح عليه السلام شرب يوم ولقومه شرب يوم، صار شريعةً لنبينا ﷺ، فاحتج بها محمّد رضي الله عنه لجواز قسمة الشِّرب ـ أي بطريق المهايأة ـ."]]},{"id":"u60_9","kind":"text","label":"الفصل الخامس شرائع من قبلنا · الفقرة ٩","segs":[["ctx","ـ قال تعالى في حق قوم لوط عليه السلام: ﴿إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ﴾ [الأعراف:٨١] يدل على حرمة اللواطة علينا."]]}]},{"id":"u61","title":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u61_1","kind":"text","label":"الباب الثَّاني السُّنة النَّبوية الشَّريفة · الفقرة ١","segs":[["ctx","تُعدُّ السُّنة النَّبويّة الشَّريفة المصدر الثَّاني من مصادر التَّشريع الإسلامي، فنتكلَّم فيه عن تعريفها وأقسامها من حيث ورودها، والرُّواة الذين يكون خبرُهم حجّةً، وشروط الرَّاوي، وانقطاع الحديث عن رسول الله ﷺ في المُرْسَل، ونقصان في النَّاقل، ومعارضة للأقوى، والمواضع التي يكون فيها خبرُ الواحد حجّة، وأقسام الخبر من حيث الصِّدق والكذب، والطَّعن الذي يلحق الحديث، وحجّة السُّنّة ومنزلتُها في التَّشريع في المباحث الآتية:"]]}]},{"id":"u62","title":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u62_1","kind":"def","label":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم · الفقرة ١","segs":[["matn","السُّنة لغةً: الطريقة"],["ctx","، ومنها الحديث في مجوس هجر: «سُنوا بهم سُنَّة أهل الكتاب»: أي اسلكوا بهم طريقهم، يعني عاملوهم معاملة هؤلاء في إعطاء الأمان بأخذ الجزية منهم، وفي الحديث: «مَن سَنَّ في الإسلام سُنَّةً حسنةً»: أي مَن وضع طريقة حسنةً أو سيئةً."]]},{"id":"u62_2","kind":"def","label":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم · الفقرة ٢","segs":[["matn","واصطلاحاً"],["ctx","للسُّنة معاني عديدة على حسب موضوعها، فمثلاً عند الفقهاء: هي ما واظب عليه النَّبي ﷺ مع التَّرك أحياناً بلا عذر."]]},{"id":"u62_3","kind":"def","label":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم · الفقرة ٣","segs":[["matn","وعند الأصوليين: قول النَّبي ﷺ وفعله وتقريره وقول الصَّحابي رضي الله عنه وفعله."]]},{"id":"u62_4","kind":"text","label":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم · الفقرة ٤","segs":[["ctx","وإدراج قول الصَّحابي وفعله في تعريف السُّنَّة عليه عامَّة كتب الحنفية، قال السَّرَخسي: «ما سَنَّه رسول الله ﷺ والصَّحابة بعده»، وقال ابن نجيم: «قوله ﷺ وفعله، وطريقة الصَّحابة رضي الله عنهم»."]]},{"id":"u62_5","kind":"text","label":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم · الفقرة ٥","segs":[["ctx","ومَن لم يصرّح هاهنا بذكر الصَّحابة رضي الله عنهم صرَّح به في مواضع أخرى، كما فعله ابن الهمام وملا خسرو مثلاً في موضع آخر، وَنُقل الاتفاق على اعتبار فعل الصَّحابة رضي الله عنهم وأقوالهم من السُّنة."]]},{"id":"u62_6","kind":"text","label":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم · الفقرة ٦","segs":[["ctx","ويشهد لذلك: عن العِرْباض بن سارية رضي الله عنه: قال ﷺ: (مَن يعش منكم بعدي فسيرى اختلافاً كثيراً، فعليكم بسنتي وسُنّة الخلفاء المهديين الرَّاشدين، تمسّكوا بها وعضّوا عليها بالنواجذ، وإيّاكم ومُحدثات الأمور، فإنَّ كلَّ محدثة بدعة، وكلّ بدعة ضلالة»، وعن حذيفة رضي الله عنه، قال ﷺ: «اقتدوا باللذين من بعدي أبي بكر و عمر»، وعن ابن عمر رضي الله عنهم قال: «مَن كان مستناً فليستن بمَن قد مات، أولئك أصحاب محمد ﷺ كانوا خير هذه الأُمَّة، أبرّها قلوباً، وأعمقها علماً، وأقلّها تكلُّفاً، قوم اختارهم الله لصُحبة نبيه ﷺ»، وعن عليّ رضي الله عنه قال: «جَلَدَ النَّبي ﷺ أربعين، وَجَلَدَ أبو بكر أربعين، وعمر ثمانين، وكلٌّ سُنَّة»."]]}]},{"id":"u62a","title":"ومن خلال تعريف الحنفية للسُّنة فتكون على عدّة صور","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u62a_1","kind":"def","label":"ومن خلال تعريف الحنفية للسُّنة فتكون على عدّة صور · الفقرة ١","segs":[["matn","ومن خلال تعريف الحنفية للسُّنة فتكون على عدّة صور:"],["matn","١. سُنَّة قولية:"],["ctx","وهي الأحاديث التي قالها النَّبي ﷺ في مختلف الأغراض والمناسبات، كقوله ﷺ: «إنَّما الأعمال بالنِّيات»."]]},{"id":"u62a_2","kind":"def","label":"ومن خلال تعريف الحنفية للسُّنة فتكون على عدّة صور · الفقرة ٢","segs":[["matn","٢. سُنَّة فعلية:"],["ctx","وهي الأعمال التي قام بها النَّبي ﷺ على سبيل التَّشريع ولم يكن من خصائصه، مثل توضيح هيئة الصَّلاة ومناسك الحجّ، حيث أمر بإتباع فعله فيهما بقوله ﷺ: «صلوا كما رأيتموني أُصَلِّي»، وقوله ﷺ: «لتأخذوا مناسككم»."]]},{"id":"u62a_3","kind":"def","label":"ومن خلال تعريف الحنفية للسُّنة فتكون على عدّة صور · الفقرة ٣","segs":[["matn","٣. سُنّة تقريرية:"],["ctx","بأن يرى ﷺ من أُمّته فعلاً أو قولاً فلم يُنكر النَّبيّ ﷺ وسكت، فهذا تقرير منه ﷺ، لكن يشترط أن لا يكون سهواً، ولا طبعاً، ولا خاصة، مثل: إقراره ﷺ لمعاذ رضي الله عنه طريقة القضاء والاستدلال."]]},{"id":"u62a_4","kind":"def","label":"ومن خلال تعريف الحنفية للسُّنة فتكون على عدّة صور · الفقرة ٤","segs":[["matn","٤. سُنَّة الصَّحابة رضي الله عنهم:"],["ctx","بأن لم يواظب عليها رسول الله ﷺ، بل واظب عليها الصَّحابة رضي الله عنهم، وهذا مما يُندب إلى تحصيله ويُلام على تركه، ولكنَّه دون ما واظب عليه رسول الله ﷺ، فإنَّ سُنَّة النَّبيّ ﷺ أقوى من سُنَّة الصَّحابة رضي الله عنهم، وأقوال الصَّحابة رضي الله عنهم حجّة فيكون أفعالهم سنة، كما في التَّراويح في رمضان."]]},{"id":"u62a_5","kind":"def","label":"ومن خلال تعريف الحنفية للسُّنة فتكون على عدّة صور · الفقرة ٥","segs":[["matn","حجية قول الصَّحابي:"],["ctx","وهذا يوصلنا إلى حجية قول الصَّحابي رضي الله عنه عند الحنفية، حيث اتسع مفهومِ السُّنّةِ عند السَّادة الحنفية بحيث يشمل أَقوالَ الصَّحابةِ رضي الله عنهم وأَفعالَهم، وقد كان لهذا الأمر أثرٌ ظاهرٌ في مسألةِ حجيّةِ قول الصَّحابي رضي الله عنه، التي بُنِي عليها من المسائل ما لا يُعَدُّ ولا يُحْصَى، فقد خالفهم بعض الفقهاء في عدم اعتباره حجّة، وبالتالي لا يشمل مفهوم السُّنة تصرفات الصَّحابة عندهم."]]},{"id":"u62a_6","kind":"text","label":"ومن خلال تعريف الحنفية للسُّنة فتكون على عدّة صور · الفقرة ٦","segs":[["ctx","قال الدُّبوسيُّ: «ذَكَرَ أَصحابُ الشَّافعيِّ أنَّ السُّنةَ المطلقةَ عند صاحبنا تنصرف إلى سنةِ الرُّسول ﷺ، وأنَّه على مذهبِهِ صحيحٌ؛ لأنَّه لا يَرَى اتّباع الصَّحابيّ رضي الله عنه إلا بحجّة، كما لا يُتَّبع مَن بعده إلا بحجّة، ويحتمل لأنَّه لم يبلغه استعمال السَّلف إطلاق السُّنة على طرائق العُمَرين والصَّحابة رضي الله عنهم»، وظاهر مذهب مالك أنَّه معتبر عنده كأبي حنيفة؛ لبناء فقهه على الفقه المتوارث عن الصَّحابة في المدينة."]]}],"sup":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم"},{"id":"u62b","title":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u62b_1","kind":"def","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ١","segs":[["matn","واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي:"],["ctx","١."],["matn","إنَّ تقليدَ الصَّحابيّ رضي الله عنه واجبٌ يُترك بقوله القياس"],["ctx","، وهو قولُ أبي سعيد البردعي وأبي بكر الرازي، وهو مختار الشَّيخين وأبي اليُسر، قال السَّمرقنديّ: «وعليه أكثر مشايخنا»، وقال البَزْدويّ: «وعلى هذا أدركنا مشايخنا»؛ لقوله تعالى: ﴿وَٱلسَّـٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَـٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَـٰنٍ﴾ [التوبة:١٠٠]، مدح الصَّحابة رضي الله عنهم والتَّابعين لهم بإحسان، وإنَّما استحق التَّابعون لهم المدح؛ لاتباعهم بالإحسان من حيث الرُّجوع إلى رأيهم، ولأنَّ القياسَ عَملٌ بغالب الرَّأي والظَّنّ لا بطريق التَّيقن، ولا شكّ في خفاء طريق الاجتهاد، ولا شَكّ في تفاضل النَّاس في باب الاجتهاد، فكان العملُ باجتهاد مَن هو أبصر لوجهِ الحقّ أَوْلى كالصَّحابة رضي الله عنهم."]]},{"id":"u62b_2","kind":"def","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ٢","segs":[["ctx","٢."],["matn","لا يجوز تقليد الصَّحابي رضي الله عنه إلا فيما لا يُدرك بالقياس"],["ctx","، وهو قولُ أبي الحسن الكَرْخيّ؛ لأنَّ الظَّاهر أنَّ الصَّحابيَّ الفقيه لم يَقُل بقولٍ مخالفٍ للقياس إلا عن حديثٍ ثابتٍ عنده عن رسول الله ﷺ فيجب حملُه عليه."]]},{"id":"u62b_3","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ٣","segs":[["ctx","فالاختلاف في تقديم الصَّحابيّ على القياس، والاتفاق في تقليدِه فيما لا يُعقل بالقياس."]]},{"id":"u62b_4","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ٤","segs":[["ctx","وهذا الأصلُ الكبيرُ عند الحنفيّة في إدراج تصرُّفات الصَّحابة رضي الله عنهم في السُّنّة وَرِثُوه عن سلفهم من الصَّحابة والتَّابعين رضي الله عنهم، لاسيما مؤسِّس مدرسة الكوفة الأوّل من الصَّحابة رضي الله عنهم، وهو عبدُ الله ابن مسعود رضي الله عنه؛ إذ يؤكِّدُ هذا المنهج ويرسمُه لتلامذتِهِ ويُطالبهم باتباعه، فيقول: «مَن كان منكم مُتأسياً فليتأسَ بأَصحاب مُحمّد ﷺ، فإنَّهم كانوا أَبَرَّ هذه الأَمّة قلوباً، وأَعمقها علماً، وأقلُّها تكلُّفاً، وأقومها هدياً، وأَحسنها حالاً، اختارهم الله تعالى لصحبة نبيّه ﷺ وإقامةِ دينه، فاعرفوا لهم فضلَهم واتبعوهم في آثارهم، فإنَّهم كانوا على الهدي المستقيم»."]]},{"id":"u62b_5","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ٥","segs":[["ctx","ولم يكن هذا الطَّريق خاصّاً بابن مسعود رضي الله عنه، بل هو منهجٌ عامٌّ متبعٌ في هدي الصَّحابة بَين بعضهم البعض ولِمَن جاء بعدهم؛ كعمر وحذيفة وابن عباس رضي الله عنهم."]]},{"id":"u62b_6","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ٦","segs":[["ctx","وسرُّ اعتماد هذا المنهج؛ حتى لا يُتعامل مع القرآن والسُّنة كنصوص جامدة كلٌّ يؤوِّلُها كيفما يريدُ ويفهمُها على أي طريقٍ شاء فيَضِلَّ ويُضِلَّ، وإنَّما في فعلِهم وقولهم رضي الله عنهم تطبيقٌ لنصوصِ القرآنِ والسُّنةِ وتفسيرٌ لهما على الصُّورةِ الصَّحيحةِ المرادةِ من الشَّارعِ الحكيم، ففي تطبيقهم يَتَبَيَّن لنا مقصود المُشَرِّع؛ لمعايشتهم النَّبيّ ﷺ."]]},{"id":"u62b_7","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ٧","segs":[["ctx","فكما أنَّ أفعال النَّبيّ ﷺ وأقواله هي تفسير للقرآن، وهذا ما شَهِدَت به أمُّ المؤمنين في الأثر عن سعد بن هشام قال: «أتيت عائشة رضي الله عنها، فقلت: يا أم المؤمنين، أخبريني بخلق رسول الله؟ قالت: كان خلقه القرآن، أَما تَقْرَأ: ﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ﴾ [القلم:٤]»، فأفعال الصَّحابة رضي الله عنهم هي التَّفسير والبيان لسُّنَّة النَّبيّ ﷺ."]]},{"id":"u62b_8","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ٨","segs":[["ctx","وهذا ما كان يأمر به الفاروق رضي الله عنه الصَّحابةَ والتَّابعين، فيقول وهو على المنبر: «أُحَرِّج بالله على رجلٍ رَوَىٰ حديثاً العملُ على خلافه»."]]},{"id":"u62b_9","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ٩","segs":[["ctx","وهو الظَّاهرُ من عملِ مجتهدي الصَّحابة رضي الله عنهم، فإنَّهم كانوا يُميِّزون ما يؤخذ به مِمَّا وَرَدَ عن النَّبي ﷺ وما يُترك، وفي هذا يقول ابن أبي حازم: «كان أبو الدَّرداء رضي الله عنه يُسأل فيجيب، فيُقال: إنَّه بلغنا كذا وكذا ـ بخلاف ما قال ـ فيقول: وأنا قد سمعته، ولكنِّي أدركت العمل على غير ذلك»."]]},{"id":"u62b_10","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ١٠","segs":[["ctx","وهذا التَّمييزُ من كبارِ الصَّحابة رضي الله عنهم؛ لمعرفتهم النَّاسخ من المنسوخ، فيتَّبعون آخر ما استقرَّ عليه أَمرُ الشَّرع، ويوضح ذلك الحافظ المشهور ابن شهاب الزُّهريّ بقوله: «كان الصَّحابةُ رضي الله عنهم يتَّبعون الأحدثَ فالأَحدث من أَمره ﷺ ويَرَوْنَ النَّاسخَ المحكم»، ومثلُه رُوِي عن ابنِ عَبَّاس رضي الله عنهم: «إنَّ رسولَ الله ﷺ صام عام الفتح حتى بلغ الكديد، ثُمَّ أفطر وأفطر أصحابه، فهم يَتَّبعون الأحدثَ فالأحدثَ من أمرِ رسول الله ﷺ، وإنَّ ذلك هو النَّاسخ المحكم»."]]},{"id":"u62b_11","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ١١","segs":[["ctx","فيكون ما يَرِدُ عن هؤلاء المجتهدين من الصَّحابة رضي الله عنهم بيانٌ للسُّنة المعمول بها في الدِّين، والأمرُ الذي انتهى إليه الشَّرع، قال ابنُ أبي ليلى: «لا يفقه الرَّجل في الحديث حتى يأخذَ منه ويدَع»."]]},{"id":"u62b_12","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ١٢","segs":[["ctx","ويُصَوِّرُ أحدُ كبار التَّابعين وهو إبراهيم النَّخعيّ ـ وقد كان فقيه أهل زمانه ـ شدّة التَّمسّك بِهَدي الصَّحابة رضي الله عنهم فيما نقلوه من الدِّين وتقديم رأيهم وفَهمهم على كلِّ شيء، حتى لو عارض صريحَ القرآن؛ لأَنَّهم مُؤتمنين فيما يَنقلونه من أَمر الشَّرعِ الأَخير، فيقول: «لو رأيت الصَّحابة رضي الله عنهم يتوضؤون إلى الكوعين ـ أي الرُّسغين ـ لتوضّأت كذلك وأنا أقرأها إلى المرافق؛ وذلك لأَنَّهم لا يُتهمون في تركِ السُّنن، وهم أربابُ العلم وأَحرص خلقِ الله تعالى على اتّباع رسول الله ﷺ، فلا يَظنّ ذلك بهم أحدٌ إلا ذو ريبة في دينه»."]]},{"id":"u62b_13","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ١٣","segs":[["ctx","ولم يكن هذا المسلك خاصّاً بالحنفية، بل كانت طريقُ نقل العلم في تلك المدّة هي هذه؛ لذا نجد مالك يقول: «والعمل أثبت من الأحاديث، قال مَن اقتدي به: يصعب أن يُقال في مثل ذلك: حدثني فلان عن فلان، وكان رجالٌ من التَّابعين تبلغهم عن غيرهم الأحاديث فيقولون: ما نجهل هذا، ولكن مضى العمل على خلافه، وكان محمد بن أبي بكر بن حَزْم رُبّما قال له أخوه: لِمَ لَم تقضِ بحديث كذا؟ فيقول: لم أجد النَّاس عليه»."]]},{"id":"u62b_14","kind":"text","label":"واختلف الحنفيّة في حجيّة قول الصَّحابيّ رضي الله عنه على النحو الآتي · الفقرة ١٤","segs":[["ctx","وتَحَصَّل مما سبق: أنَّ الحثَّ على اتباع طريق الصَّحابة رضي الله عنهم المتمثل في أقوالهم وأفعالهم هو الهدي الذي كان من كبار الصَّحابة رضي الله عنهم ومجتهديهم، وأنَّهم أقدر مَن في الأُمَّة على معرفة المعمول به من السُّنة، وأنَّ تصرُّفاتهم تُمثل الأمر الذي استقرَّ عليه الشَّرع، وأنَّ تقليدهم واتباعهم هو طريق السَّلف من كبار التَّابعين، وبسبب ذلك وجدنا الحنفية جعلوا هديهم سنة تتبع."]]}],"sup":"المبحث التَّمهيدي: شمول مفهم السُّنَّة لتصرُّفات الصَّحابة رضي الله عنهم"},{"id":"u63","title":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u63_1","kind":"text","label":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ · الفقرة ١","segs":[["ctx","إنَّ للحنفية تقسيماً مختلفاً عن غيرِهم في قوَّةِ ورودِ السُّنةِ إلينا وثُبوتِها عن النَّبيِّ ﷺ، يُراعي الجانب العملي الذي يهتمون به في فقههم؛ لاهتمامهم بمراعاةِ مراتبِ الأدلة في الثُّبوت والدَّلالةِ لإعطاء الحكم قوّته من الفرضيةِ والوجوبِ والسُّنيةِ والحرمةِ والكراهيّة، فلا يَقبلون في إثباتِ الأَركان مثلاً إلاّ دَليلاً قَطعياً، كما في الوضوءِ والصَّلاةِ والحَجِّ وغيرِها."]]},{"id":"u63_2","kind":"text","label":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ · الفقرة ٢","segs":[["ctx","وبسببِ تأخيرِهم للدليل الأدنى رتبةً عن الأَعلى، فلا يُقدِّمون الآحاد على القرآن، ولا على المُتواتر، ولا على المَشهور؛ ليتمكَّنوا من التَّرجيحِ بين الأدلّة إذا تَعارضت؛ لذلك اهتموا جلياً بقوّة الثُّبوتِ عن الحضرةِ النَّبويةِ ﷺ، فكان لهم تقسيماً بديعاً في هذا الباب يبيِّن لنا مراتب الاتصال بالنَّبي ﷺ، وهي:"]]},{"id":"u63_3","kind":"text","label":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ · الفقرة ٣","segs":[["ctx","١. اتصالٌ كامل بلا شبهة: أي لا صورةً ولا معنى، وهو المتواتر، بأن يكون نُقِل بطرقٍ يستحيل الكذب فيها، فصار مقبولاً عند الأُمَّة؛ لعدم الشَّكّ فيه."]]},{"id":"u63_4","kind":"text","label":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ · الفقرة ٤","segs":[["ctx","٢. اتصالٌ فيه ضربُ شبهة صورة، وهو المشهور، بأن يكون نُقِل بطريق آحاد في عهد الصَّحابة رضي الله عنهم، ولكن تَلَقي الأُمَّة له بالقَبول رفع هذه الشُّبهة التي حصلت في إسناده في الطَّبقة الأُولى؛ لعدم توافق العلماء على الخطأ، وعصمة الأُمَّة عن ذلك."]]},{"id":"u63_5","kind":"text","label":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ · الفقرة ٥","segs":[["ctx","٣. اتصالٌ فيه شبهةٌ صورةً ومعنى، وهو الآحاد، أمّا ثبوتُ الشُّبهة فيه صورةً؛ فِلأنَّ الاتصالَ بالنَّبيّ ﷺ لم يثبت قطعاً، وأَمّا معنى؛ فِلأنَّ الأُمَّةَ ما تلقته بالقَبول."]]},{"id":"u63_6","kind":"text","label":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ · الفقرة ٦","segs":[["ctx","فمراعاتُهم لجانبِ المعنى في الاتصال والقَبول والتَّصحيح جَعَلَت عندهم قسماً مستقلاً لم يوجد عند المُحَدِّثين، وهو المشهور، فعند المُحَدِّثين المتواتر لا يختلف حاله عن المتواتر عند الحنفية، ولكنَّ المشهور من أَقسام الآحاد عند المُحَدِّثين؛ إذ يقسمون الآحاد إلى ثلاثة أقسام: المشهور (المستفيض): وهو ما تكون له طرق محصورة بأكثر من اثنين، والعزيز: وهو أن يرويه اثنان، والغريب: وهو ما يتفرّدُ بروايته شخص واحد."]]},{"id":"u63_7","kind":"text","label":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ · الفقرة ٧","segs":[["ctx","وهذا لا يُنقص أبداً من قدرِ المُحَدِّثين، فتقسيمهم متلائمٌ مع فنِّهم واشتغالهم بالرِّجال واعتمادهم عليهم في النَّقل لا على المعاني والأُصول والقَبول للأُمَّة، وكلُّ علم له اصطلاحاتُه وتقسيماتُه المتناسبةُ معه، والخطأُ في محاكمةِ علمٍ إلى علمٍ آخر بإنزال اصطلاحاته وتقديراته على غيره، ومحاسبته بذلك."]]},{"id":"u63_8","kind":"text","label":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ · الفقرة ٨","segs":[["ctx","وهذه هي الورطة الظَّلماء التي وقع فيها كثيرون؛ إذ حاسبوا الفقهاءَ والأصوليين بمصطلح أهل الحديث وعلمهم وثقافتهم، فزعزعوا الثِّقة بالفقه وشككوا في أصله وسَعَوا في هدم بنائه، وغَفِلوا عن أنَّ لهذا العلم قواعد وأصولاً واصطلاحات بُني عليها وسار بها على مدارِ القرون، بحيث لم يُخدم علمٌ من علوم الدُّنيا كما خُدِمَ؛ لأنَّه الإسلامُ العمليُّ التَّطبيقيُّ المعاشُ بين الأفرادِ والجماعاتِ والدُّول."]]}]},{"id":"u64","title":"المطلب الأول: السُّنة المتواترة","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u64_1","kind":"text","label":"المطلب الأول: السُّنة المتواترة · الفقرة ١","segs":[["ctx","والتَّواتر لغةً: التتابع، يُقال: تواترت الخيل إذا جاءت يتبع بعضها بعضاً."]]},{"id":"u64_2","kind":"text","label":"المطلب الأول: السُّنة المتواترة · الفقرة ٢","segs":[["ctx","واصطلاحاً على حسب الأقسام الآتي ذكرها، قال الكشميري: «والتَّواتر عندي على أربعة أقسام»."]]},{"id":"u64_3","kind":"text","label":"المطلب الأول: السُّنة المتواترة · الفقرة ٣","segs":[["ctx","وهذه الأربعة التي ذكرها الكشميري لم يكن هو أوّل مَن قال بها، بل اثنان منها مُسَلَّمٌ بهما عند كافة العلماء، وهما: تواتر الإسناد للفظ الواحد للحديث، وتواتر المعنى بألفاظ مختلفة في أحاديث متعددة تتفق على قضية ما."]]},{"id":"u64_4","kind":"text","label":"المطلب الأول: السُّنة المتواترة · الفقرة ٤","segs":[["ctx","وأما الثَّالث: فهو تواتر النَّقل طبقة عن طبقة بدون ذكر للأسانيد، كما هو الحاصل في القرآن، وهي طريقة مشهورة جداً عند الفقهاء، تُسمَّى عند الحنفية بالنَّقل المتوارث، وعند المالكية بإجماع أهل المدينة ـ كما سيأتي ـ."]]},{"id":"u64_5","kind":"text","label":"المطلب الأول: السُّنة المتواترة · الفقرة ٥","segs":[["ctx","وأَمّا الرَّابعة: فهي تواتر العمل من الصَّحابة والتَّابعين رضي الله عنهم في مسألة ما، وهي ظاهرةٌ في فهم سلف الأُمَّة فيما يَعتمدون ويَعتبرون، وقد نَصَّ عليها الطَّحاويّ، وصَرَّح بحقيقتِها الكاسانيُّ ـ كما سيأتي ـ."]]},{"id":"u64_6","kind":"text","label":"المطلب الأول: السُّنة المتواترة · الفقرة ٦","segs":[["ctx","وبهذا يَتَبَيَّن أنَّ هذا التَّقسيمَ جديدٌ بذكره مجموعاً كاصطلاح عند المعاصرين، وهو قديم بأصله وحقيقته عند السَّابقين، وبه يفهم التَّواتر لأحكام عديدة في الدِّين، بخلاف التَّقسيم المشهور عند المُحَدِّثين؛ إذ حصل نزاع في الأفراد التي يشملها ولاسيما اللفظي منه؛ لصعوبة الحصول على أحاديث تتوفَّر فيها الشُّروط العديدة التي ذكروها فيه."]]}],"sup":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ"},{"id":"u64a","title":"أولاً: تواتر الإسناد «اللفظي»","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u64a_1","kind":"def","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ١","segs":[["matn","أولاً: تواتر الإسناد «اللفظي»:"],["ctx","فهذا هو التَّواترُ المشهور في كتب المصطلح والأصول، وإذا أُطلق التَّواترُ فهو المقصود بصورة عامّة، وله تعريفات عديدةٌ تتفاوت في الدَّلالة على المقصود، ومنها: ما بلغت رُواتُه في الكثرة مبلغاً أحالت العادة تواطؤهم على الكذب، ويدوم هذا، فيكون أَوّله كآخِره، ووسَطُه كطرفَيْه، أو خبرُ جماعة يُفيد بنفسه العلم بصدقه."]]},{"id":"u64a_2","kind":"text","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ٢","segs":[["ctx","وعلامة المتواتر حصول العلم الضَّروري، فوجود المتواتر ليس موقوفاً على رواية عددٍ دون عدد، إنَّما العبرةُ بحصول العلم الضَّروري، فكلّ ما يحصل به هذا العلم يُحكم بكونه متواتراً."]]},{"id":"u64a_3","kind":"text","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ٣","segs":[["ctx","وحكمه عند جمهور الأصوليين والمُحَدِّثين: هو أنَّ العلم الحاصل به علم اليقين كالعيان الذي يوجبه الحس من البصر والسَّمع، فإنّا نجد المعرفة بآبائنا بالخبر مثل المعرفة بأولادنا عياناً، وهذا العلم المستفاد ضروريّ لا يحتاج إلى تجشم الاستدلال ـ أي لا يحتاج إلى نظر وفكر ـ بل يقع في القلب بمجرد سماعه، ومثاله: نقل القرآن، وأعداد الصَّلوات، وعدد الرّكعات، ومقادير الزَّكاة، وأروش الجنايات، وأعداد الطواف، والوقوف بعرفات، ونحو ذلك."]]},{"id":"u64a_4","kind":"def","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ٤","segs":[["matn","ثانياً: تواتر القدر المشترك «المعنوي»:"],["ctx","وهو أن يكون مضمون ما مذكوراً في كثيرٍ من الآحاد، كتواترِ المعجزة، فإنَّ مفرداتها وإن كانت آحاداً، لكنَّ القدر المشترك متواتر قطعاً، كسخاء حاتم، فإنَّ أَخباره وإن كانت آحاداً، إلا أن سخاءه معلومٌ متواتراً."]]},{"id":"u64a_5","kind":"text","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ٥","segs":[["ctx","وحكمه: قال الكشميري: «إن كان ضرورياً فيكفر جاحدُه، وإن كان نظرياً فلا». وهذا مناسب؛ لأنَّ ما ثبت بحيث كان مِمَّا يُعلم في الدِّين ضرورة، فلا شكّ بكفر جاحده، وما لم يصل هذا إلى هذا الحدّ بحيث فيه اختلاف واستدلال ونظر، فلا يصل بمَن يقوله إلى حدّ الضَّرورة، لكن عامَّة فروعِهِ لا تفيدُ العلم الضَّروريّ."]]},{"id":"u64a_6","kind":"text","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ٦","segs":[["ctx","ومن أمثلته:"]]},{"id":"u64a_7","kind":"text","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ٧","segs":[["ctx","أ. حديث: «المسح على الخفين» رواه ثمانون صحابياً، وصرَّح بتواتره الكرخي وابن عبد البرّ وابن الهمام وابن حجر والزَّرقاني وغيرهم."]]},{"id":"u64a_8","kind":"text","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ٨","segs":[["ctx","ب. أحاديث: لا يصلح للمرأة أن تسافر إلا ومعها محرم، قال الطَّحاوي: «فإنَّ الحجةَ عليهم في ذلك ما قد تواترت به الآثار التي قد ذكرناها عن رسول الله ﷺ فهي حجة على كل من خالفها»."]]},{"id":"u64a_9","kind":"text","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ٩","segs":[["ctx","ج. أحاديث النَّهي عن لبس خاتم الذَّهب، قال الطَّحاوي: «رُوي في النَّهي من خاتم الذَّهب... آثار متواترة جاءت مجيئاً صحيحاً»."]]},{"id":"u64a_10","kind":"text","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ١٠","segs":[["ctx","د. أحاديث فرضية الاستماع والإنصات للخطيب، قال الطَّحاوي: «تواترت الرِّوايات عن رسول الله ﷺ بأنَّ من قال لصاحبه: أنصت والإمام يخطب يوم الجمعة فقد لغا»."]]},{"id":"u64a_11","kind":"text","label":"أولاً: تواتر الإسناد «اللفظي» · الفقرة ١١","segs":[["ctx","هـ. أحاديث النَّهي عن أكل ذي ناب من السِّباع، قال الجصَّاص: «فهذه آثار مستفيضة في تحريم ذي النَّاب من السِّباع وذي المخلب من الطير، والثَّعلب والهر والنِّسر والرخم داخلة في ذلك، فلا معنى لاستثناء شيء منها إلا بدليل يوجب تخصيصه»."]]}],"sup":"المطلب الأول: السُّنة المتواترة"},{"id":"u64b","title":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي»","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u64b_1","kind":"def","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١","segs":[["matn","ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي»:"],["ctx","وهو أن تأخذَ طبقةٌ عن طبقةٍ بلا إسناد، والقرآنُ متواترٌ بهذا التَّواتر؛ لأنَّه تواتر على البسيطة شرقاً وغرباً، درساً وتلاوةً، حفظاً وقراءةً، وتلقَّاه الكافَّةُ عن الكافَّة، طبقة عن طبقة، فهذا لا يحتاجُ إلى إسنادٍ مُعيَّن، يكون عن فلانٍ عن فلان."]]},{"id":"u64b_2","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٢","segs":[["ctx","ويصدق عليه التَّوارث المدرسيِّ للعلم؛ ولذلك لقَّبه الكشميريّ «بتواترِ الفقهاء»."]]},{"id":"u64b_3","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٣","segs":[["ctx","وخلاصة ما فيه: اقتضت الحاجة من الصَّحابة رضي الله عنهم في تعليم الإسلام أن ينتقل المجتهدون منهم إلى البلاد المفتوحة؛ ليُعَلِّموا الإسلام وينشروه بالهيئة التي تلقوه بها، فكان أبو الدَّرداء ومعاذ بن جبل رضي الله عنهم في الشَّام، وأبو موسى الأشعري رضي الله عنه في البصرة، وابنُ عَبّاس رضي الله عنه في مكة، وزيد بن ثابت وعائشة وابن عمر وأبو هريرة رضي الله عنهم في المدينة، وابن مسعود وعليّ رضي الله عنهم في الكوفة، وهكذا، ومنهم تكوَّنت نواة المذاهب الفقهية في نقل الجانب العملي للإسلام لَمن بعدهم."]]},{"id":"u64b_4","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٤","segs":[["ctx","وطالما بحثنا عن أصول الحنفية، فنبيِّن مثال هذا القسم عندهم؛ إذ بعد فتح الكوفة على يدِ سعد بن أبي وقاص رضي الله عنه سنة (١٧هـ)، بعثَ عمرُ رضي الله عنه لها عمار بن ياسر رضي الله عنه أَميراً، وابنَ مسعود رضي الله عنه قاضياً؛ لأَنَّه من أكابر المجتهدين من الصَّحابة رضي الله عنهم، فهو خامس مَن أسلم، وقال عنه ﷺ: «رضيت لأُمَّتي ما رضي لها ابن أم عبد»، و«تمسّكوا بعهد ابن أم عبد»، و«خذوا القرآن عن أَربعة... وذكر منهم ابن أم عبد»، وقال عنه عمر رضي الله عنه: «كنيف مليء فقهاً»، ووصفه حذيفة رضي الله عنه بأَنَّه أشبه الصَّحابة رضي الله عنهم بهدي النَّبي ﷺ وسمته وسلوكه، وكان يظنُّ أبو موسى الأشعرى رضي الله عنه عندما جاء مسلماً إلى المدينة أنَّه من بعض أهل النَّبي ﷺ لكثرةِ دخوله عليه."]]},{"id":"u64b_5","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٥","segs":[["ctx","فهذا الصُّحبة المديدة والمُلَازمة العجيبة لا بُدَّ أن تجعله مُدركاً وضابطاً لهدي النَّبيّ ﷺ وفاهماً لمقاصد الشَّرع وحافظاً لما ورد منه، ومثلُه أهلٌ بأن يأتي بمذهبٍ يُبيّن فيه حقيقة الإسلام الذي تلقاه من الحضرة النَّبويّة، وقد تجسّد هذا في المذهب الحنفيّ، فهو مذهب ابن مسعود رضي الله عنه؛ إذ أَنَّه الرَّكيزةُ الأساسيةُ في بنائه وتأسيسه."]]},{"id":"u64b_6","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٦","segs":[["ctx","فقد نُقل عن ابن مسعود رضي الله عنه كلَّ ما تعلمه من النَّبي ﷺ واجتهد به كبارُ التَّابعين في الكوفة؛ إذ بقي في الكوفة ما يَقْرُب من خمس عشرة سنة يُربي ويُعَلِّم، فيَقول ابن مسعود رضي الله عنه عن علقمة النَّخعي رضي الله عنه الذي صحبه عشر سنين: «لا أَعلم شيئاً إلا وعلقمة يعلمه»، وهذه شهادة عظيمةٌ يتضح من خلالها كمال النَّقل لهدي النَّبيّ ﷺ بطريق المدرسة، وشهد بذلك الطَّبري فقال: «لم يكن أحدٌ له أصحاب معروفون حرَّروا فتياه ومذاهبه في الفقه غير ابن مسعود رضي الله عنه، وكان يترك مذهبه وقوله لقول عمر رضي الله عنه، وكان لا يكاد يخالفه في شيء من مذاهبه، ويرجع من قوله إلى قوله»، فحُفِظ وضُبِط بهذا الطريق كلُّ ما قاله ابن مسعود رضي الله عنه من نقلٍ واجتهادٍ."]]},{"id":"u64b_7","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٧","segs":[["ctx","وهذا الأمر الذي جعل عليّ بن أبي طالب رضي الله عنه يُؤثر الكوفة في أن تكون مكاناً لخلافته بدلاً عن المدينة رغم أنَّها مهبط الوحي؛ لما امتاز أهلُها عن غيرهم من المعرفة الصَّحيحة للإسلام والفهم العميق، قال عليّ رضي الله عنه: «رحم الله ابن أم عبد قد ملأ هذه القرية علماً»، وقال سعيد بن جبير: «كان أصحاب ابن مسعود رضي الله عنه سُرج هذه القرية»."]]},{"id":"u64b_8","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٨","segs":[["ctx","فإذا أضيف إلى تعليم ابن مسعود رضي الله عنه تعليمَ عليٍّ رضي الله عنه لأهل الكوفة ببقائه فيهم أربع سنوات وهو خليفةٌ للمسلمين، وكلُّ همساته وحركاته وسَكَناته معلومة بينهم؛ لمكانته، فعليٌّ رضي الله عنه أكثر النَّاس حفظاً لحال النَّبيّ رضي الله عنه؛ وذلك لتربيته له قبل الإسلام وتزويجه ابنته وقرابته منه وذكائه الشَّديد، وهذه المدةُ كافية لكي يَنقل سلوك النَّبي ﷺ لأهل الكوفة، فهو الشَّخصية الثَّانية من الصَّحابة رضي الله عنهم الأكثر تأثيراً في بناء المذهب الحنفي."]]},{"id":"u64b_9","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٩","segs":[["ctx","وهذا يكفي للطمأنينة بوجود الإسلام بتمامه في الكوفة زمن الصَّحابة رضي الله عنهم، فكيف إذا كان ابنُ مسعود رضي الله عنه يترك قوله لقول عمر رضي الله عنه، ويُخبر النَّاس بكلِّ ما يُفتي به عمر رضي الله عنه، وكيف إذا وُجد في الكوفة سبعين بدرياً وألف وخمسمئة صحابيّاً كما شهد بذلك العجليّ."]]},{"id":"u64b_10","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١٠","segs":[["ctx","وقد تلقَّى عن هؤلاء أئمة التَّابعين مثل: ١) علقمة النَّخعي (ت٦٣هـ) الذي رحل إلى أبي الدَّرداء وعمر وعائشة رضي الله عنهم، ٢) ومسروق الهمداني (ت٦٣هـ) الأعلم بالفتوى بشهادة الشَّعبي، ٣) والحارث الهمداني (ت٦٥هـ) المُقَدَّم بالعلم في الكوفة بشهادة ابن سيرين، ٤) وعبيدة السلمي (ت٧٢هـ) المقدَّم في علم الفريضة، ٥) وعمرو الأودي (ت٧٤هـ) من أصحاب معاذ رضي الله عنه، ٦) وعبد الله السلمي (ت٧٤هـ) عمدة القراء وقد تلقى عنه السّبطان، وأخذ عنه عاصم قراءته المشهورة، ٧) والأسود النَّخعي (ت٧٤هـ) الذي قالت عنه عائشة رضي الله عنها: «ما مات رجل بالعراق أكرم عليَّ من الأسود»، ٨) والقاضي شريح المشهور (ت٨٠هـ) الذي استمر في قضاء الكوفة اثنين وستين سنة وقد ولاه عمر رضي الله عنه، وغيرهم من العِظام الذين يطول الكلام بذكرهم."]]},{"id":"u64b_11","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١١","segs":[["ctx","وقد أخذ عن هذه الطبقة سعيدُ بن جبير (٩٥هـ)، والشَّعبيُّ (ت١٠٤هـ) الذي يقول عنه ابن عمر رضي الله عنهم: «لهو أحفظ للمغازي مني، وإن كنت قد شهدتها مع رسول الله ﷺ»، وإبراهيم النَّخعي (ت٩٥هـ) الذي يعتبر من أَبرز الشَّخصيات الفقهية التي بُني عليها المذهب الحنفي بعد ابن مسعود رضي الله عنه، قال الأعمش: «ما عرضت على إبراهيم حديثاً قط إلا وجدت عنده منه شيئاً، وكان صيرفيّ الحديث، فكنت إذا سمعت الحديث من بعض أَصحابنا عرضته عليه»."]]},{"id":"u64b_12","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١٢","segs":[["ctx","وعنه أخذ أبو حنيفة، ولكن جلَّ أخذه كان على حماد بن أبي سليمان الذي كان له ملازمة تامّةٌ لإبراهيم حتى في أُمور حياته العادية، وأبو حنيفة لازم أيضاً حماداً ملازمةً لم يلازم أحدٌ أحداً مثلها كما قال."]]},{"id":"u64b_13","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١٣","segs":[["ctx","فانظر كيف أنَّ ابنَ مسعود رضي الله عنه لازم النَّبيَّ ﷺ وتلقَّى عنه الدِّين بقرآنه وأحاديثه مع تطبيقها وفهمها، ولازم علقمةُ النَّخعيُّ ابنَ مسعود رضي الله عنهم ملازمةً حمل فيها الإسلام بكماله وتمامه، ونشأ إبراهيمُ النَّخعيّ في أُسرة فقهيّة عريقة كما شهد الشَّعبيّ، فالأسودُ النَّخعيُّ خاله، ثُمَّ صَحِبَهُ حمادُ صحبةً تامّة، وصَحِبَ حمادَ أبو حنيفة وتلقَّى عنه هذا الفهم النَّاضج لأحكام الدِّين من هؤلاء العِظام، وكان في كلِّ طبقةٍ رجالٌ غير هؤلاء زادوا في هذا الخير ـ كما سَبَق ـ."]]},{"id":"u64b_14","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١٤","segs":[["ctx","وهذا الطَّريق مشهورٌ عند المالكية بإجماع أهل المدينة، وهم يُقَدِّمونه على حديث الآحاد؛ لأنَّه عبارةٌ عن نقلِ طبقةٍ عن طبقةٍ من أئمةِ الاجتهادِ من الصَّحابةِ والتَّابعين رضي الله عنهم؛ لذلك يقول فقيه المدينة وشيخ مالك ربيعة الرَّأي: «ألف عن ألف خير من واحد عن واحد»."]]},{"id":"u64b_15","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١٥","segs":[["ctx","وعند السَّادة الحنفية مشهورٌ بالمتوارث، فهم يحتجُّون به في كثيرٍ من المسائل، ويَرون أنَّ لديهم نقلاً بطريق مدرسة الكوفة أَقوى من النَّقل بطريق مدرسة المدينة، وفي ذلك يقول القدوري (ت٤٢٨هـ) على احتجاج المالكية بعمل أهل المدينة: «وقولهم: إنَّ أهل المدينة يفعلون وينقلون، لا يصحّ؛ لأَنَّ أهل الكوفة يفعلون وينقلون، ومَن انتقل إلى الكوفة من الأئمة أكثر ممَّن بقي بالمدينة»."]]},{"id":"u64b_16","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١٦","segs":[["ctx","ويُقرِّر هذا النَّقل المدرسي الذَّهبيّ فيقول: «أفقه أهل الكوفة عليّ وابن مسعود رضي الله عنهم، وأفقه أصحابهما علقمة، وأفقه أصحابه إبراهيم، وأفقه أصحاب إبراهيم حماد، وأفقه أصحاب حماد أبو حنيفة، وأفقه أصحابه أبو يوسف، وانتشر أصحاب أبي يوسف في الآفاق، وأفقههم محمد، وأفقه أصحاب محمد أبو عبد الله الشَّافعيّ»."]]},{"id":"u64b_17","kind":"def","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١٧","segs":[["matn","وحكم التَّواتر الطَّبقي"],["ctx",": قال الكشميري: «أنَّه يكفر جاحده»، وينبغي أن يصحَّ كلامُه على أحد نوعي هذا القسم، وهو ما كان تواتره ظاهراً من طبقة إلى طبقة بدون اعتماد على إسناد، بحيث صار معلوماً من الدِّين بالضَّرورة: كالقرآن، والتَّحريمة، والقراءة."]]},{"id":"u64b_18","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١٨","segs":[["ctx","وأما النَّوع الثاني، وهو اعتماد كلّ مدرسة على نقل الجانب العملي لحياة النَّبيّ ﷺ من خلال الطَّبقات الموصلة إليه، فلا يصلح أن يثبت به علماً ضرورياً يكفر جاحدُه؛ لأَنَّه قائمٌ على الاستدلال، وإنَّما يفيدنا اعتماد كلَّ مدرسة طريقاً خاصّاً تتثبت به وتعرفه حقّ المعرفة وتَثِق بحاله وتَعلم خبايا دقائقه بحيث يوصلُها إلى ما كان عليه النَّبيّ ﷺ."]]},{"id":"u64b_19","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ١٩","segs":[["ctx","ومن أمثلته:"]]},{"id":"u64b_20","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٢٠","segs":[["ctx","أ. أحاديث: «أسفروا بالفجر فإنَّه أعظم للأجر»، صرَّح بتواتره السُّيوطي والمنَّاوي."]]},{"id":"u64b_21","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٢١","segs":[["ctx","ب. أحاديث الإقامة مثنى مثنى، قال الطَّحاوي: «فتصحيح معاني هذه الآثار يوجب أن يكون الإقامةُ مثل الأذان سواء على ما ذكرنا؛ لأنَّ بلالاً اختلف فيما أَمر به من ذلك، ثم ثبت هو من بعد على التَّثنية في الإقامة بتواتر الآثار في ذلك، فعُلِم أنَّ ذلك هو ما أمر به»."]]},{"id":"u64b_22","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٢٢","segs":[["ctx","ج. أحاديث: «إذا اشتدّ الحرّ أبردوا بالصَّلاة» رواه سبعة عشر صحابياً، وصرَّح بتواتره السُّيوطي."]]},{"id":"u64b_23","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٢٣","segs":[["ctx","د. أحاديث تأخير العصر والشَّمس بيضاء نقيّة، قال الطَّحاوي: «تواترت به الآثار، وقد روي عن أصحابه من بعده ما يدلّ على ذلك أيضاً»."]]},{"id":"u64b_24","kind":"text","label":"ثالثاً: التَّواترُ الطَّبقي «التَّوارث المدرسي» · الفقرة ٢٤","segs":[["ctx","هـ. أحاديث تلبية النَّبي ﷺ بعد عرفة إلى رمي جمرة العقبة، قال الطَّحاوي: «وقد جاءت عن رسول الله ﷺ آثار متواترة بتلبيته بعد عرفة الى أن رمى جمرة العقبة»."]]}],"sup":"المطلب الأول: السُّنة المتواترة"},{"id":"u64c","title":"رابعاً: التَّواترُ العمليُّ","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u64c_1","kind":"def","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ١","segs":[["matn","رابعاً: التَّواترُ العمليُّ:"],["ctx","وهو أن يتواتر العمل على أمرٍ ما بحيث يستحيل تكذيبهم، أو تواترُ العمل على شيءٍ من لَدَنِ صاحبِ الشَّريعة إلى يومنا هذا: كالسِّواك."]]},{"id":"u64c_2","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ٢","segs":[["ctx","وأوضحه الكاساني، فقال: «تواترٌ من حيث ظهور العمل به قرناً فقرناً من غيرِ ظهور المنع والنَّكير عليهم في العمل به، إلا أنَّهم ما رووه على التَّواتر؛ لأنَّ ظهورَ العمل به أَغناهم عن روايته، وقد ظَهَرَ العملُ بهذا مع ظهورِ القولِ أيضاً من الأئمةِ بالفتوى به بلا تنازع منهم»."]]},{"id":"u64c_3","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ٣","segs":[["ctx","ووجه افتراقه عن المعنوي: أَنَّه عملي تطبيقي من الصَّحابة والتَّابعين رضي الله عنهم لِما شاهدوه من فعل النَّبي ﷺ، بخلاف المعنوي، فهو يجمع المعنى المتفق فيما روي عن النَّبي ﷺ في روايات مختلفة من فعله ﷺ أو قوله."]]},{"id":"u64c_4","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ٤","segs":[["ctx","ووجه افتراقه عن الطَّبقي: أَنَّه عمليٌّ عام في جميع الطَّبقات من جميع المدارس بصورة مجملة، بخلاف الطبقي فهو متعلقٌ بنقل طبقات المدرسة، سواء كان ذلك النَّقل قولاً أو تطبيقياً."]]},{"id":"u64c_5","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ٥","segs":[["ctx","ويُمكن القول إنَّ هذين القسمين عند الحنفية هما من أَفراد المشهور؛ لأَنَّهما اعتمدوا على العمل والقَبول من الصَّحابة والتَّابعين رضي الله عنهم في تَرَقِّي الحديث إلى درجةٍ يكون بها مُعتبراً مُحتجّاً به في إثبات الرُّكن والشَّرط والزِّيادة على القرآن وتخصيصه، وهذا هو الحال بصورةٍ إجماليةٍ في المشهور."]]},{"id":"u64c_6","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ٦","segs":[["ctx","وحكمه: التَّواتر العملي يوجب العمل قطعاً، فيجوز نسخ الكتاب العزيز به، كما يجوز بالمتواتر في الرِّواية، إلا أَنَّهما يَفترقان من وجهٍ، وهو أنَّ جاحدَ المتواتر في الرِّواية ـ أي الإسناد ـ يكفرُ، وجاحدُ المتواتر في ظهورِ العملِ لا يكفر، هذا ما صَرَّحَ به الكاسانيّ."]]},{"id":"u64c_7","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ٧","segs":[["ctx","ومن أمثلته:"]]},{"id":"u64c_8","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ٨","segs":[["ctx","أ. حديث: «سئل ﷺ عن البحر فقال: هو الطهور ماؤه الحل ميتته» رواه اثنا عشر صحابياً، قال الزَّرقانيّ: وهذا الحديث أصل من أصول الإسلام، تَلَقَّته الأئمة بالقَبول، وتداولته فقهاء الأمصار في سائر الأعصار في جميع الأقطار."]]},{"id":"u64c_9","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ٩","segs":[["ctx","ب. حديث: «لا زكاة في المال حتى يحول عليه الحول»، قال الجصَّاص: «وهذا الخبر في الحول وإن كان من أخبار الآحاد، فإنَّ الفقهاء قد تَلَقَّته بالقَبول واستعملوه فصار في حيز المتواتر المُوجب للعلم»."]]},{"id":"u64c_10","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ١٠","segs":[["ctx","ج. أحاديث في الرّكاز الخمس، قال الطَّحاوي: «الرّكاز الذي جعل الله فيه على لسان رسوله ﷺ الخمس، وتواترت بذلك الآثار عنه ﷺ»."]]},{"id":"u64c_11","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ١١","segs":[["ctx","د. أحاديث عدم الجهر بالبسملة في الصَّلاة، قال الطَّحاوي: «وقد جاءت الآثار متواترة عن رسول الله ﷺ وعن أبي بكر وعمر وعثمان رضي الله عنهم أنَّهم كانوا لا يجهرون بها في الصَّلاة»."]]},{"id":"u64c_12","kind":"text","label":"رابعاً: التَّواترُ العمليُّ · الفقرة ١٢","segs":[["ctx","هـ. أحاديث إجزاء الجزور والبقرة عن سبعة، قال الطَّحاوي: «تواترت عنهم رضي الله عنهم الرِّوايات بذلك»."]]}],"sup":"المطلب الأول: السُّنة المتواترة"},{"id":"u65","title":"المطلب الثَّاني: السُّنة المشهورة","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u65_1","kind":"def","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ١","segs":[["matn","تمهيد: الشُّذوذ والعلَّة بين الفقهاء والمُحَدِّثين:"],["ctx","إنَّ المُطالعَ لكتبِ أُصول الحنفية يجد تَحَرياً وتَثبُّتاً في تنقيحِ ما يُنسب إلى النَّبيِّ ﷺ من الأحاديث، بحيث يُمكن مُعالجةُ قضيةِ الخطأ والسَّهو الواقعين من الرَّاوي الثِّقة؛ إذ هما أمران حاصلان وواقعان في أحاديث الثِّقات فضلاً عن وقوعهما في أَحاديث الضُّعفاء، وما يُذكر في حدِّ الصَّحيح من كونِ راويه تامّ الضَّبط فإنَّه أَمرٌ نسبيٌّ؛ لأنَّه يشترطُ في الصَّحيح أن لا يكون شاذاً ولا مُعلَّلاً مع كون راويه ثقةً، واشترط المُحَدِّثون هذا للوقوف على الوهم والخطأ الذي يدخل إلى أحاديث الثِّقات."]]},{"id":"u65_2","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ٢","segs":[["ctx","ثُمَّ إنَّ الوهم والخطأ من الأسباب الرِّئيسة للاختلاف بين الأحاديث، وبالسَّبر والنَّظر إلى كتب السُّنة النَّبوية نجد عدداً كبيراً من الرُّواة الثِّقات قد أخطؤوا في بعض ما رووا، وهو أَمرٌ متفاوت بين الرُّواة حسب مَروياتهم قلّةً وكثرةً، ورُبَّما كان حظّ المكثرين مِن الرِّوَايَة مِن الخطأ أكبر مِن المقلين؛ لذا نجد غلطات عُدَّتْ على الأئمة العلماء الحُفَّاظ لكنَّها لم تُؤثِّر عليهم في سعة ما رووه، قال الإمام مسلمُ: «فليس من ناقلِ خبرٍ وحاملِ أثرٍ من السَّلفِ الماضين إلى زماننا ـ وإن كان من أحفظ النَّاس وأشدهم توقياً وإتقاناً لما يحفظ وينقل ـ إلا الغلط والسَّهو ممكنٌ في حفظِه ونقلِه»."]]},{"id":"u65_3","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ٣","segs":[["ctx","ومعنى الشُّذوذ عند فقهاء الحنفية قريبٌ من معناه عند المُحَدِّثين، لكن بالنَّظر إلى المعنى والعمل، فعدم القَبول للرِّواية من قِبَلِ مجتهدي الصَّحابة والتَّابعين رضي الله عنهم يجعلها شاذة، وتركهم للعمل بها يعتبر علَّة قادحة مؤثرة في الرِّواية."]]},{"id":"u65_4","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ٤","segs":[["ctx","فإذا كانت مخالفةُ الثِّقةِ للثِّقات سبباً لشذوذِ الرِّوايةِ والطَّعن فيها، فلا شَكَّ أَنَّ مخالفةَ الرَّاوي لَمن هو أَعلى درجةً من الثِّقات من كبارِ الصَّحابةِ والتَّابعين رضي الله عنهم الذين لم يقبلوا هذه الرِّواية أَكثر تأثيراً في الطَّعن بها، وكذلك إن كانت وجوهُ العللِ المُختلفة في الأسانيدِ والمتونِ سبباً لردِّ الرِّواية وتضعيفِها، فلا شَكَّ أَنَّ عدمَ عملِ مجتهدي الصَّحابة والتَّابعين رضي الله عنهم فيها أَقوى في رَدِّها، فهم غيرُ متهمين أَبداً، وهذا ظاهرٌ في وقوفِهم على أمرٍ من نسخٍ أو تخصيصٍ أو تأويلٍ يمنعُ الأخذ بها رغم روايتها عنهم."]]},{"id":"u65_5","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ٥","segs":[["ctx","ويُوَضِّح عيسى بن أبان المقصود بالشَّاذِّ عند الحنفية، فيقول: «لا يُقبل خبرٌ خاصٌ في رَدِّ شيء من القرآن ظاهر المعنى أن يصيرَ خاصّاً أو منسوخاً، حتى يجيء ذلك مجيئاً ظاهراً يعرفه النَّاس ويعلمون به، مثل: ما جاء عن النَّبي ﷺ أن «لا وصية لوارث»، «ولا تنكح المرأة على عمّتها»، فإذا جاء هذا المجيء فهو مقبول؛ لأنَّ مثله لا يكون وهماً، وأما إذا رُوِي عن رسول الله ﷺ حديث خاصّ وكان ظاهرُ معناه بيان السُّنن والأحكام، أو كان ينقض سنةً مُجمعاً عليها، أو يُخالف شيئاً من ظاهر القرآن، فكان للحديث وجهٌ ومعنى يُحمَل عليه لا يُخالف ذلك، حُمل معناه على أحسن وجوهه وأشبهه بالسُّنن وأوفقه لظاهر القرآن، فإن لم يكن معنى يحمل ذلك، فهو شاذ»."]]},{"id":"u65_6","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ٦","segs":[["ctx","ويُستفاد من كلامه: أَنَّ الشُّذوذَ متعلِّق بخبرٍ مَرويٍّ بطريق الآحاد ـ خاص ـ وجاء بمعنى مخالفٍ لما هو أَثبت وأَقوى منه من قرآن أو سنة ثابتة، فإن كان له معنى لا يُخالف الأقوى، فيُحمل على ما يتوافق مع السُّنن وظواهر القرآن، ولا يَكون شاذّاً إن تَلَقَّته الأُمَّة بالقَبول وعملت به؛ لأنَّ قَبولَ العلماء له يرفع احتمال الوهم الحاصل في روايةِ الثِّقات، ويؤكِّدُ ثبوته عن النَّبيّ ﷺ."]]},{"id":"u65_7","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ٧","segs":[["ctx","فمدارُ الشُّذوذِ عندهم على آحادية نقله، وعدم القَبول له، ومُخالفته لما هو أقوى منه."]]},{"id":"u65_8","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ٨","segs":[["ctx","وهذا الكلام في غايةِ الدِّقّةِ والضَّبطِ والتَّمكنِ في تنقيحِ الثَّابتِ من حديثِ المصطفى ﷺ؛ لما سيترتب عليه من بناء الأحكام ."]]},{"id":"u65_9","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ٩","segs":[["ctx","وكان لهم استعمال واسعٌ لمصطلح العلَّة، وردوا كثيراً من الأحاديث؛ لكونها معلولة، ولكنَّ وصف العلَّة عندهم مختلفٌ عن المُحَدِّثين في أَنَّ مداره على المعنى والقَبول والعمل والمخالفة والمعارضة التي هي محلُّ اهتمام الفقهاء دون المُحَدِّثين، فمن العلل التي تُرَدُّ بها أخبار الآحاد كما قال ابن أبان: «ذكر أنَّ خبر الواحد يُرَدُّ لمعارضةِ السُّنة الثَّابتة إيّاه، أو أن يَتَعلَّق القرآن بخلافه فيما لا يحتمل المعاني، أو يكون من الأمور العامَّة، فيجيء خبر خاصٌ لا تعرفه العامَّة، أو يكون شاذّاً قد رواه النَّاس وعملوا بخلافه ... حديث: «إنَّ الميت يعذب ببكاء أهله عليه» ظاهره مخالفٌ لقوله تعالى: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ﴾ [الإسراء:١٥]، وكذلك معارضةُ السُّنةُ الثَّابتةُ إيّاه، علَّةٌ تَرُدُّ هذا المعنى بعينه؛ لأنَّ السُّنة الثَّابتة من طريق التَّواتر توجب العلم كنص الكتاب...»."]]},{"id":"u65_10","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ١٠","segs":[["ctx","ومدارُ الشُّهرةِ على القَبول والعَمل من السَّلف: قال الجصَّاص: «إنَّ ما تَلَقَّاه النَّاسُ بالقَبول وإن كان من أخبار الآحاد فهو عندنا يجري مجرى التَّواتر، وهو يوجب العلم، فجاز تخصيص القرآن به». وقال الكوثري: «واحتجاج الأئمة بحديث تصحيحٌ له منهم، بل جمهورُ أهل العلم من جميع الطَّوائف على أنَّ خبرَ الواحد إذا تَلَقَّته الأُمَّة بالقَبول تصديقاً له أو عملاً به أَنَّه يوجب العلم»."]]},{"id":"u65_11","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ١١","segs":[["ctx","ومعاملة الأخبار التي تَلَقَّتها الأُمَّة بالقَبول معاملة المتواتر إجمالاً لأمور منها:"]]},{"id":"u65_12","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ١٢","segs":[["ctx","أ. أَنَّه إذا ظهر في السَّلف استعماله والقول به مع اختلافهم في شرائط قَبول الأخبار وتسويغ الاجتهاد في قَبولها وردِّها، فلولا أَنَّهم قد علموا صحّتَه واستقامتَه لَما ظَهَرَ منهم الاتفاق على قَبوله واستعماله، وهذا وجهٌ يوجب العلم بصحّة النَّقل."]]},{"id":"u65_13","kind":"text","label":"المطلب الثَّاني: السُّنة المشهورة · الفقرة ١٣","segs":[["ctx","ب. أنَّ مثلَهم إذا اتفقوا على شيء ثبت به الإجماع، وإن انفرد عنهم بعضُهم كان شاذّاً لا يقدح خلافه في صحّةِ الإجماع، ولا يُلتفت بعد ذلك إلى خلافِ مَن خالف فيه، فلذلك جاز تخصيصُ ظاهر القرآن بما كان هذا وصفُه من الأخبار."]]}],"sup":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ"},{"id":"u65a","title":"أولاً: معنى المشهور","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u65a_1","kind":"def","label":"أولاً: معنى المشهور · الفقرة ١","segs":[["matn","أولاً: معنى المشهور:"],["ctx","سُمِّيَ بذلك؛ لوضوحه، ويُسَمَّى المستفيض، يقال: استفاض: أي شاع، وخبرٌ مستفيضٌ: أي منتشرٌ بين النَّاس؛ لاشتهاره، من فاض الماء يفيض فيضاً."]]},{"id":"u65a_2","kind":"def","label":"أولاً: معنى المشهور · الفقرة ٢","segs":[["matn","واصطلاحاً: ما كان من الآحاد في الأصل، ثُمَّ انتشر فصار ينقلُه قومٌ لا يتوهم تواطؤهم على الكذب، وهم القرن الثَّاني بعد الصَّحابة رضي الله عنهم، ومَن بعدهم."]]},{"id":"u65a_3","kind":"text","label":"أولاً: معنى المشهور · الفقرة ٣","segs":[["ctx","وإنَّما كان الاعتبار للاشتهار في القرن الثَّاني والثَّالث، ولا عبرة للاشتهار في القرون التي بعد القرون الثَّلاثة؛ لأنَّ عامَّة أَخبار الآحاد اشتُهرت بعد القرن الثَّالث، ولا تُسَمَّى بسبب ذلك مشهورة، فلا يجوز بها الزِّيادة على الكتاب، مثل: خبر الفاتحة والتَّسمية في الوضوء وغيرهما."]]},{"id":"u65a_4","kind":"text","label":"أولاً: معنى المشهور · الفقرة ٤","segs":[["ctx","وظاهرُ الكلام أَنَّه ما كَثُر عدد رواته بعد الصَّحابة رضي الله عنهم إلى حدِّ التَّواتر كان مشهوراً، فينبغي أن يُفهمَ هذا بمعنى قَبولهم له وأخذهم به فشاعت روايته بينهم، وإلا فستكون أفرادُه قليلةً ويصعب ضبطها، وكذا سيخرج كثيرٌ من الأحاديث التي ذكروها من أفرادِ المشهور؛ لكونها آحاداً."]]},{"id":"u65a_5","kind":"def","label":"أولاً: معنى المشهور · الفقرة ٥","segs":[["ctx","والذي يَتَرَجَّحُ عندي بعد استقرائيّ لما ذكروا من المشهورِ في كتبِ الفقهِ والأُصول في ضبطِ السُّنة المشهورة: أَنَّه سُنَّة الآحاد إذا تأيّدت بعمل الصَّحابة رضي الله عنهم والتَّابعين وقَبولهم، وبعبارة أُخرى:"],["matn","هو حديث الآحاد الذي تَلَقَّاه السَّلف بالقَبول."]]},{"id":"u65a_6","kind":"text","label":"أولاً: معنى المشهور · الفقرة ٦","segs":[["ctx","فما عرفته به ظاهر في عامَّةِ الأحاديثِ التي اعتبروها مشهورةً، حيث بيّنوا أَنَّها تَلَقَّتها الأُمَّةُ بالقَبول وإن كانت آحاداً في حقيقتِها، وهذا التَّلقي بالقَبول والعمل ليس خاصّاً بمَن بعد الصَّحابة رضي الله عنهم كما يفيدُه تعريفُهم السَّابق، وإنَّما تتحقَّق الشُّهرةُ بقَبول الصَّحابة رضي الله عنهم وتلقيهم لها، وهو الأَقوى في شهرتها."]]},{"id":"u65a_7","kind":"text","label":"أولاً: معنى المشهور · الفقرة ٧","segs":[["ctx","وبهذا لا يتمكن أَحدٌ من الإنكارِ على الفقهاءِ في عَدِّهم لأحاديث الآحاد مشهورةً أثناء استدلالهم؛ لأنَّ كلامهم في رفعها إلى هذه الدَّرجة غير راجع إلى طرقِ الرِّواية، وإنَّما إلى العمل والقَبول."]]},{"id":"u65a_8","kind":"text","label":"أولاً: معنى المشهور · الفقرة ٨","segs":[["ctx","وهذا الاعتبار للعمل والقَبول في تقوية الحديث غير خاصّ بالحنفية، وإنَّما مشهورٌ عند المالكية بـ«عمل أهل المدينة»، وأيضاً وجدنا كبار الحُفَّاظ من أهل الحديث يعتبرونه ويعتمدونه، فها هو الخطيب البغداديُّ عند كلامه على حديث معاذ رضي الله عنه في الاجتهاد ـ الآتي ذكره ـ يقول: «إنَّ أهل العلم قد تقبلوه واحتجوا به، فوقفنا بذلك على صحَّته عندهم، كما وقفنا على صحّة قول رسول الله ﷺ: «لا وصية لوارث»، وقوله ﷺ في البحر: «هو الطَّهور ماؤه الحل ميتته»، وقوله ﷺ: «إذا اختلف المتبايعان في الثَّمن والسِّلعة قائمةً تحالفا وترادا»، وقوله ﷺ: «الدِّيَة على العاقلة»، وإن كانت هذه الأحاديث لا تَثبت من جهة الإسناد، لكن لما تَلَقَّتها الكافَّة عن الكافَّة غنوا بصحتها عندهم عن طلبِ الإسناد لها، فكذلك حديث معاذ رضي الله عنه لَمّا احتجوا به جميعاً غنوا عن طلب الإسناد له»."]]},{"id":"u65a_9","kind":"text","label":"أولاً: معنى المشهور · الفقرة ٩","segs":[["ctx","وهذا يؤيِّدُ ما رَجَّحناه من تعريفٍ للمشهور في حصول الغنى عن البحثِ في الأسانيد؛ بسبب حصول هذا القَبول، قال الكوثري عند مناقشته لشهرة حديث: «لا وصية لوارث»: «ولا يَضرُّ الكلام في سندِ خاصٍّ من أسانيد الحديث بعد أن ورد بأسانيد لا تحصى، وأخذت به الأُمَّة جمعاء خلفاً عن سلف، على أنَّ الكلام في الأسانيد إنَّما يكون عند أهل النَّقد فيما لم يستفض هذه الاستفاضة، ولم تُأخذ هذا الأخذ»."]]}],"sup":"المطلب الثَّاني: السُّنة المشهورة"},{"id":"u65b","title":"ثانياً: حكم المشهور","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u65b_1","kind":"def","label":"ثانياً: حكم المشهور · الفقرة ١","segs":[["matn","ثانياً: حكم المشهور:"],["ctx","إنَّ هذا الخبر وإن كان من الآحاد في أصلِه، إلا أنَّ هؤلاء القوم أئمةٌ ثقاتٌ لا يُتهمون، فصار الخبر بشهادتهم وتصديقهم بمنزلة المتواتر حجةٌ من حجج الله تعالى، لكن للأصوليين في حكمه قولان مشهوران، وهما:"]]},{"id":"u65b_2","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ٢","segs":[["ctx","أ. أَنَّه مثل المتواتر، فيثبت به علم اليقين لكن بطريق الاستدلال لا بطريق الضَّرورة؛ لأنَّ التَّابعين لَمّا أَجمعوا على قَبوله والعمل به ثبت صدقه؛ لأَنَّه لا يتوهم اتفاقَهم على القَبول إلا بجامعٍ جمعَهم عليه، وليس ذلك إلا تعيينُ جانبِ الصِّدقِ في الرُّواة، ولهذا سَمَّينا العلم الثَّابت به استدلالياً لا ضرورياً، فلا يَكفر جاحدُه؛ لأنَّ إنكارَه وجحودَه لا يؤدي إلى تكذيب الرَّسول ﷺ."]]},{"id":"u65b_3","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ٣","segs":[["ctx","ب. أَنَّه يوجب علم طمأنينة لا علم يقين، والطمأنينة: زيادة توطين وتسكين يحصل للنَّفس على ما أدركته، فإن كان المدركُ يقينياً فاطمئنانها زيادة اليقين وكماله، كما يحصل للمتيقّن بوجود مكّة بعدما يشاهدُها، وإليه الإشارةُ بقوله تعالى حكاية عن إبراهيم عليه السلام: ﴿وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِي﴾ [البقرة:٢٦٠]، وإن كان ظنيّاً فاطمئنانها رُجحان جانب الظَّنِّ بحيث يكاد يدخل في حدّ اليقين، وهو المراد هاهنا."]]},{"id":"u65b_4","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ٤","segs":[["ctx","وحاصله سكون النَّفس عن الاضطراب بشبهة إلا عند ملاحظة كونه آحاد الأصل، فكان دون المتواتر وفوق خبر الواحد، حتى جازت الزِّيادة به على كتاب الله تعالى التي هي تعدل النَّسخ، وبه قال عيسى بن أبان، وهو اختيارُ القاضي الإمام أبي زيد، والشَّيخين، وعامَّة المتأخرين، وصَحَّحه فخرُ الإسلام البَزْدويّ؛ لأنَّ المشهورَ بشهادةِ السَّلف صار حجّة للعمل به كالمتواتر، فيسقط به علم اليقين؛ ولهذا لم يكفر جاحده؛ لأَنَّه لا يثبت إلا بإنكار اليقين، ولكنَّه يُضلَّل."]]},{"id":"u65b_5","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ٥","segs":[["ctx","قال أبو اليسر: وحاصل الاختلاف راجعٌ إلى الإكفار، فعند الفريق الأوّل ـ يعني من أَصحابنا ـ يَكفر جاحدُه، وعند الفريق الثَّاني لا يكفر."]]},{"id":"u65b_6","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ٦","segs":[["ctx","ونصَّ شمسُ الأئمة السَّرَخسيُّ على أنَّ جاحدَه لا يَكفر بالاتفاق، وإليه أُشير في «الميزان» أيضاً، وعلى هذا لا يظهر أثر الخلاف في الأحكام على الصَّحيح."]]},{"id":"u65b_7","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ٧","segs":[["ctx","«فلم يختلف حكم الجصَّاص عن حكم ابن أبان في المتواتر والمشهور، حيث صرحا في المتواتر أنَّه يوجب علم الاضطرار، أما في المشهور فصرحا أيضاً أنَّه لا يوجب علم الاضطرار، ولم يُكَفِّر الإمام الجصَّاص جاحد المشهور أبداً»."]]},{"id":"u65b_8","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ٨","segs":[["ctx","ومن أمثلته:"]]},{"id":"u65b_9","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ٩","segs":[["ctx","أ. الأحاديث المشهورة في رجم ماعز والغامدية، وغيرها: كحديث عبادة بن الصَّامت رضي الله عنه، قال ﷺ: «خذوا عنّي خذوا عنّي، قد جَعَلَ اللهُ لَهُنَّ سبيلا، البكرُ بالبكر جلدُ مئة ونفي سنة، والثَّيبُ بالثَّيبِ جلدُ مئةٍ والرَّجم»، جاز الزِّيادة بها على عمومِ قوله جل جلاله: ﴿ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجْلِدُواْ كُلَّ وَٰحِدٖ مِّنْهُمَا مِاْئَةَ جَلْدَةٖ﴾ [النور:٢]؛ إذ يتناول الحديث المُحْصَن كما يتناول غيره، فبزيادة الرَّجم انتسخ حكم الجلد في حقّه."]]},{"id":"u65b_10","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ١٠","segs":[["ctx","ب. أثر ابن مسعود رضي الله عنه: «كان إذا رأى النِّساء قال: أخروهنَّ حيث أَخَّرهنَّ الله، وقال: إنَّهن مع بني إسرائيل يصففن مع الرِّجال، كانت المرأة تلبس القالب فتطال لخليلها، فسلطت عليهن الحيضة ، وحرمت عليهن المساجد»، وهذا من المشاهير، فجازت الزِّيادة به على الكتاب، وهو اختيارُ المكان المختار، إذ المختار للرِّجال التَّقدُّم على النِّساء، ففي ترك المكان المختار ترك لفرض من فروض الصَّلاة؛ لأنَّ الأمرَ بالتَّأخير كان من أَجل الصَّلاة، فكان من فرائض الصَّلاة."]]},{"id":"u65b_11","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ١١","segs":[["ctx","ج. الحديث المشهور في رفع اليدين: «ترفع الأيدي في سبعة مواطن: في افتتاح الصَّلاة، وفي التكبير للقنوت في الوتر، وفي العيدين، وعند استلام الحجر، وعلى الصَّفا والمروة، وبجمع، وعرفات، وعند المقامين، وعند الجمرتين»، قال السَّرَخسيّ: «إنَّ الآثار لَمّا اختلفت في فعلِ النَّبي ﷺ ـ أي في الرَّفع عند الرُّكوع والقيام ـ يتحاكم إلى الحديث المشهور» هذا."]]},{"id":"u65b_12","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ١٢","segs":[["ctx","د. الحديث المشهور في حرمة الجمع بين المرأة وعمّتها وخالتها: «نهى رسول الله ﷺ أن تنكح المرأة على عمّتها أو خالتها»، وهذا الحديث يرويه رجلان من الصَّحابة رضي الله عنهم: ابن عباس وجابر رضي الله عنهم، وهو مشهور في لغة العلماء بالقَبول والعمل به، ومثلُه حجةٌ يجوز به الزِّيادة على كتابِ الله جل جلاله، وفيه دليل على حرمةِ نكاح المرأة على عمَّتِها وخالتِها."]]},{"id":"u65b_13","kind":"text","label":"ثانياً: حكم المشهور · الفقرة ١٣","segs":[["ctx","هـ. الحديث المشهور: «لا يُقتل والدٌ بولده»، قال الجصَّاص: «وهذا خبرٌ مستفيضٌ مشهورٌ، وقد حكم به عمر بن الخطاب رضي الله عنه بحضرة الصَّحابة رضي الله عنهم من غير خلاف من واحدٍ منهم عليه، فكان بمنزلة قوله: «لا وصية لوارث» ونحوه في لزوم الحكم به، وكان في حيزِ المستفيض المتواتر»."]]}],"sup":"المطلب الثَّاني: السُّنة المشهورة"},{"id":"u66","title":"المطلب الثَّالث: سُنَّة الآحاد","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u66_1","kind":"def","label":"المطلب الثَّالث: سُنَّة الآحاد · الفقرة ١","segs":[["matn","وهو كل خبر يرويه الواحد أو الاثنان فصاعداً، لا عبرة للعدد فيه بعد أن يكون دون المشهور والمتواتر."]]},{"id":"u66_2","kind":"def","label":"المطلب الثَّالث: سُنَّة الآحاد · الفقرة ٢","segs":[["matn","وحكم الآحاد: إفادة غلبة الظَّنِّ بمدلولها"],["ctx","، لا اليقين ولا الطَّمأنينة، وهي كافيةٌ في"],["matn","وجوب العمل دون العلم القطعي"],["ctx","؛ لقوله جل جلاله: ﴿فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٖ مِّنْهُمْ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوْمَهُمْ إِذَا رَجَعُوٓاْ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ﴾ [التوبة:١٢٢]، الطائفة: الواحد والاثنين فأكثر، فهذا يوجب العمل بخبر الواحد أو الاثنين، وإذا أُوجب ههنا أُوجب مطلقاً، ولأنَّ رسول الله ﷺ قَبِل خبر الواحد."]]},{"id":"u66_3","kind":"text","label":"المطلب الثَّالث: سُنَّة الآحاد · الفقرة ٣","segs":[["ctx","فعن أنس رضي الله عنه: «إنَّ النَّبي ﷺ أتي بلحم تُصُدِّقَ به على بريرة رضي الله عنها، فقال: هو عليها صدقة، وهو لنا هدية»؛ إذ قبل قول بريرة في الصَّدقة، وكذلك كان يرسل الأفراد من أصحابه إلى الآفاق؛ لتبليغ الأحكام وإيجاب قَبولها على الأنام كما حصل عند بعث معاذ وعليّ رضي الله عنهم لليمن، فلو لم يكن خبر الواحد موجباً للعلم لما بعثهم، ولأنَّ الصَّحابة رضي الله عنهم أجمعوا على قَبول خبر الواحد في العمل كما حصل مع سيدنا أبي بكر الصِّديق عندما احتج على الأنصار بقوله ﷺ: «الأئمة من قريش»، فقبلوه من غير إنكار، وعلى هذا جرت سُنَّة التَّابعين، وأجمعوا على قَبول خبر الواحد في أمور الدِّين مثل الإخبار بطهارة الماء ونجاسته، ولأنَّ المتواتر لا يوجد في كلِّ حادثةٍ، فلو رد خبر الواحد لتعطلت الأحكام."]]}],"sup":"المبحث الأوّل كيفيّة الاتصال بنا من النَّبيّ ﷺ"},{"id":"u68","title":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u68_1","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١","segs":[["ctx","هذا المطلب متعلِّقٌ برواةِ الأحاديث من الصَّحابة رضي الله عنهم، فبسبب أنَّ أبا حنيفة كان تابعياً، فبحث الرِّجال بالنِّسبة لأبي حنيفة كان متعلِّقاً بالصَّحابة رضي الله عنهم؛ لأنَّها الطَّبقة التي بينه وبين رسول الله ﷺ بعد شيوخه من التَّابعين."]]},{"id":"u68_2","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ٢","segs":[["ctx","ولدقَّة الحنفية الفائقة في علم الحديث وتحريهم الشَّديد فيما يثبت عن رسول الله ﷺ، قاموا بتقسيم الصَّحابة رضي الله عنهم إلى سبع طبقات، لكلّ طبقةٍ منها حكمها في قَبول الأحاديث، وتندرج هذه الطَّبقات تحت قسمين رئيسيين، وهما:"]]},{"id":"u68_3","kind":"def","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ٣","segs":[["matn","الأول: معروف، وهو نوعان:"],["ctx","١."],["matn","مَن كان معروفاً بالفقه والرَّأي في الاجتهاد، وهم كبار المجتهدين من الصَّحابة رضي الله عنهم"],["ctx","؛ كأبي بكر وعمر وعثمان وعليّ وابن مسعود وابن عباس وأبي الدَّرداء وزيد بن ثابت ومعاذ بن جبل وأبي موسى الأشعري وعائشة وغيرهم من المشهورين بالفقه من الصَّحابة رضي الله عنهم."]]},{"id":"u68_4","kind":"def","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ٤","segs":[["matn","وحكم خبرهم: وجوب العمل به، سواء كان موافقاً للقياس أو مخالفاً له"],["ctx","، فإن كان موافقاً للقياس تأيّد به، وإن كان مخالفاً للقياس يُتْرَكُ القياسُ ويُعمل بالخبر؛ لأنَّ قولَ النَّبي ﷺ موجبٌ للعلم باعتبار أصله، وإنَّما الشُّبهة في النَّقل عنه، بخلاف الوصف الثَّابت به القياس، فالشُّبهةُ والاحتمالُ في أصله؛ لأنا لا نعلم يقيناً أنَّ ثبوت الحكم المنصوص باعتبار هذا الوصف من بين سائر الأوصاف، وما يكون الشُّبهة في أصله أقلُّ درجةً مما يكون الشُّبهة في طريقه بعد التَّيقُّن بأصله."]]},{"id":"u68_5","kind":"def","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ٥","segs":[["ctx","٢."],["matn","مَن كان معروفاً بالعدالة وحسن الضَّبط والحفظ، ولكنَّهم لم يبلغوا درجةَ كبار المجتهدين من الصَّحابة رضي الله عنهم، فكانت رتبتهم في الاجتهاد أقلّ"],["ctx",": كأبي هريرة وابن عمر وأنس بن مالك وسلمان وبلال رضي الله عنهم وغيرهم مِمَّن اشتهر بالصُّحبة مع رسول الله ﷺ والسَّماع منه مدّةً طويلةً في الحضر والسَّفر."]]},{"id":"u68_6","kind":"def","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ٦","segs":[["matn","وحكم خبرهم: إن وافق القياس عُمِل به، وإن خالفه لم يترك إلا إن أدى العمل به إلى انسداد باب الرَّأي، فحينئذ يترك ويُعمل بالقياس."]]},{"id":"u68_7","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ٧","segs":[["ctx","فإنَّ أبا هريرة رضي الله عنه ممن لا يَشكُّ أحدٌ في عدالته وطول صحبته مع رسول الله ﷺ، وكذلك في حُسن حفظه وضبطه، فقد دعا له رسول الله ﷺ بذلك، قال أبو هريرة رضي الله عنه: «إنَّكم تزعمون أنَّ أبا هريرة يُكثر الحديث على رسول الله ﷺ، والله المَوْعِدُ إني كنت امرأً مسكيناً أَلزم رسول الله ﷺ على ملء بطني، وكان المهاجرون يشغلهم الصَّفق بالأسواق، وكانت الأنصارُ يشغلهم القيام على أموالهم، فشهدت من رسول الله ﷺ ذات يوم، وقال: مَن يبسط رداءه حتى أقضي مقالتي ثمّ يقبضه، فلن ينسى شيئاً سمعه مني، فبسطت بردة كانت عليَّ، فوالذي بعثَه بالحقّ ما نسيتُ شيئاً سمعته منه»، ولكن مع هذا قد اشتهر عن الصَّحابة رضي الله عنهم ومَن بعدهم بترك بعض روايات أبي هريرة رضي الله عنه إن خالفت القياس، ومنها:"]]},{"id":"u68_8","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ٨","segs":[["ctx","عن أبي هريرة رضي الله عنه، قال ﷺ: «الوضوء مما مسَّت النَّار ولو من ثور أقط، فقال له ابن عباس رضي الله عنه: يا أبا هريرة، أنتوضأ من الدُّهن؟ أنتوضأ من الحميم؟ فقال أبو هريرة رضي الله عنه: يا ابن أخي، إذا سمعت حديثاً عن رسول الله ﷺ فلا تضرب له مثلاً»: أي إن توضأنا بماء سُخن أنتوضأ بماء بارد، وإن ادهنا أنتوضأ، فقد رد ابن عباس رضي الله عنهم خبر أبي هريرة رضي الله عنه بالقياس."]]},{"id":"u68_9","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ٩","segs":[["ctx","وعن عائشة رضي الله عنها سمعت أنَّ أبا هريرة رضي الله عنه يروي: «أنَّ ولد الزِّنا شر الثلاثة»، و«إنَّ الميت ليعذب ببكاء أهله عليه»، ردت هذا بقوله تعالى: ﴿وَلَا تَزِرُ وَازِرَةٞ وِزْرَ أُخْرَىٰ﴾ [الإسراء:١٥]."]]},{"id":"u68_10","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١٠","segs":[["ctx","وعن أبي هريرة رضي الله عنه: «مَن غسل ميتاً اغتسل ومَن حمله توضأ»، فبلغ ذلك عائشة رضي الله عنها فَرَدَّت حديثه بالقياس، فقالت: «أوينجس موتى المسلمين، وما على رجل لو حمل عوداً»."]]},{"id":"u68_11","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١١","segs":[["ctx","وعن عمر بن الخطاب رضي الله عنه قال لأبي هريرة رضي الله عنه: «لتتركنَّ الحديث عن رسول الله ﷺ أو لأُلحقنك بأرض دوس»."]]},{"id":"u68_12","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١٢","segs":[["ctx","قال إبراهيم النَّخعي: «لم يكونوا يأخذون من حديث أبي هريرة رضي الله عنه إلا كذا وكذا»، وفي لفظ: «كانوا يأخذون من حديث أبي هريرة رضي الله عنه ويدعون»."]]},{"id":"u68_13","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١٣","segs":[["ctx","وقال السَّرَخسيّ بعد ذِكر الآثار السَّابقة: «فلما كان ما اشتهر من السَّلف في هذا الباب، قلنا ما وافق القياس من روايته فهو معمول به، وما خالف القياس فإن تَلَقَّته الأُمَّة بالقَبول فهو معمول به، وإلا فالقياس الصَّحيح شرعاً مقدَّمٌ على روايته فيما ينسد باب الرَّأي فيه."]]},{"id":"u68_14","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١٤","segs":[["ctx","ولعلَّ ظاناً يظنّ أنَّ في مقالتنا ازدراء به، ومعاذ الله تعالى من ذلك، فهو مُقدَّمٌ في العدالة والحفظ والضَّبط كما قرَّرنا، ولكنّ نقل الخبر بالمعنى كان مستفيضاً فيهم، والوقوف على كلِّ معنى أراده رسول الله ﷺ بكلامه أمرٌ عظيمٌ، فقد أوتي جوامع الكلم على ما قال: «أُوتيت جوامع الكلم»، واختصر لي اختصاراً، ومعلوم أنَّ النَّاقل بالمعنى لا ينقل إلا بقدر ما فهمه من العبارة، وعند قصور فهم السَّامع ربّما يذهب عليه بعض المراد، وهذا القصور لا يشكل عند المقابلة بما هو فقه لفظ رسول الله ﷺ، فلتوهم هذا القصور، قلنا: إذا انسد باب الرَّأي فيما رُوي، وتحقَّقت الضَّرورة بكونه مخالفاً للقياس الصَّحيح، فلا بُدَّ من تركه؛ لأنَّ كونَ القياس الصَّحيح حجّة ثابتة بالكتاب والسُّنة والإجماع، فما خالف القياس الصَّحيح من كلِّ وجهٍ فهو في المعنى مخالف للكتاب والسُّنة المشهورة والإجماع."]]},{"id":"u68_15","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١٥","segs":[["ctx","وبيان هذا في حديث المُصَرَّاة، فإنَّ الأمرَ بردِّ صاع من تمر مكان اللبن قلَّ أو كثر مخالفٌ للقياس الصَّحيح من كلِّ وجهٍ؛ لأنَّ تقديرَ الضَّمان في العدوانات بالمثل أو القيمة حكمٌ ثابت بالكتاب والسُّنة والإجماع... ويتبين أنَّه كالمخالف للكتاب والسُّنة المشهورة والإجماع."]]},{"id":"u68_16","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١٦","segs":[["ctx","ثُمَّ هذا النَّوع من القصور لا يتوهم في الرَّاوي إذا كان فقيهاً؛ لأنَّ ذلك لا يخفى عليه لقوّة فقهه، فالظَّاهر أنَّه إنَّما روى الحديث بالمعنى عن بصيرة، فإنَّه علم سماعه من رسول الله ﷺ كذلك مخالفاً للقياس، ولا تهمة في روايته، فكأنا سمعنا ذلك من رسول الله ﷺ، فيلزمنا ترك كلّ قياس بمقابلته؛ ولهذا قلَّت روايةُ الكبار من فقهاء الصَّحابة رضي الله عنهم..."]]},{"id":"u68_17","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١٧","segs":[["ctx","ومع هذا كله، فالكبارُ من أصحابنا يُعَظِّمون روايةَ هذا النَّوع منهم ويَعتمدون قولهم، فإنَّ مُحمّداً ذكر عن أبي حنيفة أنَّه أخذ بقول أنس رضي الله عنه في مقدار الحيض وغيره، وكان درجةُ أبي هريرة رضي الله عنه فوقَ درجته، فعرفنا بهذا أنَّهم ما تركوا العمل بروايتهم إلا عند الضَّرورة لانسداد باب الرَّأي من الوجه الذي قرّرنا»."]]},{"id":"u68_18","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١٨","segs":[["ctx","وهذا النَّقل عن السَّرخسي يوضح لنا الاحترام والتَّقدير والتَّبجيل العظيم الذي يَكُنُّهُ أصوليوا وفقهاء المذهب الحنفي لصحابة رسول الله ﷺ عامَّة وأبي هريرة رضي الله عنه خاصَّة، رغم مشي السَّرخسي مع جمهور علماء الحنفية القائلين باعتبار فقه الرَّاوي، وعدم أخذهم بحديثه في حالة روايته؛ لما يخالف الأصول الأُخرى من القرآن والسُّنة والإجماع، فالمسألةُ إذن مسألةٌ علميةٌ باعتماد أصل يرجح فيه الأدلة عند تعارضها لا غير، وقد لاحظنا قوّة استدلالهم على ذلك."]]},{"id":"u68_19","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ١٩","segs":[["ctx","وحصل اختلاف بين علماء الحنفية في اجتهاد أبي هريرة رضي الله عنه، فلم يُسلِّم بعضهم أنَّ أبا هريرة رضي الله عنه لم يكن فقيهاً، بل كان فقيهاً، ولم يعدم شيئاً من أسباب الاجتهاد، وقد كان يُفتي في زمان الصَّحابة رضي الله عنهم، وما كان يُفتي في ذلك الزَّمان إلا فقيه مجتهد، وكان من عِلية أصحاب رسول الله ﷺ ورضي عنهم، وقد دعا النَّبي ﷺ له بالحفظ، فاستجاب الله تعالى له فيه، حتى انتشر في العالم ذكره وحديثه، فلا وجه إلى ردِّ حديثه بالقياس، قال عبد العزيز البخاري: «إنَّا لا نُسَلِّمُ أنَّ أبا هريرة لم يكن فقيهاً...»، ومثله ابنُ ملك، وجزم بذلك ابنُ الهُمام وقال ابنُ أمير حاج: «هذا هو الصَّحيح»."]]},{"id":"u68_20","kind":"text","label":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة · الفقرة ٢٠","segs":[["ctx","لذلك كان الأولى عدّه ومَن في طبقته من المجتهدين، لكن اجتهادهم لم يبلغ درجة اجتهاد كبار المجتهدين من الصَّحابة رضي الله عنهم؛ لأنَّ عصر الصَّحابة رضي الله عنهم كان من عصور الاجتهاد المطلق، فمَن كان مشتغلاً بالعلم فهو في درجات الاجتهاد، لكن درجاتهم متفاوتة فيه، والله أعلم."]]}],"sup":"المبحث الثَّاني رُواة الأحاديث"},{"id":"u68a","title":"الثاني: مجهول","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u68a_1","kind":"def","label":"الثاني: مجهول · الفقرة ١","segs":[["matn","الثاني: مجهول:"],["ctx","وهم مَن لم يشتهروا بطول الصُّحبة مع رسول الله ﷺ، وإنَّما عُرِف بما روى من حديث أو حديثين، نحو: وابصة بن معبد، وسلمة بن المحبق، ومعقل بن سنان الأشجعيّ رضي الله عنهم وغيرهم،"],["matn","ورواية هذا النَّوع على خمسة أوجه:"]]},{"id":"u68a_2","kind":"def","label":"الثاني: مجهول · الفقرة ٢","segs":[["ctx","١."],["matn","أن يشتهر خبره؛ لقَبول الفقهاء روايته والرِّواية عنه."]]},{"id":"u68a_3","kind":"def","label":"الثاني: مجهول · الفقرة ٣","segs":[["matn","وحكم خبره: وجوب العمل به مطلقاً"],["ctx","؛ لأنَّه بمنزلة المشهورين في الرِّواية؛ لأنَّ الفقهاء ما كانوا يقبلون الحديث حتى يصحّ عندهم أنَّه يروي عن رسول الله ﷺ؛ لعلمهم بعدالة الرَّاوي وحُسن ضبطه، ولموافقته لما عندهم مما سمعوه من رسول الله ﷺ."]]},{"id":"u68a_4","kind":"def","label":"الثاني: مجهول · الفقرة ٤","segs":[["ctx","٢."],["matn","أن يسكت الفقهاء عن الطَّعن في روايته بعدما اشتهرت."]]},{"id":"u68a_5","kind":"def","label":"الثاني: مجهول · الفقرة ٥","segs":[["matn","وحكم خبره: وجوب العمل به مطلقاً"],["ctx","؛ لأنَّ السُّكوت بعد تحقق الحاجة لا يحل إلا على وجه الرِّضا بالمسموع، فكان سكوت الفقهاء عن الرَّدِّ دليل التَّقرير، بمنزلة ما لو قبلوه وردّوا عنه."]]},{"id":"u68a_6","kind":"def","label":"الثاني: مجهول · الفقرة ٦","segs":[["ctx","٣."],["matn","أن يختلف الفقهاء في الطَّعن في روايته."]]},{"id":"u68a_7","kind":"def","label":"الثاني: مجهول · الفقرة ٧","segs":[["matn","وحكم خبره: وجوب العمل به مطلقاً"],["ctx","؛ لأنَّه حين قَبله بعض الفقهاء المشهورين منهم، فكأنَّ الفقيه الذي قَبِلَ روى الحديث بنفسه، كما في حديث معقل بن سنان رضي الله عنه: «إنَّ رسول الله ﷺ قضى لبُروع بنت واشق الأشجعية بمهر مثلها حين مات عنها زوجها ولم يسمّ لها صداقاً»، فإنَّ ابن مسعود رضي الله عنه قَبِلَ روايته وسُرَّ به لما وافق قضاءه قضاء رسول الله ﷺ، وعليّ رضي الله عنه ردَّه، فقال: «ماذا نصنع بقول أعرابي بوال على عقبه، حسبها الميراث لا مهر لها»، فلما اختلفوا فيه في الصَّدر الأول أخذنا بروايته؛ لأنَّ الفقهاء من القرن الثَّاني: كعلقمة ومسروق والحسن ونافع بن جبير قَبلوا روايتَه فصار مُعَدَّلاً بقَبول الفقهاء روايته، فتبيَّن بهذا أنَّ رواية مثل هذا فيما يوافق القياس يكون مقبولاً ثم العمل يكون بالرِّواية."]]},{"id":"u68a_8","kind":"def","label":"الثاني: مجهول · الفقرة ٨","segs":[["ctx","٤."],["matn","أن يطعنوا في روايته من غير خلاف بين الفقهاء في ذلك."]]},{"id":"u68a_9","kind":"def","label":"الثاني: مجهول · الفقرة ٩","segs":[["matn","وحكم خبره: لا يجوز العمل بروايته"],["ctx","؛ لأنَّ الفقهاء كانوا لا يُتهمون برد الحديث الثَّابت عن رسول الله ﷺ، ولا بترك العمل به، وترجيح الرَّأي بخلافه عليه، فاتفاقهم على الرَّد دليلٌ على أنَّهم كذَّبوه في هذه الرِّواية، وعلموا أنَّ ذلك وهم منه، كما في حديث فاطمة بنت قيس رضي الله عنها، قالت: «إنَّ رسول الله ﷺ لم يجعل لها سكنى ولا نفقة، فَرَدَّ عمر رضي الله عنه: لا نترك كتاب الله وسنّة نبينا ﷺ لقول امرأة لا ندري لعلها حفظت أو نسيت، لها السُّكنى والنَّفقة، قال الله تعالى: ﴿لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖ﴾ [الطلاق:١])."]]},{"id":"u68a_10","kind":"def","label":"الثاني: مجهول · الفقرة ١٠","segs":[["ctx","٥."],["matn","أن لا تظهر روايته ولا الطَّعن فيها بين الفقهاء"],["ctx","، بأن لم يشتهر عندهم ولم يعارضوه بالرَّدّ."]]},{"id":"u68a_11","kind":"def","label":"الثاني: مجهول · الفقرة ١١","segs":[["matn","وحكم خبره: لا يجب العمل به"],["ctx","، ولكن يجوز العمل به إذا وافق القياس؛ لأنَّ من كان من الصَّدر الأول فالعدالة ثابتة له باعتبار الظَّاهر؛ لأنَّه في زمانٍ الغالب من أهله العدالة على ما قال ﷺ: «خير الناس قرني، ثم الذين يلونهم، ثم الذين يلونهم»، فباعتبار الظَّاهر يترجَّح جانب الصِّدق في خبره، وباعتبار أنَّه لم تشتهر روايته في السَّلف يتمكّن تهمة الوهم فيه، فيجوز العمل به إذا وافق القياس على وجه حُسن الظنّ به، ولكن لا يجب العمل به؛ لأنَّ الوجوب شرعاً لا يثبت بمثل هذا الطَّريق الضَّعيف."]]}],"sup":"المطلب الأول: الرُّواة الذين يكون خبرهم حجة"},{"id":"u69","title":"المطلب الثَّاني: شروط الرَّاوي","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u69_1","kind":"def","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ١","segs":[["ctx","١."],["matn","العقل"],["ctx","؛ والمعتبر هو عقل البالغ دون القاصر: كالصَّبيّ والمعتوه والمجنون؛ لأنَّ الشَّرع لما لم يجعلهم أهلاً في التَّصرُّف في أمور أنفسهم لنقصان عقلهم ففي أمر الدِّين أولى، وهذا إذا كان السَّماع والرِّواية قبل البلوغ، وأما إذا كان السَّماع قبل البلوغ والرِّواية بعد البلوغ يُقبل قول الصَّبيّ فيه؛ إذ لا خلل في تحمّله؛ لكونه مميزاً، ولا في روايته؛ لكونه عاقلاً."]]},{"id":"u69_2","kind":"def","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ٢","segs":[["ctx","٢."],["matn","الضَّبط"],["ctx","؛ لأنَّ قَبول الخبر باعتبار معنى الصِّدق فيه، ولا يتحقَّق ذلك إلا بحسن ضبط الرَّاوي من حين يسمع إلى حين يروي."]]},{"id":"u69_3","kind":"text","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ٣","segs":[["ctx","وحدُّ الضَّبط: هو سماع الكلام كما يحقّ سماعه من أوَّله إلى آخره بتمام الكلمات والهيئة التَّركيبة، ثم فهمه بمعناه الذي به لغوياً كان أو شرعياً، ثمّ حفظه ببذل المجهود له، ثمّ الثَّبات عليه بمحافظة حدوده بالعمل بموجبه ببدنه، ومراقبتُه بمذاكرته على إساءة الظنّ بنفسه بأن لا يعتمد على نفسِه بالقوَّة الحافظةِ بل يقول: إنّي إذا تركتُه نسيتُه، وهذا كلُّه إلى حين أدائه وتبليغه."]]},{"id":"u69_4","kind":"def","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ٤","segs":[["ctx","٣."],["matn","الإسلام"],["ctx","؛ لأنَّ الكلام في الأخبار التي يثبت بها أحكام الشَّرع، والكفّار يعادوننا في أصل الدِّين بغير حقّ على وجهٍ هو نهاية في العداوة، فيحملهم ذلك على السَّعي في هدم أركان الدِّين بإدخال ما ليس منه فيه، فلا تُقبل أخبارهم."]]},{"id":"u69_5","kind":"text","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ٥","segs":[["ctx","ويكون الإسلام بالتَّصديق والإقرار بالله تعالى كما هو واقعٌ بأسمائه وصفاته من العلم والقدرة وسائر صفات الكمال، وقَبول أحكامه وشرائعه، والشَّرط فيه البيان إجمالاً ـ كما ذكرنا ـ لا تفصيلاً للحرج؛ ولهذا الواجب أن يستوصف، فيقال: أهو كذا وكذا، فإذا قال: نعم يكمل إيمانه، وهذا المراد بقوله تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ٱلۡمُؤۡمِنَٰتُ مُهَٰجِرَٰتٖ فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِيمَٰنِهِنَّ﴾ [الممتحنة: ١٠]."]]},{"id":"u69_6","kind":"def","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ٦","segs":[["ctx","٤."],["matn","العدالة"],["ctx","؛ لأنَّ الكلام في خبر مَن هو غير معصوم عن الكذب، فلا تكون جهة الصِّدق متعيّناً في خبره لعينه، وإنَّما يترجَّح جانب الصِّدق بظهور عدالته: أي استقامته، وحدُّها هنا: رجحان جهة الدِّين والعقل على طريق الهوى والشَّهوة حتى إذا ارتكب كبيرةً أو أصرَّ على صغيرةٍ سقطت عدالته."]]},{"id":"u69_7","kind":"text","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ٧","segs":[["ctx","والتَّقييد بالإصرار على الصَّغيرة؛ لأنَّ التَّحرز عن جميع الصَّغائر متعذِّرٌ عادة، واشتراط التَّحرُّز عن جميعها سدٌّ لباب الرِّواية. والمجهول من القرونِ الثَّلاثةِ عدلٌ بتعديل صاحب الشَّرع إيّاه ما لم يتبيَّن منه ما يُزيل عدالته."]]},{"id":"u69_8","kind":"def","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ٨","segs":[["matn","تنبيه: في عدالة الصَّحابة رضي الله عنهم:"],["ctx","إنَّ الذي ذهب إليه جمهور أهل السُّنة، وأدرجه نُقَّاد أهل الحديث والمتكلِّمون وغيرهم في تصانيفهم، هو أنَّ الصَّحابةَ كلَّهم عدول، كبيرهم وصغيرهم، قبل زمان الفتن وبعدَه، سواء كان من الدَّاخلين في الفتن أو من غير الدَّاخلين؛ لدلالة الأدلة العقلية والنَّقلية عليه، وبتتبع سير الصَّحابة كلهم حتى من دخل منهم في الفتنة والمشاجرات، فوجدناهم يعتقدون الكذب على النَّبي ﷺ أشدّ الذُّنوب، ويحترزون عنه غاية الاحتراز، كما لا يخفى على أهل السِّير."]]},{"id":"u69_9","kind":"text","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ٩","segs":[["ctx","ومراد المُحَدِّثين من قولهم الصَّحابة رضي الله عنهم كلّهم عدول: هو التَّجنُّب عن تَعَمُّدِ الكذب في الرِّواية وانحراف فيها بارتكاب ما يوجب عدم قَبولها."]]},{"id":"u69_10","kind":"text","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ١٠","segs":[["ctx","قال الإبياريُّ: «وليس المراد بعدالتهم ثبوت العصمة لهم، واستحالة المعصية، وإنَّما المراد قَبول رواياتهم من غير تكلف بحث عن أسباب العدالة، وطلب التَّزكية، إلا من يثبت عليه ارتكاب قادح، ولم يثبت ذلك، والحمد لله»."]]},{"id":"u69_11","kind":"text","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ١١","segs":[["ctx","وقال الغزاليُّ: «والذي عليه سلف الأُمَّة وجماهير الخلف: أنَّ عدالتَهم معلومةٌ بتعديل الله تعالى إيّاهم وثنائه عليهم في كتابه، فهو معتقدنا فيهم، إلا أن يثبت بطريق قاطع ارتكاب واحد لفسق مع علمه به، وذلك ممَّا لا يثبت، فلا حاجة لهم إلى التَّعديل...»."]]},{"id":"u69_12","kind":"text","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ١٢","segs":[["ctx","وقال الخطيبُ البغدادي: «يجب النَّظر في أحوالهم سوى الصَّحابي الذي رفعه إلى رسول الله ﷺ؛ لأنَّ عدالة الصَّحابة رضي الله عنهم ثابتة معلومة بتعديل الله لهم، وإخباره عن طهارتهم، واختياره لهم في نص القرآن»."]]},{"id":"u69_13","kind":"text","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ١٣","segs":[["ctx","وقال ابنُ حجر العسقلاني: «اتفق أهل السُّنة على أنَّ الجميع عدول، ولم يخالف في ذلك إلا شذوذ من المبتدعة»."]]},{"id":"u69_14","kind":"text","label":"المطلب الثَّاني: شروط الرَّاوي · الفقرة ١٤","segs":[["ctx","وقال ابنُ أمير الحاج: «إنَّ ابن عبد البرِّ حكى إجماع أهل الحق من المسلمين ـ وهم أهل السُّنة والجماعة ـ على أنَّ الصَّحابة رضي الله عنهم كلهم عدول»."]]}],"sup":"المبحث الثَّاني رُواة الأحاديث"},{"id":"u70","title":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u70_1","kind":"def","label":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ · الفقرة ١","segs":[["matn","وهذا الانقطاع على صورتين: ظاهرة؛"],["ctx","بأن يفقد فيه أحد رجال الإسناد،"],["matn","وباطنة؛"],["ctx","بأن يلحق الحديث طعنٌ يورث الانقطاع،"],["matn","ونتكلَّم عنهما في مطلبين:"]]}]},{"id":"u71","title":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u71_1","kind":"text","label":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل · الفقرة ١","segs":[["ctx","فالكلام هنا عن المُرْسَل فحسب؛ لأنَّ سائر أنواع الانقطاع الظَّاهرة من مُعضل ومُنقطع تُسَمَّى عند الفقهاء والأصوليين مرسلاً، قال النَّووي: «اتفق علماء الطَّوائف على أنَّ قول التَّابعي: قال رسول الله ﷺ كذا، أو فعله، يُسَمَّى مرسلاً، فإن انقطع قبل الصَّحابي واحد أو أكثر، قال الحاكم وغيره من المُحَدِّثين: لا يُسَمَّى مُرسلاً، بل يختص المرسل بالتَّابعي عن النَّبي ﷺ، فإن سقط قبله فهو منقطع، وإن كان أكثر فمعضل ومنقطع، والمشهور في الفقه والأصول أنَّ الكلَّ مرسلٌ، وبه قطع الخطيب، وهذا اختلاف في الاصطلاح والعبارة»."]]},{"id":"u71_2","kind":"def","label":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل · الفقرة ٢","segs":[["matn","والمُرْسَل لغةً: من الإرسال، وهو الإطلاق"],["ctx","، يُقال: أرسل البعير: أطلق، وأرسلتُ الكلام إرسالاً، أطلقته من غير تقييد، وسمَّى به من الأخبار ما انعدم فيه التَّقييد بذكر الواسطة بين الرَّاوي وبين من روى عنه، فحديث مرسل لم يتصل إسناده بصاحبه."]]},{"id":"u71_3","kind":"def","label":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل · الفقرة ٣","segs":[["matn","واصطلاحاً: عند الفقهاء والأصوليين"],["ctx","، له تعاريف متقاربة في الدَّلالة على المراد منها:"],["matn","قول الإمام الثِّقة: قال ﷺ مع حذف من السَّند،"],["matn","أو ترك الواسطة بين الرَّاوي والمروي عنه."]]},{"id":"u71_4","kind":"text","label":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل · الفقرة ٤","segs":[["ctx","وبهذا يظهر الفرق في إطلاقِ مصطلحِ المُرْسَلِ بين الفقهاءِ والمُحَدِّثين، بأنَّ الفقهاءَ يقصدون به كلَّ حديثٍ رُفِع إلى النَّبيِّ ﷺ لم يذكر سنده، والمُحَدِّثين يَخُصُّونه بعدم ذكر الصَّحابي الرَّاوي للحديث من قبل التَّابعي فقط، وعلى هذا فهو على أقسام عند الفقهاء، وهي:"]]},{"id":"u71_5","kind":"def","label":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل · الفقرة ٥","segs":[["ctx","١."],["matn","مُرْسَل الصَّحابي رضي الله عنه"],["ctx","، وهو مقبول بالإجماع."]]},{"id":"u71_6","kind":"def","label":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل · الفقرة ٦","segs":[["ctx","٢."],["matn","مُرْسَل من القرن الثَّاني والثَّالث"],["ctx","، فإنَّه مقبولٌ عند الفقهاء؛ لثبوت عدالتهم بشهادة النَّبي ﷺ، وخالف الشَّافعيُّ رضي الله عنه فلم يَقبل إلا بمؤيد: كأن يُسنده غيره، أو أن يرسله آخر وعلم أنَّ شيوخهما مختلفة، وأن يعضده قول صحابيّ، وأن يعضدَه قول أكثر أهل العلم، أو يعلم من حاله أنَّه لا يُرْسِلُ إلا بروايتِهِ عن عدل، قال أبو بكر الرَّازيّ: «مذهب أصحابنا: أنَّ مراسيلَ الصَّحابة والتَّابعين مقبولةٌ، وكذلك عندي قَبوله في أَتباع التَّابعين بعد أن يُعرف بإرسال الحديث عن العدول الثِّقات»."]]},{"id":"u71_7","kind":"def","label":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل · الفقرة ٧","segs":[["ctx","٣."],["matn","مُرْسَلُ غيرُ القرون الثَّلاثة الأولى"],["ctx","، فهو مقبولٌ عند الكرخيّ، فإنَّه لا يُفَرِّق بين مراسيلِ أهل الأعصار، ويقول: من تُقبل روايته مسنداً تُقبل روايته مرسلاً، وقال عيسى بن أبان: لا تُقبل؛ لتغير الزَّمان بالفسق وفشو الكذب بشهادة النَّبي ﷺ، وقيل: الصَّحيحُ أنَّ مُرْسَلَ مَن كان من القرون الثَّلاثة حجةٌ ما لم يعرف منه الرِّواية عَمَّن ليس بعدلٍ ثقة، ومُرْسَلُ مَن كان بعدهم لا يكون حجّةً إلا إذا اشتُهر بأنَّه لا يَرْوِي عَمَّن هو عدلٌ ثقة."]]},{"id":"u71_8","kind":"text","label":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل · الفقرة ٨","segs":[["ctx","قال أبو بكر الرَّازي: «أمّا مراسيلُ مَن كان في القرن الرَّابع من الأُمَّة: فإني كنت أَرى بعض شيوخنا يقول: إنَّ مراسيلهم غير مقبولة... ولم أر أبا الحسن الكرخي يُفَرِّق بين المراسيل من سائر أهل الأعصار، وأما عيسى بن أبان فإنَّه قال: مَن أرسل من أهل زماننا حديثاً عن النَّبي ﷺ فإن كان من أئمة الدِّين، وقد نقله عن أهل العلم، فإنَّ مُرْسَله مقبول، كما يقبل مُسنده، ومَن حمل عنه النَّاس الحديث المسند ولم يحملوا عنه المُرْسَل، فإنَّ مرسله عندنا موقوف»."]]},{"id":"u71_9","kind":"def","label":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل · الفقرة ٩","segs":[["ctx","٤."],["matn","مرسلٌ أُرسل من وجهٍ، وأُسند من وجهٍ"],["ctx","، فهو مقبولٌ عند الأكثر؛ إذ لا شبهة في قَبوله عند مَن يَقْبَلُ المُرْسَل."]]}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u71a","title":"وحجّة قَبول المُرْسَل","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u71a_1","kind":"def","label":"وحجّة قَبول المُرْسَل · الفقرة ١","segs":[["matn","وحجّة قَبول المُرْسَل:"],["ctx","أ."],["matn","النَّص"],["ctx","؛ وهو عموم قوله تعالى: ﴿فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ﴾ [التوبة: ١٢٢]، وقوله تعالى: ﴿إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ﴾ [الحجرات: ٦]، فإذا أَخبر من لا يكون فاسقاً وجب القَبول؛ لما سبق أنَّ خبر الواحد العدل مقبول، والمُرْسِل ليس بفاسق، فخبره مقبول."]]},{"id":"u71a_2","kind":"def","label":"وحجّة قَبول المُرْسَل · الفقرة ٢","segs":[["ctx","ب."],["matn","الإجماع"],["ctx","؛ فإنَّ الصَّحابة والتَّابعين أجمعوا على قَبول المراسيل من العدل، أما الصَّحابة فإنَّهم قَبلوا أخبار ابن عباس رضي الله عنه مع كثرة روايته مع أنَّه قيل: إنَّه لم يسمع من النَّبي ﷺ إلا تسعة أو عشرة أو أربعين حديثاً، وكذلك عن أبي هريرة رضي الله عنه، فعن البراء رضي الله عنه قال: «ما كلّ ما نحدثكموه سمعناه من رسول الله ﷺ، ولكن حَدَّثنا أَصحابنا، وكانت تشغلنا رعية الإبل»."]]},{"id":"u71a_3","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ٣","segs":[["ctx","وأَمَّا التَّابعون فقد كان من عادتهم إرسال الأخبار، ويدلُّ على ذلك ما رُوي عن الأعمش أنَّه قال: «قلت لإبراهيم النَّخعي: إذا حدثتني فأسند، فقال: إذا قلت لك: حدثني فلان عن عبد الله ـ أي ابن مسعود رضي الله عنه ـ، فهو الذي حدثني، وإذا قلت لك: حدثني عبد الله فقد حدثني جماعة عنه»، ويدلُّ على ذلك ما اشتُهر من إرسال ابن المُسَيَّب والشَّعبي وغيرهما، ولم يزل ذلك مشهوراً فيما بين الصَّحابة والتَّابعين رضي الله عنهم من غير نكير، فكان إجماعاً."]]},{"id":"u71a_4","kind":"def","label":"وحجّة قَبول المُرْسَل · الفقرة ٤","segs":[["ctx","ج."],["matn","المعقول"],["ctx","؛ فهو أنَّ العدلَ الثِّقة إذا قال: قال رسول الله ﷺ كذا، مُظهراً للجزم بذلك، فالظَّاهر من حاله أنَّه لا يستجيز ذلك إلا وهو عالم أو ظانّ أنَّ النَّبي ﷺ قال ذلك، فإنَّه لو كان ظانّاً أنَّ النَّبي ﷺ لم يقله، أو كان شاكّاً فيه، لما استجاز في دِينه النَّقل الجازم عنه؛ لما فيه من الكذب والتَّدليس على المستمعين، وذلك يستلزم تعديل مَن رَوَى عنه، وإلا لما كان عالماً أو ظانّاً بصدقِهِ في خبرِه."]]},{"id":"u71a_5","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ٥","segs":[["ctx","ونخلص ممَّا سَبَقَ: إلى قَبولِ السَّادة الحنفيّة للمُرْسَل، وعدم التَّفريق بينه وبين المُسْنَد إذا كان مرسلُه ثقةٌ ولا يروي إلا عن ثقةٍ، لاسيما في القرونِ الثَّلاثةِ الأُولى، وأمّا بعدها فالمشهور عدم قَبوله، والقَبول مجرد قول عندهم، والله أعلم، قال الجصَّاص: «والصَّحيح عندي، وما يدل عليه مذهب أصحابنا: أنَّ مرسل التَّابعين وأتباعهم مقبول ما لم يكن الرَّاوي ممن يُرسل الحديث عن غير الثِّقات، فإنَّ من استجاز ذلك لم تُقبل روايته، لا لِمسند ولا لمرسل...»."]]},{"id":"u71a_6","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ٦","segs":[["ctx","وقال ابن عبد البرِّ: «كل مَن عُرف أنَّه لا يأخذ إلا عن ثقة فتدليسُه ومرسلُه مقبولٌ، فمراسيلُ سعيد ابن المُسَيَّب ومحمد بن سيرين وإبراهيم النَّخعي عندهم صحاح، وقال العجلي: مرسلُ الشَّعبي صحيح لا يكاد يرسل إلا صحيحاً»."]]},{"id":"u71a_7","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ٧","segs":[["ctx","بل جعلوا المُرْسَل في درجة أعلى من المُسْنَد على حسب حال راويه وثقته ومكانته ودرجته العلمية، قال عيسى بن أبان: «المُرْسَل أقوى عندي من المُسْنَد»، ومردُّ ذلك للثِّقة بالمُرسِل وتَكَفُّلُه بصحَّة نسبته للنَّبي ﷺ."]]},{"id":"u71a_8","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ٨","segs":[["ctx","قال السَّرَخسيُّ: «الحديث مرسل بالطَّريق الذي رواه، ولكنَّ المراسيل حجة عندنا كالمسانيد أو أقوى من المسانيد؛ لأنَّ الرَّاوي إذا سمع الحديث من واحد لا يشق عليه حفظ اسمه فيرويه مسنداً، وإذا سمعه من جماعة يشق عليه حفظ الرِّواية، فَيُرسل الحديث، فكان الإرسال من الرَّاوي المعروف دليل شهرة الحديث»."]]},{"id":"u71a_9","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ٩","segs":[["ctx","وهذا القَبول للمُرْسَل ليس خاصّاً بالحنفية، بل عليه جمهور الفقهاء."]]},{"id":"u71a_10","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١٠","segs":[["ctx","قال الكوثري: «يرى الحنفية قَبولَ الخبرِ المُرْسَلِ إذا كان مُرْسِلُه ثقةً كالخبرِ المُسْنَد، وعليه جرت جمهرة فقهاء الأُمَّة من الصَّحابة والتَّابعين وتابعيهم إلى رأس المئتين؛ ولا شكَّ أنَّ إغفال الأخذ بالمُرْسَل ـ ولاسيما مرسل كبار التَّابعين ـ تَرْكٌ لشطر السُّنَّة."]]},{"id":"u71a_11","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١١","segs":[["ctx","قال الطَّبريُّ: «لم يزل النَّاس على العمل بالمُرْسَل وقَبوله، حتى حدث بعد المئتين القول بردّه»."]]},{"id":"u71a_12","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١٢","segs":[["ctx","وقال أبو داود: «وأما المراسيل، فقد كان يحتج بها العلماء فيما مضى، مثل سفيان الثَّوري ومالك بن أنس والأوزاعي حتى جاء الشَّافعي، فتكلَّم فيه»."]]},{"id":"u71a_13","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١٣","segs":[["ctx","والإمام الشَّافعيُّ الذي اشتهر عنه ردّ المُرْسَل طريقه في التعامل معه لا يبعد عن غيره في قَبوله، وإنَّما مدارُ الأمر على التَّوثق في النَّقل، فهو بحثٌ عن مؤكداتٍ أُخر لذلك ـ كما سَبَق ـ، وهذا ما صَرَّحَ به إمام الحرمين، فقال: «والذي لاح لي أنَّ الشَّافعيّ ليس يرد المراسيل، ولكن يبغي فيها مزيد تأكيد بما يغلب على الظَّنِّ من جهة الإرسال على حال يجرّ ضرباً من الجهالة في المسكوت عنه، فرأي الشَّافعيّ أن يؤكد الثِّقة، فليثق النَّاظر بهذا المسلك الذي ذكرته، فعلى الخبير سقط، وقد عثرت من كلام الشَّافعي على أنَّه إن لم يجد إلا المُرْسَل، مع الاقتران بالتَّعديل على الإجمال، فإنَّه يَعْمَلُ به»."]]},{"id":"u71a_14","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١٤","segs":[["ctx","وطالما أنَّ كلامنا عن الفقهاء، فيكون المقصود بهم أئمة المذاهب، وهم من أهل القرن الثَّاني لاسيما أبو حنيفة ومالك، وقد كان الإرسال طريق الرِّواية ـ بالدَّرجة الأولى ـ عن النَّبي ﷺ في تلك الحقبة."]]},{"id":"u71a_15","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١٥","segs":[["ctx","قال الدَّارقطني: «ومن عادة مالك إرسال الأحاديث وإسقاط رجل»."]]},{"id":"u71a_16","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١٦","segs":[["ctx","وقال الحافظ محمد بن عبد الواحد: «وقد رأيتُ ابن المبارك يروي كثيراً من حديث صحيح فيوقفه»."]]},{"id":"u71a_17","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١٧","segs":[["ctx","وقال أحمد الغماري: «إنَّ هؤلاء ـ الحُفّاظ ـ قد عُلِمَ من صنيعهم في مؤلفاتهم هم وسائر الأقدمين من طبقتهم: كمالك وابن أبي شيبة وعبد الرَّزاق وابن المبارك أنَّهم يؤثرون الموقوفات والمقاطيع والمراسيل على المرفوعات والموصولات، فكم من حديث موصول مرفوع في الصَّحيحين والسُّنن تجده في هذه الكتب موقوفاً ومرسلاً من نفس الطَّريق التي هو منها موصول ومرفوع في الصَّحيحين، وجلّ المقاطيع والمراسيل والموقوفات في موطأ مالك موصولة مرفوعة في الصَّحيحين، وربما من طريق مالك نفسه، فلا يدل ذلك على ضعف ما في الصَّحيحين والسُّنن، فكذا هنا»."]]},{"id":"u71a_18","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١٨","segs":[["ctx","وبهذا يُعلم أنَّ هذا طريق الأُمَّة في الرِّواية في تلك الأزمنة، فلا ينكر البتة، كما لا ينكر عدم تدوين السُّنة في عصر النَّبي ﷺ والصَّحابة رضي الله عنهم، ولا يُتهمون بالتَّقصير في ذلك لعدم وجود حاجة إليه، وإن وجدت الحاجة عند مَن بعدهم، ويدلُّ عليه قول عروة بن الزُّبير: «إنَّ عمر بن الخطاب رضي الله عنه أراد أن يكتب السُّنن، واستشار فيها أصحاب رسول الله ﷺ، فأشار إليه عامتهم بذلك، فلبث عمر رضي الله عنه شهراً يستخير الله في ذلك شاكاً فيه، ثم أصبح يوماً وقد عزم الله له، فقال: إني كنت ذكرت لكم من كتاب السُّنن ما قد علمتم، ثم تذكرت، فإذا أُناس من أهل الكتاب من قبلكم قد كتبوا مع كتاب الله كُتباً، فأكبوا عليها، وتركوا كتاب الله، وإنّي والله لا أَلبس بكتاب الله بشيء، فترك كتابة السُّنن»."]]},{"id":"u71a_19","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ١٩","segs":[["ctx","فكل عصر له طريقه في حفظ الدِّين ونقل العلم، فلا يقاس على غيره من العصور، وكل أهل علم وفن لهم أصولهم وضوابطهم في نقله وتحريره، فلا يُحاكمون بأهل علم آخر، وهذه النُّكتة اللطيفة غفل عنه كثيرون، فظنُّوا الظُّنون بأئمة الدِّين وبعلوم الإسلام، وقد أوضح ذلك الحافظ ابن رجب، فقال: «واعلم أنَّه لا تنافي بين كلام الحُفَّاظ وكلام الفقهاء في هذا الباب، فإنَّ الحُفَّاظ إنَّما يريدون الحديث المعين إذا كان مرسلاً، وهو ليس بصحيح على طريقتهم؛ لانقطاعه وعدم اتصال إسناده إلى النَّبي ﷺ."]]},{"id":"u71a_20","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ٢٠","segs":[["ctx","وأما الفقهاء، فمرادهم صحة ذلك المعنى الذي دَلَّ عليه الحديث، فإذا عضد ذلك المُرْسَل قرائن تدل على أنَّ له أصلاً قوي الظَّنّ بصحّة ما دَلَّ عليه، فاحتج به مع ما احتفّ به من القرائن."]]},{"id":"u71a_21","kind":"text","label":"وحجّة قَبول المُرْسَل · الفقرة ٢١","segs":[["ctx","وهذا هو التَّحقيقُ في الاحتجاج بالمُرْسَل عند الأئمة: كالشَّافعي وأحمد وغيرهما، مع أنَّ في كلام الشَّافعيّ ما يقتضي صحّة المُرْسَل حينئذٍ»."]]}],"sup":"المطلب الأوَّل: الظَّاهر: وهو المُرْسَل"},{"id":"u72","title":"المطلب الثَّاني: الباطن","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u72_1","kind":"text","label":"المطلب الثَّاني: الباطن · الفقرة ١","segs":[["ctx","والمقصود بالباطن ما حصل فيه انقطاع خفي في الحديث، بحيث يكون في اتصال الحديث بالنَّبي ﷺ نظرٌ من جهةِ مشكلةٍ في الرَّاوي، أو معارضةِ الحديث لما هو أقوى منه، أو مخالفةِ الحديث للعمل، وهذا ما نبحثه في النِّقاط الآتية:"]]},{"id":"u72_2","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ٢","segs":[["matn","أولاً: نقصان في النَّاقل:"],["ctx","وهو أن يكون الاتصال فيه ظاهراً، ولكن وقع الخلل بوجه آخر، وهو فقد شرائط الرَّاوي ـ كما سبق تفصيلها ـ، وحكمه: أن لا يُقبل خبر الكافر والفاسق والصَّبي والمعتوه الذي اشتدت غفلته ـ كما سبق ـ."]]},{"id":"u72_3","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ٣","segs":[["matn","ولا يُعتبر الطَّعن في الرَّاوي إن لم يكن مُفَسَّراً من أئمة الحديث بما هو جرح متفق عليه"],["ctx","، بخلاف الطَّعن المبهم، فإنَّه لا يجرح الرَّاوي؛ لاحتمال ما ليس بجرح جرحاً، ولا بدَّ أن يكون الجرح المفسَّرُ المعتبرُ صادراً من طاعن مشتهر بالنَّصيحة دون التَّعصب والعداوة، فلا يُقبل الطَّعن فيما يلي مثلاً:"]]},{"id":"u72_4","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ٤","segs":[["ctx","أ."],["matn","التَّلبيس"],["ctx",": وهو أن يذكر الرَّاوي شيخه بالكنية لا بالاسم، أو يذكره بصفة غير مشهورة حتى لا يُعرف فيما بين النَّاس ولا يطعنوا عليه."]]},{"id":"u72_5","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ٥","segs":[["ctx","ب."],["matn","الإرسال"],["ctx",": وهو ليس بطعن ـ كما سبق ـ."]]},{"id":"u72_6","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ٦","segs":[["ctx","ج."],["matn","ركض الدَّابة"],["ctx",": ليس بطعن أيضاً؛ لأنَّه أمر مشروع من أصحاب الجهاد، فلا يصلح جرحاً."]]},{"id":"u72_7","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ٧","segs":[["ctx","د."],["matn","المزاح"],["ctx",": وهو لا يصلح جرحاً؛ لأنَّ النَّبي ﷺ كان يُمازح كثيراً، ولكن لا يقول إلا حقاً؛ فعن أبي هريرة رضي الله عنه، قال ﷺ: «إني لا أقول إلا حقاً، قال بعض أصحابه: فإنَّك تُداعبنا يا رسول الله، فقال: إني لا أقول إلا حقاً»."]]},{"id":"u72_8","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ٨","segs":[["ctx","هـ."],["matn","حداثة السِّنّ"],["ctx","؛ لأنَّ كثيراً من الصَّحابة رضي الله عنهم كانوا يروون في حداثة سِنهم، بشرط الإتقان عند التَّحمل، والعدالة عند الأداء."]]},{"id":"u72_9","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ٩","segs":[["ctx","و."],["matn","عدم الاعتبار بالرِّواية"],["ctx",": فإنَّ أبا بكر رضي الله عنه لم يكن معتاداً بالرِّواية مع أنَّ أحداً لم يعادله في الضَّبط والإتقان."]]},{"id":"u72_10","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ١٠","segs":[["ctx","ز."],["matn","استكثار مسائل الفقه"],["ctx",": كما يَطعن كثير من الرُّواة على المشتغلين بالفقه."]]},{"id":"u72_11","kind":"def","label":"المطلب الثَّاني: الباطن · الفقرة ١١","segs":[["matn","ثانياً: معارضة الأقوى:"],["ctx","وهو ما وقع فيه الخلل لمعارضته لدليل فوقه بالعَرْض عليه؛ لأنَّ معارضة الآحاد لما هو أَقوى من حيث قوَّة النَّقل يندرج تحتها معارضته للقرآن والحديث المتواتر والحديث المشهور، ولا ريب أنَّها مقدَّمةٌ عليه؛ لقوتها وترجحها عليه، وهذا ما نبيِّنه في النِّقاط الآتية:"]]}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u73","title":"الأَوَّل: مخالفةُ الآحاد للقرآن","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u73_1","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ١","segs":[["ctx","دلَّ القرآن على تقديمه على غيره عند تعارضه في قوله تعالى: ﴿ٱتَّبِعُواْ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡ﴾ [الأعراف: ٣]، قال الجصَّاص: «دليلٌ على وجوب اتباع القرآن في كلِّ حال، وأنَّه غيرُ جائز الاعتراض على حكمِه بأخبار الآحاد؛ لأنَّ الأمرَ باتباعه قد ثبت بنصِّ التَّنزيل، وقَبول خبر الواحد غير ثابت بنصِّ التَّنزيل، فغير جائز تركه؛ لأنَّ لزوم اتباع القرآن قد ثبت من طريق يوجب العلم، وخبر الواحد يوجب العمل، فلا يجوز تركه ولا الاعتراض به عليه»."]]},{"id":"u73_2","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ٢","segs":[["ctx","وأشارت عدَّة أحاديث لهذا التَّقديم، فعن أبي جعفرَ رضي الله عنه، قال ﷺ: «إنَّ الحديث سيفشو عنّي، فما أتاكم عنّي يوافقُ القرآن فهو عنّي، وما أتاكم عنّي يخالف القرآن فليس عنّي»، وعن عليّ رضي الله عنه، قال ﷺ: «إنَّها تكون بعدي رواة يرون عنّي الحديث، فاعرضوا حديثهم على القرآن، فما وافقَ القرآن فحدِّثوا به، وما لم يوافق القرآن فلا تأخذوا به»."]]},{"id":"u73_3","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ٣","segs":[["ctx","وعن أبي هريرةَ رضي الله عنه، قال ﷺ: «سيأتيكم عنّي أحاديثُ مختلفة، فما أتاكم موافقاً لكتابِ الله وسنّتي فهو منّي، وما أتاكم مخالفاً لكتاب الله وسنّتي فليس منّي»."]]},{"id":"u73_4","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ٤","segs":[["ctx","قال أبو سعيد الخادمي: «إنَّ مثلَها محمولٌ على حديث لم يكن ثابتاً بطريق صحيح، قال القاري: من الأمور الكلية التي نعرف بها كون الحديث موضوعاً: مخالفتُه لصريح القرآن؛ ولهذا كان في مذهب أبي حنيفة رضي الله عنه أنَّ المُتشابه لا يثبت بخبر الواحد»."]]},{"id":"u73_5","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ٥","segs":[["ctx","ومعارضة ظاهر القرآن أو عمومه؛ بأن يكون خبرُ الواحد معارضاً لعموم الكتاب أو ظاهره سبب للاعتذار عن العمل به؛ لأنَّ الحنفية لا يرون تخصيص عموم القرآن أو نسخه بالآحاد؛ لأنَّ عمومات الكتاب وظواهرها لمّا أفادت اليقين، قُدِّمت على الظَّني المستفاد من الآحاد، فصارت كالنُّصوص الخاصَّة، والخصوصات لا يجوز تخصيصها ومعارضتها بغيرها؛ لأنَّ فيه ترك العمل بالأقوى من الدَّليل بما هو أضعفُ منه، وذلك لا يجوز، ومن أمثلته:"]]},{"id":"u73_6","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ٦","segs":[["ctx","أ. حديث الآحاد في عدمِ صحّةِ الصَّلاةِ لَمن لم يقرأ الفاتحة، فقال ﷺ: «لا صلاة لَمن لم يقرأ بفاتحة الكتاب»، وهو مخالفٌ لعمومَ قوله جل جلاله: ﴿فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِ﴾ [المزمل: ٢٠]، فقُدِّمَ القرآن، وكان حكم الفاتحة الوجوب لا الفرضية، وإنَّما فَرْضُ القراءة قراءة آية من القرآن، قال الجصَّاص: «وذلك نسخ، وغيرُ جائز نسخ القرآن بأَخبار الآحاد»، ويُستدلُّ لهم أيضاً بعدم اعتبار الفاتحة رُكناً بحديث: «مَن صَلَّى صلاةً لم يقرأ فيها بفاتحة الكتاب، فهي خداجٌ، يقولها ثلاثاً): أي ناقصة، فالحديث يدل على نقصان الصَّلاة بدون قراءة الفاتحة لا على بطلانها من أصلها، فهو نصّ على نفي الكمال، فلا دلالة فيه على عدم الجواز بدون الفاتحة، بل على النَّقص، وهو ما يقول به الحنفية."]]},{"id":"u73_7","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ٧","segs":[["ctx","ب. حديث فاطمة بنت قيس رضي الله عنها، قالت: «إنَّ رسول الله ﷺ لم يجعل لها سكنى ولا نفقة، فردَّ عمر رضي الله عنه: لا نترك كتاب الله وسنّة نبينا ﷺ لقول امرأة لا ندري لعلها حفظت أو نسيت، لها السُّكنى والنَّفقة، قال الله تعالى: ﴿لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖ﴾ [الطلاق: ١])، فلَمّا خالف قول فاطمة رضي الله عنها القرآن تركه عمر رضي الله عنه، ومن ثَمّ لم يعمل به السَّادةُ الحنفيةُ فأوجبوا النَّفقة والسُّكنى للمرأة في عدّتها، ولم يجوزوا الخروج لها إلا لحاجة؛ عملاً بعموم القرآن."]]},{"id":"u73_8","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ٨","segs":[["ctx","ج. حديث الآحاد في سقوط ذكاة الجنين عند تذكية أُمّه: «ذكاةُ الجنين ذكاةُ أمّه» خالف قوله تعالى: ﴿إِلَّا مَا ذَكَّيۡتُمۡ﴾ [المائدة: ٣]، فلم يحل عند أبي حنيفة: الجنين إلا إذا ذُكّي الذَّكاةَ الشَّرعية المعروفة، ويؤيده: ذكاة الجنين في الحديث مبتدأ وذكاة أمه خبره، لكن فيه حذف مضاف، وهو مثل كأنَّه قال: ذكاة الجنين مثل ذكاة أمه."]]},{"id":"u73_9","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ٩","segs":[["ctx","د. حديث الآحاد في سنية الأضحية: «ثلاث هُنَّ عليَّ فرائض وهُنَّ لكم تطوُّع: الوتر، والنَّحر، وصلاة الضُّحى»، خالف قوله تعالى: ﴿فَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ﴾ [الكوثر: ٢]: أي صل صلاة العيد وانحر البدن بعدها، ومطلق الأمر للوجوب في حَقّ العمل، ومتى وَجَبَ على النَّبيّ ﷺ يجب على الأُمَّة؛ لأنَّه قدوةٌ للأُمَّة، فكانت مفيدة للوجوب."]]},{"id":"u73_10","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ١٠","segs":[["ctx","ويؤيده عن زيدِ بن أرقم رضي الله عنه، قال: «قلنا: يا رسول الله، ما هذه الأضاحي؟ قال: سنةُ أَبيكم إبراهيم عليه السلام، قال: قلنا: فما لنا منها؟ قال: بكلِّ شعرةٍ حسنة...»، وعن أَنس رضي الله عنه: «إنَّ رسولَ الله ﷺ خطب فأَمَرَ مَن كان ذبح قبل الصَّلاة أن يعيدَ ذبحَه»، وأمره ﷺ بذبح الأضحية وإعادتها إذا ذبحت قبل الصَّلاة دليلُ الوجوب؛ ولأنَّ إراقةَ الدَّم قربةٌ، والوجوب هو القربة في القربات، وعن أبي هريرة رضي الله عنه، قال ﷺ: «مَن كان له مال فلم يُضَحِّ فلا يقربن مصلانا، وقال مَرَّةً: مَن وَجَدَ سعةً فلم يذبح فلا يَقْرَبَنَّ مُصلاّنا»."]]},{"id":"u73_11","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ١١","segs":[["ctx","وهذا خَرَجَ مخرجَ الوعيد على تركِ الأضحية، ولا وعيد إلا بتركِ الواجب."]]},{"id":"u73_12","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ١٢","segs":[["ctx","هـ. حديث الآحاد: «الحرم لا يعيذ عاصياً ولا فاراً بدم» يُخالف عموم قوله تعالى: ﴿وَمَن دَخَلَهُۥ كَانَ ءَامِنٗا﴾ [آل عمران: ٩٧]: أي إنَّ مباح الدَّم بِرِدَّة أو زنا أو قطع طريق أو قصاص إذا التجأ إلى الحرم لا يقتل فيه ولا يؤذى ليخرج، ولكن لا يُطعم ولا يُسقى ولا يُجالس ولا يبايع حتى يضطر إلى الخروج، فيقتل خارج الحرم؛ لعموم القرآن."]]},{"id":"u73_13","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ١٣","segs":[["ctx","و. حديث الآحاد في التَّسمية في الوضوء: «لا وضوء لمن لم يذكر اسم الله تعالى عليه» يخالف ظاهر قوله تعالى: ﴿فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ﴾ [المائدة: ٦] فلا يترك العمل بالكتاب بهذا، قال الجصَّاص: «إنَّ أخبار الآحاد غير مقبولة فيما عمَّت البلوى به، وإن صحَّ احتمل أنَّه يريد به نفي الكمال لا نفي الأصل...»."]]},{"id":"u73_14","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ١٤","segs":[["ctx","س. حديث الآحاد في خمس رضعات عن عائشة رضي الله عنها: «كان فيما أُنزلَ من القرآن عشر رضعات معلومات يُحَرِّمن، ثُمَّ نسخن بخمس رضعاتٍ معلومات يُحَرِّمن، فتوفي النَّبيّ ﷺ وهنَّ فيما يقرأ في القرآن» خالف عموم قوله تعالى: ﴿وَأُمَّهَٰتُكُمُ ٱلَّٰتِيٓ أَرۡضَعۡنَكُمۡ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ﴾ [النساء: ٢٣]؛ لأنَّه مهما قلَّ فقد نشأ منه جزءٌ مناسبٌ، ولكن لَمّا كان النُّمو بالرَّضاع أَمراً غيرَ ظاهر أُسند الحكم بالتَّحريم إلى سببه، وهو الرَّضاع."]]},{"id":"u73_15","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ١٥","segs":[["ctx","ويشهد له ظاهر حديث: «يحرمُ من الرضاع ما يحرمُ من النَّسب»، قال الجصَّاص: «ولا يجوز قَبول أخبار الآحاد عندنا في تخصيص حكم الآية الموجبة للتَّحريم بقليل الرَّضاع؛ لأنَّها آية محكمةٌ ظاهرةُ المعنى بيّنةُ المراد لم يثبت خصوصها بالاتفاق، وما كان هذا وصفه فغيرُ جائز تخصيصُه بخبر الواحد ولا بالقياس»."]]},{"id":"u73_16","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ١٦","segs":[["ctx","ح. حديث حذيفة رضي الله عنه قال: «تسحرنا مع رسول الله ﷺ وكان نهاراً، إلا أنَّ الشَّمس لم تطلع»، فإنَّه لا يثبت ذلك عن حذيفة رضي الله عنه، وهو مع ذلك من أخبار الآحاد، فلا يجوز الاعتراض به على القرآن، قال تعالى: ﴿حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِ﴾ [البقرة: ١٨٧]، فأوجب الصَّوم والإمساك عن الأكل والشُّرب بظهور الخيط الذي هو بياض الفجر."]]},{"id":"u73_17","kind":"text","label":"الأَوَّل: مخالفةُ الآحاد للقرآن · الفقرة ١٧","segs":[["ctx","ك. حديث الآحاد يما يتعلّق بالسُّجود: «أُمرت أن أسجد على سبعةِ أعظم: على الجبهة، وأشار بيده على أنفه، واليدين، والرُّكبتين، وأطراف القدمين» مخالف لقوله تعالى: ﴿ٱرۡكَعُواْ وَٱسۡجُدُواْ﴾ [الحج: ٧٧]، فالآيةُ مقتصرة على ما يتمّ به السُّجود وهو الجبهة، وبها يتحقق السُّجود، والزِّيادة عليها بحديث آحاد لا يجوز."]]}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u74","title":"الثَّاني: معارضة الآحاد للحديث المتواتر","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u74_1","kind":"text","label":"الثَّاني: معارضة الآحاد للحديث المتواتر · الفقرة ١","segs":[["ctx","سبق التَّكلُّم في الحديث المتواتر، ونذكر هاهنا أمثلة في تقديمه على الآحاد:"]]},{"id":"u74_2","kind":"text","label":"الثَّاني: معارضة الآحاد للحديث المتواتر · الفقرة ٢","segs":[["ctx","أ. الأحاديث المتواترة في تَشَهُّد ابن مسعود: «التَّحيات لله الصَّلوات الطَّيبات، السَّلام عليك أيها النَّبي ورحمة الله، السَّلام علينا وعلى عباد الله الصَّالحين، أشهد أنَّ لا إله إلا الله، وأشهد أنَّ محمداً عبده ورسوله»، مُقَدَّمةٌ على حديث ابن عباس رضي الله عنهم: «التَّحيات المباركات، الصَّلوات الطَّيبات لله...»، قال الطَّحاويُّ: «قد تواترت بذلك عن النَّبيّ ﷺ الرِّوايات، فلم يُخالفها شيءٌ، فلا ينبغي خلافها، ولا الأخذ بغيرها، ولا الزِّيادة على شيء ممّا فيها، إلا أنَّ في حديث ابن عباس رضي الله عنهم حرفاً يزيد على غيره، وهو المباركات»."]]},{"id":"u74_3","kind":"text","label":"الثَّاني: معارضة الآحاد للحديث المتواتر · الفقرة ٣","segs":[["ctx","ب. الأحاديث المتواترة في (غسل الرِّجلين) رواه أربعة وثلاثون صحابياً، وصرح بتواترها ابن الهمام وابن أمير الحاج والشِّيرازي وابن الجوزي، قال الطَّحاوي: «فهذه الآثار قد تواترت عن رسول الله ﷺ أنَّه غسل قدميه في وضوئه للصَّلاة»، وهي مُقَدَّمَةٌ على حديث الآحاد عن المغيرة رضي الله عنه: «إنَّ رسول الله ﷺ توضَّأَ ومسح على الجوربين والنَّعلين»."]]},{"id":"u74_4","kind":"text","label":"الثَّاني: معارضة الآحاد للحديث المتواتر · الفقرة ٤","segs":[["ctx","ج. الأحاديث المتواترة في الإمساك عن الأكل والشُّرب بطلوع الفجر، قال الطَّحاوي: «فلا يجب ترك آية من كتاب الله تعالى نصاً، وأحاديث عن رسول الله ﷺ متواترة قد قَبِلَتها الأُمَّة وعملت بها من لدن رسول الله ﷺ إلى اليوم إلى حديث قد يجوز أن يكون منسوخاً بما ذكرناه في هذا الباب» مُقَدَّمَةٌ على حديث الآحاد: «إذا سمع أحدكم النِّداء والإناء في يده فلا يضعه حتى يقضي حاجته منه»."]]},{"id":"u74_5","kind":"text","label":"الثَّاني: معارضة الآحاد للحديث المتواتر · الفقرة ٥","segs":[["ctx","د. الأحاديث المتواترة في النَّهي عن أكل ذي ناب من السِّباع، قال الطَّحاوي: «قامت الحجة عن رسول الله ﷺ بنهيه عن أكل كلِّ ذي ناب من السِّباع، وتواترت بذلك الآثار عنه، فلا يجوز أن يخرج من ذلك الضَّبع إذا كانت ذات ناب من السِّباع إلا بما يقوم علينا به الحجة بإخراجها من ذلك»، وقال الجصَّاص: «فهذه آثار مستفيضة في تحريم ذي النَّاب من السِّباع وذي المخلب من الطير، والثَّعلب والهر والنِّسر والرخم داخلة في ذلك، فلا معنى لاستثناء شيء منها إلا بدليل يوجب تخصيصه»، فهي مُقَدَّمَةٌ على حديث الآحاد في أكل الضَّبع عن جابر رضي الله عنه: «إنَّ رسول الله ﷺ سُئل عن الضَّبع، فقال: هي من الصَّيد»."]]}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u75","title":"الثَّالث: معارضة الآحاد للحديث المشهور","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u75_1","kind":"text","label":"الثَّالث: معارضة الآحاد للحديث المشهور · الفقرة ١","segs":[["ctx","تحدَّثنا عن الحديث المشهور، ونذكر هاهنا أمثلة في تقديمه على الآحاد:"]]},{"id":"u75_2","kind":"text","label":"الثَّالث: معارضة الآحاد للحديث المشهور · الفقرة ٢","segs":[["ctx","أ. حديث القضاء المشهور: «البيّنةُ على المُدَّعي واليمينُ على مَن أنكر»، قال الجصَّاص: «وهذا الخبر وإن كان وروده من طريق الآحاد، فإنَّ الأُمَّة قد تَلَقَّته بالقَبول والاستعمال، فصار في حيز المتواتر»، فقَدَّموه على حديث الآحاد: «قضى رسول الله ﷺ باليمين مع الشَّاهد الواحد»."]]},{"id":"u75_3","kind":"text","label":"الثَّالث: معارضة الآحاد للحديث المشهور · الفقرة ٣","segs":[["ctx","ب. الحديث المشهور في عصمةِ دم المسلم: «لا يَحِلّ دم امرئ مسلم يشهد أنَّ لا إله إلا الله وأنّي رسول الله إلاّ بإحدى ثلاث: النَّفس بالنَّفس، والثَّيب الزَّاني، والتَّارك لدينه»، فقدَّموه على حديث الآحاد: «إنَّ مَن شَرِبَ الخمرَ فاجلدوه، فإن عاد في الرَّابعةِ فاقتلوه، قال: ثمّ أُتي النَّبيُّ ﷺ بعد ذلك برجلٍ قد شَرِب الخمرَ في الرَّابعة فضربه ولم يقتله»."]]},{"id":"u75_4","kind":"text","label":"الثَّالث: معارضة الآحاد للحديث المشهور · الفقرة ٤","segs":[["ctx","ج. الحديث المشهور في بطلان الصَّلاة بالكلام مطلقاً، فقال ﷺ: «إنَّ هذه الصَّلاة لا يصلح فيها شيء من كلام النَّاس، إنَّما هو التَّسبيحُ والتَّكبيرُ وقراءةُ القرآن»، حتى منعوا من الدُّعاء بما يشبه كلامَ النّاس في الصَّلاة، وتركوا العمل بحديث الآحاد: «ليسأل أحدُكم رَبَّه حاجتَه كلَّها حتى شِسْع نعله إذا انقطع»."]]},{"id":"u75_5","kind":"text","label":"الثَّالث: معارضة الآحاد للحديث المشهور · الفقرة ٥","segs":[["ctx","د. الحديث المشهور: «في النَّفس المؤمنة مئة من الإبل»، رُجِّح به قولُ ابن مسعود رضي الله عنه: «شبه العمد خمس وعشرون حقه، وخمس وعشرون جذعة، وخمس وعشرون بنت مخاض، وخمس وعشرون بنت لبون» في مقابل حديث الآحاد في إيجاب الحوامل من الإبل: فعن عبد الله بن عمرو رضي الله عنه، قال ﷺ: «ألا إنَّ ديةَ الخطأ شبه العمد ما كان بالسَّوط والعصا مئة من الإبل منها أربعون في بطونها أولادها»؛ لأنَّ في إيجاب الحوامل إيجاب الزِّيادة على المئة؛ لأنَّ الحمل أصلٌ من وجه."]]},{"id":"u75_6","kind":"text","label":"الثَّالث: معارضة الآحاد للحديث المشهور · الفقرة ٦","segs":[["ctx","هـ. الحديث المشهور في الاستنزاه من البول مطلقاً دون تفصيلٍ بين بولٍ وبولٍ، قدَّموه على حديث: «إنَّ رسول الله ﷺ قال في بول الغلام الرَّضيع: ينضح بول الغلام ويغسل بول الجارية»، فإنَّه غريب لا يُقبل، خصوصاً إذا خالف المشهور."]]},{"id":"u75_7","kind":"def","label":"الثَّالث: معارضة الآحاد للحديث المشهور · الفقرة ٧","segs":[["matn","ثالثاً: مخالفة الحديث للعمل:"],["ctx","ويقصد بالمخالفة للعمل أن يخالف راوي الحديث ما رواه في عمله أو فتياه، أو يخالف الصَّحابة رضي الله عنهم فيفتون أو يعملون بغيره، أو يعرض الصَّحابة رضي الله عنهم عن العمل بالحديث، أو يترك العمل بالآحاد لوروده في عموم البلوى، وهذا ما نبحثه في"],["matn","النِّقاط الآتية:"]]}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u76","title":"الأولى: مخالفة الرَّاوي لمرويه","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u76_1","kind":"def","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ١","segs":[["matn","ويشتمل على ثلاث صور:"]]},{"id":"u76_2","kind":"def","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ٢","segs":[["ctx","١."],["matn","إنكار راوي الحديث الرِّوايةَ"],["ctx","، فإن كان إنكار جاحد، بأن يقول: كذب عليَّ، أو ما رويت هذا، فإنَّه يسقط العمل بالحديث اتفاقاً، وإن كان إنكارَ مُتوقِّف؛ بأن قال: لا أذكر أنّي رويت لك هذا الحديث، أو لا أعرفه، ففيه خلافٌ: فعند الكرخيّ وجماعة وهو مختارُ أبي حنيفة وأبي يوسف: يسقط العمل به، وقال محمد: لا يسقط."]]},{"id":"u76_3","kind":"text","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ٣","segs":[["ctx","ولعلَّ قريب من هذا ما اشتُهر عن أبي حنيفة من دوام حفظ الرَّاوي للحديث، فإنَّه يشترط استدامة الحفظ من آن التَّحمّل إلى آن الأداء، وعدم الاعتداد بالحفظ إذا لم يكن الرَّاوي ذاكراً لمرويه؛ إذ أنَّه قال: «لا ينبغي للرَّجل أن يُحَدِّثَ من الحديث إلا بما حفظه من يوم سمعه إلى يوم يحدِّث به»، قال العلَّامة محمد عوَّامة: «وهذا شرطٌ شديد، حَمَله عليه ما شَهِده من اضطراب الرُّواة وتصرّفهم، وبحكم هذا الشَّرط سيختلف مع غيره في تضعيف بعض الأحاديث وتصحيح غيره لها»."]]},{"id":"u76_4","kind":"text","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ٤","segs":[["ctx","ومثاله: الحديث الذي أَنكره المروي عنه حديث ربيعة بن عبد الرَّحمن عن سهيل بن أبي صالح عن أبيه عن أبي هريرة رضي الله عنه أنَّ النَّبي ﷺ: «قضى بشاهد ويمين»، فإنَّ عبدَ العزيز بن محمد الدراوردي قال: لقيت سهيلاً فسألته عن رواية ربيعة عنه هذا الحديث فلم يعرفه، وكان يقول بعد ذلك: حدثني ربيعة عنّي، فأَصحابُنا لم يقبلوا هذا الحديث؛ لانقطاعه بإنكار."]]},{"id":"u76_5","kind":"def","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ٥","segs":[["ctx","٢."],["matn","عمل راوي الحديث بخلاف مرويه، وهذا يسقط اعتباره"],["ctx","، فإن عمل الرَّاوي بعدما روى حديثاً بخلاف ما رواه فلا عبرة لما روى بل العبرة عند الحنفية بما رأى لا بما روى؛ لأنَّ الرَّاوي العدل المؤتمن إذا رَوَى حديثاً عن رسول الله ﷺ وعمل بخلافه، دلَّ ذلك على شيءٍ ثبت عنده من نسخٍ أو مُعارضةٍ أو تخصيصٍ، أو لكونِهِ غيرِ ثابت، أو غير ذلك من الأسباب، وهذا مما خالف فيه الرَّاوي مرويه بيقين، فإنَّه يُسقط العمل به، لا أن يكون الحديث محتملاً لمعنيين فيعمل الرَّاوي بأحدهما ـ كما سيأتي ـ؛ وإن خالف لقلّة المبالاة به أو لغفلتِه فقد سقطت عدالته، وهذا بعيدٌ عن حال الصَّحابيّ، ومن أَمثلته:"]]},{"id":"u76_6","kind":"text","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ٦","segs":[["ctx","أ. حديث السيدة عائشة رضي الله عنها: «أيما امرأة نكحت بغير إذن وليها فنكاحها باطل»، فأفاد أنَّه لا تصحّ عبارة المرأة في النِّكاح، لكنَّ عائشة رضي الله عنها عملت بخلافه في تزويجها لبنت أَخيها؛ فعن عبد الرَّحمن بن القاسم عن أبيه: «إنَّ عائشة زَوّجَ النَّبي ﷺ زوَّجت حفصة بنت عبد الرَّحمن المنذر بن الزُّبير وعبد الرَّحمن غائب بالشَّام، فلما قدم عبد الرَّحمن قال: ومثلي يصنع هذا به، ومثلي يُفتات عليه، فكلَّمت عائشة المنذر بن الزُّبير، فقال المنذر: فإنَّ ذلك بيدِ عبد الرَّحمن، فقال عبد الرَّحمن: ما كنت لأرد أمراً قضيته، فقرت حفصة ثم المنذر، ولم يكن ذلك طلاقاً»، فعلم منه سقوط الاحتجاج بظاهر الحديث، وأنَّه محمول على نفي الكمال؛ لئلا تُنسب إلى الوقاحة."]]},{"id":"u76_7","kind":"text","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ٧","segs":[["ctx","ب. حديث أبي هريرة رضي الله عنه، قال ﷺ: «إذا شرب الكلب من إناء أحدكم فليغسله سبعاً»، فأفاد لزوم غسل الإناء من شرب الكلب سبع مرات، لكنَّ رواي الحديث خالف مرويه، فقد غسل أبو هريرة رضي الله عنه «ثلاث مرّات»، فثبت بذلك نسخ السَّبع؛ لأنا نُحسن الظَّن به، فلا نتوهم عليه أن يترك ما سمعه إلاّ على مثله."]]},{"id":"u76_8","kind":"text","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ٨","segs":[["ctx","ج. حديث ابن عباس رضي الله عنهم، قال ﷺ: «من بدَّل دينه فاقتلوه»، فإنَّه مُختصٌّ بالرِّجال؛ لأنَّ راويه ابن عَبَّاس رضي الله عنهم قد أَفتى بخلافه، فقال: «لا يُقتلن النِّساء إذا هنّ ارتددن عن الإسلام، ولكن يحبسن ويدعين إلى الإسلام فيجبرن عليه»، والرَّاوي إذا أَفْتَى بخلاف الرِّواية يدلّ على الاختصاص ابتداءً أو على انتساخه."]]},{"id":"u76_9","kind":"text","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ٩","segs":[["ctx","د. حديث ابن عباس رضي الله عنه: «إنَّ امرأة أتت رسول الله ﷺ، فقالت: إنَّ أمي ماتت وعليها صوم شهر، فقال: أرأيت لو كان عليها دين أكنت تقضينه؟ قالت: نعم، قال: فدينُ الله أَحقُّ بالقضاء»، فقد خالفه ابن عباس رضي الله عنهم فأفتى: «لا يُصَلِّ أحد عن أحد ولا يصوم أحد عن أحد»، وقال أيضاً: «لا يصوم أحد عن أحد ويطعم عنه»، وفتوى الرَّاوي على خلاف مرويه بمنزلة روايته للناسخ، ونسخ الحكم يدل على إخراج علَّته عن الاعتبار؛ ولذا صرّحوا بأن من شرط القياس أن لا يكون حكم الأصل منسوخاً؛ لأنَّ التَّعدية بالجامع، ونسخ الحكم يستلزم إبطال اعتباره؛ إذ لو كان معتبراً لاستمر ترتيب الحكم على وفقه، ولذلك فهو منسوخ أيضاً؛ للاتفاق على صرفه عن ظاهره في حق الصَّلاة، فإنَّه لا يصحّ صلاة أحد عن أحد."]]},{"id":"u76_10","kind":"text","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ١٠","segs":[["ctx","هـ. حديث عائشة رضي الله عنها، قال ﷺ: «مَن مات وعليه صيام صام عنه وليه» فقد خالفت رضي الله عنها ما روت، وأفتت بعدم إجزاء الصَّوم؛ فعن عَمرة بنت عبد الرَّحمن قلت لعائشة رضي الله عنها: «إنَّ أُمي توفيت وعليها صيام رمضان أيصلح أن أقضي عنها؟ فقالت: لا؛ ولكن تصدقي عنها مكان كلّ يوم على مسكين خيرٌ من صيامك»، فدلَّ هذا على نَسخه، لا سيما وقد رُوي عن ابن عمر رضي الله عنه أنَّه «كان إذا سُئل عن الرَّجل يموت وعليه صوم من رمضان أو نذر يقول: لا يصوم أحد عن أحد، ولكن تصدقوا عنه من ماله للصَّوم لكلّ يوم مسكيناً»، وذكر مالك رضي الله عنه بلاغاً: «ولم أسمع عن أحد من الصَّحابة رضي الله عنهم ولا من التَّابعين رضي الله عنهم ولا بالمدينة أنّ أحداً منهم أَمر أحداً أن يصومَ عن أحدٍ ولا يُصلي عن أحد»، قال ابنُ الهُمام: «وهذا مما يؤيد النَّسخ، وأنَّه الأمر الذي استقرَّ الشَّرع عليه آخراً»."]]},{"id":"u76_11","kind":"text","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ١١","segs":[["ctx","و. حديث ابن عمر رضي الله عنهم: «كان رسول الله ﷺ إذا قام إلى الصَّلاة رفع يديه حتى تكونا حذو منكبيه، ثم كبَّر وهما كذلك فيركع، ثم إذا أراد أن يرفع صُلبه رفعهما حتى تكونا حذو منكبيه، ثم قال: سمع الله لمن حمده ولا يرفع يديه في السُّجود ويرفعهما في كل تكبيرة يكبرها قبل الرُّكوع حتى تنقضي صلاته»، فإنَّ ابن عمر رضي الله عنهم امتنع عن العملِ بالحديث، قال مُجاهد: «ما رأيت ابن عمر رضي الله عنهم يرفع يديه إلا في أَوّل ما يفتتح الصَّلاة»، وهذا يُخرج الحديثَ عن الحجيّة؛ لأنَّ تركَ العمل بالحديث حرام، فدلَّ على نسخِه، قال الطَّحاويّ: «فهذا ابن عمر رضي الله عنهم قد رأى النَّبيّ ﷺ يرفع، ثمّ قد ترك هو الرَّفع بعد النَّبيّ ﷺ فلا يكون ذلك إلاّ وقد ثبت عنده نسخ ما قد رأى النَّبيّ ﷺ فعله وقامت الحجّة عليه بذلك»."]]},{"id":"u76_12","kind":"def","label":"الأولى: مخالفة الرَّاوي لمرويه · الفقرة ١٢","segs":[["ctx","٣."],["matn","تعيينُ الرَّاوي بعض محتملات المروي"],["ctx",": بأن كان عامّاً فعمل بخصوصه، أو مشتركاً فعمل بأحد معنييه، فإنَّه لا يَمنع العمل به؛ لأنَّه تأويل لا حجر، مثل حديث ابن عمر رضي الله عنهم: «المتبايعان بالخيار ما لم يتفرقا»، يحتمل التَّفرُّق بالأَقوال والأَبدان، وقد حَمَلَ ابنُ عمر رضي الله عنهم على تفرَّق الأبدان، فعن نافع: «كان ابن عمر رضي الله عنهم إذا بايع رجلاً فأَراد أن لا يقيلَه قام فمشي هنيهة ثم رجع إليه»، ولم يأخذ الحنفية به وحملوه على تفرُّق الأقوال."]]}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u77","title":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u77_1","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ١","segs":[["ctx","إن خالف بعضِ الصَّحابة رضي الله عنهم العملَ بالحديث إذا كان ظاهراً لا يحتمل الخفاءَ عليهم يُورث الطَّعن فيه؛ لذلك قالوا: عمل صحابيّ آخر بخلافه يُسقطه عن درجة الاعتبار، بخلاف عمل الصَّحابي نفسه بخلاف مرويه، فإنَّه يجعله غير معتبر أصلاً."]]},{"id":"u77_2","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ٢","segs":[["ctx","ومن أمثلته:"]]},{"id":"u77_3","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ٣","segs":[["ctx","أ. حديث عبادة بن الصامت رضي الله عنه، قال ﷺ: «البكرُ بالبكرِ جلدُ مئة، ونفي سنة»، فظاهر الحديث يفيد أنَّ النَّفي من الحدّ، وقد عمل عمر رضي الله عنه بخلافه وترك الحديث فيما روى سعيد بن المُسَيَّب رضي الله عنه قال: «غرَّب عمر رضي الله عنه ربيعة بن أمية في الخمر إلى خيبر، فلحق بهرقل فتنصَّر، فقال عمر رضي الله عنه: لا أُغرب بعده مسلماً»، فلو كان النَّفي حَدّاً لَمّا حلف على تركه، فعُلِم أنَّ النَّفي منه كان سياسةً لا حَدّاً، وحديث الحدود كان ظاهراً لا يحتمل الخفاء على الخلفاء الذين نصّبوا لإقامة الحدود، وعن عليّ رضي الله عنه: «حسبهما من الفتنة أن ينفيا»."]]},{"id":"u77_4","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ٤","segs":[["ctx","واحترز به عما لا يحتمل الخفاء عليهم، فإنَّه لا يوجب جرحاً في الحديث. قال اللكنوي: «فترك عمر رضي الله عنه العمل به أسقطه عن درجةِ الاعتبار؛ ولذا لم يعملوا به، ولم يُدخلوا النَّفي في الحدّ، بل جعلوه من أُمور السِّياسة». قال الجصاص: «فلَمّا لم يكن خبر النَّفي بهذه المنزلة، بل كان ورودُه من طريق الآحاد، ثبت أنَّه ليس بحد»."]]},{"id":"u77_5","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ٥","segs":[["ctx","ب. حديث أبي هريرة رضي الله عنه، قال ﷺ: «إذا سرق السَّارق فاقطعوا يده، فإن عاد فاقطعوا رجلَه، فإن عاد فاقطعوا يده، فإن عاد فاقطعوا رجله)، فإنَّه يفيد قطع جميع أطرافه، وهذا مخالفٌ لعمل الصَّحابة رضي الله عنهم، فعن عليٍّ رضي الله عنه قال: «إذا سَرَقَ السَّارقُ قطعت يده اليمنى، فإن عاد قُطِعتْ رجلُه اليُسرى، فإن عادَ ضمنه السِّجن حتى يحدث خيراً، إنّي استحيي من الله تعالى أن أَدعه ليس له يدٌ يأكل بها ويستنج بها، ورِجل يمشي عليها»، وعن ابن عَبّاس رضي الله عنهم: «كتب إلى نجدة الحروري بمثل قول عليّ رضي الله عنه، وإنَّ عمرَ رضي الله عنه استشارهم في سارق فأجمعوا على مثل قول عليّ رضي الله عنه»، وعن عمر رضي الله عنه، قال: «إذا سرق فاقطعوا يده، ثمّ إن عاد فاقطعوا رجلَه، ولا تقطعوا يده الأخرى، وذروه يأكل بها، ويستنج بها، ولكن احبسوه عن المسلمين»."]]},{"id":"u77_6","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ٦","segs":[["ctx","قال ابنُ الهمام: «إنَّ هذا قد ثبتَ ثبوتاً لا مردَّ له، وبعيدٌ أن يقطعَ النَّبيُّ ﷺ السَّارقَ أربعةً ثُمّ يقتله ولا يَعلمه مثل عليٍّ وعمر وابنِ عبّاس من الصَّحابة رضي الله عنهم الملازمين له ﷺ، ولو غابوا لا بُدّ من علمِهم عادةً، فاتباع عليّ رضي الله عنه إما لضعف ما مرَّ، أو لعلمِه بأنَّ ذلك ليس حَدّاً مستمراً، بل من رأي الإمام»."]]},{"id":"u77_7","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ٧","segs":[["ctx","ج. حديث عائشة رضي الله عنها: أنَّ أبا حذيفة بن عتبة تبنى سالماً، وإنَّ سهلةَ بنت سهيل كانت تحت أبي حذيفة رضي الله عنهم، فجاءت رسول الله ﷺ فقالت: يا رسول الله، إنا كنا نرى سالماً ولداً، وكان يدخل عليَّ وليس لنا إلاّ بيتٌ واحد، فماذا تَرَى في شأنه؟ فقال رسول الله ﷺ: «أَرضعيه، فأَرضعته خمس رضعات، فحرم بهنّ، وكان بمنزلة ولدها من الرَّضاعة»."]]},{"id":"u77_8","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ٨","segs":[["ctx","فظاهر الحديث يفيد أنَّ إرضاع الكبير يحرم من الرَّضاع كما هو الحال في الصغير، ولكن هذا مخالف لعمل عامة الصَّحابة رضي الله عنهم؛ لذلك جعلوه خاصّاً بسالم رضي الله عنه لمخالفته للآثار الأخرى."]]},{"id":"u77_9","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ٩","segs":[["ctx","فعن عليّ رضي الله عنه قال: «لا رضاع بعد الفصال»، وعن ابن عبَّاس رضي الله عنهم قال: «لا رضاع بعد الفصال الحولين»، وعن عمر رضي الله عنه، قال: «لا رضاع بعد الفصال»."]]},{"id":"u77_10","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ١٠","segs":[["ctx","د. حديث جابر رضي الله عنه قال: «أَعتَقَ رجلٌ منا عبداً له عن دبر، فدعا النَّبي ﷺ به فباعه»، فهو يفيد صحة بيع المدبّر، وهو مخالف لعمل الصَّحابة رضي الله عنهم."]]},{"id":"u77_11","kind":"text","label":"الثَّانية: مخالفةُ الصَّحابة رضي الله عنهم للحديث · الفقرة ١١","segs":[["ctx","فعن ابن عمر رضي الله عنهم أنَّه قال: «لا يباع المُدَبَّر»، وعن زيد بن ثابت رضي الله عنه قال: «لا يباع المُدَبَّر»، ولم يقف الأمر عند هذا فقط، بل إنَّ راوي الحديث أيضاً لم يَعمل به، قال الطَّحاوي: «ولقد وجدنا عن جابر بن عبد الله رضي الله عنه ـ وهو الذي روى الحديث ـ ما يدل على أنَّ مذهبَه كان أن لا يُباع المُدَبَّر»؛ لذلك قال مالك: «الأمر المجتمع عليه عندنا في المُدَبَّر أنَّ صاحبه لا يبيعه...»."]]}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u78","title":"الثَّالثة: إعراضُ الصَّحابة رضي الله عنهم عن الحديث","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u78_1","kind":"text","label":"الثَّالثة: إعراضُ الصَّحابة رضي الله عنهم عن الحديث · الفقرة ١","segs":[["ctx","إنَّ أعرض الأئمةِ من الصَّدرِ الأَوّل عن الحديث؛ بأن تركوا المحاجّة به عند الحاجة، فإنَّه يعتبر رداً له؛ فإنَّهم إذا تركوا المحاجة به مع وقوع الاختلاف فيما بينهم يكون مردوداً عند بعض الحنفية المتقدِّمين وعامَّة المتأخِّرين؛ لأنَّ الصَّحابة رضي الله عنهم هم الأصل في نقل الدِّين، ولم يتهموا بترك الاحتجاج بما هو حجّة، والاشتغال بما ليس بحجّة، مع أنَّ عنايتَهم بالحجج أقوى من عناية غيرهم، فترك المحاجّة والعمل به عند ظهور الاختلاف فيهم، دليل ظاهر على وجود السَّهو ممَّن رواه بعدهم أو نَسخِهِ، ومن أمثلته:"]]},{"id":"u78_2","kind":"text","label":"الثَّالثة: إعراضُ الصَّحابة رضي الله عنهم عن الحديث · الفقرة ٢","segs":[["ctx","أ. حديث وجوب الزَّكاة في مال الصَّبي: «ألا مَن ولي يتيماً له مال فليتجر فيه ولا يتركه حتى تأكله الصَّدقة»، فإنَّ الصَّحابة رضي الله عنهم لما اختلفوا فيما بينهم في وجوب الزَّكاة على الصَّبيّ وتكلموا بالرَّأي ولم يلتفتوا إلى الحديث كان ذلك دليل انقطاعه."]]},{"id":"u78_3","kind":"text","label":"الثَّالثة: إعراضُ الصَّحابة رضي الله عنهم عن الحديث · الفقرة ٣","segs":[["ctx","ب. حديث اعتبار الطَّلاق بالرِّجال: «الطَّلاق بالرِّجال والعِدَّة بالنِّساء»، فإنَّ الصَّحابة رضي الله عنهم اختلفوا في هذه المسألة، فذهب عمر وعثمان وزيد وعائشة رضي الله عنهم إلى أنَّ الطَّلاقَ معتبرٌ بحال الرَّجل في الرِّقِّ والحرية كما هو مذهب الشَّافعي، وذهب عليّ وابن مسعود رضي الله عنهم إلى أنَّه معتبر بحال المرأة كما هو مذهب الحنفية، وعن ابن عمر رضي الله عنه: «أنَّه يعتبر بمَن رقّ منهما، حتى لا يملك الزَّوج عليه ثلاث تطليقات إلا إذا كانا حُرَّين»، وإنَّهم تكلموا في هذه المسألة بالرَّأي وأعرضوا عن الاحتجاج بهذا الحديث مع أنَّ راويه ـ وهو زيد ـ فيهم، فدلَّ ذلك على أنَّه غير ثابت أو منسوخ، ولئن ثبت فهو موؤل بأنَّ إيقاع الطَّلاق إلى الرِّجال."]]}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u79","title":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى»","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u79_1","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ١","segs":[["ctx","إنَّ معنى اصطلاح الحادثة المشتهرة أو ما يعمّ به البلوى: هو ما تمسُّ الحاجةُ إليه في عمومِ الأحوال، أو يحتاج إليه الكلُّ حاجةً متأكدةً مع كثرةِ تكرُّرِه."]]},{"id":"u79_2","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ٢","segs":[["ctx","وذلك بأن يكون وَرَدَ حديثُ آحادٍ فيما اشتهر من الحوادث وعَمَّ به البلوى، بأن لم ينتشر في الصَّدرِ الأوّل والثَّاني؛ لأنَّهم لا يُتهمون بالتَّقصير في متابعةِ السُّنة، فإذا لم يشتهر الخبر في القرنين مع شدّةِ الحاجةِ وعمومِ البلوى كان ذلك علامةَ عدم صحَّتِه."]]},{"id":"u79_3","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ٣","segs":[["ctx","فما كان من أحكام الشَّريعة بالنَّاس حاجةٌ إلى معرفتِهِ، فسبيلُ ثبوته الاستفاضة والخبر الموجب للعلم، وغيرُ جائز إثباتُ مثلِهِ بأخبارِ الآحاد، نحو: إيجاب الوضوء من مسِّ الذكر، ومسِّ المرأة، والوضوءِ ممَّا مَسَّت النَّار، والوضوءِ مع عدم تسمية الله عليه."]]},{"id":"u79_4","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ٤","segs":[["ctx","ولَمّا كانت البلوى عامَّةٌ من كافَّة النَّاس بهذه الأمور ونظائرها، فغيرُ جائز أن يكون فيه حكم الله تعالى من طريق التَّوقيف إلاَّ وقد بلَّغ النَّبي ﷺ ذلك ووَقَفَ الكافَّةُ عليه، وإذا عَرَفته الكافَّةُ، فغيرُ جائزٍ عليها تركُ النَّقل والاقتصار على ما ينقله الواحد منهم بعد الواحد؛ لأنَّهم مأمورون بنقله، وهم الحجَّةُ على ذلك المنقول إليهم، وغيرُ جائز لها تضييع موضع الحجّة، فعلمنا بذلك أنَّه لم يكن من النَّبيِّ ﷺ توقيفٌ في هذه الأُمور ونظائرها."]]},{"id":"u79_5","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ٥","segs":[["ctx","قال الكوثريُّ: «وهذا إذا توفَّرت الدَّواعي إلى نقلِها بطريقِ الاستفاضة، حيث يَعدُّون ذلك ممَّا تُكذِّبُه شواهدُ الحال، واشتراط شهرة الخبر عند طوائف الفقهاء»، وقال سبطُ ابنُ الجوزي: «إنَّ خبرَ الواحد فيما تعمّ به البلوى ليس بحجَّةٍ عند الإمام أبي حنيفة»."]]},{"id":"u79_6","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ٦","segs":[["ctx","ومعلومٌ أَنَّ تصحيحَ الأحاديث وتضعيفَها مسألةٌ اجتهاديةٌ خاضعةٌ لنظرِ المجتهدِ فيما يعتبر من شروط وقواعد وأُصول، كاشتراط البُخاريِّ اللقيا ومخالفة تلميذه مسلمٌ له في الاكتفاء بالمعاصرة، وهكذا."]]},{"id":"u79_7","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ٧","segs":[["ctx","وإنَّ للسَّادة الحنفية أُصولاً اعتمدوها في قَبولهم للأخبار: كعدم مخالفةِ القرآن أو المتواتر أو المشهور أو روايته فيما تعمّ به البلوى أو غيرها، قال عيسى بن أبان: «إنَّ خبرَ الواحد يُرَدُّ لمعارضةِ السُّنة الثَّابتة إيّاه، أو أن يتعلّق القرآن بخلافه فيما لا يَحتمل المعاني، أو يكون من الأُمور العامّة فيجيءُ خبرٌ خاصٌّ لا تَعرفُه العامَّة، أو يكون شاذّاً قد رواه النَّاسُ وعملوا بخلافه»."]]},{"id":"u79_8","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ٨","segs":[["ctx","وما نحن بصدده هو اعتبارُهم لشرطِ عدم ورود حديث الآحاد فيما تعمَّ به البلوى، إذ يكون سبباً لردِّه وتركِه، قال الجصَّاصُ: «إنَّ لنا أَصلاً في قَبول الأَخبار وشرائط نعتبرها فيه متى خرج الخبر عنها لم نقبله، وهو أنَّ ما كان بالنَّاس إلى معرفتِهِ حاجةٌ عامّة، فغيرُ جائز ورودُه من جهةِ الآحاد»."]]},{"id":"u79_9","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ٩","segs":[["ctx","وهذا الاشتراط من الحنفية لا يعني القطع بوروده متواتراً عند عموم الحاجة، وإنَّما مدار الأمر على الظنِّ والاجتهاد، فعدمُ اشتهاره بين العلماءِ والعامَّة مع شدّةِ الضَّرورة إليه، يُورث شبهة في حاله، تمنعُهم من إثبات الفرضيه به، والاقتصار على إثبات السُّنيّة والاستحباب به، قال علاء الدِّين البُخاريُّ: «لم نَدَّعِ الاشتهار عند عموم البلوى قطعاً، بل ادّعيناه ظاهراً، وكذا الصَّحابة رضي الله عنهم إنَّما عملوا بخبر الواحد في تلك الحوادث؛ لقرائن اختصّت به، أو لصيرورته مشهوراً عند بلوغه إيّاهم»."]]},{"id":"u79_10","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ١٠","segs":[["ctx","فإنَّ خبر الآحاد إذا ورد في غير الوجوب والحظر: كالمسنون والمباح ونحوهما، فإنَّه يكون مقبولاً عند الحنفية. قال الجصَّاص: «وأما مجيئه فيما تعم البلوى به فإنَّما كان علَّة لرده من توقيفٍ من النَّبي ﷺ الكافَّةَ على حكمه فيما كان فيه إيجابٌ أو حظر»."]]},{"id":"u79_11","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ١١","segs":[["ctx","وقال ابن الهمام: «خبر الواحد فيما تعم به البلوى... لا يثبت به وجوب دون اشتهار أو تلقي الأُمَّة بالقَبول عند عامَّة الحنفية»."]]},{"id":"u79_12","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ١٢","segs":[["ctx","فطالما أنَّ طريقَ إثبات خبر الآحاد والعمل بموجبه الاجتهاد، فيجوز رَدُّ أحاديث الآحاد لأسبابٍ اجتهادية إذا كان طريقُ قَبولها من رواةٍ معيَّنين هو الاجتهادُ، وغالبُ الظنّ بإحسان الظنِّ بهم، قال عيسى بن أبان: «وَرَدُّ أَخبارُ الآحادِ لعللٍ عليه عملُ النَّاس، وهو مذهب الأئمة من الصَّحابة رضي الله عنهم... وهذا مذهب التَّابعين ومَن بعدهم في قَبول أَخبار الآحاد وردِّها بالعلل...، فهو مذهبُ السَّلف»."]]},{"id":"u79_13","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ١٣","segs":[["ctx","ومن هذه العلل عموم البلوى، قال البَزْدَويُّ: «إذا اشتهرت حادثة ـ بأن كان للناس حاجة ـ وخَفِي الحديث، كان ذلك دلالة على السَّهو؛ لأنَّ الحادثةَ إذا اشتهرت استحالَ أن يَخفى عليهم ما يثبت به حكم الحادثة...، فإذا شَذَّ الحديثُ مع اشتهار الحادثة كان ذلك زيافةً وانقطاعاً»."]]},{"id":"u79_14","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ١٤","segs":[["ctx","وعلى رغم كلِّ ما سبق من النَّقل عن أئمة الحنفية في اعتبار عُموم البلوى علَّةً لردِّ حديث الآحاد، إلا أَنَّ في المسألة خلافاً بين علماء الحنفية، فنُسِب للكَرخيِّ القولُ بأنَّ خبرَ الواحد إذا وَرَدَ موجباً للعمل فيما يَعمُّ به البَلوى لا يُقبل، وهو مُختار المتأخِّرين، وأمّا عند عامَّةِ الأُصوليين: فخبرُ الواحد فيما تعمُّ به البلوى مقبول إذا صَحّ سندُه."]]},{"id":"u79_15","kind":"text","label":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى» · الفقرة ١٥","segs":[["ctx","ولكن يؤخذ على هذا الخلاف المذكور عند الحنفيّة أنَّه مُخالف لمّا هو شائعٌ في كتبهم؛ إذ عند مناقشتهم للعديد من الأحاديث اعتبروا علَّة عموم البلوى؛ لذا يكاد أن يكون الخلاف المذكور بين الحنفية في اعتباره نظرياً؛ لإطباق كتبهم على ذكرِه والاعتماد عليه، وَنِسْبَة القول به للكرخيِّ مَحلُّ نظرٍ؛ لنقلِهِ عن عيسى ابنِ أبان والجصَّاصِ وغيرِهم من أكابرِ علماءِ الحنفيةِ المتقدِّمين."]]}],"sup":"المبحث الثَّالث انقطاع الحديث عن النَّبي ﷺ"},{"id":"u79a","title":"ومن الأدلة على اعتبارِ عمومِ البلوى علَّةً لردِّ الآحاد","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u79a_1","kind":"def","label":"ومن الأدلة على اعتبارِ عمومِ البلوى علَّةً لردِّ الآحاد · الفقرة ١","segs":[["matn","ومن الأدلة على اعتبارِ عمومِ البلوى علَّةً لردِّ الآحاد:"],["ctx","قوله تعالى: ﴿وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ﴾ [الإسراء:٣٦]، وقوله تعالى: ﴿وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ﴾ [البقرة:١٦٩]، وقوله تعالى: ﴿مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ﴾ [الزخرف:٨٦] وقوله جل جلاله: ﴿وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ﴾ [النساء:١٧١]، ووجه الدَّلالة: أنَّ خبر الواحد لا يوجب العلم، فانتفى قَبوله بظاهر هذه الآيات، وقال تعالى: ﴿وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا﴾ [النجم:٢٨]."]]},{"id":"u79a_2","kind":"text","label":"ومن الأدلة على اعتبارِ عمومِ البلوى علَّةً لردِّ الآحاد · الفقرة ٢","segs":[["ctx","وقوله تعالى: ﴿يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ﴾ [المائدة:٦٧]، ووجه الدَّلالة: أَنَّ كلَّ ما كان من الأحكام بالنَّاس إليه حاجةٌ عامَّة أنَّ النَّبيَّ ﷺ قد بلَّغه الكافَّة، وأنَّ وروده ينبغي أن يكون من طريق التَّواتر والشُّهرة؛ لعموم البلوى بها، فإذا لم نجد ما كان منها بهذه المنزلة وارداً من طريق التَّواتر عَلِمنا أنَّ الخبرَ غيرُ ثابت في الأصل، أو تأويله ومعناه غير ما اقتضاه ظاهرُه من نحو: الوضوء الذي هو غسلُ اليد دون وضوء الحدث."]]},{"id":"u79a_3","kind":"text","label":"ومن الأدلة على اعتبارِ عمومِ البلوى علَّةً لردِّ الآحاد · الفقرة ٣","segs":[["ctx","ولأنَّ النَّبيَّ ﷺ لم يقتصر على خبرِ ذي اليدين، بل سأل النَّاس؛ لأنَّه يمتنعُ في العادةِ أن يَختَصَّ هو بعلمِ ذلك من بين الجماعة...."]]},{"id":"u79a_4","kind":"text","label":"ومن الأدلة على اعتبارِ عمومِ البلوى علَّةً لردِّ الآحاد · الفقرة ٤","segs":[["ctx","فعن أبي هريرة رضي الله عنه: «صلَّى بنا رسول الله ﷺ صلاة في ركعتين، فقام ذو اليدين، فقال: أَقُصِرَت الصَّلاة يا رسول الله أم نسيت؟ فقال رسول الله ﷺ: كلُّ ذلك لم يكن، فقال: قد كان بعضُ ذلك يا رسول الله، فأَقْبَل رسولُ الله ﷺ على النَّاس، فقال: أصدق ذو اليدين؟ فقالوا: نعم يا رسول الله، فأَتَمَّ رسول الله ﷺ ما بَقِي من الصَّلاةِ ثُمَّ سَجَدَ سجدتين، وهو جالس بعد التَّسليم»."]]},{"id":"u79a_5","kind":"text","label":"ومن الأدلة على اعتبارِ عمومِ البلوى علَّةً لردِّ الآحاد · الفقرة ٥","segs":[["ctx","ولأنَّ عمر رضي الله عنه رَدَّ حديث أبي موسى رضي الله عنه في الاستئذان ثلاثاً؛ لأنَّه مِمَّا تَعُمُّ به البَلوى، وهو في كتاب الله تعالى، قال الله تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدْخُلُواْ بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُواْ وَتُسَلِّمُواْ عَلَىٰٓ أَهْلِهَا﴾ [النور:٢٧]، فاستنكر عمر رضي الله عنه انفراد أبي موسى رضي الله عنه بمعرفة تحديد الاستئذان بالثَّلاث دون الكافَّة مع عموم الحاجة إليه."]]},{"id":"u79a_6","kind":"text","label":"ومن الأدلة على اعتبارِ عمومِ البلوى علَّةً لردِّ الآحاد · الفقرة ٦","segs":[["ctx","فعن سعيد الخدري رضي الله عنه، يقول: «كنا في مجلس عند أُبَيّ بن كعب رضي الله عنه فأتى أبو موسى الأشعري رضي الله عنه مغضباً حتى وقف، فقال: أنشدكم الله هل سمع أحدٌ منكم رسول الله ﷺ يقول: الاستئذان ثلاث فإن أذن لك وإلا فارجع، قال أُبَيّ رضي الله عنه: وما ذاك؟ قال: استأذنت على عمر بن الخطاب رضي الله عنه أمس ثلاث مرَّات فلم يُؤْذن لي فرجعت ثمَّ جئته اليوم فدخلت عليه فأخبرته أني جئت أمس فسلمت ثلاثاً ثُمَّ انصرفت، قال: قد سمعناك ونحن حينئذٍ على شغل فلو ما استأذنت حتى يؤذن لك؟ قال: استأذنت كما سمعت رسول الله ﷺ، قال: فوالله لأوجعن ظهرك وبطنك أو لتأتين بمَن يشهد لك على هذا، فقال أُبَيّ بن كعب رضي الله عنه: فوالله لا يقوم معك إلا أَحدثنا سناً، قم يا أبا سعيد، فقمت حتى أتيت عمر رضي الله عنه، فقلت: قد سمعت رسول الله ﷺ يقول هذا»."]]}],"sup":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى»"},{"id":"u79b","title":"ومن أمثلته","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u79b_1","kind":"def","label":"ومن أمثلته · الفقرة ١","segs":[["matn","ومن أمثلته:"],["ctx","أ. حديث الآحاد في الجهر بالبسملة عند القراءة في الصَّلاة: «كان رسول الله ﷺ يجهر ببسم الله الرحمن الرحيم»، فإنَّه لما شَذَّ ـ أي ورد بطريق آحاد ـ مع اشتهار الحادثة وعموم البلوى بها لم يعمل به؛ لأنَّ شهرة الحادثة تقتضي شهرة ما يثبت به حكم الحادثة، فإذا لم يشتهر النَّقل عنهم في هذه الحادثة لم يقبل النقل."]]},{"id":"u79b_2","kind":"text","label":"ومن أمثلته · الفقرة ٢","segs":[["ctx","ب. حديث الآحاد في رفع اليدين عند الرُّكوع والقيام منه: «إذا افتتح ﷺ الصَّلاة يرفع يديه حتى يحاذي منكبيه وإذا ركع وإذا رفع رأسه من الرُّكوع»، وهو أمرٌ تعمُّ به البلوى فيتكرَّر كلَّ يوم مرّات، ولا يرويه إلاّ أفرادٌ من الصَّحابة رضي الله عنهم، فهذا يورث الشَّكَّ في ثبوتِهِ؛ لأنَّه ينبغي أن يتواتر ورودُه كما تواتر الرُّكوع والسُّجود، فهو من الأفعال الظَّاهرة في الصَّلاة مثلهما، كيف وقد عارضه أحاديث أُخرى أيضاً عن الصَّحابة رضي الله عنهم بعدم الرَّفع إلا في التكبيرة الأولى، قال البابرتي: «أحاديث الرَّفع مما تعمُّ به البلوى، فلا يكون حجة»، ويؤيده: ما روي عن علقمة، قال ابنُ مسعود رضي الله عنه: «ألا أصلِّي بكم صلاة رسول الله ﷺ، فصلَّى فلم يرفع يديه إلا في أول مرة»، وعن الأسود رضي الله عنه قال: «رأيت عمر بن الخطاب رضي الله عنه يرفع يديه في أول تكبيرة ثُمَّ لا يعود»، قال: «ورأيت إبراهيم والشَّعبي يفعلان ذلك»، قال الطَّحاوي: «فهذا عمر رضي الله عنه لم يكن يرفع يديه أيضاً إلا في التَّكبيرة الأولى في هذا الحديث، وهو حديث صحيح...»."]]},{"id":"u79b_3","kind":"def","label":"ومن أمثلته · الفقرة ٣","segs":[["matn","ج."],["ctx","حديث الآحاد في مَن لم يجد السُّترة للصَّلاة فيختط خطاً بين يديه: «إذا صلَّى أحدكم فليجعل تلقاء وجهه شيئاً، فإن لم يجد فلينصب عصاً، فإن لم يكن معه عصاً، فليخطط خطاً، ثُمَّ لا يضرّه ما مرَّ أمامه»، فإنَّ الخط وتركه سواء، قال الكاساني: «ولكنَّ الحديث غريب ورد فيما تعمُّ به البلوى، فلا نأخذ به»، وقال السَّرخسي: «ولكنَّ الحديث شاذٌّ فيما تعمُّ به البلوى فلم نأخذ به لهذا»؛ ولأنَّ المقصود أن يبدو للنَّاظر فيمتنع من المرور بين يديه، وما دون غلظ الإصبع بقدر ذراع لا يبدو للنَّاظر من بعيد، فلا فائدة فيه، ويشهد لذلك ما روي عن سبرة رضي الله عنه قال ﷺ: «ليستتر أحدكم في صلاته ولو بسهم»."]]},{"id":"u79b_4","kind":"text","label":"ومن أمثلته · الفقرة ٤","segs":[["ctx","وعن موسى بن طلحة رضي الله عنه، قال ﷺ: «إذا وضع أحدكم بين يديه مثل مؤخرة الرَّحل فليصلِ ولا يبال مَن مرَّ وراء ذلك»."]]},{"id":"u79b_5","kind":"text","label":"ومن أمثلته · الفقرة ٥","segs":[["ctx","د. حديث الآحاد في وضوءِ الرَّجل بفضل وضوء المرأة: «نهى ﷺ أن يتوضأ الرَّجل بفضل وضوء المرأة»، قال السَّرخسيّ: «شاذٌّ فيما تعمُّ به البلوى فلا يكون حجة»، ويؤيده: ما روي عن عائشة رضي الله عنها، قالت: «كنت أغتسل أنا ورسول الله ﷺ من إناء واحد ونحن جُنبان»، وعن أم صبية الجهنية رضي الله عنها، قالت: «اختلفت يدي ويد رسول الله ﷺ في الوضوء من إناء واحد»."]]},{"id":"u79b_6","kind":"text","label":"ومن أمثلته · الفقرة ٦","segs":[["ctx","هـ. حديث الآحاد في إفراد الإقامة: «أُمِرَ بلالٌ أن يشفع الأذان، وأن يوتر الإقامة، إلا الإقامة»، قال السَّرَخْسيُّ عن واحد من أحاديث الباب: «ولكنَّه شاذٌّ فيما تعمُّ به البلوى، والشَّاذ في مثلِهِ لا يكون حجة»، فالمعتمد عند أبي حنيفة أنَّ الإقامة كالأذان مثنى مثنى؛ لحديث عبد الله بن زيد رضي الله عنه فهو الأصل، وقد حكى فيه الإقامة مثل الأذان، ولأنَّ المختص بالإقامة قوله: قد قامت الصَّلاة، ولا إفراد في هذه الكلمة، ففي غيرها أولى، وقال إبراهيم النَّخعيّ: كان النَّاس يشفعون الإقامة حتى خرج هؤلاء ـ يعني بني أُمية ـ فأفردوا الإقامة، ومثله لا يكذب، وأشار إلى كون الإفراد بدعة، والحديث محمولٌ على الشَّفع والإيتار في حقِّ الصَّوت والنَّفس دون حقيقة الكلمة فمعناه: أن يؤذن بصوتين ويقيم بصوت واحد."]]},{"id":"u79b_7","kind":"text","label":"ومن أمثلته · الفقرة ٧","segs":[["ctx","و. حديث الآحاد في الصَّلاة على الدَّابة في المصر: «إنَّ النَّبيَّ ﷺ ركب الحمار في المدينة يعود سعد بن عبادة رضي الله عنه، وكان يُصلِّي وهو راكب»، هذا حديثٌ شاذٌّ فيما تعمُّ به البلوى، والشَّاذُّ في مثلِهِ لا يكون حجّةً، فعند أبي حنيفة: لا يجوز التَّطوع على الدَّابّة في المصر، وقال أبو يوسف: لا بأس به وأخذ بالحديث، ومُحمّد أخذ به إلاّ أنَّه كَرِه ذلك في المصر؛ لأنَّ اللغط يكثر فيها، فلكثرة اللغط ربما يُبتلى بالغلط في القراءة؛ فلذلك كره."]]},{"id":"u79b_8","kind":"text","label":"ومن أمثلته · الفقرة ٨","segs":[["ctx","ح. حديث الآحاد في مشروعيّة صلاة الاستسقاء: «خرج النَّبي ﷺ يستسقي فتوجّه إلى القبلة يدعو وحوّل رداءه، ثُمَّ صلّى ركعتين جهر فيهما بالقراءة»، قال السَّرَخْسيّ: «الأثر الذي نُقل أنَّه صلَّى فيها ﷺ شاذٌّ فيما تعمُّ به البلوى، وما يحتاج الخاصُّ والعامُّ إلى معرفته لا يُقبل فيه شاذّ، وهذا ممَّا تعمُّ به البلوى في ديارهم»، فلا تشرع صلاة الاستسقاء عند أبي حنيفة."]]},{"id":"u79b_9","kind":"text","label":"ومن أمثلته · الفقرة ٩","segs":[["ctx","ويؤيَّد ذلك: عن أنس رضي الله عنه: «إنَّ رجلاً دخل المسجد يوم جمعة من باب كان نحو دار القضاء ورسول الله ﷺ قائم يخطب، فاستقبل رسول الله ﷺ قائماً، ثُمَّ قال: يا رسول الله، هلكت الأموال وانقطعت السُّبل فادع الله يُغثنا، فرفع رسول الله ﷺ يديه، ثُمّ قال: اللهم أغثنا، اللهم أغثنا، اللهم أغثنا...»، وعن الشَّعبي، قال: «خرج عمر بن الخطاب رضي الله عنه يستسقي بالنَّاس فما زاد على الاستغفار حتى رجع، فقالوا: يا أمير المؤمنين، ما رأيناك استسقيت، قال: لقد طلبت المطر بمَجَاديح السَّماء التي تستنزل بها المطر، ﴿فَقُلْتُ ٱسْتَغْفِرُواْ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًا يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّٰتٍ وَيَجْعَل لَّكُمْ أَنْهَٰرًا﴾ [نوح:١٢]، ﴿ٱسْتَغْفِرُواْ رَبَّكُمْ ثُمَّ تُوبُوٓاْ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ﴾ [هود:٥٢]»."]]},{"id":"u79b_10","kind":"text","label":"ومن أمثلته · الفقرة ١٠","segs":[["ctx","ط. حديث الآحاد في التَّسمية عند الوضوء: «لا وضوء لمَن لم يذكر اسم الله عليه»، غيرُ معمول بظاهره في الزِّيادة على القرآن ركناً أو شرطاً؛ لأنَّه من أخبار الآحاد، وهي غير مقبولة فيما عمَّت البلوى به، وإن صح احتمل أنَّه يريد به نفي الكمال لا نفي الأصل: كقوله: «لا صلاة لجار المسجِّد إلا في المسجِّد»، و«مَن سمع النِّداء فلم يأته فلا صلاة له إلا من عذر» ونحو ذلك."]]},{"id":"u79b_11","kind":"text","label":"ومن أمثلته · الفقرة ١١","segs":[["ctx","ي. حديث: الاغتسال لمن غسل الميت والوضوء لمن حمله: «من غسله الغسل ومن حمله الوضوء»، فجعله الكَاسانيّ من: «أَخبار آحاد وردت فيما تعمُّ به البلوى، ويغلب وجوده، ولا يقبل خبر الواحد في مثله؛ لأنَّه دليلُ عدم الثُّبوت إذ لو ثبت لاشتهر»، ويؤيده: أنَّه لما بلغ ذلك عائشة رضي الله عنها ردَّته، فقالت: «أوينجس موتى المسلمين، وما على رجل لو حمل عوداً»."]]},{"id":"u79b_12","kind":"text","label":"ومن أمثلته · الفقرة ١٢","segs":[["ctx","ك. حديث: «الوضوء مما مست النَّار»، رَدَّه ابن عباس رضي الله عنهم، إذ لما روى أبو هريرة رضي الله عنه قال ﷺ: «الوضوء مما مست النَّار ولو من ثور أقط»، قال له ابن عباس رضي الله عنهم: «يا أبا هريرة، أنتوضأ من الدُّهن؟ أنتوضأ من الحميم؟ فقال أبو هريرة رضي الله عنه: يا ابن أخي، إذا سمعت حديثاً عن رسول الله ﷺ فلا تضرب له مثلاً»: أي إن توضأنا بماء سخن أنتوضأ بماء بارد، وإن ادهنا أنتوضأ، وقد رَدَّه الكاسانيّ؛ لأنَّه من أخبار الآحاد وَرَدَ فيما تعمُّ به البلوى."]]},{"id":"u79b_13","kind":"def","label":"ومن أمثلته · الفقرة ١٣","segs":[["matn","الخامسة: مخالفة الحديث للقياس إن لم يكن راويه مجتهداً:"],["ctx","إنَّ اشتراط فقه الرَّاوي «اجتهاد الرَّاوي» لم ينصّ عليه أئمةُ المذهب، بل هو تخريج عمّا ورد عنهم من فروع، واختلف أصوليو المذهب في هذا التَّخريج على قولين:"]]},{"id":"u79b_14","kind":"text","label":"ومن أمثلته · الفقرة ١٤","segs":[["ctx","١. اشتراط فقه الرَّاوي؛ لتقديم خبره على القياس على التَّفصيل السَّابق، وهو مذهب عيسى بن أبان واختاره القاضي أبو زيد وتابعه أكثر المتأخِّرين: كالبزدويّ والسَّرَخْسيّ والنَّسَفيّ وابن العَينيّ والحُساميّ وابن الهمام والكراماستي وغيره."]]},{"id":"u79b_15","kind":"text","label":"ومن أمثلته · الفقرة ١٥","segs":[["ctx","وخُرِّجت عليه مسائل عديدة، منها: حديث العرايا: فعن سهل بن أبي حثمة رضي الله عنه وغيره: «إنَّ رسول الله ﷺ نهى عن بيع الثمر بالتَّمر، ورخَّص في العرية أن تباعَ بخرصها يأكلها أهلها رطباً»، فهو مخالفٌ للقياس الثَّابت في الحديث المشهور: «الذهب بالذهب والفضة بالفضة والبرّ بالبرّ والشَّعير بالشَّعير والتَّمر بالتَّمر والملح بالملح مثلاً بمثل يداً بيد، فمَن زاد أو استزاد فقد أربى، الآخذ والمعطي فيه سواء»، فترك العمل به على ظاهره؛ لأنَّ روايه لم يكن فقيهاً."]]},{"id":"u79b_16","kind":"text","label":"ومن أمثلته · الفقرة ١٦","segs":[["ctx","٢. لا يشترط فقه الرَّاوي لتقديم خبره على القياس، بل يقبل خبر كلّ عدل ضابط إذا لم يكن مخالفاً للكتاب والسُّنة المشهورة ويُقدَّم على القياس، وهذا عند أبي الحسن الكرخي ومَن تابعه، قال أبو اليسر: وإليه مال أكثر العلماء؛ لأنَّ التَّغيير من الرَّاوي بعد ثبوت عدالته وضبطه موهوم، والظاهر أنَّه يروي كما سمع، ولو غيَّر لغيّر على وجه لا يتغيّر المعنى، هذا هو الظَّاهر من أحوال الصَّحابة رضي الله عنهم والرُّواة العدول؛ لأنَّ الأخبارَ وردت بلسانهم، فعلمهم باللسان يمنع من غفلتهم عن المعنى، وعدم وقوفهم عليه وعدالتهم وتقواهم تدفع تهمة التَّزايد عليه والنُّقصان عنه...."]]},{"id":"u79b_17","kind":"text","label":"ومن أمثلته · الفقرة ١٧","segs":[["ctx","ولم يُنقل القول بتقديم القياس على خبر غير الفقيه عن أصحابنا، بل المنقول عنهم أنَّ خبر الواحد مقدَّمٌ على القياس ولم ينقل التَّفضيل، ألا ترى أنَّهم عملوا بخبر أبي هريرة رضي الله عنه في الصَّائم إذا أكل أو شرب ناسياً، وإن كان مخالفاً للقياس، حتى قال أبو حنيفة: لولا الرِّواية لقلت بالقياس، وثبت عنه أنَّه قال: ما جاءنا عن الله وعن رسوله فعلى الرَّأس والعين، ولم يُنقل عن أحد من السَّلف اشتراط الفقه في الرَّاوي، فثبت أنَّ هذا القول مستحدث، وأجاب عن حديث ..العرية وأشباهها فقال: إنَّما تَرك أصحابنا العمل بها لمخالفتها الكتاب أو السُّنة المشهورة لا لفوات فقه الرَّاوي. قال الحصكفي: على أنَّ الحق تقديمه عندنا على القياس مطلقاً."]]}],"sup":"الرَّابعة: مخالفة الآحاد للحادثة المشهورة «ما يعم به البلوى»"},{"id":"u81","title":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u81_1","kind":"text","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ١","segs":[["ctx","وهذا التَّقسيم لمطلق الخبر الواحد، وهو أعمّ من أن يكون خبر النَّبي ﷺ أو أصحابه رضي الله عنهم أو عامَّة الخلق من أهل السُّوق."]]},{"id":"u81_2","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ٢","segs":[["matn","١. إن كان في حقوق الله"],["ctx","تعالى، فإنَّ خبر الواحد فيه حجة على النَّحو الآتي:"]]},{"id":"u81_3","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ٣","segs":[["matn","أ. إن كان في العبادات يقبل؛"],["ctx","لأنَّ الصَّحابة رضي الله عنهم قَبلوا حديث الآحاد: «إذا التقى الختانان وتوارت الحشفة فقد وجب الغسل» بشرائطه السَّابقة من عائشة رضي الله عنها وحدها."]]},{"id":"u81_4","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ٤","segs":[["matn","وما كان من الدِّيانات: كالإخبار بطهارة الماء ونجاسته، فيثبت بخبر الواحد العدل أن هذا الماء طاهر أو نجس؛ لكن إن أخبر بها الفاسق أو المستور يتحرى"],["ctx","، ففي كثير من الأحوال لا يكون العدل حاضراً عند الماء، فاشتراط العدالة بمعرفة الماء حرج، فلا يكون خبر الفاسق والمستور ساقط الاعتبار، فأوجبنا انضمام التَّحرِّي به، بخلاف أمر الأحاديث، فإنَّ الذين يتلقونها هم العلماء الأتقياء، فلا حرج إذا لم يعتبر قول الفسقة والمستورين في الأحاديث، فلا اعتبار لأحاديثهم أصلاً."]]},{"id":"u81_5","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ٥","segs":[["matn","وأما أخبار الصَّبي والمعتوه والكافر، فلا تُقبل في الدِّيانات"],["ctx",": كالإخبار عن طهارةِ الماء ونجاسته، ولا يجب التَّحرّي، بخلاف أخبار الفاسق، فإنَّ الواجبَ فيه التَّحرِّي."]]},{"id":"u81_6","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ٦","segs":[["matn","ب. إن كان في العقوبات، فلا تثبت الحدود من حديث الآحاد"],["ctx","عند الكرخي؛ لأنَّ في اتصاله إلى رسول الله ﷺ شبهة، والحدود تندرئ بها، وأمّا إثبات الحدود بالبينات عند القاضي، وهي خبر واحد، فيجوز بالنَّصّ على خلاف القياس، وهو قوله تعالى: ﴿فَٱسْتَشْهِدُواْ عَلَيْهِنَّ أَرْبَعَةً مِّنكُمْ﴾ [النساء:١٥] وأمثاله؛ لأنَّ الحدودَ لم تثبت بالبينات، وإنَّما تثبت أسبابُها، والحدودُ في نفسها ثابتةٌ بالقرآن أو الإجماع."]]},{"id":"u81_7","kind":"text","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ٧","segs":[["ctx","وقال الجصاص: تثبت الحدود بخبر الواحد؛ لأنَّه يفيد من العلم ما يصح به العمل في الحدود."]]},{"id":"u81_8","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ٨","segs":[["matn","الثَّاني: إن كان في حقوق العباد،"],["ctx","فله ثلاث صور:"]]},{"id":"u81_9","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ٩","segs":[["matn","أ. إن كان مما فيه إلزامٌ محضٌ:"],["ctx","كخبر إثبات الحقّ على أحد في الدُّيون والأعيان المبيعة والمرتهنة والمغصوبة."]]},{"id":"u81_10","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ١٠","segs":[["matn","فإنَّه يشترط فيه سائر شرائط الأخبار من العقل والعدالة والضَّبط والإسلام مع العدد بأن يكون اثنين، والتَّلفظ بقوله: أشهد، وتكون له الولاية بالحرية"],["ctx","، فحينئذ يقبل الخبر عند القاضي في المعاملات التي فيها إلزام على المُدَّعى عليه."]]},{"id":"u81_11","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ١١","segs":[["matn","ب. إن لم يكن فيه إلزام أصلاً؛"],["ctx","كخبر الوكالة والمضاربة والرِّسالة في الهدايا ونحوها، بأن يقول: وكلك فلان، أو شاركك في هذا، أو هدى إليك هذا الشَّيء هدية، فإنَّه لا إلزام فيه على أحد، بل يختار بين أن يقبل الوكالة والمضاربة والهدية وبين أن لا يقبل."]]},{"id":"u81_12","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ١٢","segs":[["matn","فيثبت الخبر بشرط التَّمييز دون العدالة"],["ctx","وإن كان عبداً أو كافراً أو فاسقاً، فيجوز لمن أخبره بالوكالة والمضاربة أن يتصرّف فيه ويُباشره؛ لأنَّ الإنسان قلما يجد رجلاً مستجمعاً للشرائط يبعثه إلى وكيله أو غلامه بالخبر، فلو شرطت فيه الشُّروط لتعطَّلت المصالح في العالم، ولأنَّ الخبر غير مُلزم في الواقع، فلا تعتبر فيه شرائط الإلزام."]]},{"id":"u81_13","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ١٣","segs":[["matn","ج. إن كان فيه إلزام من وجه دون وجه"],["ctx",": كخبر عزل الوكيل، وحجر المأذون، فإنَّه من حيث إنَّ الموكل والمولى يتصرف في حق نفسه بالعزل والحجر كما يتصرف بالتَّوكيل والإذن فلا إلزام فيه أصلاً، ومن حيث إنَّ التَّصرف يقتصر على الوكيل والعبد بعد العزل والحجر وتلزمه العهدة في ذلك ففيه إلزام ضرر على الوكيل والعبد."]]},{"id":"u81_14","kind":"def","label":"المطلب الأول: المواضع التي يكون خبر الواحد حجّةً فيها · الفقرة ١٤","segs":[["matn","فإنَّه يشترط فيه أحد شطري الشَّهادة من العدد أو العدالة؛"],["ctx","إذ لا بدّ أن يكون المُخبر اثنين أو واحداً عدلاً؛ رعاية لشبه الجانبين؛ إذ لو كان إلزماً محضاً يشترط فيه كلاهما، ولو لم يكن إلزاماً أصلاً ما شرط فيه شيء منهما، فوفرنا حظاً من الجانبين فيه."]]}],"sup":"المبحث الرَّابع حجية خبر الآحاد وأقسامه"},{"id":"u82","title":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u82_1","kind":"def","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١","segs":[["matn","أولاً: قسم يحيط العلم بصدق الخبر:"],["ctx","كخبر الأنبياء ﷺ لعصمتهم، وحكمه: اعتقاد الحقية والائتمار، قال جل جلاله: ﴿وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُواْ﴾ [الحشر:٧]."]]},{"id":"u82_2","kind":"def","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٢","segs":[["matn","ثانياً: قسم يحيط العلم بكذبه:"],["ctx","كدعوى فرعون الرُّبوبية: ﴿فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ﴾ [النازعات:٢٤]، وحكمه: اعتقاد البطلان، والاشتغال برده."]]},{"id":"u82_3","kind":"def","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٣","segs":[["matn","ثالثاً: قسم يحتمل الصِّدق والكذب على السَّواء:"],["ctx","كخبر الفاسق، وحكمه التَّوقف فيه؛ لاستواء الجانبين فيه، قال جل جلاله: ﴿إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍ فَتَبَيَّنُوٓاْ﴾ [الحجرات:٦]."]]},{"id":"u82_4","kind":"def","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٤","segs":[["matn","رابعاً: قسم يرجح أحد احتماليه الصِّدق على الكذب:"],["ctx","كخبر العدل المستجمع لشرائط الرِّواية، وحكمه:"],["matn","العمل به لا العلم والاعتقاد بحقيقته، وهذا القسم له ثلاثة أطراف:"]]},{"id":"u82_5","kind":"def","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٥","segs":[["matn","١. طرف السَّماع،"],["ctx","بأن يسمع الحديث من المُحَدِّث أولاً:"]]},{"id":"u82_6","kind":"def","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٦","segs":[["matn","والعزيمة فيه لها صور:"],["ctx","أ. أن يقرأ على المُحَدِّث من كتاب أو حفظ، وهو يسمعه، ثم تقول له مستفهماً: أهو كما قرأت عليك؟ فهو يقول: نعم."]]},{"id":"u82_7","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٧","segs":[["ctx","ب. أن يقرأ المُحَدِّث عليك من كتاب أو حفظ وأنت تسمعه، قال أبو حنيفة: الوجهان سواء بل الأول أحوط؛ لأنَّ السَّامع إذا قرأ بنفسه كان أشد عناية في ضبط المتن؛ لأنَّه عامل لنفسه، والمُحَدِّث عامل لغيره."]]},{"id":"u82_8","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٨","segs":[["ctx","ج. أن يكتب المُحَدِّث إليك كتاباً على رسم الكتب بأن يكون مختوماً بختم معروف معنوناً، فيكتب قبل التَّسمية من فلان بن فلان إلى فلان بن فلان، ثم يبدأ بالتَّسمية، ثم بالثناء، ويذكر فيه حدثني فلان عن فلان إلى أن يقول: قال النَّبي ﷺ، ويذكر متن الحديث، ثم يقول: إذا بلغك كتابي هذا وفهمته حدث به عني بهذا الإسناد، فهذا الكتاب من الغائب كالخطاب في جواز الرِّواية."]]},{"id":"u82_9","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٩","segs":[["ctx","د. أن يرسل المُحَدِّث رسولاً، ويقول للرَّسول: بلغ عني فلاناً أَنَّه قد حدثني بهذا الحديث فلان بن فلان ـ ويذكر إسناده ـ فإذا بلغك رسالتي هذه فاروه عني بهذا الإسناد، فيكون الرِّسالة والكتاب حجة إذا ثبتا بالبينة أنَّه رسول فلان أو كتاب فلان."]]},{"id":"u82_10","kind":"def","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١٠","segs":[["matn","والرُّخصة فيه لها صور:"],["ctx","أ. الإجازة: بأن يقول المُحَدِّث لغيره: أجزت لك أن تروي عني هذا الكتاب الذي حدّثني فلان عن فلان...الخ."]]},{"id":"u82_11","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١١","segs":[["ctx","ب. المناولة: بأن يعطي الشَّيخ كتاب سماعه بيده إلى المستفيد، ويقول: هذا كتاب سماعي من شيخي فلان أجزت لك أن تروي عني هذا، فهو لا يصح بدون الإجازة، والإجازة تصح بدون المناولة، فالإجازة لا بد منها في كل حال، ويجوز الإجازة لمعدوم كقوله: أجزت لفلان ولمن يولد له ما تناسلوا."]]},{"id":"u82_12","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١٢","segs":[["ctx","والمجاز له لا بدّ أن يكون عالماً بما في الكتاب قبل الإجازة، وإلا لا تصحّ الإجازة، كما لو أجزنا بكتاب المشكاة مثلاً لأحد، فإن كان ذلك الشَّخص عالماً بكتاب المشكاة قبل ذلك بالمطالعة بقوّة نفسه، أو بإعانة الشُّروح، أو نحو ذلك، ولكن لم يكن له سند صحيح يتصل بالمصنف، فحينئذ تصحّ إجازته له، وإن لم يكن كذلك بل يعتمد على أن يطالع بعد الإجازة ويُعلِّم النَّاس لم تكن الإجازة حجة، بل تكون إجازة تبرّك."]]},{"id":"u82_13","kind":"def","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١٣","segs":[["matn","٢. طرف الحفظ،"],["ctx","بأن يحفظ بعد ذلك من أوله إلى آخره:"]]},{"id":"u82_14","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١٤","segs":[["ctx","والعزيمة فيه: وهو أن يحفظ المسموع من وقت السَّماع إلى وقت الأداء، ولم يعتمد على الكتاب."]]},{"id":"u82_15","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١٥","segs":[["ctx","والرُّخصة فيه: وهو أن يعتمد الكتاب فإن نظر فيه وتذكَّر ما كان مسموعاً له صار كأنَّه حفظه من وقت السَّماع إلى وقت الأداء؛ لأنَّ التَّذكر بمنزلة الحفظ، فيكون حجة سواء كان بخطه أو بخط غيره، أما إن لم يتذكَّر من الخط شيئاً فلا تحل له الرِّواية؛ لأنَّ الخط وضع لتذكرة القلب، كالمرآة للعين، فلا عبرة للمرآة إذا لم ير الرَّائي بها وجه، فكذا لا عبرة للكتاب إذا لم يتذكر القلب به علماً؛ لأنَّ الخط يشبه الخط."]]},{"id":"u82_16","kind":"def","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١٦","segs":[["matn","٣. طرفُ الأداء،"],["ctx","بأن يلقيه إلى الآخر لتفرغ ذمته:"]]},{"id":"u82_17","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١٧","segs":[["ctx","والعزيمة فيه: وهو أن يؤدي على الوجه الذي سمع بلفظه ومعناه، فعن ابن مسعود رضي الله عنه، قال ﷺ: «نضر الله امرأً سمع منا شيئاً فبلغه كما سَمِع، فربَّ مبلَّغ أوعى من سامع»."]]},{"id":"u82_18","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١٨","segs":[["ctx","والرُّخصة فيه: وهو أن ينقله بمعناه: أي بلفظ آخر يؤدّي معنى الحديث، وهذا صحيح عند العامَّة، فعن سليمان بن أكيمة الليثي قال: «أتينا رسول الله ﷺ فقلنا له: بآبائنا أنت وأُمهاتنا يا رسول الله، إنا نسمع منك الحديث فلا نقدر أن نؤديه كما سمعناه فقال: إذا لم تُحلُّوا حراماً ولم تُحرِّموا حلالاً، وأَصبتم المعنى فلا بأس»، وهذا الجانب في قَبوله تفصيل:"]]},{"id":"u82_19","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ١٩","segs":[["ctx","أ. إن كان محكماً لا يحتمل إلا معنى واحداً، يجوز نقله بالمعنى لمن له معرفة في وجوه اللغة: كنقل قعد إلى جلس، والاستطاعة إلى القدرة."]]},{"id":"u82_20","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٢٠","segs":[["ctx","ب. إن كان ظاهراً معلوماً يحتمل غير معناه؛ بأن كان عاماً يحتمل الخصوص، أو حقيقةً يحتمل المجاز، فلا يجوز نقله بالمعنى إلا للفقيه المجتهد؛ لأنَّه يقف على ما هو وجيزاً وتحته معان كثيرة، مثاله: حديث: «مَن بدل دينه فاقتلوه»، فإنَّ موجبَه العموم، والمراد محتمله وهو الخصوص؛ إذ الأنثى والصَّغير ليسا بمرادين."]]},{"id":"u82_21","kind":"text","label":"المطلب الثَّاني: أقسام الخبر من حيث الصِّدق والكذب أربعة · الفقرة ٢١","segs":[["ctx","ج. إن كان من جوامع الكلم، بأن كان لفظه وجيزاً وتحته معان كثيرة، أو كان من المشكل أو المشترك أو المُجْمل، فإنَّه لا يجوز نقله بالمعنى للمجتهد وغيره، أما جوامع الكلم؛ فلما رُوي أنَّه ﷺ خُصِّص بجوامع الكلم، فعن أبي هريرة رضي الله عنه قال ﷺ: «فُضِّلت على الأنبياء بست: أُعطيت جوامع الكلم، ونُصرت بالرُّعب، وأُحلَّت ليَّ الغنائم، وجُعلت ليَّ الأرض طهوراً ومسجداً، وأُرسلت إلى الخلق كافَّة، وخُتم بي النَّبيون»، فلا يقدر أحد بعده على ما كان مخصوصاً به، وأما المشكل والمشترك؛ فلأنَّه إنَّما ينقله بتأويل مخصوص لا يكون حجة على غيره، وأمّا في المجمل؛ فلعدم الوقوف على معناه بدون الاستفسار من المُجْمِل."]]}],"sup":"المبحث الرَّابع حجية خبر الآحاد وأقسامه"},{"id":"u83","title":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع","group":"الباب الثَّاني السُّنة النَّبوية الشَّريفة","units":[{"id":"u83_1","kind":"def","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١","segs":[["matn","أولاً: حجية السُّنة الشَّريفة:"],["ctx","فإنَّه يجب العمل بالسُّنة كما يجب العمل بالكتاب؛ للأدلة الواردة في ذلك ومنها:"]]},{"id":"u83_2","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ٢","segs":[["ctx","١. قال تعالى: ﴿وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ إِنْ هُوَ إِلَّا وَحْىٌ يُوحَىٰ﴾ [النجم:٤]، فهذه الآية دلَّت على أنَّ قوله ﷺ فيما هو من جنس التَّشريع وحيٌ من الله تعالى كالقرآن الكريم يجب العمل به كالقرآن."]]},{"id":"u83_3","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ٣","segs":[["ctx","٢. الأمر بطاعته كطاعة الله تعالى بقوله: ﴿أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ﴾ [النساء:٥٩]، وأحياناً يقرن طاعته بطاعته تعالى بقوله: ﴿مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ﴾ [النساء:٨٠]."]]},{"id":"u83_4","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ٤","segs":[["ctx","٣. الأمر بإتباع وأخذ ما آتانا به بقوله تعالى: ﴿وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُواْ﴾ [الحشر:٧]."]]},{"id":"u83_5","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ٥","segs":[["ctx","٤. وجوب تحكيمه ﷺ في شؤون الأُمَّة وما يحصل بينهم مع قَبول حكمه بقوله تعالى: ﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُواْ فِىٓ أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُواْ تَسْلِيمًا﴾ [النساء:٦٥]."]]},{"id":"u83_6","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ٦","segs":[["ctx","٥. وجوب ردِّ المنازعة التي تحصل بين النَّاس إلى رسول الله ﷺ كما تُرد إلى كتاب الله تعالى بقوله: ﴿فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا﴾ [النساء:٥٩]."]]},{"id":"u83_7","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ٧","segs":[["ctx","٦. نفي الخيار عن المسلم إذا أمر رسول الله ﷺ كما لا خيار له إذا أمر الله تعالى بقوله: ﴿وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَٰلًا مُّبِينًا﴾ [الأحزاب:٣٦]."]]},{"id":"u83_8","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ٨","segs":[["ctx","٧. التَّحذير من مخالفة أمره ﷺ بقوله تعالى: ﴿فَلْيَحْذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ﴾ [النور:٦٣]."]]},{"id":"u83_9","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ٩","segs":[["ctx","٨. منحه ﷺ من الله عز وجل سلطة بيان كتابه العزيز بقوله تعالى: ﴿وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ﴾ [النحل:٤٤]."]]},{"id":"u83_10","kind":"def","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١٠","segs":[["matn","ثانياً: منزلة السُّنة في التَّشريع:"],["ctx","اتفقت الأُمَّة على أنَّ السُّنةَ تأتي بالاحتجاج بها بعد كتاب الله فيما إذا لم تجد الحكم فيه، أو جاء مجملاً، أو عاماً، أو مطلقاً، وبيَّنت السُّنةُ تفصيلَه، أو تخصيصَه، أو تقييدَه، أو نسخَه، فإن وجد الحكم في كتاب الله تعالى وجب الوقوف عنده، وان لم يوجد فُتِّش عنه في سنة رسول الله ﷺ، ومما يستدل به على ذلك:"]]},{"id":"u83_11","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١١","segs":[["ctx","١. حديث معاذ بن جبل رضي الله عنه عندما أوفده ﷺ إلى اليمن ليكون قاضياً هناك قال له ﷺ: «بمَ تقضي يا معاذ؟ قال: بكتاب الله، قال: فإن لم تجد؟ قال: بسنَّة رسوله، قال: فإن لم تجد؟ قال: اجتهدُ فيه برأيي، فقال رسول الله ﷺ: الحمدُ لله الذي وفَّق رسولَ رسولِه بما يرضى به رسوله»."]]},{"id":"u83_12","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١٢","segs":[["ctx","٢. رسالة عمر رضي الله عنه إلى أبي موسى الأشعري رضي الله عنه، قال فيه: الفهم الفهم فيما يختلج في صدرك مما لم يبلغك في القرآن والسُّنة فتعرَّف الأمثال والأشباه ثم قس الأمور عند ذلك واعمد إلى أحبّها إلى الله وأشبهها فيما ترى."]]},{"id":"u83_13","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١٣","segs":[["ctx","٣. قال ابن مسعود رضي الله عنه: ...فمَن عرض له منكم قضاء بعد اليوم، فليقض بما في كتاب الله، فإن جاء أمر ليس في كتاب الله، فليقض بما قضى به نبيه ﷺ، فإن جاء أمر ليس في كتاب الله ولا قضى به نبيه ﷺ، فليقض بما قضى به الصالحون...."]]},{"id":"u83_14","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١٤","segs":[["ctx","٤. عن الشَّعبي أنَّ عمر رضي الله عنه كتب إلى شريح: إذا جاءك شيء في كتاب الله فاقض به ولا يغلبنك عليه الرِّجال، وإذا جاءك ما ليس في كتاب الله تعالى فانظر في سنة رسول الله ﷺ فاقض بها....."]]},{"id":"u83_15","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١٥","segs":[["ctx","٥. عن ابن عباس رضي الله عنهم إذا سئل عن شيء هو في كتاب الله قال به، وإذا لم يكن في كتاب الله وقاله رسول ﷺ قال به...."]]},{"id":"u83_16","kind":"text","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١٦","segs":[["ctx","وفي كل هذا دلالة واضحة على أنَّ السُّنة تأتي في الاحتجاج بعد كتاب الله تعالى."]]},{"id":"u83_17","kind":"def","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١٧","segs":[["matn","ثالثاً: أفعالُ النَّبيِّ ﷺ:"],["matn","إنّ مما يتصل بالسُّنن أَفعالُ النَّبيّ ﷺ"],["ctx","الاختيارية الصَّالحة للاقتداء،"],["matn","وهي ثلاثة: مباحٌ، ومستحبّ، وواجبٌ."]]},{"id":"u83_18","kind":"def","label":"المطلب الثَّالث: حجيّة السُّنة ومنزلتها في التَّشريع · الفقرة ١٨","segs":[["matn","وقد اختلف العلماءُ فيها، والصَّحيحُ أَنَّ بكلِّ ما عُلِم وقوعُه"],["ctx","من الأفعال"],["matn","على وجهٍ"],["ctx","يُقْتَدى به في إيقاعِهِ على تلك الصِّفةِ من الوجوبِ والنَّدبِ والإباحة، حتى يقوم به دليل الخصوص، فما كان واجباً عليه ﷺ يكون واجباً علينا، وما كان مندوباً عليه ﷺ يكون مندوباً علينا،"],["matn","وما لا نعلم"],["ctx","على أَي صفةٍ فعله ﷺ فيُعتقد فيه الإباحة؛ لتيقّنها، فيكون لنا اتّباعه إلى أن يقوم دليل المنع."]]}],"sup":"المبحث الرَّابع حجية خبر الآحاد وأقسامه"},{"id":"u84","title":"الباب الثَّالث الإجماع","group":"الباب الثَّالث الإجماع","units":[{"id":"u84_1","kind":"text","label":"الباب الثَّالث الإجماع · الفقرة ١","segs":[["ctx","إنَّ الإجماعَ هو المصدرُ الثَّالثُ من مصادر الاستنباط للفقه وواحد من الأدلة الأربعة المعتبرة في الشَّرع، وكلُّ مسألة شرعية انعقد الإجماع عليها يقال لها: مسألة إجماعية، أو مسألة مجمع عليها، أو قضية إجماعية، وتفصيل ما يتعلق بالإجماع في النّقاط الآتية:"]]},{"id":"u84_2","kind":"def","label":"الباب الثَّالث الإجماع · الفقرة ٢","segs":[["matn","أولاً: تعريفه:"],["matn","الإجماع لغةً: العزم،"],["ctx","قال الفراء: «الإجماع: الإعداد والعزيمة على الأمر»، قال تعالى: ﴿فَأَجْمِعُواْ كَيْدَكُمْ ثُمَّ ٱئْتُواْ صَفًّا﴾ [طه:٦٤]، وأجمع أمره: أي جعله جميعاً بعدما كان متفرّقاً."]]},{"id":"u84_3","kind":"def","label":"الباب الثَّالث الإجماع · الفقرة ٣","segs":[["matn","واصطلاحاً: هو اتفاق المجتهدين من أُمَّة سيدنا محمد ﷺ في عصر من العصور على أمر شرعيّ."]]},{"id":"u84_4","kind":"text","label":"الباب الثَّالث الإجماع · الفقرة ٤","segs":[["ctx","والمراد بالاتفاق: الاشتراك في الاعتقاد أو القول أو الفعل."]]},{"id":"u84_5","kind":"text","label":"الباب الثَّالث الإجماع · الفقرة ٥","segs":[["ctx","وقيَّد بالمجتهدين؛ إذ لا عبرة باتفاق العوام، وعرَّف بلام الاستغراق احترازاً عن اتفاق بعض مجتهدي عصر."]]},{"id":"u84_6","kind":"text","label":"الباب الثَّالث الإجماع · الفقرة ٦","segs":[["ctx","واحترز بقوله: من أُمَّة محمد ﷺ عن اتفاق مجتهدي الشَّرائع السَّالفة."]]},{"id":"u84_7","kind":"text","label":"الباب الثَّالث الإجماع · الفقرة ٧","segs":[["ctx","وقوله: في عصر؛ معناه زمان ما، قل أو كثر. وفائدته الاحتراز عما يرد على من ترك هذا القيد من لزوم انعقاد الإجماع إلى آخر الزَّمان؛ إذ لا يتحقَّق اتفاق جميع المجتهدين حينئذٍ."]]}]},{"id":"u84a","title":"الأول: عزيمة، ولها وجهان","group":"الباب الثَّالث الإجماع","units":[{"id":"u84a_1","kind":"def","label":"الأول: عزيمة، ولها وجهان · الفقرة ١","segs":[["matn","الأول: عزيمة، ولها وجهان:"],["matn","١. التَّكلُّم بما يوجب اتفاق الكلّ على الحكم،"],["ctx","بأن يقولوا: أجمعنا على هذا إن كان ذلك الشَّيء من باب القول. ويُسمّى إجماعاً قولياً؛ إذا اجتمعوا على قول واحد، بأن قال جميع أهل الاجتهاد جواب المسألة على وجه واحد من الجواز أو الفساد أو الحِل أو الحُرمة."]]},{"id":"u84a_2","kind":"def","label":"الأول: عزيمة، ولها وجهان · الفقرة ٢","segs":[["matn","٢. الشُّروع في الفعل إن كان ذلك الشَّيء من باب الفعل،"],["ctx","كما إذا شَرع أهلُ الاجتهاد جميعاً في المضاربة أو المزارعة، أو الشَّركة، كان إجماعاً منهم على شرعيتها."]]},{"id":"u84a_3","kind":"text","label":"الأول: عزيمة، ولها وجهان · الفقرة ٣","segs":[["ctx","ويُسمّى إجماعاً فعلياً إذا اجتمعوا على فعل واحد، بأن فعلوا أجمعهم فعلاً واحداً."]]},{"id":"u84a_4","kind":"text","label":"الأول: عزيمة، ولها وجهان · الفقرة ٤","segs":[["ctx","وهذان القسمان مسلَّمٌ بحجيّتهما عند جميع الفقهاء المجتهدين."]]},{"id":"u84a_5","kind":"def","label":"الأول: عزيمة، ولها وجهان · الفقرة ٥","segs":[["matn","الثاني: رخصة، ولها وجهان:"],["matn","١. التَّكلم بما يوجب اتفاق بعضهم على الحكم، وسكوت الباقين منهم بعد بلوغ الخبر إليهم"],["ctx","، وعدم ردهم عليهم بعد مرور مدة التَّأمل، والأكثر لم يُقَدِّر مدة التَّأمل بشيء، بل لا بدّ من مرور أوقات يعلم عادة أنَّه لو كان هناك مخالف لأظهر الخلاف."]]},{"id":"u84a_6","kind":"def","label":"الأول: عزيمة، ولها وجهان · الفقرة ٦","segs":[["matn","٢. الشُّروع في الفعل من بعضهم إن كان ذلك الشَّيء من باب الفعل، وسكوت الباقين"],["ctx","ـ كما سبق ـ."]]},{"id":"u84a_7","kind":"text","label":"الأول: عزيمة، ولها وجهان · الفقرة ٧","segs":[["ctx","ويُسمَّى هذا النَّوع إجماعاً سكوتياً؛ إذ رضي جميع أهل الاجتهاد على حكم من أمور الدِّين، ومعرفة الرِّضا لها طريقان:"]]},{"id":"u84a_8","kind":"text","label":"الأول: عزيمة، ولها وجهان · الفقرة ٨","segs":[["ctx","أ. الإخبار عن الرِّضا بذلك طوعاً؛ لأنَّه أمر باطن لا يعرف إلا بسبب ظاهر دالّ عليه، وهو الخبر عنه طوعاً."]]},{"id":"u84a_9","kind":"text","label":"الأول: عزيمة، ولها وجهان · الفقرة ٩","segs":[["ctx","ب. انتشار قول واشتهاره فيهم، ولم يوجد من أهل الاجتهاد من يرد ذلك وينكر عليهم في حال التّقية؛ لأنَّ إظهار الرِّضا في حال التَّقي وترك الإنكار والرَّد أمر معتاد، بل أمر مشروع فلا يدل على الرِّضا، فلهذا شرطنا مع السُّكوت وترك الإنكار زوال التّقية."]]},{"id":"u84a_10","kind":"text","label":"الأول: عزيمة، ولها وجهان · الفقرة ١٠","segs":[["ctx","وهذا الإجماع السُّكوتي من الأدلّةِ القطعيّةِ عند أكثر الحنفيّة، وإنَّما لا يكفر جاحدُه؛ لما فيه من توهم الشُّبهة."]]},{"id":"u84a_11","kind":"def","label":"الأول: عزيمة، ولها وجهان · الفقرة ١١","segs":[["matn","ويُستدلُّ للإجماع السُّكوتي:"],["ctx","أنَّه كان رخصة؛ لأنَّه جعل إجماعاً ضرورة؛ لما فيه من نفي نسبة مجتهدي الأُمَّة إلى الفسق والتَّقصير في أمر الدِّين، فلو لم يثبت الإجماع بهذا يلزم تفسيق بعض الصَّحابة رضي الله عنهم، وهو منتف؛ لأنَّ السَّاكت عن الحقّ شيطان أخرس في موضع الحاجة، ولأنَّه لو شُرِطَ لانعقاد الإجماع التَّنصيص من الكلّ؛ لأدَّى ذلك إلى تعذّر انعقاده؛ لأنَّ الوقوف على قول كلِّ واحد منهم في حكم حادثة حرجٌ بيِّن، فينبغي أن يجعل اشتهار الفتوى والسُّكوت من الباقين كافياً في انعقاد الإجماع، ولأنَّ المعتادَ في كلِّ عصر أن يتولى الكبار الفتوى ويُسلِّم سائرهم، وهذا التَّسليم بعد عرض الفتيا، وفي ذلك وجوب الفتوى وحرمة السُّكوت لو كان مخالفاً."]]}],"sup":"الباب الثَّالث الإجماع"},{"id":"u84b","title":"ثالثاً: حجيّة الإجماع","group":"الباب الثَّالث الإجماع","units":[{"id":"u84b_1","kind":"def","label":"ثالثاً: حجيّة الإجماع · الفقرة ١","segs":[["matn","ثالثاً: حجيّة الإجماع:"],["ctx","إنَّ القرآنَ والسُّنةَ يُثبتان أنَّ ما ينتهي إليه اجتهاد أُمَّة الإسلام في القضايا الحادثة في ضوء القرآن والسُّنة مع الاتفاق عليها قولاً أو فعلاً يجب على المسلمين اتباعه ويَحرم عليهم مخالفته؛ إذ أنَّ الله تعالى منح هذه الأُمَّة بمجموعها العصمة من خطأ أو زلل في أُمور الدِّين."]]},{"id":"u84b_2","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ٢","segs":[["ctx","فمجموع الأُمَّة معصومٌ عن التَّواطؤ والاتفاق على ضلالة، أو على عمل مخالف للقرآن والسُّنة، أو عمل غير مرضي عنه من الله ورسوله ﷺ، فكما أنَّ أحكام الكتاب والسُّنة محفوظة من الخطأ والبطلان، ولا سبيل إلى تخطئتها، فكذلك ما انتهى إليه الإجماع من أحكام قطعيّة لا يحلّ لأحدٍ أن يُنكرها، بل يلزم العمل بها؛ لما يلي:"]]},{"id":"u84b_3","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ٣","segs":[["ctx","١. قال تعالى: ﴿وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ وَسَآءَتْ مَصِيرًا﴾ [النساء:١١٥]، فيها إنذار من الله جل جلاله لمن يخالف المجمع عليه لجماعة المؤمنين بنفس العذاب الذي سيلقاه من يخالف النَّبي ﷺ."]]},{"id":"u84b_4","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ٤","segs":[["ctx","٢. قال تعالى: ﴿كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ﴾ [آل عمران:١١٠]، ففيها أنَّ الله تعالى خاطب الأُمَّة على العموم في كلِّ أعصرها، وكلّ الأحكام التي أجمعت عليها الأُمَّة سواء كانت من المأمورات أو المناهي، فعلاً أو تركاً واجتناباً، لا بُدَّ وأن تكون موافقة لمرضاة الله تعالى، ولو افترضنا خلاف ذلك؛ بأنَّ بعضَ ما تأمر به منكر، وما تَنهى عنه معروف؛ لأدَّى ذلك إلى أن تكون آمرةً بالمنكر وناهيةً عن المعروف، وهذا مضادٌّ لإخبار الله تعالى في هذه الآية بكونها آمرة بالمعروف وناهية عن المنكر، ومخرجة لصلاح النَّاس ونفعهم."]]},{"id":"u84b_5","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ٥","segs":[["ctx","٣. عن عليّ رضي الله عنه قلت: يا رسول الله، إن نزل بنا أمر ليس فيه بيان أمر ولا نهي فما تأمرنا؟ قال: «شاوروا فيه الفقهاء والعابدين ولا تمضوا فيه رأي خاصة»."]]},{"id":"u84b_6","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ٦","segs":[["ctx","٤. عن جابر وغيره رضي الله عنهم، قال ﷺ: «لا تزال طائفة من أمتي يقاتلون على الحق ظاهرين إلى يوم القيامة»، وحمل البخاري الطائفة على أهل العلم."]]},{"id":"u84b_7","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ٧","segs":[["ctx","٥. عن ابن عمر رضي الله عنهم، قال ﷺ: «إنَّ الله لا يجمع أُمتي على ضلالة، ويد الله مع الجماعة، ومن شذَّ شذَّ إلى النَّار»، وهذا الحديث شاهد صريح على حجية الإجماع، وقد رواه ثمانية من أصحاب النَّبي ﷺ."]]},{"id":"u84b_8","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ٨","segs":[["ctx","٦. عن أنس رضي الله عنه، قال ﷺ: «إنَّ أمتي لا تجتمع على ضلالة، فإذا رأيتم اختلافاً فعليكم بالسَّواد الأعظم»، وبالتَّأمّل في معنى هذا الحديث يتبين لنا أنَّ السَّواد الأعظم من هذه الأُمَّة لا يجتمع على ضلالة، وإلا للزم الطَّعن على أمر الشَّارع ﷺ بوجوب لزوم السَّواد الأعظم حيث يجتمع على ضلالة."]]},{"id":"u84b_9","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ٩","segs":[["ctx","٧. عن معاذ بن جبل رضي الله عنه، قال ﷺ: «إنَّ الشَّيطان ذئب الإنسان كذئب الغنم يأخذ الشَّاة القاصية والناحية، فإياكم والشّعاب وعليكم بالجماعة والعامَّة والمسجد»."]]},{"id":"u84b_10","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ١٠","segs":[["ctx","٨. عن ابن مسعود رضي الله عنه: «ما رآه المسلمون حسناً فهو عند الله حسن، وما رأوه سيئاً فهو عند الله سيء»."]]},{"id":"u84b_11","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ١١","segs":[["ctx","٩. عن الشَّعبي أنَّ عمر رضي الله عنه كتب إلى شريح: إذا جاءك شيء في كتاب الله فاقض بها، فإن كان أمر ليس في كتاب الله تعالى فانظر في سنة رسول الله ﷺ فاقض بها، فإن كان أمر ليس في كتاب الله تعالى ولم يكن في سنة رسول الله ﷺ فانظر ما أجمع عليه النَّاس فخذ به، فإن كان مما ليس في كتاب الله تعالى ولا في سنّة رسول الله ﷺ ولم يتكلم فيه قبلك أحد فاختر أي الأمرين شئت: إن شئت أن تجتهد برأيك وتقدم فتقدم، وإن شئت أن تتأخر فتأخر، ألا وإنَّ التَّأخير خير لك."]]},{"id":"u84b_12","kind":"text","label":"ثالثاً: حجيّة الإجماع · الفقرة ١٢","segs":[["ctx","١٠. عن ابن عمر وابن مسعود رضي الله عنهم قال: «اتقوا الله واصبروا حتى يستريح برٌ، أو يستراح من فاجر، وعليكم بالجماعة، فإنَّ الله لا يجمع أُمَّة محمّد على ضلالة»."]]}],"sup":"الباب الثَّالث الإجماع"},{"id":"u84c","title":"رابعاً: فائدة الإجماع وسنده","group":"الباب الثَّالث الإجماع","units":[{"id":"u84c_1","kind":"def","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ١","segs":[["matn","رابعاً: فائدة الإجماع وسنده:"],["ctx","لا يقصد من كون الإجماع حجّةً أنَّ المجمعين على مسألةٍ من المسائل يُشَرِّعونها من عند أنفسهم، ويُحلون ما شاءوا مع قطع النَّظر عن الكتاب والسُّنة؛ لأنَّ المُشَرِّعَ هو الله تعالى، ولا حقّ لغيره في التَّشريع، ودورُ الفقهاء هو بيانُ وتوضيحُ مراد الله تعالى."]]},{"id":"u84c_2","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ٢","segs":[["ctx","بل ويجب أن يعلم أنَّ كلَّ مسألة من المسائل الفقهيّة لا بُدّ وأن تكون مستندة إلى نصٍّ من الكتابِ أو السُّنةِ قبل أن ينعقدَ الإجماع."]]},{"id":"u84c_3","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ٣","segs":[["ctx","وبناءً على هذا إن انعقد الإجماع يتوقَّفُ على أصل من الكتاب والسُّنة، فكلُّ مسألة مجمع عليها فهي مستفادة من الكتاب أو السُّنة أو من قياس متأصل فيهما، وهذا الأصل من الكتاب أو السُّنة ما يقال له: سند الإجماع."]]},{"id":"u84c_4","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ٤","segs":[["ctx","وهنا ينشأ السُّؤال عما إذا كانت المسألة المجمع عليها مستفادة من الكتاب أو السُّنة، فما فائدة الإجماع؟ وكيف يعتبر الإجماع من الأدلة الشَّرعية؟"]]},{"id":"u84c_5","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ٥","segs":[["ctx","والجواب أنَّ للإجماع فائدتين:"]]},{"id":"u84c_6","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ٦","segs":[["ctx","١. إنَّ الحكم الثَّابت من الكتاب أو السُّنة أو القياس إن كان ظنياً، فإنَّه يصبح بالإجماع قطعياً، حيث لا يبقى لثبوته أدنى تردد، ويسد باب الاختلاف أمام أي فقيه مجتهد، أما إن كان الحكم قطعياً من قبل، فإنَّ الإجماع يزيد في قطعيته."]]},{"id":"u84c_7","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ٧","segs":[["ctx","٢. إنَّ الدَّليل الشَّرعي الذي ينبني عليه الإجماع لا يلزم لمن بعدهم من النَّاس أن يتكلّفوا عناء البحث عنه، بل يكفيهم التَّأكد من صحة الحكم في المسألة معرفتهم إجماع مجتهدي عصر واحد على هذا الحكم حجّة؛ لأنَّ إجماعهم قد انعقد على أصل شرعي، وبالتالي فلا يلزم لمن بعدهم البحث عن ذلك الأصل الشَّرعي... ومن أمثلته:"]]},{"id":"u84c_8","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ٨","segs":[["ctx","ـ إجماع سنده القرآن: إنَّ نكاح أم الأب وأم الأم وبنت البنت حرام بالإجماع استناداً إلى قوله تعالى: ﴿حُرِّمَتْ عَلَيْكُمْ أُمَّهَٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ﴾ [النساء:٢٣]، فهذه الآية سند الإجماع، وحرمة النِّكاح وإن كانت ثابتة بهذه الآية؛ لشمول لفظ: الأمهات أمهات الأب وأمهات الأم، ولفظ البنات بنات البنات، إلا أنَّه كان ظنياً لا قطعية فيه، لوجود احتمال إرادة المعنيين الحقيقيين لهذين اللفظين المذكورين دون العموم، فلما انعقد الإجماع على الحكم بالتَّحريم، صار الأخذ بالعموم قطعيّاً، ولم يترك مجالاً للاختلاف."]]},{"id":"u84c_9","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ٩","segs":[["ctx","ـ إجماعٌ سنده السُّنة: أنَّه لا يجوز بيع شيء اشتراه قبل قبضه بالإجماع، وسند الإجماع مأخوذ من قول النَّبي ﷺ: «من ابتاع طعاماً فلا يبعه حتى يستوفيه»."]]},{"id":"u84c_10","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ١٠","segs":[["ctx","والحكم المذكور في الحديث بالرغم من وضوحه الكامل، إلا أنَّه كان ظنيّاً لا يفيد العلم اليقيني؛ لعدم ثبوت الحديث بالتَّواتر، ولكن بعد انعقاد الإجماع عليه صار قطعياً مجزوماً بقطعيّته."]]},{"id":"u84c_11","kind":"text","label":"رابعاً: فائدة الإجماع وسنده · الفقرة ١١","segs":[["ctx","ـ إجماعٌ سنده القياس: بيع الأرز حيث ضموه إلى الأموال الرِّبوية، فأوجبوا فيه المساواة، والتَّعاطي باليد، ويَحرم الفضل والنَّساء فيه كما في سائر الرِّبويَّات إذا بيع بجنسه ولو كان مختلف النَّوع قياساً على حديث: «الذَّهب بالذَّهب والفضة بالفضة والتَّمر بالتَّمر والبرّ بالبرّ والشَّعير بالشَّعير والملح بالملح مثلاً بمثل يداً بيد، والفضل ربا»، فكان الأرزُ مسكوتاً عنه، ثم لما أجمع عليه قياساً أصبح واجباً إجراء حكم الأصناف السِّتة عليه."]]}],"sup":"الباب الثَّالث الإجماع"},{"id":"u84d","title":"خامساً: أهل الإجماع وشروطه","group":"الباب الثَّالث الإجماع","units":[{"id":"u84d_1","kind":"def","label":"خامساً: أهل الإجماع وشروطه · الفقرة ١","segs":[["matn","خامساً: أهل الإجماع وشروطه:"],["ctx","يشترط في الإجماع ومن ينعقد بهم الإجماع ما يلي:"]]},{"id":"u84d_2","kind":"text","label":"خامساً: أهل الإجماع وشروطه · الفقرة ٢","segs":[["ctx","١. أن يكون مجتهداً صالحاً؛ إذ لا حظ للمقلِّد في الإجماع، إنَّما له تقليد مجتهد من مجتهدي الأُمَّة المحمديّة، وهذا الشَّرطُ خاصٌّ بالمسائل التي لا يستغنى فيها عن الاجتهاد، وأما المسائل التي يستغنى فيها عن الاجتهاد: كنقل القرآن، وأعداد الرّكعات، ومقادير الزَّكاة، فإنَّ إجماع العوام فيه كإجماع المجتهدين."]]},{"id":"u84d_3","kind":"text","label":"خامساً: أهل الإجماع وشروطه · الفقرة ٣","segs":[["ctx","٢. أن لا يكون فيه هوى؛ بأن يكون صاحب بدعة، فإنَّ من كان رأيه مذموم عند الله تعالى ورسوله ﷺ لا يعتد برأيه، إنَّما الاعتبار للرأي المحمود."]]},{"id":"u84d_4","kind":"text","label":"خامساً: أهل الإجماع وشروطه · الفقرة ٤","segs":[["ctx","٣. أن لا يكون فاسقاً؛ لأنَّه يورثُ التُّهمة ويُسقط العدالة، والأهلية إنَّما تثبت بالعدالة."]]},{"id":"u84d_5","kind":"text","label":"خامساً: أهل الإجماع وشروطه · الفقرة ٥","segs":[["ctx","٤. أن يكون الإجماع من كلِّ المجتهدين، فيمنع الإجماع خلاف الواحد الصَّالح للاجتهاد كما يمنع خلاف الأكثر؛ لأنَّ كلَّ مُجْتَهَد فيه يحتمل الصَّواب والخطأ، فيحتمل أن يكون الصَّواب مع المخالف."]]},{"id":"u84d_6","kind":"def","label":"خامساً: أهل الإجماع وشروطه · الفقرة ٦","segs":[["matn","ويخرج من أهلية وشروط الإجماع:"],["ctx","١. أن يكون في الصَّحابة رضي الله عنهم."]]},{"id":"u84d_7","kind":"text","label":"خامساً: أهل الإجماع وشروطه · الفقرة ٧","segs":[["ctx","٢. أن يكون في العترة؛ وعترة النَّبيّ ﷺ: عليّ وفاطمة والحسن والحسين وأولادهم."]]},{"id":"u84d_8","kind":"text","label":"خامساً: أهل الإجماع وشروطه · الفقرة ٨","segs":[["ctx","٣. أن يكون في أهل المدينة."]]},{"id":"u84d_9","kind":"text","label":"خامساً: أهل الإجماع وشروطه · الفقرة ٩","segs":[["ctx","٤. أن ينقرض العصر بموت جميع المجتهدين بعد اتفاقهم فيه على حكم ليس بشرط لانعقاده؛ لأنَّ الأدلّة الدَّالّة على حجيّة الإجماع لم تَفصّل بين الانقراض وعدمه، وشرط الانقراض زيادة على النَّص، والزِّيادةُ نسخ فلا يجوز، وثمرة الخلاف تظهر فيما إذا رجع بعضهم بعد الانعقاد."]]},{"id":"u84d_10","kind":"text","label":"خامساً: أهل الإجماع وشروطه · الفقرة ١٠","segs":[["ctx","٥. أن لا يسبقه اختلاف سابق في المسألة، فإذا اختلف أهل عصر في مسألة وماتوا على ذلك الخلاف، فلا يَمنع هذا الاختلاف انعقاد الإجماع وارتفاع هذا الخلاف."]]},{"id":"u84d_11","kind":"text","label":"خامساً: أهل الإجماع وشروطه · الفقرة ١١","segs":[["ctx","وهذا بخلاف ما إذا اجتمعت الأُمَّة على أقوال في مسألة فإنَّ ما عدا هذه الأقوال باطل، ولا يجوز لمن بعده إحداث قول آخر."]]}],"sup":"الباب الثَّالث الإجماع"},{"id":"u84e","title":"خامساً: مراتب الإجماع","group":"الباب الثَّالث الإجماع","units":[{"id":"u84e_1","kind":"def","label":"خامساً: مراتب الإجماع · الفقرة ١","segs":[["matn","خامساً: مراتب الإجماع:"],["matn","المرتبة الأقوى:"],["ctx","أقواها مرتبة وأعلاها درجة الإجماع القولي والفعلي للصَّحابة، فالأُمَّة متفقة على ذلك، واعتبار إجماعهم هذا حجّة مقطوعاً به، مثل الآيات والخبر المتواتر حتى يكفر جاحده."]]},{"id":"u84e_2","kind":"def","label":"خامساً: مراتب الإجماع · الفقرة ٢","segs":[["matn","والمرتبة الوسطى:"],["ctx","الإجماع السُّكوتي أوسطها درجة بالنِّسبة إلى صحابة رسول الله ﷺ، لكن حجيّته على سبيل القطع مختلف فيها بين فقهاء الأُمَّة ـ كما سبق ـ."]]},{"id":"u84e_3","kind":"def","label":"خامساً: مراتب الإجماع · الفقرة ٣","segs":[["matn","والمرتبة الدُّنيا:"],["ctx","تنحصر في إجماع مَن بعد الصَّحابة رضي الله عنهم من فقهاء كلّ عصر، فهو حجّة عند جمهور من فقهاء الأُمَّة، ولكن لا على سبيل القطع؛ لأنَّ اختلاف من لا يَعتبر الإجماع إلا إجماع الصَّحابة رضي الله عنهم يخرجه عن كونه قطعياً، ولذلك يُنزَّل منزلة السُّنّة المشهورة، كما أنَّه لا يكفر جاحده."]]},{"id":"u84e_4","kind":"def","label":"خامساً: مراتب الإجماع · الفقرة ٤","segs":[["matn","سادساً: نقل الإجماع:"],["ctx","١. إن نُقل إلينا إجماع الصَّحابة رضي الله عنهم بإجماع كلِّ عصر على نقله بالتَّواتر، فإنَّه يكون حجّةً قطعيّة موجبةً للعلم والعمل قطعاً حتى يكفر جاحده: كإجماعهم على كون القرآن كتاب الله تعالى وفرضيّة الصَّلاة وغيرها."]]},{"id":"u84e_5","kind":"text","label":"خامساً: مراتب الإجماع · الفقرة ٥","segs":[["ctx","٢. إن نُقل إلينا بالإفراد بإسناده موثوق به بأنَّ الصَّحابة رضي الله عنهم أجمعوا على كذا، كما تُنقل سُنّة الآحاد، فإنَّه لا يبقى قطعياً، بل يكون ظنيّاً كسائر الأخبار التي تتمتع بالحجيّة لثبوت الأحكام الشَّرعية؛ إذ توجب العمل دون العلم حتى لا يكفر جاحده: كقول عبيدة السلماني: اجتمعت الصَّحابة رضي الله عنهم على محافظة الأربع قبل الظُّهر، وتحريم نكاح الأخت في عدَّة الأخت، وتوكيد المهر بالخلوة الصَّحيحة."]]},{"id":"u84e_6","kind":"text","label":"خامساً: مراتب الإجماع · الفقرة ٦","segs":[["ctx","٣. إن نُقل إلينا بسند ضعيف غير موثوق به، فلا يعتبر حجّة، ويأخذ حكم سائر الأحاديث الضَّعيفة، فلا يثبت به حكم شرعي."]]},{"id":"u84e_7","kind":"text","label":"خامساً: مراتب الإجماع · الفقرة ٧","segs":[["ctx","والخلاصة: أنَّ مكانة الإجماع كدليل شرعي تتوقف على درجة سند وصولها إلينا تماماً كمكانة السُّنة النبوية، فما وصل منهما إلينا بالتَّواتر كان قطعياً، وما وصل إلينا بسند موثوق به دون التَّواتر كان ظنياً، وما وصل إلينا بسند ضعيف غير موثوق به فلا وزن له عندنا من حيث كونه دليلاً شرعياً يُحتج به."]]}],"sup":"الباب الثَّالث الإجماع"},{"id":"u85","title":"الباب الرابع القياس","group":"الباب الرابع القياس","units":[{"id":"u85_1","kind":"text","label":"الباب الرابع القياس · الفقرة ١","segs":[["ctx","اقتضت حكمة الله تعالى أن تكون نصوص الشَّرع محدودة وحوادث الدَّهر ممدودة وغير معدودة، فما ورد من نصوصٍ في الكتاب والسُّنة هي محدودة بالنِّسبة لما يستجد من حوادث وأمور هي بأمسِّ الحاجة إلى إعطاء حكم شرعي لها، وعندما نرجع إلى الكتاب والسُّنة لا نجد لها دليلاً نعتمده فيها، ولم يقم عليها إجماع، ولكننا نجد أنَّ لها مثيلاً له حكم في الآية أو الحديث، فيصل المجتهد باجتهاده إلى أنَّ هذا الأمر المستجد يشترك مع ذلك المثيل بعلَّة، فيُعطى حكم هذا المثيل لتلك الحادثة المستجدة، وبذلك يجد المجتهد وسيلة من الوسائل التي تعينه على إعطاء الحكم لكثير من المسائل المستجدة بما يسمى بـ«القياس»."]]},{"id":"u85_2","kind":"text","label":"الباب الرابع القياس · الفقرة ٢","segs":[["ctx","فإنَّ القياس أصلٌ عظيم الشَّأن جليل القدر له دور كبير في استنباط الأحكام الشَّرعية؛ ولهذا كان الأصل الرَّابع بعد الكتاب والسُّنة والإجماع، وتأخيره عنها لا يقلِّل من أهميته أبداً؛ إذ هو عكاز الفقيه الذي يتوكأ عليه إذا لم يجد نصاً أو إجماعاً في المسألة المستجدة، وتفصيل أحكامه في المطالب الآتية:"]]}]},{"id":"u86","title":"المطلب الأول: تعريفه وحجيته","group":"الباب الرابع القياس","units":[{"id":"u86_1","kind":"def","label":"المطلب الأول: تعريفه وحجيته · الفقرة ١","segs":[["matn","لغةً: تقدير الشَّيء على مثاله"],["ctx","، فيقال: قس الشيء بغيره، وعلى غيره، فانقـاس: أي قدّره على مثاله، ومن هنا سمي المقدار مقياساً."]]},{"id":"u86_2","kind":"def","label":"المطلب الأول: تعريفه وحجيته · الفقرة ٢","segs":[["matn","واصطلاحاً:"],["ctx","عُرِّف بتعاريف عديدة تُبيِّن حدوده، أقتصر منها على اثنين، وهما:"]]},{"id":"u86_3","kind":"def","label":"المطلب الأول: تعريفه وحجيته · الفقرة ٣","segs":[["matn","١.تقديرُ الفرع بالأصل في الحكم والعلَّة."]]},{"id":"u86_4","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ٤","segs":[["ctx","ومعنى تقدير: أي إلحاق الفرع بالأصل، وجعله مماثلاً له."]]},{"id":"u86_5","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ٥","segs":[["ctx","والحكم: هو الثَّابتُ بالأدلّة الثَّلاثة، وهي القرآنُ والسُّنّة والإجماع."]]},{"id":"u86_6","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ٦","segs":[["ctx","والعلَّة: هي العلَّةُ الشَّرعيّةُ الجامعةُ المشتركةُ التي تَعلَّق بها الحكم التـي لا تـدرك بمجرد اللغة."]]},{"id":"u86_7","kind":"def","label":"المطلب الأول: تعريفه وحجيته · الفقرة ٧","segs":[["matn","٢.إبانة مثل حكم أحد المذكورين مثل علَّته في الآخر."]]},{"id":"u86_8","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ٨","segs":[["ctx","واختار لفظ الإبانة دون الإثبات؛ لأنَّ القياس مُظهر لا مُثبت؛ لأنَّ المُثبت هو الله تعالى، أمَّا القياس ففعل القائس، وهو تبيين وإعلام أنَّ حكم الله تعالى كذا وعلَّته كذا، وهما موجودان في الموضع المختلف فيه."]]},{"id":"u86_9","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ٩","segs":[["ctx","وبهذا يعلم أنَّ للقياس أربعة أركان، وهي: الفرع والأصل والحكم والعلَّـة، كـما سيأتي، ويكون القياس باشتراك العلَّة بين الأصل والفرع، فنعدي حكم الأصل المُصَرَّح به في القرآن والسُّنة في الفرع الحادث، فيكون فعل المجتهد هو إظهار حكم الله تعـالى في الفرع."]]},{"id":"u86_10","kind":"def","label":"المطلب الأول: تعريفه وحجيته · الفقرة ١٠","segs":[["matn","ومن حجيّة القياس:"],["ctx","معلومٌ أنَّ القياس هو المصدرُ الرَّابع من مصادر التّشريع الفقهي، وأنَّ العمل بـه محلّ اتفاق في المذاهب الفقهيّة المعتبرة؛ لأنَّ به حياة الشَّـريعة وحيويتهـا، وقـدرتها عـلى مواجهة المستجدات الحياتية، فبه يعرف حكم عامـة المسـائل الفقهيـة؛ لأنَّ المنصـوص منها من القرآن والسُّنة بالنِّسبة لغير المنصوص من المسائل الفقهية قليلة جداً كما سبق ـ ولذلك وردت أدلّة عديدة في إثبات حجيّة القياس، ومنها:"]]},{"id":"u86_11","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ١١","segs":[["ctx","١.قال تعالى: ﴿فَٱعۡتَبِرُواْ يَٰٓأُوْلِي ٱلۡأَبۡصَٰرِ﴾ [الحشر:٢]، والاعتبار: هو النَّظرُ في الحكم الثَّابت في الشَّيء أنّه لأيّ معنى ثبت، وردّ نظيره إليه في الحكم، وقياس غيره عليه، فكأنَّه قال: قيسوا الشَّيءَ على نظيره، وهو شاملٌ لكلِّ قياس: كقياس الفروع الشَّرعيّة على الأُصول، فيكون إثبات حجيّة القياس ثابتاً بالنَّص."]]},{"id":"u86_12","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ١٢","segs":[["ctx","٢.قال تعـالى: ﴿فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ﴾ [النسـاء:٥٩]: أي ردوه إلى حكم الله تعالى ورسوله ﷺ، ولا شكّ أنَّ التنازع إنَّما يقع في الأمر الخفي الذي يحتاج فيه إلى الرَّأي دون الحكم الظَّاهر الجلي؛ ولهذا قال الله تعالى: ﴿وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡ﴾ [النساء:٨٣]، فكـأنَّ الأمـر بـالرَّدِّ إلى حكـم الله تعالى ورسوله ﷺ بواسطة الرَّأي والاجتهاد يكون أمراً بالمقايسة."]]},{"id":"u86_13","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ١٣","segs":[["ctx","٣.قال رسول الله ﷺ لمعاذ بن جبل رضي الله عنه: «بِمَ تقضي يا معاذ؟ قال: بكتاب الله، قال: فإن لم تجد؟ قال: بسنّة رسوله، قال: فإن لم تجد؟ قـال: أجتهـد فيـه برأيـي، فقـال رسول الله ﷺ: الحمد لله الذي وفق رسول رسوله بما يرضى به رسوله»، ولـو لم يكـن القياس حجة موجبة للعمل بعد الكتاب والسنة لأنكر عليه رسول الله ﷺ، ولمـا مدحـه به، ولما حمد الله تعالى بتوفيقه لمعاذ رضي الله عنه بالعمل بالرأي والاجتهاد."]]},{"id":"u86_14","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ١٤","segs":[["ctx","٤.عن عمر رضي الله عنه قال: «هششت يوماً فقبلت وأنا صائم فأتيـت النبـي ﷺ فقلـت: صنعت اليوم أمراً عظيماً، فقبلت وأنا صائم، فقال رسول الله ﷺ: أرأيت لو تمضمضـت بماء وأنت صائم؟ قلت: لا بأس بذلك، فقال رسول الله ﷺ: فَفيمَ»، إذ قاس النبـي ﷺ القُبلة من غير إنزال وإيلاج في نفي الفساد على المضمضة من غير ابتلاع."]]},{"id":"u86_15","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ١٥","segs":[["ctx","٥.سئل أبو بكر رضي الله عنه عن الكلالة فقال: إني سأقول فيها برأيـي فـإن كـان صـواباً فمن الله تعالى، وإن كان خطأ فمني ومن الشَّيطان، أراه مـا خـلا الوالـد والولـد، فلـما استُخلف عمر رضي الله عنه، قال: إني لأستحيي الله تعالى أن أردّ شيئاً قاله أبو بكر."]]},{"id":"u86_16","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ١٦","segs":[["ctx","٦.رسالة عمر رضي الله عنه إلى أبي موسى الأشعري رضي الله عنه قال فيها: «الفهم الفهم فيما يختلج في صدرك مما لم يبلغك في القرآن والسنة فتعرف الأمثال والأشباه ثم قس الأمور عند ذلك واعمد إلى أحبّها إلى الله وأشبهها فيما ترى»."]]},{"id":"u86_17","kind":"text","label":"المطلب الأول: تعريفه وحجيته · الفقرة ١٧","segs":[["ctx","٧.قال ابن مسعود رضي الله عنه: مَن عرض له منكم قضاء بعد اليوم، فليقض بما في كتاب الله، فإن جاء أمر ليس في كتاب الله، فليقض بما قضى به نبيه ﷺ، فإن جاء أمر ليس في كتاب الله ولا قضى به نبيه ﷺ، فليقض بما قضى به الصَّـالحون، فـإن جـاء أمـر لـيس في كتاب الله ولا قضى به نبيه ﷺ ولا قضى بـه الصَّـالحون، فليجتهـد رأيـه ولا يقـول: إنّي أخاف وإنّي أخاف، فإنَّ الحلالَ بيِّن والحرامَ بيِّن، وبين ذلك أمـور مشـتبهات، فـدع مـا يَريبك إلى ما لا يَريبك."]]}]},{"id":"u87","title":"المطلب الثَّاني: شروط القياس","group":"الباب الرابع القياس","units":[{"id":"u87_1","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ١","segs":[["ctx","يذكر الأصوليون من الحنفية شروطاً للقياس المعتبر في استخراج الأحكام، وهي خمس شروط، وتفصيلها كالآتي:"]]},{"id":"u87_2","kind":"def","label":"المطلب الثَّاني: شروط القياس · الفقرة ٢","segs":[["matn","١.أن لا يكون الأصل مخصوصاً:"],["ctx","أي بسبب آخر يدلُّ على اختصاص المَقيس عليه بحكمه، وهو ما يُعبِّر عنه الفقهاء بحكاية حال: أي حكم خاصّ بهذه الحادثة لا يُقاس عليه غيرُه، وهو كثير، ومن أمثلة ذلك:"]]},{"id":"u87_3","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ٣","segs":[["ctx","ـ ما روي: «أنَّ النبي ﷺ ابتاع فرساً من أعرابي فاستتبعه النبي ﷺ ليقضيه ثمن فرسه فأسرع رسول الله ﷺ المشي وأبطأ الأعرابي، فطفق رجال يعترضون الأعرابي فيساومونه بالفرس، ولا يشعرون أنَّ النبي ﷺ ابتاعه، فنادى الأعرابي رسول الله ﷺ، فقال: إن كنت مبتاعاً هذا الفرس، ولا بعته، فقام النبي ﷺ حين سمع نداء الأعرابي فقال: أوليس قد ابتعته منك؟ فقال الأعرابي: لا والله ما بعتكه، فقال النبي ﷺ: بلى قد ابتعته منك، فطفق الأعرابي يقول: هلم شهيداً! فقال خزيمة بن ثابت رضي الله عنه: أنا أشهد أنَّك قد بايعته، فأقبل النبي ﷺ على خزيمة، فقال: بمَ تشهد؟ فقال: بتصديقك يا رسول الله، فجعل النبي ﷺ شهادة خزيمة بشهادة رجلين»."]]},{"id":"u87_4","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ٤","segs":[["ctx","فجعل رسول الله ﷺ شهادة خزيمة رضي الله عنه كشـهادة رجلـين كرامـةً وتفضـيلاً عـلى غيره، مع أنَّ النُّصوص أوجبت اشتراط العدد من رجلـين أو رجـل وامـرأتين في حـق العامة، فلا يقاس عليه غيره؛ لأنَّ الحكم مقصوراً عليه بـالنص؛ فينبغـي أن لا يقـاس عليه غيره ممن هو أعلى حالاً منه كالخلفاء الرَّاشدين؛ إذ تبطل حينئذ كرامـة اختصاصـه بهذا الحكم."]]},{"id":"u87_5","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ٥","segs":[["ctx","ـ أنَّه حلَّ زواج النبي ﷺ بتسع نسوة إكراماً له، فلم يصح تعليله والقياس عليه."]]},{"id":"u87_6","kind":"def","label":"المطلب الثَّاني: شروط القياس · الفقرة ٦","segs":[["matn","٢.أن لا يكون حكم الأصل معدولاً به عن القياس"],["ctx","؛ بأن لا يكون الأصلُ مخالفـاً للقياس؛ إذ لو كان هو بنفسه مخالفاً للقياس، فكيف يُقاس عليه غيره؟ لأنَّ حاجتنـا إلى إثبات الحكم بالقياس، فإذا جاء مخالفاً للقياس لم يصح إثباته به، وهذا هو الاستحسـان بالنَّصّ، ومن أمثلته:"]]},{"id":"u87_7","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ٧","segs":[["ctx","ـ بقاءُ الصَّوم مع الأكل والشُّرب ناسياً، فإنَّه مخـالف للقيـاس؛ إذ يقتضيـ فسـاد الصَّوم به؛ لدخول الطَّعام أو الشَّراب إلى الجوف المعتبر من المنفذ المعتبر حقيقـة، إلا أنَّ الشَّارع الكريم اعتبره صائماً حكماً استحساناً؛ لما ورد عن رسـول الله ﷺ أنَّـه قـال: «إذا نسي فأكل وشرب فليتمَّ صومه فإنَّما أطعمه الله وسقاه»؛ لذلـك لا يقاس عليه الخاطئ والمكره."]]},{"id":"u87_8","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ٨","segs":[["ctx","ـ جواز السَّلم رغم أنَّ المبيع فيه معدوماً؛ لأنَّ القياس أن يكون المبيع محلاً مملوكاً مقدوراً، قال ﷺ: «لا تبع ما ليس عندك»، وجوَّز رسـول الله ﷺ السَّـلم، فقـال: «مـن أسلف في شيء ففي كيل معلوم إلى أجل معلوم»، وما ثبت بـهذا الـنَّص بعـدم ملـك المحل إلا مؤجلاً يكون خارجاً عن القياس، وثابتاً استحساناً بالنَّصِّ."]]},{"id":"u87_9","kind":"def","label":"المطلب الثَّاني: شروط القياس · الفقرة ٩","segs":[["matn","٣.أن يتعدّى الحكم الشَّرعي الثَّابت بالنَّصِّ بعينه إلى فرع هو نظيره ولا نصّ فيه،"],["ctx","ويتضمن هذا الشَّرط أربعة شروط، ولكنَّها كلها راجعةٌ إلى تحقيق التَّعدّي، فإنَّه لا يتم إلا بالجميع، وهي:"]]},{"id":"u87_10","kind":"def","label":"المطلب الثَّاني: شروط القياس · الفقرة ١٠","segs":[["matn","أ.أن يكون الحكم شرعياً لا لغوياً"],["ctx","، فلا يجوز القياس في اللغـة؛ بـأن يوضـع لفـظ لمسمّى مخصوص باعتبار معنى يوجد في غيره، فيطلق ذلك اللفظ على ذلك الغير، ومن أمثلته:"]]},{"id":"u87_11","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ١١","segs":[["ctx","ـ عدم صحّة إثبات حكم الزِّنا للواطة؛ بإثبات اسم الزِّنا للواطة؛ لأنَّه ليس بحكـم شرعي؛ لأنَّ الزِّنا وإن كان سفح ماء محرم، وهذا المعنى موجـود في اللواطـة، بـل هـي فوق الزِّنا في الحرمة والشَّهوة؛ لأنَّ الإيلاجَ في الدُّبر لا يحل قطعـاً بخـلاف الإيـلاج في القُبل فإنَّه يحل بالنِّكاح، فيُجري على اللواطة اسم الزِّنا وحكمه، وهـذا لا يجـوز؛ لأنـه قياس في اللغة."]]},{"id":"u87_12","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ١٢","segs":[["ctx","ـ عدم إعطاء النَّبيذ حكم الخمر؛ بأن يعطى اسم الخمر لكلّ ما يخامر العقل، فيُقال: بعدم جواز النَّبيذ المثلث المسكر ـ وهو المطبوخ حتى ذهب ثلثاه وبقي ثلثه ـ وأنَّ حكمه حكم الخمر؛ لأنَّ النَّبيذَ المسكر في معنى الخمر، فإثبات اسم الخمر لذلك المائع المسـكر يكون إثباتاً بتعدّية الاسم لغة، وهذا قياس فاسد؛ لأنَّ الاسم متى وضع لعـين خاصّـة بهيئةٍ مخصوصةٍ وصفاتٍ معلومةٍ فلا يُقاس عليه ما سـواه في المعنـى المقصـود منـه مـع المخالفة في الصُّورة، بل المعتبر فيه وضع اللغة، فلو عُدِّي الاسم مـن الوضـع إلى غـيره باعتبار المساواة في المعنى المقصـود الظَّـاهر يُسـمَّى مجـازاً لا حقيقـة، فالمجـاز اسـتعارة العرب الاسم لاسم، وطريق الاستعارة فيما بين أهل اللغة غير طريق التَّعدية في أحكام الشَّرع، فلا يكون هذا النَّوع من القياس الذي يدرك به حكم الشرع."]]},{"id":"u87_13","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ١٣","segs":[["ctx","ـ عدم إعطاء حكم السَّارق للنباش ـ من يحفر القبر ويأخذ الكفن ـ بأن نثبت اسم السَّارق للنبّاش باعتبار أنَّ كلّ واحدٍ منهما آخذ مال الغير على سبيل الخفية؛ لما أنَّ القطع لا يجب بالإجماع بدون اسم السَّرقة، وقـد عُـدِم الاسـم في النَّبـاش؛ لأنَّ السَّرـقةَ اسـمٌ للأخذ على وجهٍ يُسارق عين صاحبه، وهـذا لا يُتصـوُّر في أخـذِ الكفـن؛ لأنَّ صـاحبَه ميت، فكيف يُسارق عينه، فلا يُقاس النَّباش على السَّارق."]]},{"id":"u87_14","kind":"def","label":"المطلب الثَّاني: شروط القياس · الفقرة ١٤","segs":[["matn","ب.أن يُعدّى الحكمُ بعينه بلا تغيير، فإن تغيّر الحكم بعد التَّعدية لم يصح القياس."]]},{"id":"u87_15","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ١٥","segs":[["ctx","ومثاله: عدم صحّة ظهار الذِّمي قياساً على ظهار المسلم؛ لعدم تعدية الحكم بعينـه؛ لكون هذا التَّعليل تغييراً للحكم من التَّأقيت للتَّأبيـد؛ لأنَّ الحرمـةَ في الظِّهـار توجـب الكفَّارة، والذِّمي غير قادر على الكفَّارة، فظهار المسلم ينتهي بالكفارة، وظهـار الـذمي يكون مؤبداً؛ إذ ليس هو أهلاً للكفَّـارة التـي هـي دائـرة بـين العبـادة والعقوبـة، فـإنَّ المقصود بالكفَّارة التَّطهير والتَّكفير، فلا تتأدى الكفَّارة إلا بنية العبـادة، والكـافر لـيس بأهل للعبادة."]]},{"id":"u87_16","kind":"def","label":"المطلب الثَّاني: شروط القياس · الفقرة ١٦","segs":[["matn","ج.أن يكون الفرعُ نظيراً للأصل لا أدون منه"],["ctx",": أي أقل منه، فلا يصح قياسه عليه."]]},{"id":"u87_17","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ١٧","segs":[["ctx","ومثاله: عدم تعدي حكم النَّـاسي في الفطـر إلى المكـره والخـاطئ لكـونهما ليسـا بعامدين في نفس الفعل كالنَّاسي؛ لأنَّ عذرَهما أقل من عذر النَّاسي، فـإنَّ النِّسـيان يقـع بلا اختيار، وهو منسوب إلى الله تعالى، وفعل الخاطئ والمكره من الإنسان، فإنَّ الخاطئ يَذكر الصَّوم، ولكنَّه يُقَصِّر في الاحتياط في المضمضة حتى دخل الماء في حلقه، والمكـره أكرهه الإنسان وألجأه إليه، فلم يكن عذرهما كعذر النَّـاسي فيفسـد صـومهما، وتفريـع المكره والمخطئ هنا لا يعارض تفريعهما فيما سبق على كون الأصل مخالفاً للقيـاس؛ لأنَّ أكثر المسائل تتفرّع على أصول مختلفة."]]},{"id":"u87_18","kind":"def","label":"المطلب الثَّاني: شروط القياس · الفقرة ١٨","segs":[["matn","د.أن لا يوجد في الفرع نصٌ"],["ctx","، فإن وجد نصّ في الفرع لم يصح قياسه على غيره."]]},{"id":"u87_19","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ١٩","segs":[["ctx","ومثاله: عدم صحة اشتراط الإيمان في رقبةِ كفَّـارة القتـل: ﴿فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ﴾ [النساء:٩٢] في كفَّارة اليمين والظهار؛ لوجـود الـنَّصِّ المطلـق فيهما عن قيد الإيـمان، قـال تعـالى في كفَّـارة اليمـين: ﴿فَكَفَّٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖ﴾ [المائـدة:٨٩]، وقـال جل جلاله في كفَّـارة الظِّهار: ﴿فَتَحۡرِيرُ رَقَبَةٖ مِّن قَبۡلِ أَن يَتَمَآسَّا﴾ [المجادلة:٣]؛ لأنَّـه لا يحتـاج إلى القيـاس مـع وجود النَّصِّ في الفرع."]]},{"id":"u87_20","kind":"def","label":"المطلب الثَّاني: شروط القياس · الفقرة ٢٠","segs":[["matn","٤.أن يبقى الحكم في الأصل بعد التَّعليل على ما كان قبله"],["ctx","، والمراد بالتَّغيير تغيّر المعنى المفهوم من النَّص لغة دون التَّغيير الحاصل من الخصوص إلى العموم، فإنَّ هذا التَّغيير من ضرورات القياس؛ إذ لا فائدة للقياس إلاّ تعميم حكم النَّصِّ."]]},{"id":"u87_21","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ٢١","segs":[["ctx","ومثاله: عدم جواز اشتراط التَّمليك في الإطعام في الكفَّارات قياساً على الكسوة؛ لأنَّه تغيير لحكم النَّصِّ؛ لأنَّ الإطعام اسم لفعل يُسمّى لازمه طعماً، وهو الأكل، ويتحقّق الأكل بالتَّمليك والإباحة للطعام، وتخصيصه بالتَّمليك دون الإباحة تغييراً لحكم الأصل: ﴿إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ﴾ [المائدة:٨٩]؛ لأنَّها عامَّة تشتمل التَّمليك والإباحة، فلم يصح اشتراط التَّمليك قياساً على الكسوة."]]},{"id":"u87_22","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ٢٢","segs":[["ctx","ولا يقال: إنَّكم خصصتم القليل، وهو بيع الحفنة بالحفنتين من الرِّبا كما في قوله ﷺ: «الطَّعام بالطَّعام مثلاً بمثل» مع عمومه للقليل والكثير؛ لأنَّ المرادَ من التَّساوي التَّساوي في الكيل شرعاً بالإجماع، والحفنة لم تدخل في المكيال الشَّرعي، وهو نصف صاع، فلم تكن معتبرة؛ لأنَّ التَّفاضل إنَّما يكون عند وجود الفضل على أَحدِ المتساويين، والمجازفةُ عبارةٌ عن عدم العلم بالمساواة كيلاً، والكلُّ لا يتأتى إلاّ في الكثير، فلم يكن فيه تغيير المنصوص عليه."]]},{"id":"u87_23","kind":"def","label":"المطلب الثَّاني: شروط القياس · الفقرة ٢٣","segs":[["matn","٥.أن لا يكون التَّعليل متضمناً إبطال شيءٍ مـن ألفـاظ المنصـوص"],["ctx","؛ لأنَّ الـنَّصَّ مقدمٌ على القياس بلفظه ومعناه، فكما لا يُعْتَبَرُ القياس في معارضة النَّصّ بإبطال حكمه لا يعتبر في معارضته بإبطال لفظ النّصّ."]]},{"id":"u87_24","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ٢٤","segs":[["ctx","ومثاله: عدم جواز قياس السِّباع سوى الخمس المؤذيـات عـلى الخمـس بطريـق التَّعليل في إباحة قتلها للمُحرم وفي الحرم؛ لأنَّ نصّ الحديث: «خمس فواسـق يقـتلن في الحرم: الفأرة، والعقرب، والحِدأة، والغراب، والكلب العقور»."]]},{"id":"u87_25","kind":"text","label":"المطلب الثَّاني: شروط القياس · الفقرة ٢٥","segs":[["ctx","فإذا تعدَّى الحكم إلى محلّ آخر يكون أكثر من خمس فكان في هذا التَّعليـل إبطـال لفظ من ألفاظ النَّصّ، بخلاف حكم الرِّبا فـإنَّ النبـي ﷺ لم يقـل في الرِّبـا سـتّة أشـياء: «الذهب بالذهب رباً إلا هاء وهاء، والبر بالبر رباً إلا هاء وهاء، والتمر بـالتمر ربـاً إلا هاء وهاء، والشَّعير بالشَّعير رباً إلا هاء وهاء»، ولكن ذكر حكـم الرِّبـا في أشـياء فـلا يكون في تعليل ذلك النَّص إبطالُ شيء من ألفاظ النَّصِّ."]]}]},{"id":"u88","title":"المطلب الثالث: العلَّة","group":"الباب الرابع القياس","units":[{"id":"u88_1","kind":"text","label":"المطلب الثالث: العلَّة · الفقرة ١","segs":[["ctx","إنَّ أهمَّ موضوعات الأصول هو القياس، وأهمّ شيءٍ في القياس هو العلَّة، فهـي في الحقيقةِ سِرُّ الشَّريعة العظيم الذي تتسابق أفهام العظام لإدراكها، فهي محطّ الأنظار، ومرمى الأفئدة، ومنتهى العقول، وهي أحد أركان القياس الأربعة، وهي:"]]},{"id":"u88_2","kind":"def","label":"المطلب الثالث: العلَّة · الفقرة ٢","segs":[["matn","١.الأصل المقيس عليه"],["ctx",": وهو ما يبتنى عليه غـيره كـالبُرّ الـوارد في حـديث الرِّبـا المشهور."]]},{"id":"u88_3","kind":"def","label":"المطلب الثالث: العلَّة · الفقرة ٣","segs":[["matn","٢.الفرع المقيس"],["ctx",": وهو ما يبتني على غيره كالذَّرة، فإننا إذا قسنا الذَّرة على الـبُرّ في حرمة الرِّبا، فالأصل هو البُرّ، والفرع هو الذَّرة؛ لابتنائها عليه في الحكم."]]},{"id":"u88_4","kind":"def","label":"المطلب الثالث: العلَّة · الفقرة ٤","segs":[["matn","٣.حكم الأصل"],["ctx",": وهو ما أفاده الـنَّصّ كتابـاً كـان أو سُـنَّة أو إجماعـاً، كوجـوب التَّساوي والتَّقابض في الرِّبَويَّات، وأمـا حكـم الفـرع فهـو ثمـرة القيـاس ونتيجتـه لا ركنه."]]},{"id":"u88_5","kind":"def","label":"المطلب الثالث: العلَّة · الفقرة ٥","segs":[["matn","٤.العلَّة"],["ctx",": وهي الوصفُ الجامعُ بين الأصل والفرع: كالجنس والقـدر(الـوزن أو الكيل) في الرِّبَويَّات."]]},{"id":"u88_6","kind":"text","label":"المطلب الثالث: العلَّة · الفقرة ٦","segs":[["ctx","وبالتَّالي كلُّ ما وجد فيه علَّة الرِّبا ـ وهي الجنسُ والقـدر ـ مـن الفـروع كـالأرز بالأرز والعدس وبالعدس والحديد بالحديد والنُّحاس بالنُّحاس أُلحق بحكم الأصـل، وهو جوب التَّساوي والتَّقابض فيها، قياساً له على الأصل من الحنطة والذَّهب وغيره."]]}]},{"id":"u88a","title":"أوّلاً: تعريف العلَّة وصورها","group":"الباب الرابع القياس","units":[{"id":"u88a_1","kind":"def","label":"أوّلاً: تعريف العلَّة وصورها · الفقرة ١","segs":[["matn","أوّلاً: تعريف العلَّة وصورها:"],["ctx","عُرِّفت بعدة تعاريف تتفاوت بحسب النَّظرة إليها، ومنها:"]]},{"id":"u88a_2","kind":"def","label":"أوّلاً: تعريف العلَّة وصورها · الفقرة ٢","segs":[["matn","ـ ما جعلت عَلَماً على حكم النَّصّ مما اشتمل عليه النَّصّ، وجعل الفرع نظيراً له في حكمه بوجودها فيه."]]},{"id":"u88a_3","kind":"text","label":"أوّلاً: تعريف العلَّة وصورها · الفقرة ٣","segs":[["ctx","فالعلَّة هي المعنى الجامع، وجعلت ركناً للقياس؛ لأنَّ مـدارَ القيـاس عليهـا فـلا يقوم القياس إلا بها، وسميت عَلَـماً؛ لأنَّ علـل الشَّرـع: أمـارات ومُعرِّفـات للحكـم، وعلامة عليه، والموجب الحقيقي هو الله تعالى."]]},{"id":"u88a_4","kind":"text","label":"أوّلاً: تعريف العلَّة وصورها · الفقرة ٤","segs":[["ctx","ومعنى: ما اشتمل عليه النَّصّ: أي حال كون ذلك العلم مما اشتمل عليه الـنَّصّ إمّا بصيغته كاشتمال نصّ الرِّبا على الكيل والجنس، أو بغير صيغته كاشتمال نصّ النَّهـي عن بيع العبد الآبق كما في حديث: «لا تبع ما ليس عندك» على العجـز عـن التسـليم، فعجز البائع عن التَّسليم علّة للنَّهي عن بيع الآبق، ولا ذكر لهذا العجز صريحاً في نـصّ ذلك النّهي إلا أنَّه مستنبط منه، فإنَّ البيع مذكور فيـه، ولا بـدّ لـه مـن بـائع، والعجـز صفته، فإذا لم يقدر على التَّسليم، فكيف تتحقق المبادلة."]]},{"id":"u88a_5","kind":"def","label":"أوّلاً: تعريف العلَّة وصورها · الفقرة ٥","segs":[["matn","ـ الوصفُ الصَّالحُ المؤثِّرُ في ثبوت الحكم في الأصل متى وُجد مثلُه في الفرع يثبت مثل ذلك الحكم فيه قياساً عليه."]]},{"id":"u88a_6","kind":"text","label":"أوّلاً: تعريف العلَّة وصورها · الفقرة ٦","segs":[["ctx","وسيأتي معنا مفصَّلاً معنى الصَّالح والتأثير، فإنَّ مدارَ العلَّة على التَّأثير، فهي في نظر المجتهد كانت السَّببَ في حكـم الأصـل، فلـمّا وجـدت في الفـرع اسـتحقّ نفـس الحكم."]]},{"id":"u88a_7","kind":"text","label":"أوّلاً: تعريف العلَّة وصورها · الفقرة ٧","segs":[["ctx","والقياس لما كان ردّ الفرع إلى الأصل لإثبات حكم الأصل فيه، ولا يُمكن إثبات حكم الأصل في الفرع بالنصّ؛ لأنَّ النَّصَّ خاصٌّ لا يتناول الفرع، فلا بُـدّ أن يكـون في الأصل وصف يجب به الحكم شرعاً، حتى يثبت مثله بمثل ذلك الوصف؛ إذ لو لم يكن هكذا لا يمكن إثبات الحكم في الفرع؛ لأنّ الحكمَ لا بُدّ له من دليل، ولـيس فيـه نـصٌّ ولا إجماع، ولو كان فيه نصٌّ أو إجماعٌ يكون إثبات الحكم نصّاً لا قياساً."]]}],"sup":"المطلب الثالث: العلَّة"},{"id":"u88b","title":"والوصف الذي هو ركن العلَّة له صور","group":"الباب الرابع القياس","units":[{"id":"u88b_1","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ١","segs":[["matn","والوصف الذي هو ركن العلَّة له صور:"],["matn","١.أن يكون لازماً"],["ctx",": وهو ما لا ينفك عن الأصل: كالثَّمنية علَّة لوجوب الزَّكاة في الذَّهب والفضة فإنَّها لا تنفك عنها؛ لأنَّهما خلقا في الأصل على معنى الثَّمنية، وهي مشتركة بين مضروب الذَّهب والفضّة وتبرهما وحليهما، فتكون في حُليّ النَّسيئة الزَّكاة لعلَّة الثَّمنية."]]},{"id":"u88b_2","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ٢","segs":[["matn","٢.أن يكون عارضاً"],["ctx",": كقوله ﷺ للمستحاضة في بيان علَّة انتقاض الطَّهارة: «إنَّما ذلك عرق»: أي دم عرق انفجر، فالانفجار صفة عارضة غير لازمة؛ لأنَّ الدَّم موجود في العروق بدون صفة الانفجار، فلا يلزم أن يكون كُلُّ دم عرق منفجراً، فأينما وُجِد انفجار الدم سواء كان للمستحاضة أو لغيرها من غير السَّبيلين يجب به الوضوء."]]},{"id":"u88b_3","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ٣","segs":[["matn","٣.أن يكون اسماً"],["ctx",": كحرمةِ الخمر ثبت باسم الخمر: هو علتُّها، لا وصف الإسكار حتى لا يتعدّى إلى النَّبيذ المثلث، وحتى يثبت في قليل الخمر؛ لوجود الاسم وإن لم يُسكر."]]},{"id":"u88b_4","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ٤","segs":[["matn","٤.أن يكون جلياً"],["ctx",": وهو ما يفهمه كُلُّ أحد بحيث لا يحتاج إلى النَّظر الكثير: كالطَّواف لسؤر الهرة، كما في قوله ﷺ: «إنَّها ليست بنجس، إنَّما هي من الطَّوافين عليكم والطَّوافات»."]]},{"id":"u88b_5","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ٥","segs":[["matn","٥.أن يكون خفيّاً"],["ctx",": وهو ما يفهمه بعض دون بعض ، وهو لا ينال إلا بالنَّظر والتَّأمل، كما في علَّة الرِّبا عند الحنفية: القدر والجنس، وعند الشَّافعية: الطُّعم في المطعومات، والثَّمنية في الأثمان: أي الذَّهب والفضة، وعند المالكية: الاقتيات والادخار في قوله ﷺ: «الذَّهب بالذَّهب، والفضة بالفضة، والبُرّ بالبُرّ، والشَّعيرُ بالشَّعير، والتَّمرُ بالتَّمر، والملحُ بالملح مثلاً بمثل، سواء بسواء، يداً بيد، فإذا اختلفت هذه الأصناف فبيعوا كيف شئتم إذا كان يداً بيد»."]]},{"id":"u88b_6","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ٦","segs":[["matn","٦.أن يكون حكماً شرعياً"],["ctx",": أي جامعاً بين الأصل والفرع: كالتَّعليل بالدَّينية الثَّابتة في الذِّمّة في جواز أداء الدَّين عن الميت، كما ورد عن ابن عبَّاس رضي الله عنهم، قال: «جاء رجل إلى النَّبيّ ﷺ، فقال: يا رسول الله، إنَّ أُمِّي ماتت وعليها صوم شهر أفأقضيه عنها؟ فقال: لو كان على أمِّك دين أكنت قاضيه عنها؟ قال: نعم، قال: فدين الله أحقّ أن يقضى»، فقاس النَّبي ﷺ الصِّيام على دين العباد، والمعنى الجامع بينهما هو الدَّين، وهو عبارة عن حقٍّ ثابت في الذِّمة، واجب الأداء، والوجوب حكم شرعيّ."]]},{"id":"u88b_7","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ٧","segs":[["matn","٧.أن يكون فرداً"],["ctx",": فالوصفُ الفرد كالعلَّة بالقدر وحده أو الجنس وحده لحرمة ربا النَّسيئة."]]},{"id":"u88b_8","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ٨","segs":[["matn","٨.أن يكون عدداً"],["ctx",": فالوصف العدد كالقدر مع الجنس علَّة لحرمة التَّفاضل."]]},{"id":"u88b_9","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ٩","segs":[["matn","٩.أن يكون منصوصاً"],["ctx",": أي الوصف مذكوراً في النَّصّ كما في طواف الهرة مثلاً."]]},{"id":"u88b_10","kind":"def","label":"والوصف الذي هو ركن العلَّة له صور · الفقرة ١٠","segs":[["matn","١٠.أن يكون غير منصوص"],["ctx",": ولكنَّه ثابتٌ بالنَّصِّ كالأمثلة السَّابقة من اشتمال النَّهي عن بيع الآبق على العجز عن التَّسليم."]]}],"sup":"المطلب الثالث: العلَّة"},{"id":"u88c","title":"ثانياً: مسالك العلَّة","group":"الباب الرابع القياس","units":[{"id":"u88c_1","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ١","segs":[["matn","ثانياً: مسالك العلَّة:"],["ctx","إنَّ مسالك العلَّة: هي الطُّرق الدَّالة على كون الوصف المعين علَّة للحكم."]]},{"id":"u88c_2","kind":"text","label":"ثانياً: مسالك العلَّة · الفقرة ٢","segs":[["ctx","وهناك مسالك صحيحة، ومسالك يتوهّم صحّتها."]]},{"id":"u88c_3","kind":"text","label":"ثانياً: مسالك العلَّة · الفقرة ٣","segs":[["ctx","والمسالك الصَّحيحة عند الحنفية ثلاثة: النَّص والإجماع والمناسبة، وما عداها من المسالك كالسَّبر والتَّقسيم وتنقيح المناط والدَّوران والشّبه مما يتوهم صحَّتها."]]},{"id":"u88c_4","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ٤","segs":[["matn","الأول: الإجماع:"],["ctx","وهو اتفاق المجتهدين في عصر من الأعصار على كون وصف معيّن علَّة للحكـم المعيّن، مثاله: الصِّغر في ولايةِ مال الصَّغير، فإنَّه علّةٌ لها بالإجماع، ثمّ يُقاس عليـه ولايـةُ النِّكاح."]]},{"id":"u88c_5","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ٥","segs":[["matn","الثَّاني: النَّصُّ:"],["ctx","بأن تكون العِلِّية ثابتة بالنَّص،"],["matn","وهو قسمان:"]]},{"id":"u88c_6","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ٦","segs":[["matn","أولهما: الصَّريح"],["ctx",": وهو ما دلَّ بوضعه على العِلَّة،"],["matn","وله مراتب:"]]},{"id":"u88c_7","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ٧","segs":[["matn","المرتبة الأولى: التَّعليل بلفظ"],["ctx","؛ وهي أقواها ما صرَّح فيه بالعِلِّيّة بأن يـذكر لفظـاً لا يستعمل في غير العلة مثل أن يقول: لعلّة كذا، أو لأجل كذا، أو كي يكـون كـذا، أو إذا يكون كذا، كما في قوله تعالى: ﴿كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡ﴾ [الحشر:٧]، يقال: صـار الفيء دولة بينهم يتداولونه بأن يكون مرة لهذا، ومرة لذلك، وقوله ﷺ: «إنَّما نهيتكم من أجل الدَّافَّة التي دفَّت عليكم فكلوا، وتصدقوا، وادخروا»، فعلَّة النَّهي هنـا صريحـة، وهي إطعام القافلة."]]},{"id":"u88c_8","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ٨","segs":[["matn","المرتبة الثَّانية: التَّعليل بحرف"],["ctx","؛ وهي ما ورد فيه حـرفٌ ظـاهرٌ في التَّعليـل، مثـل: لكذا، أو بكذا، أو إن كان كذا، وهذه المرتبة دون ما قبلها، فإن هذه الحروف وإن كانت ظاهرة في التَّعليل لكن «اللام» تحتمل العاقبة، و«الباء» تحتمل المصاحبة، و«إن» تحتمـل مجرد الشَّرط والاستصحاب، مثل: قوله تعالى: ﴿لِدُلُوكِ ٱلشَّمۡسِ﴾ [الإسراء:٧٨]، وقوله تعالى: ﴿فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡ﴾ [آل عمران:١٥٩]، وقوله تعـالى: ﴿فَبِظُلۡمٖ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرٗا﴾ [النساء:١٦٠]، وقولـه تعـالى: ﴿وَلَا تُكۡرِهُواْ فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنٗا﴾ [النـور:٣٣]، وغيرهـا مـن ألفـاظ التعليل، فاللام والباء يحتملن التعليل كما يحتملن معنى آخر في هذه الآيات."]]},{"id":"u88c_9","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ٩","segs":[["matn","المرتبة الثَّالثة: ذكر الفاء من الشَّارع"],["ctx","؛ لأنَّ الفاء يسـتفاد منهـا التَّعليـل وإن كانـت مستعملة في غيره، فتدخل الفاء في كلام الشَّارع: إمّا في الوصف فاسـتفيد الإشـارة إلى العِلِّيَّة، كقوله ﷺ في قتلى أحد: (زملوهم بدمائهم، فإنه ليس كلـم يكلـم في الله إلا يـأتي يوم القيامة يدمى لونه لون الدم، وريحه ريح المسك)، وقوله ﷺ عـن رجـل خَـرَّ مـن بعيره فوقص فمات: (اغسلوه بماء وسدر، وكفنوه في ثوبه، ولا تخمـروا رأسـه، فـإن الله يبعثه يوم القيامة ملبياً)، وإما تدخل الفاء في كلام الشارع في الحكم فاستفيد الإشـارة للعلية كـما في قولـه تعـالى: ﴿وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا﴾ [المائـدة:٣٨]؛ لأنَّ الأصل في الفاء التَّعقيب، ودلالتها على العِلِّيَّة استدلالية."]]},{"id":"u88c_10","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ١٠","segs":[["matn","المرتبة الرَّابعة: ذكر الفاء في لفظ الرَّاوي"],["ctx","؛ بأن تكون الفـاء مـن رواي الحـديث في وصف الحادثة لا من كلام الشَّارع، فتفيد نوع من العِلِّيَّة، كقول عمران بن حصين رضي الله عنه: «إنَّ النَّبي ﷺ صلَّى بهم فسها فسجد سجدتين» ، وهذه أقل مراتب الصَّرـيح؛ لاحـتمال الغلط من الرَّاوي."]]},{"id":"u88c_11","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ١١","segs":[["matn","ثانيهما: الإيماء"],["ctx",": وهو أن يلزم من مدلول اللفظ العِلَّة، وله وجوه:"]]},{"id":"u88c_12","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ١٢","segs":[["matn","الأولى: أن يقترن وصف بحكم غير مناسب معه إن لم يكن علَّة"],["ctx","؛ بحيث لو لم يكن هذا الوصف أو نظيره يفيد التَّعليل لكان الكلام مستبعداً، فيحمل على التَّعليل؛ مراعاة لتوافق كلام الشَّارع، بأن يرتب الحكم على الوصف فيفهم لغةً أنَّ الوصف علّة لـذلك الحكم، ومتى صدر من الشَّارع يجب أن يكون الوصفُ مناسباً للحكم، وإلاّ كان عبثاً، والشَّارع مُنَزَّهٌ عنه."]]},{"id":"u88c_13","kind":"text","label":"ثانياً: مسالك العلَّة · الفقرة ١٣","segs":[["ctx","ومثال: الوصف بالحكم: علة قصة الأعرابي، حيث قال: «وقعت على أهلي في رمضان؟ قال ﷺ: فأعتق رقبة»، فإنَّ الوقاع مختلفٌ عن الإعتاق، فذكرهما مع بعضهما يكون غريباً إن لم يكن الوقاع علَّة للإعتاق، حملاً للكلام على التَّوافق والمناسبة، فيكون غرض الشَّارع من ذكر المواقعة بيان حكمها، وذكر الحكم جواباً له ليحصل غرضه؛ لئلا يلزم إخلاء السُّؤال عن الجواب، فيكون السُّؤال مُقَدَّراً في الجواب كأنَّه قال: واقعت فَكَفِّر. وهذا يفيد أنَّ الوقاع علَّة للإعتاق إلا أنَّ الفاءَ ليست محقّقة ليكون صريحاً، بل مُقَدَّرةً فيكون إيماء مع احتمال عدم قصد الجواب كما إذا قال الابن: طلعت الشَّمس، فيقول الأب: اسقني ماء."]]},{"id":"u88c_14","kind":"text","label":"ثانياً: مسالك العلَّة · الفقرة ١٤","segs":[["ctx","ومثال نظير الوصف المقترن: علّة حديث ابن عبـاس رضي الله عنهم قـال: «جـاء رجـل إلى النبي ﷺ، فقال: يا رسول الله إنَّ أُمِّي ماتت وعليها صوم شهر أفأقضيه عنها؟ فقال: لو كان على أُمِّك دين أكنت قاضيه عنها؟ قال: نعم، قال: فدين الله أحقّ أن يقضى»،فإن الرجل سأل دين الله جل جلاله، فذكر النبي ﷺ نظيره وهو دين الآدمي، فنبَّه ﷺ على كونه علَّة للنَّفع، وإلا لزم العبث، ففهم منه أنَّ نظيره في المسؤول عنه، وهـو ديـن الله جل جلاله كـذلك علَّة لمثل ذلك الحكم، وهو النفع."]]},{"id":"u88c_15","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ١٥","segs":[["matn","الثَّانية: أن يقترن وصف بحكم مناسب معه فيفيد العِلِّيَّة"],["ctx",": كقولـه ﷺ: «لا يقضيـ أحد بين اثنين وهو غضبان»، ففيه تنبيهٌ على عليّـةِ الغضـب؛ لشـغله للقلـب، ونحـو قولك: أكرم العلماء، ففيه تنبيه على أنَّ العِلمَ علّةٌ للإكرام؛ لأنه وصف مناسب للإكرام، كما أنَّ الجهل وصف مناسب للإهانة."]]},{"id":"u88c_16","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ١٦","segs":[["matn","الثَّالثة: أن يُفَرِّق بين شيئين في الحكم بصيغة صفة"],["ctx","، وله صورتان:"]]},{"id":"u88c_17","kind":"def","label":"ثانياً: مسالك العلَّة · الفقرة ١٧","segs":[["matn","أولهما: أن يذكر حكمين ويأتي بصيغة دالّة على الوصف"],["ctx","، مثل قوله ﷺ: «للفارس سهمين، وللرَّاجل سهم»، فذكر ﷺ حكمان أحدهما إعطاء سهم واحد، والآخر إعطاء سهمين، والصِّفة التي فَرَّقَت بين الشَّيئين هنا هي صفة الفروسية وضدّها، فيـؤمئ أنَّهـا علَّة للحكم."]]}],"sup":"المطلب الثالث: العلَّة"},{"id":"u88d","title":"وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه","group":"الباب الرابع القياس","units":[{"id":"u88d_1","kind":"def","label":"وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه · الفقرة ١","segs":[["matn","وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه:"],["matn","١ .أن تذكر صفة توجب الفرق"],["ctx","، مثل قوله ﷺ: «القاتل لا يرث»، فذكر ﷺ حكماً واحداً ولم يذكر الثَّاني، وهو أنَّ غيرَ القاتل يرث، فتخصـيص القاتـل بـالمنع مـن الإرث مع سابقة الإرث يُشعر بأنَّ علَّة المنع القتل."]]},{"id":"u88d_2","kind":"def","label":"وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه · الفقرة ٢","segs":[["matn","٢.أن تذكر صفة تدلّ على الغاية"],["ctx","، مثل قولـه تعـالى: ﴿وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَ﴾ [البقرة:٢٢٢]، فيؤمئ أنَّ الطَّهارة علّة جواز القربان، فقد فرَّق في هذه الآية بين الحائض وغيرها في جواز القُربان وعدمه بالطَّهارة."]]},{"id":"u88d_3","kind":"def","label":"وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه · الفقرة ٣","segs":[["matn","٣.أن تذكر صيغة تدلّ على الاستثناء"],["ctx","، نحو قوله تعـالى: ﴿فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ﴾ [البقرة:٢٣٧]، فيومئ أنَّ العفوَ علَّةٌ لسقوطِ المفروض من المهر، فقد فَرَّقَت صيغة الاستثناء بين الزَّوجة التي عفت عن مهرها والتي لم تَعْفُ، ففهمـت العِلِّيَّـة مـن العفو."]]},{"id":"u88d_4","kind":"def","label":"وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه · الفقرة ٤","segs":[["matn","٤.أن تذكر صيغة تدلّ على الشَّرط"],["ctx","، مثل قوله ﷺ: «مثلاً بمثل، سواء بسواء، يـداً بيد، فإذا اختلفت هذه الأصناف فبيعوا كيـف شـئتم»، فيـومئ أنَّ اخـتلاف الجـنس يكون علّة لجواز البيع، وفهم هذا من صورة شرط."]]},{"id":"u88d_5","kind":"text","label":"وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه · الفقرة ٥","segs":[["ctx","والمقصود ههنا بيان وجوه دلالة النَّص على العِلِّيَّة سواء أمكن بهـا القيـاس أو لم يمكن، لا بيان ما يصحُّ به القياس، وإلا فلا يستقيم بيانهـا؛ لأنَّ العليّـة في بعـض هـذه المواضع غير مسلمة نحو: (واقعت امرأتي)؛ لأنَّه وإن نسـب الحكـم إلى المواقعـة لكـن يمكن أن تكون العلَّة شيئاً يشمل علية المواقعة كهتك حرمة الصَّوم مثلاً."]]},{"id":"u88d_6","kind":"text","label":"وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه · الفقرة ٦","segs":[["ctx","وبعض تلـك العلـل لا يمكـن بهـا القيـاس أصـلاً، نحـو: ﴿وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا﴾ [المائدة:٣٨]؛ لأنَّ السَّرقة إن كانت علَّة فكلّما وجدت يثبت الحكـم القطعيّ نصّاً لا قياساً."]]},{"id":"u88d_7","kind":"text","label":"وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه · الفقرة ٧","segs":[["ctx","وأيضاً النَّصّ يدلّ عـلى ترتـب الحكـم عـلى تلـك القضـية في (واقعـت امـرأتي) ونحوها لا على كونها مناطاً فإنَّه يمكن أن يكون هتك حرمة الصَّوم."]]},{"id":"u88d_8","kind":"text","label":"وثانيهما: أن يذكر أحد الحكمين فقط، وله وجوه · الفقرة ٨","segs":[["ctx","وأيضاً الغاية والاستثناء لا يدلان على العِلِّيَّة."]]}],"sup":"المطلب الثالث: العلَّة"},{"id":"u88e","title":"الثَّالث: المناسبة بشرط الملائمة","group":"الباب الرابع القياس","units":[{"id":"u88e_1","kind":"def","label":"الثَّالث: المناسبة بشرط الملائمة · الفقرة ١","segs":[["matn","الثَّالث: المناسبة بشرط الملائمة:"],["ctx","شبَّه الأصوليون العلَّة بالشَّاهد، فتعتبر شهادته بصلاحه وعدالته، والصَّلاح يكون بوجود العقل والبلوغ والحرية والإسلام، والعدالة بأن يكون مجتنباً عن محظورات دينه؛ ليصح منه الأداء، وإلا لا تقبل شهادته."]]},{"id":"u88e_2","kind":"text","label":"الثَّالث: المناسبة بشرط الملائمة · الفقرة ٢","segs":[["ctx","وكذلك في العلَّة تكون معتبرة بأن يدلّ على كون هذا الوصف علَّة صلاحه وعدالته، بأن يكون صالحاً للحكم بوجود الملاءمة، ومن عدالته بوجود التَّأثير."]]},{"id":"u88e_3","kind":"def","label":"الثَّالث: المناسبة بشرط الملائمة · الفقرة ٣","segs":[["matn","١.المناسبة:"],["matn","هي مناسبته للحكم بأن يصحّ إضافة الحكم إليه، ولا يكون نابياً عنه: كإضافةِ"],["ctx","ثبوتِ الفُرقة في إسلامِ أحد الزَّوجين إلى إباء الآخر عـن الإسـلام؛ لأنَّـه يُناسـبُه لا إلى وصفِ الإسلام؛ لأنَّه نابٍ عنه؛ لأنَّ الإسلامَ عُرِفَ عاصماً للحقوق لا قاطعاً لها، وكذا المحظور يصلح سبباً للعقوبة، والمباح سبباً للعبادة، ولا يجوز عكسه لعدم الملائمة."]]},{"id":"u88e_4","kind":"def","label":"الثَّالث: المناسبة بشرط الملائمة · الفقرة ٤","segs":[["matn","٢.الموافقةُ:"],["matn","بأن يكون الوصفُ على موافقةِ العلّل المنقولةِ عن رسول الله ﷺ وعن السَّلفِ مـن الصَّحابة والتَّابعين رضي الله عنهم"],["ctx","، فإنَّهم كانوا يُعلِّلون بأوصافٍ ملائمةٍ للأحكام غير نابيـة عنهـا، فما كان موافقاً لها يصلح أن يكون علَّة وما لا فلا."]]},{"id":"u88e_5","kind":"text","label":"الثَّالث: المناسبة بشرط الملائمة · الفقرة ٥","segs":[["ctx","ومثاله: التَّعليلُ بالصِّغر في ولايةِ النِّكاح؛ لما يتصل به من العجـز، فإنَّـه مـؤثرٌ في إثبات الولاية في مال الصَّغير؛ لأنَّ الصِّبا مظنة العجز، وهذا التَّأثير كتأثير الطَّـواف لمـا يتصل به من الضَّرورة؛ إذ التَّعليل بالصَّغر موافق للعلل المنقولـة؛ لأنَّـه مثـل الطَّـواف الذي علل به النَّبي ﷺ سقوط النَّجاسة عن الهرة في قوله: «إنَّها ليست بنجس، إنَّـما هـي من الطَّوافين عليكم والطَّوافـات»، فـالطَّواف منشـأ للضَّرـورة، وهـي تعـذر صـون الأواني عن الهرة، والضَّرورة مؤثِّرة في إسقاط النَّجاسة."]]},{"id":"u88e_6","kind":"text","label":"الثَّالث: المناسبة بشرط الملائمة · الفقرة ٦","segs":[["ctx","وكذا الصَّغر منشأ للعجز، والعجزُ مؤثِّرٌ في إثباتِ الولاية، فكان التَّعليل بالصَّغر موافقاً لتعليل رسول الله ﷺ؛ لأنَّ العلَّة في إحدى الصُّورتين: العجـز، وفي الأخـرى: الطَّواف، فالعلَّتان وإن اختلفتا لكنَّهما مندرجتان تحت جنس واحـد، وهـو الضَّرـورة، والحكم في إحدى الصُّـورتين الولايـة، وفي الأُخـرى الطَّهـارة، وهمـا مُختلفـان لكـنَّهما مندرجان تحت جنس واحد، وهو الحكمُ الذي يندفع به الضَّرورة، فالحاصلُ أنَّ الشَّرعَ اعتـبر الضَّرـورة في إثبـاتِ حكـم ينـدفع بـه الضَّرـورة: أَي اعتـبر الضَّرـورة في حَـقّ الرُّخص."]]}],"sup":"المطلب الثالث: العلَّة"},{"id":"u88f","title":"الثَّاني: عدالة الوصف","group":"الباب الرابع القياس","units":[{"id":"u88f_1","kind":"def","label":"الثَّاني: عدالة الوصف · الفقرة ١","segs":[["matn","الثَّاني: عدالة الوصف:"],["matn","وهي تثبت بالتَّأثير، والوصفُ المؤثّر: ما جُعِلَ له أَثرٌ في الشَّرع، بأن يكون لجـنس ذلك الوصف تأثيرٌ في إثباتِ جنس ذلك الحكم في مورد الشرع"],["ctx","، فيدلّ عليه بالكتـاب أو بالسُّنة أو بالإجماع: أي يثبت أثر هذا الوصف بهذه الحجج، وذكرَ بعضُ الأصوليين أنَّ أعلى أنواع القياس المؤثر، وهو باعتبار النَّظـر إلى عـين العلَّـة وجنسـها، وعـين الحكـم وجنسه"],["matn","أَربعة أَقسام:"]]},{"id":"u88f_2","kind":"def","label":"الثَّاني: عدالة الوصف · الفقرة ٢","segs":[["matn","١.أن يظهرَ تأثيرُ عين الوصف في عين ذلك الحكم"],["ctx","؛ إذ لا يبقى بين الفرع والأصل مباينة إلا تعدد المحلّ."]]},{"id":"u88f_3","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٣","segs":[["ctx","ومن أمثلته:"]]},{"id":"u88f_4","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٤","segs":[["ctx","تأثير عين الكيل والجنس ـ وهو علَّـة في ثبـوت حكـم الرِّبـا ـ في التَّمـر بـالتَّمر، فالجصُّ بالجصِّ ملحقٌ به بلا شبهة؛ إذ لا يبقى إلا اختلاف عدد الأشخاص التـي هـي مجاري المعنى، ويكون ذلك كظهور أثر الوقاع في إيجاب الكفَّارة على الأعرابي؛ إذ يكون التركي والهندي في معناه."]]},{"id":"u88f_5","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٥","segs":[["ctx","وتأثير عين الطَّواف وهو علّة في ثبوت عين حكم طهارة سـؤر الهـرة، فسـواكنُ البيوت من الفأرةِ والحيةِ وغيرهما ملحقةٌ بها؛ لوجود علّة الطَّواف فيها."]]},{"id":"u88f_6","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٦","segs":[["ctx","وتأثير عين الصِّغر وهو علّةُ ثبوت عين حكم الولاية على البكر الصغير، ومثلهـا الثيب الصَّغيرة والصَّغير؛ لأنَّ الصِّغر علَّة للحكم بعينه."]]},{"id":"u88f_7","kind":"def","label":"الثَّاني: عدالة الوصف · الفقرة ٧","segs":[["matn","٢.أن يظهر تـأثير عـين الوصـف في جـنس ذلـك الحكـم"],["ctx",": والمـراد مـن الجـنس المجانس، والمجانسان هما المتحدان من حيث الجنس، فمـثلاً حـرج الاسـتئذان لـيس بمقول على حرج النَّجاسة وغيره من الأنواع حتى لا يكون جنساً لهما، لكـنَّهما يتحـدان في مطلق الحرج، فأمكن أن يعتبرا متجانسين."]]},{"id":"u88f_8","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٨","segs":[["ctx","ومن أمثلته:"]]},{"id":"u88f_9","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٩","segs":[["ctx","تأثير عين وصف الأخوة لأب وأم ـ وهو علَّـة في التَّقـديم في المـيراث ـ في جـنس حكم التَّقديم في الميراث وهو التَّقديم في ولايـة الإنكـاح، فيقـاس عليـه؛ لأنَّ الولايـة ليست هي عين الميراث، لكن بينهما مجانسة في الحقيقة، حيث استخرجنا من عين الحكم «التقديم في الميراث» جنساً للحكم «التقديم مطلقاً»، ثم استخرجنا من التَّقديم مطلقـاً عين حكم جديد، وهو التقديم في ولاية النكاح."]]},{"id":"u88f_10","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ١٠","segs":[["ctx","وتأثير عين وصف الطَّواف في سواكن البيوت من الهرة والفأرة والحية، وهو علـة في سقوط حرج حكم النَّجاسة في جنسه، وهـو سـقوط الحـرج مطلقـاً، ويسـتفاد مـن سقوط الحرج سقوط حرج الاستئذان فيما ملكت أيماننا؛ قـال تعـالى: ﴿لَيۡسَ عَلَيۡكُمۡ وَلَا عَلَيۡهِمۡ جُنَاحُۢ بَعۡدَهُنَّۚ طَوَّٰفُونَ عَلَيۡكُم بَعۡضُكُمۡ عَلَىٰ بَعۡضٖ﴾ [النور:٥٨]؛ لأنَّ حرج الاسـتئذان من جنس حرج النجاسة لا عينه."]]},{"id":"u88f_11","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ١١","segs":[["ctx","وتأثير عين وصف الصِّغر ـ وهو علّـة في ثبـوت حكـم ولايـة النِّكـاح للـولي ـ في جنس حكم النِّكاح، وهي الولاية مطلقاً، فيثبت حكم ولاية المال للولي."]]},{"id":"u88f_12","kind":"def","label":"الثَّاني: عدالة الوصف · الفقرة ١٢","segs":[["matn","٣.أن يؤثر جنس الوصف في عين ذلك الحكم"],["ctx",": وهو الذي خصّوه بالملائم، وخصّوا اسم المؤثر بما ظهر تأثير عينه."]]},{"id":"u88f_13","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ١٣","segs":[["ctx","ومن أمثلته:"]]},{"id":"u88f_14","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ١٤","segs":[["ctx","ملائمة جنس وصف لزوم الحرج والمشقة بعارض سماوي لعين حكم سقوط قضاء الصَّلاة الكثيرة، وهذا الجنس للوصف استفيد من وصف عين وصف الجنون والحيض يؤثر في عين حكم سقوط قضاء الصَّلاة الفائتة الكثيرة، فيندرج في هذا الجنس الإغماء لمجانسته إيّاها فتسقط الصّلاة به: أي رغم أنَّه لم يرد اعتبار الشارع علة للسقوط، لكنه اعتبر ما هو جنسه، فيقاس الإغماء على الجنون والحيض، ويعتبر علة لإسقاط قضاء الصلاة الفائتة عن المغمى عليه."]]},{"id":"u88f_15","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ١٥","segs":[["ctx","وملائمة جنس وصف المضمضة وهو عدمُ دخول شيءٍ للجوف إلى عينِ حكم عدمِ فسادِ الصَّوم، فإنَّ الوصف الذي هو المضمضة اعتبر في عين الحكم الذي هو عدم الإفساد، بل اعتبر جنسه وهو عدم دخول شيء إلى الجوف في غير ذلك الحكم."]]},{"id":"u88f_16","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ١٦","segs":[["ctx","وملائمة جنس وصف الحيض وهو الخارج من السَّبيلين إلى عين حكم حرمة الصَّلاة لا في جنس الحكم وهو حرمة القراءة مطلقاً، فتجوز القراءة بدون تلفظ."]]},{"id":"u88f_17","kind":"def","label":"الثَّاني: عدالة الوصف · الفقرة ١٧","segs":[["matn","٤.ما ظهر أثر جنس الوصف في جنس ذلك الحكم:"]]},{"id":"u88f_18","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ١٨","segs":[["ctx","ومن أمثلته:"]]},{"id":"u88f_19","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ١٩","segs":[["ctx","ملائمة جنس وصف الحرج والمشقة لجنس حكم التَّخفيف في الأحكـام، وهـذا الجنس للوصف مستفاد من عين وصـف الحـيض والسَّـفر والمـرض، وجـنس الحكـم مستفاد عين حكم سقوط القضـاء بـالحيض، وإباحـة الفطـر وقصرـ الصَّـلاة وغيرهـا بالسَّفر، وإباحة الفطر والصَّلاة قاعداً ومؤمئاً وغيرها بالمرض، فكأنَّ الشَّارع اعتبر كـلّ جنس من أجناس مظانّ الحرج علّة لكلّ جنس من أجناس الأحكام التي فيها تخفيف."]]},{"id":"u88f_20","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٢٠","segs":[["ctx","ولا ريب في أنَّ قضاء أوقات الصَّـلوات الفائتـة للحـائض مـن أجنـاس مَظَـانّ الحرج، وسقوط قضائها عن الحائض من أجناس الأحكام التي فيهـا تخفيـف، فيكـون جنس الوصف قد اعتبر علّة لجنس الحكم لا لعينه؛ لأنَّ عين الحكم في المقيس عليه هي الإفطار في رمضان، وقصر الصَّلاة في السَّفر، وقد أُبيحا لعلّة مَظِنّة الحرج، بقصد دفعه، والتَّخفيف عن المريض والمسافر، وتكليف الحائض بقضاء الصَّلوات التي فاتتهـا أثنـاء الحيض فيه حرج ومشقّة، وهو من جنس الحرج الذي يَلحق المسافر والمريض، ولذلك أُسقط عنها للتَّخفيف، ودفع الحرج والمشقّة."]]},{"id":"u88f_21","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٢١","segs":[["ctx","ومن ملائمة جنس الوصف لجنس الحكم تستفاد القواعد الفقهية، فمثلاً عرفنـا من التَّطبيق السَّابق كيف خرجت قاعدة المشقة تجلـب التَّيسـير، بـالنَّظر لعلـل عديـدة متجانسة وأحكامها، بحيث نحتكم لها في غيرها، وعليه فقس."]]},{"id":"u88f_22","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٢٢","segs":[["ctx","وملائمة جنس وصف الضَّرورة لجنس حكم إباحة المحظورات، وهذا الجنس للوصف مستفاد من عين وصف الطواف لسواكن البيوت والمضطر للأكل وغيرها، وجنس الحكم مستفاد من طهارة النَّجاسة للطواف وإباحة أكل الميتة للمضطر وغيرها، وظهر أثره في مخالطة نجاسة يشقّ الاحترازُ عنها في طهارة آبار الفلوات للضَّرورة، ومن هذا نتجت قاعدة الضرورات تبيح المحظورات."]]},{"id":"u88f_23","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٢٣","segs":[["ctx","وملائمة جنس وصف إيقاع العداوة والبغضاء لجنس حكم الحرمة والزاجر، وهذا الجنس للوصف مستفاد من السُّكر والقذف وغيره، وجنس الحكم مستفاد من الحرمة والزَّجر للسُّكر والقذف؛ لأنّ السُّكر لَمّا كان مظنّة للقذف صار المعنى المشترك بينهما، وهو إيقاع العداوة والبغضاء مؤثراً في وجوب الزَّاجر."]]},{"id":"u88f_24","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٢٤","segs":[["ctx","وملائمة جنس وصف الأذى لجنس حكم حرمة الجماع مطلقاً، وهذا الجنس للوصف مستفاد من عين وصف الحيض والنَّفاس وغيرها، وجنس الحكم مستفاد من حرمة القربان للحيض والنَّفاس، فتدخل حرمة اللواط."]]},{"id":"u88f_25","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٢٥","segs":[["ctx","وملائمة جنس وصف العجز لثبوت الولاية مطلقاً، وهذا الوصف مستفاد مـن عين وصف الجنون المطبق والصغير وغيره، وجنس الحكم مستفاد من عين حكم ولاية النكاح وولاية المال."]]},{"id":"u88f_26","kind":"def","label":"الثَّاني: عدالة الوصف · الفقرة ٢٦","segs":[["matn","والفرق بين العلَّة والحكمة:"],["ctx","سبق بيان أنَّ العلَّةَ هي الوصف الصالح المؤثر في ثبوت الحكـم في الأصـل متـى وجد مثله في الفرع."]]},{"id":"u88f_27","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٢٧","segs":[["ctx","أما الحكمة فهي الفائدة التي يتوقع حصولها من العمل بالحكم: أي الباعث على تشريع الحكم من المصلحة التي قصدها الشارع، وقد تكون تلك المصلحة جلب منفعة على العباد، وقد تكون دفع مفسدة عنهم، أو تقليل المفسدة، وتكميل المنفعة."]]},{"id":"u88f_28","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٢٨","segs":[["ctx","وهذا مثل حرمة شرب الخمر، فإنَّ حرمة الشرب حكم، وكـون المشرـوب خمـراً علّة، وصيانة الإنسان عما يُذهب عقله حكمة، فيدور حكم الحرمـة عـلى علّتـه: يعنـي كون المشروب خمراً فمهما وجدت الخمر ثبت حكم الحرمة، ولا يدور مع الحكمة، فلـو وجد رجل لا يذهب عقله بشرب الخمر لا ينتفي حكم الحرمة في حقه؛ لأنَّ العلّة وهي كون المشروب خمراً باقية."]]},{"id":"u88f_29","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٢٩","segs":[["ctx","وكذلك حكم قصر الصَّلاة علّته السفر وحكمته الاحـتراز عـن المشـقّة، فيـدور الحكم على علّته، وهو السَّفر دون حكمته، وهي المشقة فلو وجد مسافر لم تحصل له أية مشقة كما في عصرنا في سفر الطَّائرات والسّيارات السّريعة لا ينتفي حكم القصرـ؛ لأنَّ العلّة باقية، وهي السَّفر، وبالعكس لو حصلت لرجل مشقّة شـديدة في بلـده أو وطنـه الأصلي لا يجوز له أن يقصر الصَّلاة؛ لأنَّ العلّة منتفية وهي السفر."]]},{"id":"u88f_30","kind":"text","label":"الثَّاني: عدالة الوصف · الفقرة ٣٠","segs":[["ctx","فتبيّن بما ذكرنا أنَّ الحكم لا يتغير بتغير الحكمة، وإنَّما يتغيَّر بتغير العلّة، ومثال ذلك: ما ذكره الفقهاء من أن بيع الماء لسقي المزارع ممنوع، ولكن علّة هذا المنع عدم ضبط مقدار الماء، واليوم قد وجدت عدادات يمكن ضبط مقدار الماء بها فحيث وجدت هذه العدادات انتفت علة المنع، فجاز بيع الماء."]]}],"sup":"المطلب الثالث: العلَّة"},{"id":"u89","title":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس","group":"الباب الرابع القياس","units":[{"id":"u89_1","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ١","segs":[["matn","أولاً: موانع العلَّة أربعة، وهي:"],["matn","١.مانع يمنع انعقاد العلَّة"],["ctx",": كبيع الحر والميتة والدَّم؛ فإنَّ عدم المحليّة يمنع انعقاد البيع."]]},{"id":"u89_2","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ٢","segs":[["matn","٢.مانع يمنع تمام العلَّة"],["ctx",": كهلاك النِّصاب أثناء الحول يمنع وجوب الزَّكاة."]]},{"id":"u89_3","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ٣","segs":[["matn","٣.مانع يمنع ابتداء الحكم"],["ctx",": كالبيع بشرط الخيار يمنع ثبوت الملك."]]},{"id":"u89_4","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ٤","segs":[["matn","٤.مانع يمنع دوام الحكم"],["ctx",": كخيار البُلوغ يمنع دوام حكم النِّكاح."]]},{"id":"u89_5","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ٥","segs":[["matn","ثانياً: وجوه دفع القياس ثمانية، وهي:"],["matn","١.الممانعة"],["ctx",": مفاعلة من المنع،"],["matn","وهي عدم قَبول دليل المُستدل كلاً أو بعضاً، وهي نوعان:"]]},{"id":"u89_6","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ٦","segs":[["matn","أ.منع العلَّة"],["ctx",": كقول الشَّافعيّ: صدقة الفطر وجبت بالفطر عند غروب الشَّمس؛ لأن الفطر بانفصال الصَّوم، وبالغروب ينتهي رمضان؛ وتسقط بالموت ليلة الفطر، قُلنا: لا نُسَلِّم وجوبها بالفطر، بل تجب بطلوع الفجر؛ لأنه وقت ظهور فطره، فلا تسقط بالموت ليلة الفطر."]]},{"id":"u89_7","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ٧","segs":[["matn","ب.منع الحكم"],["ctx",": كقول الشَّافعي في مسح الرَّأس إنَّه ركنٌ فيُسَنُّ تثليثُه كالغَسل، قُلنا: لا نُسلِّم أنَّ المسنون في الغَسل التَّثليث، بل المسنون هو الإكمال بعد الفرض."]]},{"id":"u89_8","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ٨","segs":[["matn","٢. القول بموجب العلَّة"],["ctx",": وهو تسليم العلَّة، وبيان أنَّ حكمها غير ما ادَّعاه المُستدلّ: كقول زُفر: المِرفق غاية فلا تدخل في المُغَيَّا، قلنا: هي غاية السَّاقط دون المغسول، فتدخل في المُغَيَّا."]]},{"id":"u89_9","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ٩","segs":[["matn","٣. القلب: وهو نوعان:"]]},{"id":"u89_10","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ١٠","segs":[["matn","أ. قلب العلَّة حكماً والحكمُ علةً"],["ctx",": كقول الشَّافعيّ: يحرم بيع الحفنة من الطَّعام بالحفنتين منه؛ لأنَّ جريان الرِّبا في الكثير يوجب جريانه في القليل، قلنا: لا، بل جريانه في القليل يوجب جريانه في الكثير."]]},{"id":"u89_11","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ١١","segs":[["matn","ب. قلب علَّة الحكم علّة لضدّ ذلك الحكم"],["ctx",": كقول الشَّافعي: صومُ رمضان صوم فرض، فيشترط له التَّعيين كالقضاء، قلنا: هو صوم فرض، فلا يشترط له التَّعيين بعد تعيين الشَّرع كالقضاء بعد التَّعيين من العبد."]]},{"id":"u89_12","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ١٢","segs":[["matn","٤. العكس: هو ردُّ الحكم على خلاف سننه الأول"],["ctx","، كقول الشَّافعي: لا تجب الزَّكاة في حُليّ النِّساء كثياب البذلة، قلنا: فلا تجب في حُلي الرِّجال أيضاً كثياب البذلة."]]},{"id":"u89_13","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ١٣","segs":[["matn","٥. فساد الوضع: هو بيان كون العلَّة غير صالح للحكم"],["ctx",": كقول الشَّافعيّ: إسلام أحد الزَّوجين يُفسد النِّكاح، كارتداد أحدهما، قلنا: الإسلام عُرِفَ عاصماً للحقوق لا رافعاً لها."]]},{"id":"u89_14","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ١٤","segs":[["matn","٦. الفرق: هو بيان الفرق بين الأمرين"],["ctx",": كقول الشَّافعيّ: تجب الزَّكاة في مال الصَّبيّ؛ لإغناء الفقير، كما في مال البالغ، قلنا: وجوب الزَّكاة على البالغ؛ لتطهير الذُّنوب، لا لإغناء الفقير، فافترقا."]]},{"id":"u89_15","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ١٥","segs":[["matn","٧. النَّقض: هو بيان تَخَلُّف الحكم عن العلَّة"],["ctx",": كقول الشَّافعي: الوضوء طهارة، فيشترط له النِّية كالتيمم، قلنا: فلماذا لا تجب في غسل الثَّوب والبدن."]]},{"id":"u89_16","kind":"def","label":"المطلب الثَّالث: موانع العلَّة ووجوه دفع القياس · الفقرة ١٦","segs":[["matn","٨. المعارضة: هي إقامةُ الدَّليل على خلافِ ما أقام عليه الخصم الدَّليل"],["ctx",": كقول الشَّافعيّ: المسحُ ركنٌ في الوضوء، فيُسنُّ تثليثُه كالغَسل، قلنا: المسحُ ركنٌ فلا يُسَنُّ تثليثُه كمسح الخُفّ والتَّيمُّم."]]}]},{"id":"u90","title":"المطلب الرَّابع: الاستحسان","group":"الباب الرابع القياس","units":[{"id":"u90_1","kind":"def","label":"المطلب الرَّابع: الاستحسان · الفقرة ١","segs":[["matn","يقسم القياس من حيث جلاؤه وغموضُه إلى قسمين:"],["matn","١.القياسُ الجليّ: وهو ما تبادرت أفهام المجتهدين إلى وجهِـهِ وعلَّتـه، وإذا أُطلـق لفظ القياس ينصرف إليه."]]},{"id":"u90_2","kind":"def","label":"المطلب الرَّابع: الاستحسان · الفقرة ٢","segs":[["matn","٢.القياسُ الخفيّ: وهو ما لا تنتقل أفهام المجتهدين إلى وجهه وعلَّته إلا بعد البحث والتَّأمل، ويُسمّونه الاستحسان."]]},{"id":"u90_3","kind":"text","label":"المطلب الرَّابع: الاستحسان · الفقرة ٣","segs":[["ctx","وقد اشتهر عن أبي حنيفة أخذه بالاستحسان حتى امتلأت كتب الحنفيّة به، ويجعل في غالب الأحيان مقابلاً للقياس، فيقولون: القياس يقتضي الحظَر، والاستحسان يقتضي الإباحة، فيتخذ دليلاً شرعيّاً يعارض دليلاً شرعيّاً مثله ويُرجَّح عليه."]]},{"id":"u90_4","kind":"def","label":"المطلب الرَّابع: الاستحسان · الفقرة ٤","segs":[["matn","والاستحسان لغةً: وجود الشَّيء حسناً"],["ctx","، يقول الرَّجل: استحسنت كذا: أي اعتقدتُه حسناً على ضدِّ الاستقباح، أو معناه: طلب الأحسن للاتباع الذي هو مأمورٌ به، كما قال تعالى: ﴿فَبَشِّرۡ عِبَادِ ٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓ﴾ [الزمر:١٨]، فالقرآن كلُّه حسن، ثمّ أمر باتباع الأحسن."]]},{"id":"u90_5","kind":"def","label":"المطلب الرَّابع: الاستحسان · الفقرة ٥","segs":[["matn","واصطلاحاً: عدول المجتهد عن حكم كلِّي إلى حكـم اسـتثنائي بـدليل انقـدح في عقله رَجَّح له هذا العدول، أو عدولُ المجتهد عن قياس جلي إلى قياس خفي."]]},{"id":"u90_6","kind":"def","label":"المطلب الرَّابع: الاستحسان · الفقرة ٦","segs":[["matn","فيكون الاستحسان هو الدَّليل الذي يكون معارضاً للقياس الظَّاهر الـذي تسـبق إليه الأوهام قبل إمعان التَّأمُّل فيه"],["ctx","، وبعد إمعان التَّأمُّل في حكم الحادثـة وأشـباهها مـن الأصول يظهر أنَّ الدَّليلَ الذي عارضه فوقه في القـوَّة، فـإنَّ العمـل بـه هـو الواجـب، فسمَّوا ذلك استحساناً؛ للتَّمييز بين هذا النَّوع من الدَّليل وبين الظَّاهر الذي تسبق إليـه الأوهام قبل التَّأمُّل على معنى أنَّه يُمال بالحكم عن ذلك الظَّاهر لكونه مستحسناً؛ لقـوَّة دليله."]]},{"id":"u90_7","kind":"def","label":"المطلب الرَّابع: الاستحسان · الفقرة ٧","segs":[["matn","واستعمال الفقهاء عبارة القياس والاستحسان للتَّمييز بين الدَّليلين المتعارضين،"],["ctx","وتخصيص أحدهما بالاستحسان؛ لكون العمل به مستحسناً؛ ولكونه مائلا عن سَنن القياس الظَّاهر، واستحسان العمل بأقوى الدَّليلين لا يكون من اتباع الهوى وشهوة النَّفس في شيء."]]},{"id":"u90_8","kind":"text","label":"المطلب الرَّابع: الاستحسان · الفقرة ٨","segs":[["ctx","قـال السَّرَخْسيّ: «القيـاسُ والاستحسـانُ في الحقيقـة قياسـان: أَحـدهما جـليٌّ ضعيف أثره فسمِّي قياساً، والآخـرُ خفـيٌّ قـوي أَثَـره، فسـمِّي استحسـاناً: أي قياسـاً مستحسناً، فالتَّرجيح بالأثر لا بالخفاء والظُّهور: كالدُّنيا مع العقبى، فإنَّ الـدُّنيا ظـاهرة والعقبى باطنة، وترجَّحت بالصَّفاء والخلود، وقد يقوى أثر القياس في بعض الفصـول فيؤخذ به»."]]}]},{"id":"u90a","title":"وأنواع الاستحسان ثلاثة","group":"الباب الرابع القياس","units":[{"id":"u90a_1","kind":"def","label":"وأنواع الاستحسان ثلاثة · الفقرة ١","segs":[["matn","وأنواع الاستحسان ثلاثة:"],["ctx","إنَّ البحثَ في الاستحسان بحثُ ترجيح، فأَوَّل ما ينصرف إليه ذهن القارئ عنـد سماع الاستحسان إلى أنَّ ما في الاستحسان هو الرَّاجح على القول الآخـر؛ لأنَّ كـلَّ مـا قيل فيه الاستحسان فهو راجحٌ في نفسِهِ على غيره إلا مسائل محصورة."]]},{"id":"u90a_2","kind":"text","label":"وأنواع الاستحسان ثلاثة · الفقرة ٢","segs":[["ctx","وهذا التَّرجيح يرجع لمعاني ثلاثة حاصلة بالاستقراء في كتب الفقه ولاسيما كتـب محمد بن الحسن كـ: «الأصل»، وهي الاستنباط والبناء والإفتاء، فعندما تتأمَّل ما سبب هذا الاستحسان في مسألةٍ ما، فإنَّك تلاحظ أنَّه لا يخرج عن هذه المعاني الثَّلاثـة لقـادح انقدح في ذهن المجتهد تقوَّى به الاستحسان ـ وهو الاستثناء لهذه المسألة ـ على القياس وهو الشَّائع في نظير هذه المسألة على النَّحو الآتي:"]]},{"id":"u90a_3","kind":"def","label":"وأنواع الاستحسان ثلاثة · الفقرة ٣","segs":[["matn","أوَّلاً: استحسانٌ بأصول الاستنباط:"],["ctx","فالاستنباط يتحدّث عن كيفيّة استخراج الحكم الشَّرعيّ من الآيات والأحاديث النَّبوية، وهو المعروف بعلم أصول الفقه."]]},{"id":"u90a_4","kind":"def","label":"وأنواع الاستحسان ثلاثة · الفقرة ٤","segs":[["matn","ويكون الاستحسان به، بأن يرجّح بدليل كليٍّ وهو قاعدةٌ أصوليّةٌ في مقابل قاعدة أصولية أُخرى، أو دليل جزئيٍّ وهو آيةٌ أو حديثٌ أو أثرٌ في مقابل آياتٍ أو أحاديـث أو آثار لا حقِّيَّة للحكم بها دون غيرها تظهر في ذهن المجتهد."]]},{"id":"u90a_5","kind":"def","label":"وأنواع الاستحسان ثلاثة · الفقرة ٥","segs":[["matn","ويُعبّر عنه بأنَّه تخصيص الحكم بالنَّص مع وجود العلَّة"],["ctx","، وهو أن يثبت نصٌّ عن الشَّارع يوجب ردّ القياس، ومن أمثلته:"]]},{"id":"u90a_6","kind":"text","label":"وأنواع الاستحسان ثلاثة · الفقرة ٦","segs":[["ctx","ـ مسألة: الصَّغير يموت عن امرأته وهي حامل: ذكر محمد بن الحسن: أنَّ القياس أن تكون عدّتها أربعة أشهر وعشراً؛ لأنَّ الحمل من غير الزَّوج، إلا أنَّه ترك القياس، واستحسن أن يجعل عدتها وضع الحمل؛ لقوله تعالى: ﴿وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّ﴾ [الطلاق:٤]، فسمّى ترك القياس للعموم استحساناً."]]},{"id":"u90a_7","kind":"text","label":"وأنواع الاستحسان ثلاثة · الفقرة ٧","segs":[["ctx","ـ مسألة: جواز السَّلم؛ لقوله ﷺ: «مَن أسلف فليسـلف في كيـل معلـوم، ووزن معلوم، إلى أجل معلوم»، فالحديث يدلّ على جواز السَّلَم وان كان المباعُ معدوماً، والقاعدةُ المانعةُ هي قوله ﷺ: «ولا تبع ما ليس عندك»، فهنا استثنى السَّلم مـن هـذه القاعدة، والكلُّ يرون جواز ذلك."]]},{"id":"u90a_8","kind":"text","label":"وأنواع الاستحسان ثلاثة · الفقرة ٨","segs":[["ctx","ـ مسألة: صحّة الصِّيام مع الأكل أو الشُّرب ناسياً، قال ﷺ: «مَـن أكَـلَ أو شرب ناسياً فلا يفطر، فإنَّما هو رزق رزقه الله»، فإنَّ القياس كان يوجب الإفطار؛ لأنَّ يكون مما يدخل إلى الجوف المعتبر من منفذ معتبر وقد حصـل، ولكـن رد الإمـام أبـو حنيفـة القياس لهذه الرِّواية كما نُقِل عنه."]]},{"id":"u90a_9","kind":"text","label":"وأنواع الاستحسان ثلاثة · الفقرة ٩","segs":[["ctx","ـ مسألة: القهقهة في الصَّلاة، فالقياس أن لا وضوء فيها، كـما لا وضـوء فيهـا في غير الصَّلاة؛ لأنَّ كل ما كان حدثاً لا يختلف حكمه فيما يتعلّق به من نقـض الطَّهـارة في حال وجوده في الصَّلاة أو غيرها، إلا أنَّهم تركوا القياس فيه للأثر؛ إذ لا حظ للنَّظر مع الأثر، وهو ما روي عن عمـران بـن حصـين وأنـس وجـابر وأبي موسـى وابـن عمـر وغيرهم رضي الله عنهم: «مَن ضَحِكَ في الصَّلاة قهقهةً فَلْيُعِدِ الوضوءَ والصَّلاة»."]]},{"id":"u90a_10","kind":"text","label":"وأنواع الاستحسان ثلاثة · الفقرة ١٠","segs":[["ctx","ـ مسألة: الاستصناع فترك القياس لانعقاد الإجماع على غير ما يؤدِّي إليه القياس، وذلك كانعقاد إجماع المسلمين على صحّة عقد الاستصناع لتعامل النَّاس فيه من زمن رسول الله ﷺ إلى الآن بلا نكير، فإنَّ القياسَ كان يوجب بطلانه؛ لأنَّ محلَّ العقد معدومٌ وقت إنشاء العقد، ولكن للإجماع ترك القياس، فكان عدولاً عن دليل إلى أقوى منه."]]}],"sup":"المطلب الرَّابع: الاستحسان"},{"id":"u90b","title":"ثانياً: استحسان بأصول البناء","group":"الباب الرابع القياس","units":[{"id":"u90b_1","kind":"def","label":"ثانياً: استحسان بأصول البناء · الفقرة ١","segs":[["matn","ثانياً: استحسان بأصول البناء:"],["ctx","فالبناء يتكلّم عن اعتماد الأحكام على عللها وأصولها وكيفية تخريج غيرها عليها، وهو المعروف بعلم القواعد والضوابط والأصول الفقهية."]]},{"id":"u90b_2","kind":"text","label":"ثانياً: استحسان بأصول البناء · الفقرة ٢","segs":[["ctx","فالمجتهد يُعمل أصول استنباطه في الآيات والأحاديث من أجل استخراج أصول البناء للأحكام، ومن أصول البناء يُخرج الأحكام الفقهية، وفي تطبيقها على المُكَلَّفين يراعي قواعد أصول الإفتاء."]]},{"id":"u90b_3","kind":"text","label":"ثانياً: استحسان بأصول البناء · الفقرة ٣","segs":[["ctx","فيكون أصلُ البناء: هو خلاصةُ وزبدةُ مجموعةٍ من الآياتِ والأحاديثِ والآثارِ بعد إعمال أصول الاستنباط فيها."]]},{"id":"u90b_4","kind":"text","label":"ثانياً: استحسان بأصول البناء · الفقرة ٤","segs":[["ctx","فالبناء هو القواعد والضَّوابط والأصول الفقهيّة للمسائل؛ لأنَّه يُمَثِّل الأصل الذي بنيت عليه هذه المسألة وأمثالها من المسائل التي تُشبهها، فالمسألة دائماً هي تطبيق لأصل، وهذا الأصل عادة يشتمل مجموعة من المسائل المتشابهة."]]},{"id":"u90b_5","kind":"def","label":"ثانياً: استحسان بأصول البناء · الفقرة ٥","segs":[["matn","فالاستحسان فيه أن نترك أصلاً للبناء شاع بناء أمثال هذه المسألة عليه إلى أصل للبناء آخر أحقّ ببنائها عليه فيما يَظهر للمجتهد."]]},{"id":"u90b_6","kind":"def","label":"ثانياً: استحسان بأصول البناء · الفقرة ٦","segs":[["matn","ويعبر عن هذا بأن يكون فرع يتجاذبه أصلان، يأخذ الشّبه من كل واحد منهما، فيجب إلحاقه بأحدهما دون الآخر ؛ لدلالة توجبه"],["ctx","، فسمُّوا ذلك استحساناً، إذ لو لم يعرض شبه للوجه الثَّاني، لكان له شبه من الأصل الآخر، فيجب إلحاقه به."]]},{"id":"u90b_7","kind":"text","label":"ثانياً: استحسان بأصول البناء · الفقرة ٧","segs":[["ctx","وذلك بأن يكون في المسألة وصفان يقتضيان قياسـيين متبـاينين: أحـدهما ظـاهر متبادر، وهو القياس الاصطلاحي، والآخر خفي يقتضي إلحاقها بأصل آخـر، فيسـمى استحساناً: أي أنَّ القضية التي ينظر في حكمها يرىٰ الفقيه أنَّ كليهما ينطبق عليها، ولكن أحدهما ظاهر يَعمل في نظائر هذه المسألة، والآخر خفي في هذه المسألة؛ إذ لا يعمل في نظائرها، ولكن يكون في المسألة ما يوجب عمل هذا الخفي الذي لم يطرد في نظائرها."]]},{"id":"u90b_8","kind":"text","label":"ثانياً: استحسان بأصول البناء · الفقرة ٨","segs":[["ctx","مثاله: مسألة سؤر سباع الطَّير ـ وهو بقية الماء الذي يشرب منه ـ فإنَّ سباع الطَّير تشبه سباع البهائم في كون لحمها غير مأكول، وكون لحمها نجساً، وبما أنَّ سؤر سباع البهائم نجس، فينبغي أن يكون سؤر سباع الطَّير: كالنِّسر والحدأة نجساً أيضاً، وهو موجب القياس، ولكنَّ الاستحسان يتجه لقياس آخر خفي، وهو أنَّ سؤر سباع البهائم كان نجساً؛ لوجود لعابها فيه، واللُّعاب متصلٌ باللحم، فهو نجسٌ بنجاسته، أمّا سباع الطَّير فهي تشرب بمناقيرها فلا تلقي لعابها في الماء، فلا يتنجس به، فلا يكون السُّؤر نجساً، وللاحتياط قالوا: إنَّه مكروه الاستعمال."]]}],"sup":"المطلب الرَّابع: الاستحسان"},{"id":"u90c","title":"ثالثاً: استحسان بأصول الإفتاء","group":"الباب الرابع القياس","units":[{"id":"u90c_1","kind":"def","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ١","segs":[["matn","ثالثاً: استحسان بأصول الإفتاء:"],["ctx","فالإفتاء يتكلّم عن كيفية تقرير الحكم الشَّرعي في الواقع والعمل به."]]},{"id":"u90c_2","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ٢","segs":[["ctx","وهي قواعد الإفتاء المعروفة بعلم رسم المفتي."]]},{"id":"u90c_3","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ٣","segs":[["ctx","والرَّسم: هو العلامة التي تدل المفتي علىٰ ما يفتي به."]]},{"id":"u90c_4","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ٤","segs":[["ctx","وأصول الإفتاء: هو علم يبحث في كيفية تطبيق الفقه في الواقع بمراعاة أصوله، وهي: الضَّرورة، والحاجة ، ورفع الحرج، والتَّيسير، وتغير الزَّمان، والعرف، والمصلحة."]]},{"id":"u90c_5","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ٥","segs":[["ctx","وعامّةُ الأحكام الفقهيّة متعلّقةٌ بهذا العلم، فكان لها تأثيرها البالغ في اختلافها من مجتهد إلىٰ مجتهد، بسبب اختلاف بيئة الفقهاء وعصورهم، فقد كان لذلك أثر كبير في اختلافهم في كثير من الأحكام والفروع، حتىٰ إنَّ الفقيه الواحدَ كان يرجع عن كثيرٍ من أقوالِه إلىٰ أقوال أُخرىٰ إذا تعرّض لبيئةٍ جديدةٍ تُخالف البيئة التي كان فيها."]]},{"id":"u90c_6","kind":"def","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ٦","segs":[["matn","فالاستحسان فيه أن يترك العمل بظاهر الحكم إلى غيره؛ لوجود ضرورة أو عرف أو حرج أو غيرها."]]},{"id":"u90c_7","kind":"def","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ٧","segs":[["matn","ويُعبَّر عنه بأنَّه تخصيصُ الحكم بالرَّسم مع وجود العلَّة"],["ctx","، ومن أمثلته:"]]},{"id":"u90c_8","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ٨","segs":[["ctx","ـ تطهير الأواني، فإنَّ القياس يقتضي عدم تطهرها إذا تنجَّست؛ لأنَّه لا يمكن عصرها؛ لأنَّ الماءَ يتنجَّس بملاقاة الآنية النَّجسة، والنَّجسُ لا يفيد الطَّهارة، حتىٰ تخرج النَّجاسة منها، لكنا استحسنا تطهيرها لضرورة الابتلاء بها، والحرج في تنجسها."]]},{"id":"u90c_9","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ٩","segs":[["ctx","ـ الماء الداخل في الحوض أو الذي ينبع من البئر يتنجس بملاقاة النَّجس، والدلو يتنجس أيضاً بملاقاة الماء، فلا تزال تعود، وهي نجسة، فلا يحكم بطهارته، إلا أنَّهم استحسنوا ترك العمل بموجب القياس للضَّرورة المحوجة إلىٰ ذلك لعامَّة النَّاس، وللضرورة أثرٌ في سقوط الخطاب."]]},{"id":"u90c_10","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ١٠","segs":[["ctx","وعلىٰ كل فإنَّ جميع ما يقول فيه الحنفية بالاستحسان، فإنَّهم قالوه مقروناً بدلائله وحججه، لا علىٰ جهة الشَّهوة واتباع الهوىٰ، ووجوه دلائل مسائل الاستحسان موجودة في كتبهم."]]},{"id":"u90c_11","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ١١","segs":[["ctx","وتقديم الاستحسان علىٰ القياس؛ لقوة أثره؛ لأنَّ المدار علىٰ قوة التَّأثير وضعفه لا علىٰ الظُّهور والخفاء."]]},{"id":"u90c_12","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ١٢","segs":[["ctx","وبهذا التَّفصيل يتبيَّن معنىٰ كلام الإمام محمد بن الحسن الشَّيباني: «كان أبو حنيفة يناظر أصحابه في المقاييس فينتصفون منه، فيعارضونه حتىٰ إذا قال: أستحسن، لم يلحقه أحد منهم؛ لكثرة ما يورد في الاستحسان من المسائل، فَيَدعون جميعاً ويسلمون له»."]]},{"id":"u90c_13","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ١٣","segs":[["ctx","وبما سبق بيانه يتضح أنَّ الاستحسان هو العمل بالدَّليل الأقوىٰ والأحرىٰ بالمسألة، ولا شأن له بالاستحسان العقلي المجرد كما يتوهمه بعضهم، وبهذه الصُّورة فهو محل اتفاق بين أصحاب المذاهب المعتبرة، وإن اختلفت تعبيراتهم في ذكر مسائله، ومن المعلوم أنَّه لا مشاحة في الاصطلاح، وفي ذلك يقول الكوثري: «ظنَّ أناسٌ ممن لم يمارس العلم، ولم يؤت الفهم، أنَّ الاستحسان عند الحنفية هو الحكم بما يشتهيه الإنسان، ويهواه ويلذه، حتىٰ فسّره ابن حزم في «أحكامه» بأنّه ما اشتهته النفس ووافقتها، خطأً أو صواباً !!"]]},{"id":"u90c_14","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ١٤","segs":[["ctx","لكن لا يقول بمثل هذا الاستحسان فقيه من الفقهاء، فلو كان هذا مراد الحنفية بالاستحسان، لكان للمخالفين ملء الحق في تقريعهم والردّ عليهم، إلا أنَّ المخالفين ساءت ظنونهم، وطاشت أحلامهم، فوجَّهوا سهاماً إليهم، ترتد إلىٰ أنفسهم، وذلك لتقاصر أفهامهم عن إدراك مرامهم، ودقّة مدرك هذا البحث في حدّ ذاته."]]},{"id":"u90c_15","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ١٥","segs":[["ctx","وليس بين القائلين بالقياس مَن لا يستحسن بالمعنىٰ الذي يريده الحنفية، وهذا الموضع لا يتسع لذكر نماذج من مذاهب الفقهاء، في الأخذ بالاستحسان، وإبطال الاستحسان ما هو إلا سبق قلم من الإمام الشَّافعي، فلو صحت حججه في إبطال الاستحسان، لقضت علىٰ القياس الذي هو مذهبه، قبل أن يقضي علىٰ الاستحسان."]]},{"id":"u90c_16","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ١٦","segs":[["ctx","ومن الحكايات الطَّريفة في هذا الباب، ما يروىٰ عن إبراهيم بن جابر، أنَّه لما سأله أحد كبار القضاة في عهد المتقي لله العباسي، عن سبب انتقاله من مذهب الشَّافعي إلىٰ مذهب أهل الظَّاهر، جاوبه قائلاً: «إني قرأت إبطال الاستحسان للشَّافعي، فرأيته صحيحاً في معناه، إلا أنَّ جميع ما احتجّ به في إبطال الاستحسان هو بعينه يبطل القياس، فصحّ به عندي بطلانه»، كأنَّه لم يُرد أن يبقىٰ في مذهب يهدُّم بعضه بعضاً، فانتقل إلىٰ مذهب يبطلهما معاً!!"]]},{"id":"u90c_17","kind":"text","label":"ثالثاً: استحسان بأصول الإفتاء · الفقرة ١٧","segs":[["ctx","لكن القياس والاستحسان كلاهما بخير، لم يبطل واحد منهما بالمعنىٰ الذي يريده القائلون بهما، بل الخلاف بين أهل القياس في الاستحسان، لفظي بحت»."]]}],"sup":"المطلب الرَّابع: الاستحسان"},{"id":"u91","title":"الباب الخامس الأحكام","group":"الباب الخامس الأحكام","units":[{"id":"u91_1","kind":"def","label":"الباب الخامس الأحكام · الفقرة ١","segs":[["matn","تمهيد:"],["ctx","إنَّ الحكم يفتقر إلىٰ الحاكم، وهو الله تعالىٰ لا العقل، وإلىٰ المحكوم به، وهو فعل المكلف، وإلىٰ المحكوم عليه، وهو المكلَّف، وتفصيل الكلام عنها في المباحث الآتية."]]}]},{"id":"u93","title":"المطلب الأول: تعريفه","group":"الباب الخامس الأحكام","units":[{"id":"u93_1","kind":"def","label":"المطلب الأول: تعريفه · الفقرة ١","segs":[["matn","عند الأصوليين: هو خطاب الشَّارع المتعلّق بأفعال المكلفين طلباً أو تخييراً أو وضعاً."]]},{"id":"u93_2","kind":"text","label":"المطلب الأول: تعريفه · الفقرة ٢","segs":[["ctx","فالطَّلب يشمل الفرضية والوجوب والسُّنّة والكراهة والحرام."]]},{"id":"u93_3","kind":"text","label":"المطلب الأول: تعريفه · الفقرة ٣","segs":[["ctx","والتَّخيير يشمل المباح."]]},{"id":"u93_4","kind":"text","label":"المطلب الأول: تعريفه · الفقرة ٤","segs":[["ctx","والوضع يكون فيما إن تعلَّق بكون الشَّيء سبباً، أو شرطاً، أو مانعاً، أو صحيحاً، أو فاسداً؛ سُمِّي بذلك؛ لأنَّه متعلّق بوضع الله تعالىٰ وجعله."]]},{"id":"u93_5","kind":"def","label":"المطلب الأول: تعريفه · الفقرة ٥","segs":[["matn","وعند الفقهاء: هو الأثرُ الحاصلُ من خطابِ الله تعالى، ويُقال عنها: الوجوب، والنَّدب، والحرمة، والكراهة، والإباحة."]]},{"id":"u93_6","kind":"text","label":"المطلب الأول: تعريفه · الفقرة ٦","segs":[["ctx","وهكذا كلُّ حكم ثبت بالقرآن أو السُّنّة أو الإجماع أو القياس، سُمِّي خطاب الله تعالىٰ، فليس الخطابُ بالقرآن فقط، فخطاب النَّبي ﷺ يعدُّ خطاباً من الله تعالىٰ؛ لأنَّ الله تعالىٰ أَمرنا بقَبول خطاب النَّبي ﷺ، وكذا ما يثبت بالإجماع أو بالقياس؛ لأنَّهما مُظهران لحكم الله تعالىٰ فقط وليسا مثبتين له."]]}],"sup":"المبحث الأول الحكم"},{"id":"u94","title":"المطلب الثَّاني: أقسامُ الحكم","group":"الباب الخامس الأحكام","units":[{"id":"u94_1","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ١","segs":[["matn","الأوّل: الحكمُ الوضعيّ:"],["matn","وهو أن يكون حكمٌ بتعلّق شيءٍ بشيءٍ آخر"],["ctx",": كالحكم بكون الشَّيء ركناً لشيء، أو علَّة، أو شرط، فإن كان المتعلّق داخلاً في الشَّيء، فهو الرُّكن، وإن لم يكن المتعلِّق داخلاً في الشَّيء، فهو العلَّة والسَّبب والشَّرط والعلامة، وبيانها كالآتي:"]]},{"id":"u94_2","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ٢","segs":[["matn","إحداها: العلَّة:"],["matn","وهي ما كان مؤثِّراً في الشَّيء"],["ctx","، أو هي عبارةٌ عَمّا يُضاف إليه وجوبُ الحكم ابتداءً."]]},{"id":"u94_3","kind":"text","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ٣","segs":[["ctx","وتكون العلَّةُ الشَّرعيّة الحقيقيّة تامّةً بثلاثةِ أشياء: الاسم والمعنىٰ والحكم."]]},{"id":"u94_4","kind":"text","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ٤","segs":[["ctx","فالاسم: أن تكون العلَّة في الشَّرع وضع لهذا الحكم، فيُضاف الحكم إلىٰ هذه العلَّة."]]},{"id":"u94_5","kind":"text","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ٥","segs":[["ctx","والمعنىٰ: أن تكون العلَّةُ مؤثِّرةً في الحكم، فيُضاف الحكمُ إلىٰ العلَّة بلا تخلُّل واسطة بين العلَّة والحكم."]]},{"id":"u94_6","kind":"text","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ٦","segs":[["ctx","والحكم: أن لا يتراخىٰ الحكم عن العلَّة، فيثبت الحكم عند وجودها بلا تراخ."]]},{"id":"u94_7","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ٧","segs":[["ctx","وبناءً علىٰ هذه المعاني الثلاثة يكون"],["matn","للعلَّة سبعة أقسام:"]]},{"id":"u94_8","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ٨","segs":[["ctx","١."],["matn","علّةٌ اسماً وحكماً ومعنى"],["ctx",": كالبيع المطلق، فإنَّه موضوعٌ للملك، والبيع مؤثّرٌ في الملكِ عند وجودِه، فيُضاف الملك إلىٰ البيع بلا واسطة، وينتقل الملك بلا تراخ بتحقق البيع المطلق، ومثله النِّكاح للحل، والقتل للقصاص."]]},{"id":"u94_9","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ٩","segs":[["ctx","٢."],["matn","علّةٌ اسماً ومعنى لا حكماً"],["ctx",": كالبيع بشرط الخيار، فاسماً؛ لأنَّ البيعَ موضوعٌ للملك، ومعنىٰ؛ لأنَّ البيعَ مؤثّرٌ في ثبوتِ الملك، فيُضاف الملك إلىٰ البيع بلا واسطة، لا حُكماً؛ لأنَّ الملك يتراخىٰ عن البيع، حتىٰ يسقط خيار الشَّرط، ومثلُه البيع الموقوف."]]},{"id":"u94_10","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ١٠","segs":[["ctx","٣."],["matn","علَّةٌ اسماً وحكماً لا معنى"],["ctx",": كالسَّفر، فإنَّه علَّةٌ اسماً؛ لأنَّ التَّرخص يُضاف إلىٰ السَّفر، وحكماً؛ لأنَّ الرُّخص تثبت بنفس السَّفر متصلّةً به بلا تراخ، لا معنىٰ؛ لأنَّ المؤثِّر في ثبوتها المشقّة لا نفس السَّفر، وهو ما من باب بإقامة السَّببِ الدَّاعي مقام المدعو إليه كالسَّفر والمرض، فإنَّهما أقيما مقام المشقة، والنوم أقيم مقام استرخاء المفاصل، والنِّكاحُ «العقد» يقوم مقام الوطء في ثبوت النَّسب."]]},{"id":"u94_11","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ١١","segs":[["ctx","٤."],["matn","علّةٌ اسماً لا معنىً ولا حكماً"],["ctx",": كالطَّلاقِ المعلَّق بالشَّرطِ، مثل: إن دخلت الدَّار فأنتِ طالق؛ لأنَّ الطَّلاقَ موضوعٌ في الشَّرع لحكمِه وهو انفصال الرَّجل عن المرأة، فيُضاف الحكمُ إليه عند وجودِ الشَّرط، وهو دخول الدَّار، وليس علّةً معنىٰ؛ لأنَّه لا تأثير للطَّلاق في انفصال الرَّجل عن المرأة قبل وجود الشَّرط، وهو دخول الدَّار، ولا علَّة حُكماً؛ لأنَّ انفصال الرَّجل عن المراة يتأخّر عن الطَّلاق إلىٰ وجودِ الشَّرط، وهو دخول الدَّار."]]},{"id":"u94_12","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ١٢","segs":[["ctx","٥."],["matn","علَّة معنى وحكماً لا اسماً"],["ctx",": كآخر وصفي العلَّة، مثل: إن دخلت دار زيد ودار عمرو فأنت طالق، فليست علّةً اسماً؛ لأنَّ دخول دار عمرو وحده ليس بموضوع للحكم، وهو الطَّلاق. وعلَّةٌ معنىٰ؛ لأنَّ دخولَ دار عمرو مؤثِّرٌ في الحكم، وهو الطَّلاق، وحكماً؛ لأنَّ الحكمَ وهو الطَّلاق يوجد عند دخول دار عمرو بدون تراخ."]]},{"id":"u94_13","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ١٣","segs":[["ctx","٦."],["matn","علّةٌ لها شبهٌ بالسَّبب"],["ctx",": كشراءِ القريب، فإنَّ الشراءَ علّةٌ للملك، والملكُ في القريب علّةٌ للعتق، فيكون العتق مضافاً إلىٰ الشِّراء بواسطةِ الملك، فمن حيث إنَّ العتق لم يوجد إلا بواسطة يعتبر سبباً، ومن حيث ترتب حكم العتق علىٰ علّة الملك يعتبر علَّة يشبه السَّبب."]]},{"id":"u94_14","kind":"def","label":"المطلب الثَّاني: أقسامُ الحكم · الفقرة ١٤","segs":[["ctx","٧."],["matn","وصفٌ له شبهة العلل"],["ctx",": كربا النَّسيئة، وهو جزءُ علّة الرِّبا، فيثبت به ما يثبت بالشُّبهة؛ لأنه أَحد وصفي عِلّة ذات وصفين كالجنس مثل سيارة بسيارتين أو القدر من كيلٍ مثل قمح بأرز أو وزنٍ مثل ذهب بفضة، فيجوز التفاضل في بيعها، لكن لا بُدّ من التَّقابض في المجلس؛ لئلا يتحقَّق في ربا النَّسيئة."]]}],"sup":"المبحث الأول الحكم"},{"id":"u94a","title":"ثانيها: السبب","group":"الباب الخامس الأحكام","units":[{"id":"u94a_1","kind":"def","label":"ثانيها: السبب · الفقرة ١","segs":[["matn","ثانيها: السبب:"],["ctx","وهو ما يكون طريقاً إلىٰ الحكم من غير تأثير، يعني أنَّ السَّبب مفض إلىٰ الحكم وطريق إليه لا مؤثر فيه، فلا بُدّ للحكم من علّةٍ مؤثرةٍ فيه موضوعةٍ له، ولا بُدَّ أن تتوسط هذه العلَّة بين السَّبب وبين الحكم."]]},{"id":"u94a_2","kind":"def","label":"ثانيها: السبب · الفقرة ٢","segs":[["matn","والسَّبب ثلاثة أنواع:"],["ctx","١."],["matn","سببُ حقيقيّ: وهو ما يكون طريقاً إلى الحكم من غير أن يُضاف إليه وجوبٌ ولا وجودٌ ولا يُعقل فيه معاني العلل،"],["ctx","فيخرج بإضافة الوجوب: العلَّة، والوجود: الشَّرط، ويُعقل فيه معاني العلل: السَّبب الذي يُشبه العلَّة والسَّبب الذي فيه معنىٰ العلَّة."]]},{"id":"u94a_3","kind":"text","label":"ثانيها: السبب · الفقرة ٣","segs":[["ctx","فتكون العلَّة في الحقيقي مضافةً إلىٰ السَّبب، نحو: أن تكون العلَّة فعلاً اختيارياً، فلا يُضاف الحكم إلىٰ السَّبب، فمثلاً: لا يضمن الدَّال علىٰ مال يسرقه السَّارق؛ لأنَّه توسُّط بين السَّبب والحكم علَّة، هي فعلُ فاعل مختار، وهو السَّارقُ في السَّرقة، فتقطع هذه العلَّة نسبةَ الحكم إلىٰ السَّبب."]]},{"id":"u94a_4","kind":"def","label":"ثانيها: السبب · الفقرة ٤","segs":[["ctx","٢."],["matn","سبب مجازي"],["ctx",": كالتَّطليق والنَّذر المعلَّقة، فالمعلَّقة صفةٌ للتَّطليق والنَّذر، نحو: إن دخلت الدَّار فأنت طالق، وإن دخلت فلله عليَّ كذا، فالجزاءُ وقوع الطَّلاق ولزوم المنذور؛ لأنَّ هذه الأمور المعلقة ربما لا توصل إلىٰ الجزاء؛ لأنَّ الشَّرط معدوم علىٰ خطر الوجود، وهذا دليل علىٰ كونها سبباً مجازاً: أي هذه التعليقات كلها أسباب مجازية لعدم إفضائها إلىٰ الجزاء إلا عند وجود الشَّرط."]]},{"id":"u94a_5","kind":"def","label":"ثانيها: السبب · الفقرة ٥","segs":[["ctx","وإذا وجد الشَّرط كما في صورة تعليق الطَّلاق والنَّذر يصير الإيجاب السَّابق علَّة حقيقة؛"],["matn","لذلك يعتبر"],["ctx","السَّبب المجازي"],["matn","من العلل"],["ctx","؛ لأنَّه علَّة العلة، إلا أنَّ الحكم يُضاف إلىٰ العلَّة، فلو أضيف إلىٰ السَّبب كان سبباً في معنىٰ العلَّة ـ كما سيأتي ـ."]]},{"id":"u94a_6","kind":"def","label":"ثانيها: السبب · الفقرة ٦","segs":[["ctx","ومن السَّبب المجازي:"],["matn","اليمين بالله تعالى"],["ctx","، سمّيت سبباً للكفَّارة مجازاً؛ لأنَّ اليمين إنَّما عقدت للبرّ، لكنَّها تُفضي إلىٰ الحكم عند زوال المانع، فكانت سبباً باعتبار ما تؤول إليه."]]},{"id":"u94a_7","kind":"def","label":"ثانيها: السبب · الفقرة ٧","segs":[["ctx","٣."],["matn","سببٌ في معنى العلَّة"],["ctx",": بأن كانت العلَّة مضافة إلىٰ السَّبب المتخللة بينه وبين الحكم من غير أن يكون ذلك السَّبب موضوعاً لحكم تلك العلَّة: كوطء الدَّابّة شيئاً فإنَّه علَّة لهلاكه، وهذه العلَّة مضافةٌ إلىٰ سوقها، وهو السَّبب، فالسَّببُ في معنىٰ العلَّة، فيُضاف الحكم إليه فتجب الدِّيَة بسوق الدَّابة وقودها، ولم يجب عليه القصاص الواجب علىٰ المباشر؛ لأنَّ هذا السَّبب لم يوضع للإهلاك، فيلزم الضَّمان ولا يلزم العقاب."]]}],"sup":"المطلب الثَّاني: أقسامُ الحكم"},{"id":"u94b","title":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة","group":"الباب الخامس الأحكام","units":[{"id":"u94b_1","kind":"def","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ١","segs":[["matn","تنبيهٌ: يُطلق السَّبب ويُراد به العلّة:"],["ctx","إنَّ لكلٍّ من الأحكام سبباً ظاهراً يترتّب الحكم عليه:"]]},{"id":"u94b_2","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ٢","segs":[["ctx","فسببُ وجود الإيمان بالله تعالىٰ: حدوث العالم."]]},{"id":"u94b_3","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ٣","segs":[["ctx","وسببُ الصَّلاة: الوقت."]]},{"id":"u94b_4","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ٤","segs":[["ctx","وسببُ الزَّكاة: ملك النصاب."]]},{"id":"u94b_5","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ٥","segs":[["ctx","وسببُ صوم أيام شهر رمضان: كل يوم لصومه."]]},{"id":"u94b_6","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ٦","segs":[["ctx","وسببُ صدقة الفطر: رأس يمونه ويلي عليه ولاية كاملة."]]},{"id":"u94b_7","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ٧","segs":[["ctx","وسببُ الحجّ: البيت الحرام."]]},{"id":"u94b_8","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ٨","segs":[["ctx","وسببُ العُشر: الأرض النَّامية."]]},{"id":"u94b_9","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ٩","segs":[["ctx","وسببُ الخراج: الأرض النَّامية."]]},{"id":"u94b_10","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ١٠","segs":[["ctx","وسببُ الطَّهارة: إرادةُ الصلاة، أما الحدث فشرط وجوب الطَّهارة."]]},{"id":"u94b_11","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ١١","segs":[["ctx","وسببُ الحدود والعقوبات: ما نسبت إليه من سرقة وقتل."]]},{"id":"u94b_12","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ١٢","segs":[["ctx","وسببُ الكفَّارات: ما نسبت إليه من أمر دائر بين الحظر والإباحة."]]},{"id":"u94b_13","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ١٣","segs":[["ctx","وسببُ شرعية المعاملات: البقاء المُقَدَّر للعالم."]]},{"id":"u94b_14","kind":"text","label":"تنبيهٌ: يُطلق السَّبب ويُراد به العلّة · الفقرة ١٤","segs":[["ctx","وسببُ الاختصاصات الشَّرعية: التَّصرفات المشروعة كالبيع والنِّكاح ونحوهما."]]}],"sup":"المطلب الثَّاني: أقسامُ الحكم"},{"id":"u94c","title":"ثالثها: الشَّرط","group":"الباب الخامس الأحكام","units":[{"id":"u94c_1","kind":"def","label":"ثالثها: الشَّرط · الفقرة ١","segs":[["matn","ثالثها: الشَّرط:"],["ctx","وهو ما يتوقَّف عليه وجود الشَّيء وليس بمؤثر فيه، أو ما يتعلَّق به الوجود لا الوجوب: أي دون أن يكون مؤثِّراً في وجوده."]]},{"id":"u94c_2","kind":"def","label":"ثالثها: الشَّرط · الفقرة ٢","segs":[["matn","والشَّرط أنواع:"],["ctx","١."],["matn","شرطٌ محضٌ"],["ctx",": وهو الذي يتوقّف انعقاد العلَّة علىٰ وجوده، مثل دخول الدَّار بالنِّسبة إلىٰ وقوع الطَّلاق المُعَلَّق به في قوله: إن دخلتِ الدَّار فأنتِ طالق، فإنَّ انعقاد قوله: أنتِ طالق علَّة لوقوع الطَّلاق موقوف علىٰ وجوده وليس له تأثير فيه."]]},{"id":"u94c_3","kind":"def","label":"ثالثها: الشَّرط · الفقرة ٣","segs":[["ctx","٢."],["matn","شرط في حكم العلَّة"],["ctx",": وهو شرطٌ لا يُعارضه علَّةٌ تصلح أن يُضافَ الحكمُ إليها، فيُضاف إليه، مثاله: كحافر البئر في الطريق أو في ملك غيره، فالشَّرطُ هو الحفر؛ لأنَّ علَّة السُّقوط هو الثّقل، لكن الأرض مانعة عن السُّقوط، فبإزالة المانع صارت شرطاً للسُّقوط، وعلَّة السُّقوط وهي الثّقل لا تصلح لإضافة الحكم، وهو الضَّمان إليها؛ لأنَّ المشي أمر طبيعي مباح، فلا يصلح لإضافة الحكم، فيُضافُ إلىٰ الشَّرط؛ لأنَّ صاحبَ الشَّرط متعدّ؛ لأنَّ الضَّمانَ فيما إذا حَفَرَ في غير ملكه، وكذلك شق الزّق الذي فيه مائع، فإنَّه شرط، والعلَّة مَيَعَانه، وهي علّةٌ غير صالحة لإضافة الحكم إليها، فأضيف إلىٰ الشَّرط وهي الشقّ."]]},{"id":"u94c_4","kind":"def","label":"ثالثها: الشَّرط · الفقرة ٤","segs":[["ctx","٣."],["matn","شرطٌ له حكم السَّبب"],["ctx",": وهو الشَّرط الذي تخلل بينه وبين مشروطه فعل فاعل مختار غير منسوب لذلك الشَّرط، كما إذا فتح باب قفص أو اصطبل، حتىٰ خرج الطَّير وهربت الدَّابة، فلا يضمن عند الشَّيخين، لأنَّ فتح الباب سبب، والخروج والهروب علّة التَّلف، فلَمّا سَبَق الفتح للخروج والهروب صار شرطاً في حكم السَّبب، وهو أمر سابق اعترض بينه وبين الحكم فعل فاعل مختار، وهو الطَّير والدَّابة، فلا يُضاف الحكم إلىٰ الشَّرط الذي بِحُكم السَّبب."]]},{"id":"u94c_5","kind":"def","label":"ثالثها: الشَّرط · الفقرة ٥","segs":[["ctx","٤."],["matn","شرطٌ مجازاً"],["ctx",": أي اسماً لا حكماً: كأوّل الشَّرطين في حكم يتعلَّق بهما، فيفتقر الحكم إلىٰ وجود الشَّرط الأول ولا يوجد عند وجود الشَّرط الأول، كقوله لامرأته: إن دخلت هذه الدَّار وهذه الدَّار فأنتِ طالق، فمَن حيث إنَّه يتوقف الحكم عليه سُمّي شرطاً، ومن حيث إنَّه لا يوجد عنده لا يكون شرطاً حكماً."]]},{"id":"u94c_6","kind":"def","label":"ثالثها: الشَّرط · الفقرة ٦","segs":[["matn","رابعها: العلامة:"],["ctx","وهي ما لا يتوقف عليه الشَّيء، ولكن دلَّ علىٰ وجوده، أو ما جُعل عَلَماً علىٰ الوجود من غير أن يتعلَّق به وجوب ولا وجود."]]},{"id":"u94c_7","kind":"text","label":"ثالثها: الشَّرط · الفقرة ٧","segs":[["ctx","ومثالها: الإحصان مع أنَّ وجوب الرَّجم موقوف عليه، وسمَّاه بعضُهم شرطاً فيه معنىٰ العلامة."]]}],"sup":"المطلب الثَّاني: أقسامُ الحكم"},{"id":"u94d","title":"الثَّاني: الحكمُ التَّكليفيُّ","group":"الباب الخامس الأحكام","units":[{"id":"u94d_1","kind":"def","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ١","segs":[["matn","الثَّاني: الحكمُ التَّكليفيُّ:"],["matn","وهو ما لا يكون حُكماً بتعلّق شيءٍ بشيءٍ آخر، كأن يكون أثراً لفعل المكلّف"],["ctx",": كالملك، فإنَّه آثرٌ لفعل المكلّف؛ إذ الشِّراء فعلُ المكلّف وأَثره، وحكمه: تَمَلُّك البائع الثَّمن، وتَمَلُّك المشتري المبيع، وهذا ليس محل بحثنا هنا،"],["matn","أو يكون صفةً لفعل المكلّف"],["ctx",": كالوجوبِ والحرمةِ، فإنَّها صفات لفعل المكلَّف؛ إذ تقول: الصَّلاةُ واجبةٌ."]]},{"id":"u94d_2","kind":"def","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ٢","segs":[["matn","الأولىٰ: اعتبار المقاصد الدُّنيوية:"],["ctx","فالمقصودُ الدُّنيوي في العبادات تفريغُ الذِّمّة: أي أداء العبادة علىٰ وجهها الصَّحيح بحيث لا تحتاج إلىٰ إعادة وقضاء، وفي المعاملات الاختصاصات الشَّرعية: أي الأغراض المترتبة علىٰ العقود والفسوخ كملك الذَّات في البيع، وملك المنفعة في الإجارة، فكان النَّظر هاهنا من حيث ترتب المنافع الدُّنيوية دون الأُخروية."]]},{"id":"u94d_3","kind":"text","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ٣","segs":[["ctx","ففعل المكلّف في المقاصد الدُّنيوية ينقسم بالنَّظر إليه تارةً إلىٰ صحيح وباطل وفاسد، وتارة إلىٰ منعقد وغير منعقد، وتارة إلىٰ نافذ وغير نافذ، وتارة إلىٰ لازم وغير لازم علىٰ النَّحو الآتي:"]]},{"id":"u94d_4","kind":"def","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ٤","segs":[["ctx","١."],["matn","الصَّحيح"],["ctx",": بأن يقع الفعل بحيث يوصل إلىٰ المقصود الدُّنيوي، ويقال له: ما يكون مشروعاً بأصله ووصفه."]]},{"id":"u94d_5","kind":"def","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ٥","segs":[["ctx","٢."],["matn","غير الصَّحيح"],["ctx",": بأن كان الفعل لا يوصل إلىٰ المقصود الدُّنيوي، وله صورتان:"]]},{"id":"u94d_6","kind":"def","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ٦","segs":[["ctx","أ."],["matn","الباطل"],["ctx",": إن كان عدم إيصاله إليه من جهة خلل في أركانه وشرائطه، ويقال له: ما لا يكون مشروعاً بأصله ولا بوصفه: كبيع الميتة والدَّم، أو لانعدام أهليّة المتصرّف: كبيع الصَّبيّ والمجنون."]]},{"id":"u94d_7","kind":"def","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ٧","segs":[["ctx","ب."],["matn","الفاسد"],["ctx",": إن كان عدم إيصاله إليه من غير خلل في أركانه، ويقال له: ما يكون مشروعاً بأصله دون وصفه."]]},{"id":"u94d_8","kind":"def","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ٨","segs":[["ctx","٣."],["matn","الانعقاد"],["ctx",": وهو ارتباطُ أجزاء التَّصرف «الإيجاب والقبول» شرعاً، فالبيع الفاسد منعقد لا صحيح."]]},{"id":"u94d_9","kind":"def","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ٩","segs":[["ctx","٤."],["matn","النَّفاذ"],["ctx",": وهو ترتب الأثر علىٰ التَّصرّف: كالملك، فبيع الفضولي منعقد لا نافذ."]]},{"id":"u94d_10","kind":"def","label":"الثَّاني: الحكمُ التَّكليفيُّ · الفقرة ١٠","segs":[["ctx","٥."],["matn","اللزوم"],["ctx",": أن يكون التصرّف بحيث لا يمكن رفعه: كالبيع الصَّحيح بلا خيار شرط وعيب ورؤية."]]}],"sup":"المطلب الثَّاني: أقسامُ الحكم"},{"id":"u94e","title":"الثَّانية: اعتبار المقاصد الأُخروية","group":"الباب الخامس الأحكام","units":[{"id":"u94e_1","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١","segs":[["matn","الثَّانية: اعتبار المقاصد الأُخروية:"],["ctx","فالمقصود الأُخروي يكون بتحصيل الثَّواب والابتعاد عن العقاب، فمثلاً: إن فَعَلَ الوجوب يُثاب، وإن تَرَكَهُ يُعاقب."]]},{"id":"u94e_2","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ٢","segs":[["matn","أقسام المقاصد الأُخروية:"],["matn","أولاً: أن يكون حكماً أصلياً، ويُسمّى عزيمة"],["ctx","؛ لأنَّه غيرُ مبنيّ علىٰ أعذار العباد،"],["matn","وهو أنواع:"]]},{"id":"u94e_3","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ٣","segs":[["ctx","١."],["matn","الفرض"],["ctx",": أن يكون الفعل أولىٰ من التَّرك مع منع التَّرك بدليل بقطعي."]]},{"id":"u94e_4","kind":"text","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ٤","segs":[["ctx","وحكمه: لازمٌ علماً وعملاً حتىٰ يكفر جاحده: أي يلزم اعتقاد حقّيَّته والعمل بموجبه لثبوته بدليل قطعي حتىٰ لو أنكره قولاً أو اعتقاداً كان كافراً، ويعاقب تارك الفرض للآيات والأحاديث الدالة علىٰ وعيد العصاة إلا أن يعفو الله تعالىٰ بفضله وكرمه، أو بتوبة العاصي وندمه ؛ للنُّصوص الدالة علىٰ العفو والمغفرة؛ ولأنَّه حق الله تعالىٰ فيجوز له العفو."]]},{"id":"u94e_5","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ٥","segs":[["ctx","٢."],["matn","الواجب"],["ctx",": أن يكون الفعل أولىٰ من الترك مع منع التَّرك بدليل ظني."]]},{"id":"u94e_6","kind":"text","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ٦","segs":[["ctx","وحكمه: يلزم اعتقاد حقيّته؛ لثبوته بدليل ظنيّ، ومبنىٰ الاعتقاد علىٰ اليقين، لكن يلزم العمل بموجبه للدَّلائل الدَّالّة علىٰ وجوب اتّباع الظَّنّ، فجاحدُه لا يكفر، وتارك العمل به إن كان مؤولاً لا يفسق ولا يُضلّل؛ لأنَّ التَّأويلَ في مظانّه من سيرة السَّلف، وإن ترك العمل به بلا تأويل فإن كان مستخّفاً يُضلل؛ لأنَّ ردَّ خبر الواحد والقياس بدعةٌ، وإن لم يكن مؤولاً ولا مستخفاً يفسَّق لخروجه عن الطَّاعة بترك ما وجب عليه، ويُعاقب بتركِ الواجب إلا أن يعفو الله تعالىٰ ـ كما سبق في الفرض ـ."]]},{"id":"u94e_7","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ٧","segs":[["ctx","٣."],["matn","السُّنَّة"],["ctx",": أن يكون الفعل أولىٰ من التَّرك بلا منع التَّرك، وهي نوعان:"]]},{"id":"u94e_8","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ٨","segs":[["ctx","أ."],["matn","سننُ الهُدى"],["ctx",": إن كان الفعلُ طريقةً مسلوكةً في الدِّين: أي يتعلَّق بإقامةِ شعائر الدِّين: كالجماعةِ والأذان والإقامة ونحوها، أو ما كانت المواظبةُ من النَّبيِّ ﷺ مع التَّرك أحياناً علىٰ سبيل العبادة."]]},{"id":"u94e_9","kind":"text","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ٩","segs":[["ctx","وحكمُها: أنَّ تركَها يوجب إساءةً وكراهيةً؛ فعن أبي هريرة رضي الله عنه قال ﷺ: «مَن رَغِبَ عن سنتي فليس مني»، وعن عائشة رضي الله عنها، قال ﷺ: «ستة لعنتهم: الزَّائد في كتاب الله، والمُكَذِّب بقدر الله تعالىٰ، والمُتسلط علىٰ أُمتي بالجبروت؛ ليذلّ مَن أعزّه الله تعالىٰ، ويُعزّ مَن أذله الله تعالىٰ، والمُستحلّ لحرم الله تعالىٰ، والمُستحلّ من عترتي، والتَّارك لسنتي»."]]},{"id":"u94e_10","kind":"text","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١٠","segs":[["ctx","وعن ابن مسعود رضي الله عنه: «مَن سرَّه أن يلقىٰ الله تعالىٰ غداً مسلماً فليحافظ علىٰ هؤلاء الصلوات حيث ينادىٰ بهنّ، فإنّ الله تعالىٰ شرع لنبيكم ﷺ سنن الهدىٰ، وإنّهنّ من سنن الهدىٰ، ولو أنكم صلَّيتم في بيوتكم كما يُصلِّي هذا المتخلِّف في بيته لتركتم سُنَّة نبيّكم، ولو تركتم سنة نبيكم لضللتم»."]]},{"id":"u94e_11","kind":"text","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١١","segs":[["ctx","قال اللكنوي: «والأخبار المفيدة لهذا المطلب كثيرةٌ شهيرةٌ، وقد سلك ابن الهمام في «فتح القدير» علىٰ أنَّ الإثم منوط بترك الواجب، وردَّه صاحبُ «البحر الرَّائق» وغيره بأحسن رد»، وقال ابن نجيم: «الأصحّ أنَّه يأثم بترك المؤكدة؛ لأنَّها في حكم الواجب، والإثم مقول بالتَّشكيك هو في الواجب أقوىٰ منه في المؤكَّدة»."]]},{"id":"u94e_12","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١٢","segs":[["ctx","ب."],["matn","سنن الزَّوائد"],["ctx",": ما كانت المواظبة من النَّبي ﷺ مع التَّرك أحياناً علىٰ سبيل العادة، وهي مما يتعلَّق بأفعال النبي ﷺ الجبلية كسنن النبي ﷺ في لباسه وقيامه وقعوده والأكل باليمين وتقديم الرجل اليمنىٰ في الدُّخول."]]},{"id":"u94e_13","kind":"text","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١٣","segs":[["ctx","وحكمها: أنَّ تركها لا يوجب إساءة وكراهة."]]},{"id":"u94e_14","kind":"text","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١٤","segs":[["ctx","قال ابنُ نجيم: «كأنَّهم أرادوا بسنن الزّوائد السُّنن التي ليست بمؤكدةٍ فتارةً يُطلقون عليها اسم السُّنة، وتارةً المستحبّ، وتارة المندوب، وقد فرَّق الفقهاء بين الثلاثة فقالوا: ما واظب النبي ﷺ علىٰ فعله مع ترك ما بلا عذر سنة، وما لم يواظب مستحب إن استوىٰ فعله وتركه ﷺ، ومندوب إن ترجَّح تركه علىٰ فعله ﷺ بأن فعله مرة أو مرتين، والأصوليون لم يفرقوا بين المستحبّ والمندوب»."]]},{"id":"u94e_15","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١٥","segs":[["ctx","٤."],["matn","الحرام"],["ctx",": أن يكون التَّركُ أَوْلَىٰ من الفعل مع منع الفعل."]]},{"id":"u94e_16","kind":"text","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١٦","segs":[["ctx","وحكمُه: أنَّه يُعاقب علىٰ فعلِه."]]},{"id":"u94e_17","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١٧","segs":[["ctx","٥."],["matn","المكروه"],["ctx",": أن يكون التَّرك أولىٰ من الفعل، بلا منع الفعل، وهو نوعان:"]]},{"id":"u94e_18","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١٨","segs":[["ctx","أ."],["matn","مكروهٌ كراهة تنزيه"],["ctx",": وهو إلىٰ الحلِّ أقرب اتفاقاً: أي لا يعاقب فاعله أصلاً، لكن يثاب تاركه أدنىٰ ثواب؛ لأنَّه ليس من الحلال، ولا يلزم من عدم الحل الحرمة، ولا كراهة التَّحريم؛ لأنَّ المكروه تنزيهاً مرجعُه إلىٰ ترك الأولىٰ."]]},{"id":"u94e_19","kind":"text","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ١٩","segs":[["ctx","وكراهة التَّنزيه تقابل ترك المستحبات."]]},{"id":"u94e_20","kind":"def","label":"الثَّانية: اعتبار المقاصد الأُخروية · الفقرة ٢٠","segs":[["ctx","ب."],["matn","مكروهٌ كراهة تحريم"],["ctx",": وهو إلىٰ الحرمة أقرب علىٰ المختار؛ لتعارض الأدلة فيه، وتغليب جانب الحرمة، فيلزم تركه، وهذا قول أبي حنيفة وأبي يوسف رضي الله عنهم، وهو الصَّحيح؛ لما روي: «ما اجتمع الحلال والحرام إلا وقد غلبَ الحرامُ الحلال»، قالوا معناه: دليلُ الحلِّ ودليلُ الحرمة، فالحرام يجب تركه، والحلال يُباح فعله."]]}],"sup":"المطلب الثَّاني: أقسامُ الحكم"},{"id":"u94f","title":"وكراهة التَّحريم علىٰ نوعين","group":"الباب الخامس الأحكام","units":[{"id":"u94f_1","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١","segs":[["matn","وكراهة التَّحريم علىٰ نوعين:ـ"],["matn","ما يكون بترك الواجب"],["ctx","، قال ابن الهمام: «وهو ما تركه واجب، ويثبت بما يثبت به الواجب»، ويثبت بقطعيّ الثُّبوت ظنيّ الدَّلالة كالآيات المؤولة، وظنيّ الثُّبوت قطعيّ الدَّلالة كأخبار الآحاد التي مفهومها قطعيّ."]]},{"id":"u94f_2","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٢","segs":[["ctx","وحكمه: استحقاق الإثم والعقوبة بالنَّار."]]},{"id":"u94f_3","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٣","segs":[["ctx","ـ"],["matn","ما يكون بترك سُنّة مؤكّدة"],["ctx","، قال ابن عابدين: «ترك السُّنة المؤكدة مكروهٌ تحريماً... والمراد سنن الهدىٰ: كالجماعة والأذان والإقامة، فإنَّ تاركها مضلل ملوم... والمراد التَّرك علىٰ وجه الإصرار بلا عذر؛ ولذا يُقاتل المجمعون علىٰ تركها؛ لأنَّها من أَعلام الدِّين، فالإصرار علىٰ تركها استخفاف بالدِّين، فيقاتلون علىٰ ذلك»، ويثبت بظنيّ الثُّبوت وظنيّ الدَّلالة كأخبار الآحاد التي مفهومها ظني."]]},{"id":"u94f_4","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٤","segs":[["ctx","وحكمُه: أن يتعلّق به محذور دون استحقاق العقوبة بالنار، بل العتاب، فيستحقّ حرمان شفاعة النبي المختار ﷺ، لقوله: ﷺ: «مَن رغب عن سنتي فليس مني»."]]},{"id":"u94f_5","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٥","segs":[["ctx","٥."],["matn","المباح"],["ctx",": أن لا يكون الفعل والترك أحدهما أولىٰ من الآخر، أو ما أجيز للمكلفين فعله وتركه بلا استحقاق ثواب وعقاب، أو ما خير المكلف بين فعله وتركه."]]},{"id":"u94f_6","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٦","segs":[["ctx","وحكمة مشروعية المباح: هي ترويح النُّفوس المكلفة من مشقة القيام بتلك الأحكام الأربعة الباقية، التي هي: الفرض والمندوب فعلاً، والحرام والمكروه تركاً."]]},{"id":"u94f_7","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٧","segs":[["ctx","والمباح قابل أن يصير طاعةً بالنية الحسنة : كالأكل مقدار الشبع؛ ليتقوىٰ به علىٰ طاعة الله تعالىٰ، وأن يصير معصية بالنية القبيحة كلبس الثياب الفاخرة؛ لأجل التَّكبر علىٰ غيره."]]},{"id":"u94f_8","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٨","segs":[["matn","ثانياً: أن لا يكون حكماً أصلياً، ويُسمّى رخصةً"],["ctx","، لكونه مبنيّاً علىٰ أعذار العباد، فيتغيّر من عسرٍ إلىٰ يسرٍ بعذرٍ،"],["matn","وهو نوعان:"]]},{"id":"u94f_9","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٩","segs":[["ctx","١."],["matn","ما يطلق عليه الرُّخصة حقيقة، وله حالتان:"]]},{"id":"u94f_10","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١٠","segs":[["ctx","أ."],["matn","أولية الرُّخصة على العزيمة وإن بذل نفسه أخذاً بالعزيمة فهو مأجورٌ"],["ctx",": وهو ما استبيح مع قيام دليل المحرم ووجود حكم الحرمة، ومن أمثلتها:"]]},{"id":"u94f_11","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١١","segs":[["ctx","إجراء كلمة الكفر مكرهاً بالقتل أو القطع مع قيام دليل المحرّم، وهو الدَّلائل الدَّالة علىٰ وجوب الإيمان قائمة، ووجود حرمة الكفر؛ لقيام أدلة وجوب الإيمان، لكن حقُّ العبد يفوت بتحقيق الإكراه، وحقّ الله تعالىٰ لا يفوت معنىٰ؛ لأنَّ قلبه مطمئنٌ بالإيمان، فله أن يجري الكفر علىٰ لسانه."]]},{"id":"u94f_12","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١٢","segs":[["ctx","والإفطار في رمضان للمكرَه، فيُرَخَّصُ له في الإفطار مع قيام دليل الحكم، وهو شهود الشَّهر وقيام حُرمةِ الفطر."]]},{"id":"u94f_13","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١٣","segs":[["ctx","والأكل من مال الغير للمكرَه، فيرخص في الأكل مع قيام دليل الحرمة، وهو عصمة مال المسلم والذِّمي ووجود الحرمة."]]},{"id":"u94f_14","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١٤","segs":[["ctx","والتَّرك للصَّلاة ونحوها للمكرَه، فيرخص له في التَّرك مع قيام دليل فرضية الصَّلاة، ووجود الحرمة."]]},{"id":"u94f_15","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١٥","segs":[["ctx","ب."],["matn","أوليّة العزيمة على الرُّخصة بشرط أن لا يبذل نفسه أخذاً بالعزيمة فيكون آثماً:"],["ctx","وهو ما استبيح مع قيام دليل المحرّم دون حكم الحرمة، ومثالها:"]]},{"id":"u94f_16","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١٦","segs":[["ctx","إفطار المسافر، فإنَّ دليل المحرّم للإفطار، وهو شهود الشَّهر قائم، لكن حرمة الإفطار غير قائمة، رخص بناءً علىٰ تراخي الحكم السَّبب، فدليل المحرِّم للإفطار: ﴿فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ﴾ [البقرة: ١٨٥]، والحكم وجوب الصَّوم، وقد تراخىٰ لقوله جل جلاله: ﴿فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ﴾ [البقرة: ١٨٤]، والعزيمة أولىٰ من الرُّخصة؛ لقيام دليل المحرّم للإفطار، قال ﷺ: «مَن أفطر فرخصة، ومَن صام فالصَّوم أفضل»، ولأنَّ في العزيمة نوع يسر لموافقة المسلمين، لكن إن خاف أن يضعفَه الصَّوم، فليس له أن يبذل نفسه؛ لأنَّه يصير قاتل نفسه."]]},{"id":"u94f_17","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١٧","segs":[["ctx","والفرق بين الحالتين: أنَّ الوجوب مع رخصة التَّرك في المسافر كان ثابتاً قبل إضعاف النَّفس، فلا بد وأن يكون للإضعاف حكماً آخر لم يكن ثابتاً قبله، وليس ذلك إلا إسقاط الوجوب رأساً، وإثبات الإباحة المطلقة، وأما في إجراء كلمة الكفر وما شابهها، فإنَّ الإكراه من أسباب الرُّخصة، فكان أثر الإكراه في إثبات رخصة التَّلفظ لا في إسقاط حرمة الكفر، فكان حقّ الله جل جلاله قائماً، وكان في الامتناع باذلاً نفسه لإقامة حق الله جل جلاله، فكان أفضل."]]},{"id":"u94f_18","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١٨","segs":[["ctx","٢."],["matn","ما يطلق عليه الرُّخصة مجازاً"],["ctx","، وله حالتان:"]]},{"id":"u94f_19","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ١٩","segs":[["ctx","أ."],["matn","الأقرب للمجازية"],["ctx",": وهو ما وضع عنّا من الإصر والأغلال، ويُسمّىٰ رخصةً مجازاً؛ لأنَّ الأصل لم يبق مشروعاً أصلاً، وعرَّفه بعضهم: «هو فيما وضع عن هذه الأُمَّة من التَّكاليف الغليظة والأعمال الشَّاقة التي دلَّ عليها قوله جل جلاله: ﴿رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ﴾ [البقرة: ٢٨٦]، وقوله جل جلاله: ﴿وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡۚ﴾ [الأعراف: ١٥٧]»."]]},{"id":"u94f_20","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٢٠","segs":[["ctx","ومن أمثلته: اشتراط قتل النَّفس في صحّة التَّوبة، والقصاص في القتل العمد والخطأ، وقطع موضع النَّجاسة من الثَّوب، وعدم جواز الصَّلاة في غير المسجد، قال ﷺ: «جعلت لي الأرض طهوراً ومسجداً»، وغير ذلك من التَّكاليف التي كانت واجبة في الشَّرائع السَّالفة، فمن حيث إنَّها كانت واجبة علىٰ غيرنا ولم تجب علينا كانت توسعة وتخفيفاً، فأشبهت الرُّخصة وسُمِّيت بها."]]},{"id":"u94f_21","kind":"def","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٢١","segs":[["ctx","ب."],["matn","الأقرب للحقيقة"],["ctx","، وهو ما سقط مع كونه مشروعاً في الجملة، فمن حيث إنَّه سقط كان مجازاً، ومن حيث إنَّه مشروع في الجملة كان شبيهاً بحقيقة الرُّخصة: كأكل الميتة وشرب الخمر ضرورة، فإنَّ حرمتَها ساقطةٌ في حال الضَّرورة مع كونها ثابتة في الجملة؛ لقوله جل جلاله: ﴿إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ﴾ [الأنعام: ١١٩]، فإنَّه استثناء من الحرمة؛ ولأنَّ الحرمة لصيانة عقل، ولا صيانة عند فوت النَّفس."]]},{"id":"u94f_22","kind":"text","label":"وكراهة التَّحريم علىٰ نوعين · الفقرة ٢٢","segs":[["ctx","وعرَّفه بعضُهم: «ما بقي مشروعاً في حق بعض الأشياء، وأُسقط عن البعض الآخر: كتصحيح بعض العقود التي لم تتوافر فيها الشُّروط العامَّة لانعقاد العقد وصحَّته، ولكن جرت بها معاملات النَّاس وصارت من حاجاتهم، وحكمه: أنَّ العزيمة لا تبقىٰ مشروعة فيه»، كترخيصُ النَّبيّ ﷺ في السَّلَم؛ إذ قال ﷺ: «مَن أسلف فلا يُسلف إلا في كيلٍ معلومٍ ووزنٍ معلوم»، فإنَّ الأصل في البيع أن يلاقي عيناً؛ لقوله ﷺ: «لا تبع ما ليس عندك»، وهذا حكمٌ مشروعٌ، لكنَّه سقط في السَّلَم حتىٰ لم يبق التَّعيين عزيمةً ولا مشروعاً."]]}],"sup":"المطلب الثَّاني: أقسامُ الحكم"},{"id":"u95","title":"المبحث الثاني المحكوم به","group":"الباب الخامس الأحكام","units":[{"id":"u95_1","kind":"text","label":"المبحث الثاني المحكوم به · الفقرة ١","segs":[["ctx","وهو الفعلُ الذي تعلَّق به خطاب الشَّارع: أي فعل المكلَّف من صلاةٍ وصومٍ ووفاءٍ بالعقود وغيرها."]]},{"id":"u95_2","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ٢","segs":[["matn","أنواع المحكوم به:"],["matn","أولاً: حقوق الله تعالى"],["ctx","، وهو ما يتعلَّق به النَّفع العام من غير اختصاص بأحدٍ، فيُنسب إلىٰ الله تعالىٰ لعظم خطره وشمول نفعه،"],["matn","وهي ثمانية:"]]},{"id":"u95_3","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ٣","segs":[["ctx","١."],["matn","عباداتٌ خالصةٌ"],["ctx",": كالإيمان وفروعه، وكلٌّ مشتملٌ علىٰ الأصل والملحق به والزَّوائد، فالإيمان أصله التَّصديق، والإقرار ملحق به، حتىٰ إنَّ من تركه مع القدرة عليه لم يكن مؤمناً عند الله تعالىٰ وعند النَّاس، وهذا عند بعض علمائنا، أمّا عند البعض فالإيمان: هو التَّصديق، والإقرار شرط لإجراء الأحكام الدُّنيوية، وهو أصل في حق الأحكام الدُّنيوية اتفاقاً حتىٰ صح إيمان المكره في حق الدُّنيا، ولا تصح ردّته؛ لأنَّ الأداءَ دليلٌ محض لا ركن، وزوائد الإيمان الأعمال."]]},{"id":"u95_4","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ٤","segs":[["ctx","٢."],["matn","عبادةٌ فيها مؤنة"],["ctx",": كصدقةِ الفطر، فلم يشترط لها كمال الأهلية؛ لما فيها من معنىٰ المؤنة، لم يشترط لها كمال الأهليّة المشروطة في العبادات الخالصة، فوجبت في مال الصَّبيِّ والمجنونِ؛ اعتباراً لجانبِ المؤنة."]]},{"id":"u95_5","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ٥","segs":[["ctx","٣."],["matn","مؤنةٌ فيها عقوبة"],["ctx",": كالخراج فلا يبتدأ علىٰ المسلم لكنَّه يبقىٰ في أرض الذِّمي بعد شراء المسلم لها؛ لأنَّ الخراج لّما تردَّدَ بين العقوبة والمؤنة فلا يبطل بالشَّكِّ، فهو مؤنةٌ باعتبار الأصل، وهو الأرض، عقوبةٌ باعتبار الوصف."]]},{"id":"u95_6","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ٦","segs":[["ctx","٤."],["matn","مؤنةٌ فيها عبادة"],["ctx",": كالعُشر في الأرض العشرية علىٰ المسلم، فإن اشتراها ذمي ينقلب خراجاً."]]},{"id":"u95_7","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ٧","segs":[["ctx","٥."],["matn","حقٌّ قائمٌ بنفسه"],["ctx",": أي ثابت بذاته من غير أن يتعلّق بذمّة عبد يؤدّيه بطريق الطَّاعة: كخُمس الغنائم والمعادن، فإنَّ الجهادَ حقّ الله تعالىٰ إعزازاً لدينه، وإعلاءً لكلمته، فالمصاب به كله حق الله تعالىٰ، إلا أنَّه جعل أربعة أخماس للغانمين؛ امتناناً، واستبقىٰ الخُمس حقّاً له."]]},{"id":"u95_8","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ٨","segs":[["ctx","٦."],["matn","عقوباتٌ كاملة"],["ctx",": كالحدود."]]},{"id":"u95_9","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ٩","segs":[["ctx","٧."],["matn","عقوباتٌ قاصرة"],["ctx",": كحرمان الميراث بالقتل، فلا يثبت في حقّ الصَّبيِّ؛ لأنَّه لا يوصف بالتَّقصير، والبالغُ الخاطئُ مقصِّرٌ فلزمه الجزاء القاصر من الدِّيَة دون القصاص، ولا يثبت حرمان الميراث في القتل بسبب: كحفر البئر ونحوه."]]},{"id":"u95_10","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ١٠","segs":[["ctx","٨."],["matn","حقوقٌ دائرةٌ بين العبادةِ والعقوبة"],["ctx",": كالكفّارات فلا تجب علىٰ الصَّبي؛ لأنَّه لا يوصف بالتَّقصير فلا يستحق العقوبة، ولا تجب علىٰ الكافر؛ لأنَّها عبادة، والكافر ليس أهلاً للعبادة."]]},{"id":"u95_11","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ١١","segs":[["matn","ثانياً: حقوق العباد"],["ctx",": وهو ما يتعلّق به مصلحة خاصّة، وهو أكثر من أن يحصىٰ: كحرمة مال الغير، وبدل المُتلفات، وبَدل المغصوب والدِّيَة وملك المبيع والثَّمن، وملك النِّكاح والطَّلاق وما أشبهها."]]},{"id":"u95_12","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ١٢","segs":[["matn","ثالثاً: ما اجتمع فيه الحقَّان، وحقّ الله تعالى غالب"],["ctx",": كحدّ القذف، فإنَّه زاجر يعود نفعه إلىٰ عامّة العباد، وفيه دفع العار عن المقذوف، هذا حق العبد، ولغلبة حقّ الله تعالىٰ يجري فيه التَّداخل، حتىٰ لو قَذف جماعةً بكلمةٍ أو بكلمات متفرّقة لا يقام عليه إلا حَدٌّ واحد، ولا يجري فيه الإرث، ولا يسقط بعفو المقذوف."]]},{"id":"u95_13","kind":"def","label":"المبحث الثاني المحكوم به · الفقرة ١٣","segs":[["matn","رابعاً: ما اجتمع فيه الحقّان، وحَقُّ العبد غالب"],["ctx",": كالقصاص، ففي شرعيّة القصاص إبقاء للحقّين وإخلاء العالم عن الفساد، ولغلبة حق العبد يجري في القصاص الإرث والاعتياض بالمال وصحّة العفو."]]}]},{"id":"u96","title":"المبحث الثَّالث الحاكم","group":"الباب الخامس الأحكام","units":[{"id":"u96_1","kind":"text","label":"المبحث الثَّالث الحاكم · الفقرة ١","segs":[["ctx","اتفق علماء المسلمين علىٰ أنَّ الأحكام الشَّرعية لجميع أفعال المكلفين مصدرها الله تعالىٰ، لا فرق بين أن تكون صادرةً منه مباشرةً بالنُّصوص التي أرسلها إلىٰ رُسله، أو أن يهتدي إليها المكلَّف بواسطة الدَّلائل والأمارات التي شَرعها لاستنباط أحكامه؛ ولهذا اتفقت كلمتُهم علىٰ تعريفِ الحكمِ الشَّرعي: بأنَّه خطابُ الله تعالىٰ المتعلِّق بأفعال المكلَّفين طلباً أو تخييراً أو وضعاً."]]},{"id":"u96_2","kind":"text","label":"المبحث الثَّالث الحاكم · الفقرة ٢","segs":[["ctx","وإنَّما اختلفوا في أنَّ أحكامَ الله تعالىٰ في أفعال المكلفين هل يُمكن للعقل أن يعرفَها من غير وساطة رُسل الله تعالىٰ وكُتبه، بحيث أنَّ مَن لم تبلغه دعوة رسول يستطيع أن يعرف حكم الله تعالىٰ في أفعاله بعقله أم لا يمكنه ذلك؟ فالخلاف إذن فيما يُعرف به حكم الله تعالىٰ."]]},{"id":"u96_3","kind":"def","label":"المبحث الثَّالث الحاكم · الفقرة ٣","segs":[["ctx","وقد اختلفوا في اعتبار العقل وعدمه علىٰ"],["matn","ثلاثة مذاهب:"]]},{"id":"u96_4","kind":"def","label":"المبحث الثَّالث الحاكم · الفقرة ٤","segs":[["matn","الأول: قول المعتزلة:"],["ctx","العقل علَّة موجبة لما استحسنه ومحرِّمة لما استقبحه، فوق العلل الشَّرعية؛ لأنَّ العلل الشَّرعية أمارات ليست موجبة بذاتها، والعلل العقلية موجبة بنفسها وغير قابلة للنَّسخ والتَّبديل، فلم يُثبتوا بدليل الشَّرع ما لا يدركه العقل، مثل: رؤية الله تعالىٰ، وعذاب القبر، والميزان، والصِّراط، وعامَّة أحوال الآخرة، وتمسَّكوا في ذلك بقصة إبراهيم عليه السلام حيث قال لأبيه: ﴿ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ﴾ [الأنعام: ٧٤]."]]},{"id":"u96_5","kind":"text","label":"المبحث الثَّالث الحاكم · الفقرة ٥","segs":[["ctx","وقالوا: لا عذر لَمن عَقِلَ في الوقوف عن طلب الحقّ والنَّظر لمعرفة الصَّانع وأحكامه وترك الإيمان، والصَّبي العاقل مكلَّف بالإيمان لأجل عقله وإن لم يرد عليه السَّمع، فمَن لم تبلغه الدَّعوة بأن نشأ علىٰ شاهق الجبل لما لم يعتقد إيماناً وكفراً كان من أهل النَّار؛ لوجوب الإيمان بمجرد العقل، وأما في الشَّرائع فمعذور حتىٰ تقوم عليه الحجّة."]]},{"id":"u96_6","kind":"def","label":"المبحث الثَّالث الحاكم · الفقرة ٦","segs":[["matn","الثَّاني: قول الأشعرية:"],["ctx","لا عبرة للعقل دون السَّمع، وإذا جاء السَّمع فله العبرة دون العقل، فلا يفهم حسن شيء وقبحه وإيجابه وتحريمه بالعقل، ولا يصحّ إيمان صبيّ عاقل؛ لعدم ورود الشَّرع به، قال تعالىٰ: ﴿وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا﴾ [الإسراء: ١٥]، ومَن يغفل عن الاعتقاد حتىٰ يهلك أو يعتقد الشِّرك ولم تبلغه الدَّعوة فإنَّه معذورٌ؛ لأنَّ المعتبر عندهم السَّمع، ولم يوجد؛ ولهذا مَن قَتل مثل هذا الشَّخص ضمن؛ لأنَّ كفره معفو، وصاروا كالمسلمين في الضَّمان، ولا يصحّ إيمان الصَّبي عندهم."]]},{"id":"u96_7","kind":"def","label":"المبحث الثَّالث الحاكم · الفقرة ٧","segs":[["matn","الثَّالث: قول الماتريدية:"],["ctx","وهو الصَّحيح المعتمد ؛ لأنَّه توسّط بين مذهب المعتزلة والأشاعرة؛ إذ الشَّرعُ مبنيٌّ علىٰ العقل؛ لأنَّه مبنيٌّ علىٰ معرفةِ الله تعالىٰ، والعلم بوحدانيته، والعلم بأنَّ المعجزة دالّة علىٰ النُّبوَّة، وهذه الأمورُ لا تعرف شرعاً بل عقلاً."]]},{"id":"u96_8","kind":"text","label":"المبحث الثَّالث الحاكم · الفقرة ٨","segs":[["ctx","فإنَّ مَن لم تبلغه الدَّعوة غير مكلَّف بمجرد العقل، فإذا لم يعتقد إيماناً ولا كفراً كان معذوراً إذا لم يصادف مدّةً يتمكَّن فيها من التَّأمُّل والاستدلال، وأمّا إذا أعانه الله تعالىٰ بالتَّجربة وأمهله لدرك العواقب لم يكن معذوراً وإن لم تبلغه الدَّعوة؛ لأنَّ الإمهالَ وإدراكَ مدّة التَّأمُّل بمنزلة الدَّعوة في تنبيه القلب عن نوم الغفلة بالنَّظر في الآيات الظَّاهرة، ومَن قَتَل هذا الشَّخص لم يضمن، وإن كان قتلُه حراماً قبل الدَّعوة."]]},{"id":"u96_9","kind":"text","label":"المبحث الثَّالث الحاكم · الفقرة ٩","segs":[["ctx","وليس علىٰ حدِّ الإمهال دليلٌ يُعتمد عليه؛ لأنَّه يختلف باختلافِ الأشخاص، فرُبّ عاقل يهتدي في زمانٍ قليلٍ إلىٰ ما لا يهتدي غيرُه، فيُفوَّضُ تقديرُه إلىٰ الله تعالىٰ."]]},{"id":"u96_10","kind":"text","label":"المبحث الثَّالث الحاكم · الفقرة ١٠","segs":[["ctx","ويصحُّ إيمانُ الصَّبيِّ وإن لم يكن مُكلَّفاً به؛ لأنَّ الوجوبَ بالخطاب، وهو ساقطٌ عنه، قال ﷺ: «رُفِع القلم عن ثلاثةٍ: عن الصَّبيّ حتىٰ يحتلم، وعن النَّائم حتىٰ يستيقظ، وعن المعتوه حتىٰ يعقل»."]]}]},{"id":"u97","title":"المبحث الرَّابع المحكوم عليه","group":"الباب الخامس الأحكام","units":[{"id":"u97_1","kind":"text","label":"المبحث الرَّابع المحكوم عليه · الفقرة ١","segs":[["ctx","وهو المكلَّفُ الذي تعلَّق حكم الشَّارع بفعله، ولا بُدّ من أهليته للحكم، وهي لا تثبت إلا بالعقل؛ إذ لا يفهم الخطاب بدونه، وخطاب مَن لا يفهم قبيح، فكان معتبراً، وأقام الشَّرع البلوغ مقام اعتدال العقل."]]},{"id":"u97_2","kind":"text","label":"المبحث الرَّابع المحكوم عليه · الفقرة ٢","segs":[["ctx","والأهلية له لغةً: الصَّلاحيّة له."]]},{"id":"u97_3","kind":"def","label":"المبحث الرَّابع المحكوم عليه · الفقرة ٣","segs":[["matn","واصطلاحاً: عبارةٌ عن صلاحيته لوجوب الحقوقِ المشروعةِ له وعليه."]]}]},{"id":"u98","title":"المطلب الأول: مراحل الأهلية","group":"الباب الخامس الأحكام","units":[{"id":"u98_1","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١","segs":[["matn","الأوّل: أهليّة الوجوب:"],["ctx","وهي صلاحية لوجوب الحقوق الشَّرعية عليه،"],["matn","وهي نوعان:"]]},{"id":"u98_2","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ٢","segs":[["matn","١. أهلية الوجوب له:"],["ctx","وتكون في مرحلة الحمل، فما دام لم يولد كان جزأً من الأم، ولا تكون له ذمة صالحة لأن يجب عليه الحقّ من نفقة الأقارب وثَمن المبيع الذي اشتراه الوليّ له، وإن كانت صالحة لما يجب له من الإرث والوصية والنَّسب."]]},{"id":"u98_3","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ٣","segs":[["matn","٢. أهليّة وجوب له وعليه:"],["ctx","وتكون في مرحلةِ عدم التَّمييز للصَّغير، فالآدمي يولد وله ذمّة صالحة للوجوب له وعليه؛ إذ قبل الولادة له ذمّة من وجه يصلح ليجب له الحقّ لا ليجب عليه، فإذا ولد تصير ذمّته مطلقة."]]},{"id":"u98_4","kind":"text","label":"المطلب الأول: مراحل الأهلية · الفقرة ٤","segs":[["ctx","وتظهر ثمرة الوجوب له وعليه في الأداء علىٰ التَّفصيل الآتي:"]]},{"id":"u98_5","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ٥","segs":[["ctx","أ."],["matn","إن كان من حقوق العباد، فيلزم وصيّ الصَّبيّ الغرامات"],["ctx",": كضمان ما أتلف الصَّبيّ، وضمان العوض كثمن مبيع اشتراه الصَّبيّ، ودفع نفقة الأقارب الفقراء للصّبيّ."]]},{"id":"u98_6","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ٦","segs":[["ctx","ب."],["matn","إن كان من العقوبات، فلا يجب على الصَّبي العقوبة"],["ctx",": كالقصاص إذا قتل الصبي شخصاً، أو الضَّربُ والإيلام جزاءَ فعلٍ صادر من الصَّبيِّ بالضَّرب والإيلام؛ لأنَّه لا يصلح لحكم الوجوب."]]},{"id":"u98_7","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ٧","segs":[["ctx","ج."],["matn","إنَّ كان من حقوق الله تعالى، فلا يجب على الصَّبيّ العبادات الخالصة"],["ctx","، فإنَّ المقصود من العبادات فعل الأداء، ولا يُتصوَّر ذلك في الصَّبيّ،"],["matn","ويجب على وصيّ الصَّبيِّ أداء العُشر والخراج"],["ctx","، فإنَّهما في الأصل من المؤن ـ أي النَّفقات ـ، ومعنىٰ العبادة والعقوبة تابع فيهما، وإنَّما المقصود منهما المال، والصَّبيّ قادرٌ علىٰ أداء المال بواسطة وصيِّه."]]},{"id":"u98_8","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ٨","segs":[["matn","الثَّاني: أهلية أداء:"],["ctx","وهي صلاحيةٌ لصدور الفعل منه علىٰ وجهٍ يعتدُّ به شرعاً،"],["matn","وهي نوعان:"]]},{"id":"u98_9","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ٩","segs":[["matn","١. أهلية قاصرة:"],["ctx","وتكون في مرحلةِ الصَّبيِّ المميز أو المعتوه، فهي تبتني علىٰ القدرة القاصرة من العقل القاصر والبدن القاصر؛ لأنَّ الأداء يتعلّق بقدرتين: قدرة فهم الخطاب، وهي بالعقل، وقدرة العمل به، وهي بالبدن، فإذا كان تحقّق القدرة بهما يكون كمالها بكمالهما، وقصورُها بقصورِهما، فالصَّبيُّ العاقلُ بدنُه قاصرٌ وإن كان عقلُه يحتمل الكمال، والمعتوهُ البالغ عقلُه قاصرٌ وإن كان بدنُه كاملاً؛ لذلك يصحّ الأداء من الصَّغير وإن لم يجب عليه."]]},{"id":"u98_10","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١٠","segs":[["matn","وتظهر ثمرة الأهلية النَّاقصة في الأحكام الآتية:"],["ctx","أ."],["matn","إن كان حقّاً لله تعالى، وله ثلاثة صور:"]]},{"id":"u98_11","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١١","segs":[["ctx","ـ"],["matn","إن كان حسناً"],["ctx",": كالإيمان، فيصحّ من الصَّبي بلا لزوم أدائه؛ لأنَّه نفعٌ محض."]]},{"id":"u98_12","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١٢","segs":[["ctx","ـ"],["matn","إن كان قبيحاً"],["ctx",": كالردَّة، فإنَّه لا يجعل عفواً، فتصحّ ردّته في حقّ أحكام الدُّنيا والآخرة، فلا يرث من أقاربه مع اختلاف الدِّين، ولكن لا يُقتل؛ لأنَّ القتل ليس من أحكام الردَّة، بل هو من حكم المحاربة، ولم توجد منه المحاربة قبل البلوغ، بل يُجبر علىٰ الإسلام، ودمُه هدرٌ، فلو قَتَلَه أحدٌ قبل البلوغ أو بعده لا يجب عليه شيءٌ."]]},{"id":"u98_13","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١٣","segs":[["ctx","ـ"],["matn","إن كان متردّداً بين الحُسن في زمان والقُبح في زمان"],["ctx",": كالصَّلاة والصَّوم ونحوها من الأفعال البدنية، فالصَّلاة لم تشرع في حالة الحيض، والحجّ لم يشرع في غير وقته، فيصحّ من الصَّبيّ أداؤه من غير لزوم عهدة وضمان، فلا يجب إتمامه والمضي فيه، وإن أفسده لا يجب عليه القضاء، وفي صحّة هذا الأداء بلا لزوم عليه نفعٌ محضٌ له من حيث إنَّه يعتاد أداءه فلا يشق عليه ذلك بعد البلوغ."]]},{"id":"u98_14","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١٤","segs":[["ctx","ب."],["matn","إن كان حقاً لغير الله تعالى، وله ثلاثة صور:"]]},{"id":"u98_15","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١٥","segs":[["ctx","ـ"],["matn","إن كان نفعاً محضاً"],["ctx",": كقَبول الهبة والصَّدقة، فإنَّه يصحّ مباشرة الصَّبيِّ له من غير رضا الوليّ وإذنه."]]},{"id":"u98_16","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١٦","segs":[["ctx","ـ"],["matn","إن كان ضرراً محضاً"],["ctx","، بحيث لا يشوبه نفعٌ دنيويّ: كالطَّلاق والوصيّة ودفع الصَّدقة والهبة والقرض، فإنَّه يبطل أصلاً؛ لما فيه من إزالةِ ملكه من غير نفع يعود إليه."]]},{"id":"u98_17","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١٧","segs":[["ctx","ـ"],["matn","إن كان دائراً بين النَّفع والضَّرر"],["ctx",": كالبيع ونحوه، فإنَّه يملكه برأيّ الولي؛ إذ أنَّ البيعَ إن كان رابحاً كان نفعاً، وإن كان خاسراً كان ضرراً، فلا بُدّ أن ينضمّ إليه رأي الوليّ حتىٰ تترجَّح جهة النَّفع."]]},{"id":"u98_18","kind":"def","label":"المطلب الأول: مراحل الأهلية · الفقرة ١٨","segs":[["matn","٢. أهلية كاملة:"],["ctx","وتكون في مرحلة البلوغ إلىٰ الموت، وهي تبتني علىٰ القدرة الكاملة من العقل الكامل والبدن الكامل، ويبتني عليها وجوبُ الأداء وتوجيه الخطاب؛ لأنَّ في إلزام الأداء قبل الكمال حرج."]]}],"sup":"المبحث الرَّابع المحكوم عليه"},{"id":"u99","title":"المطلب الثَّاني: عوارض الأهلية","group":"الباب الخامس الأحكام","units":[{"id":"u99_1","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١","segs":[["ctx","العارض هنا غير الصِّفة الذَّاتية، ولا يقصد بها الصِّفة الحادثة بعد العدم؛ لكون بعص العوارض المذكورة لم تتحقق بعد العدم كالصِّغر،"],["matn","والعوارض نوعان:"]]},{"id":"u99_2","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢","segs":[["matn","الأول: العارض السَّماوي، وهي:"],["ctx","١."],["matn","الصِّغر"],["ctx",": ويقسم إلىٰ مميز وغير مميز ـ وسبق بيان أحكامه ـ."]]},{"id":"u99_3","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٣","segs":[["matn","٢.الجنون"],["ctx",": وهو آفةٌ بالدِّماغ بحيث يبعث على أفعال خلاف مقتضى العقل من غير ضعف في أعضائه."]]},{"id":"u99_4","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٤","segs":[["ctx","ويأخذ أحكام الصَّبي غير المميز من سقوط العبادات ولزوم حقوق العباد وعدم وجوب العقوبات، لكن في العبادات إذا لم يمتد الجنون أُلحق بالنَّوم استحساناً؛ لأنَّه إذا لم يمتد لم يكن موجباً للحرج على المُكَلَّف في إيجاب القضاء بعد زواله كالنَّوم والإغماء، وأمّا إذا امتدّ صار لزوم الأداء مؤدياً إلى الحرج في القضاء؛ لدخوله في حدّ التّكرار."]]},{"id":"u99_5","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٥","segs":[["ctx","وحدُّ الامتداد في الصَّلاة أن يزيدَ على يوم وليلة، وفي الصَّوم باستغراق الشَّهر، وفي الزَّكاة باستغراق الحول."]]},{"id":"u99_6","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٦","segs":[["ctx","واعتبر هذا الحدّ؛ لأنَّ الكثرة لا نهاية لها، فضبط أدناها: وهو أن يستوعب العذر وظيفة الوقت، إلا أنَّ وقت الصَّلاة يوم وليلة، فأكدت كثرتها بدخولها في حدّ التّكرار، ووقت الصَّوم وقت مديد، فاعتبر نفس الاستيعاب فيه للشهر."]]},{"id":"u99_7","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٧","segs":[["matn","٣.العته"],["ctx",": وهو آفةٌ توجب خللاً في العقل، فيصير صاحبه مختلط الكلام يُشَبَّه بعض كلامه بكلام العقلاء، وبعضه بكلام المجانين."]]},{"id":"u99_8","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٨","segs":[["ctx","وحكمه: حكم الصَّبي المميز في كلِّ الأحكام ـ كما سبق ـ."]]},{"id":"u99_9","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٩","segs":[["matn","٤.النِّسيان"],["ctx",": وهو جهلٌ ضروريّ بما كان يعلمه بغير آفةٍ مع علمِه بأمورٍ كثيرة."]]},{"id":"u99_10","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١٠","segs":[["ctx","فخرج بقولنا: لا بآفة: الجنون. وبقولنا: مع علمه: النَّوم والإغماء."]]},{"id":"u99_11","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١١","segs":[["ctx","وحكمُه: أنَّه لا يُنافي الوجوب في حقّ الله تعالى، فلا تسقط الصَّلاة إذا نسيها ويلزمه القضاء، لكن النِّسيان إذا كان غالباً كما في الصَّوم، والتَّسمية في الذَّبيحة، والسَّلام في الصَّلاة، فإنَّه يكون عفواً؛ لأنَّ النِّسيان من جهةِ صاحب الحقّ بلا اختيار للعبد فيه."]]},{"id":"u99_12","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١٢","segs":[["ctx","ولا يجعل النِّسيان عذراً في حقوق العباد، حتى لو أتلف مال إنسان ناسياً يجب الضَّمان."]]},{"id":"u99_13","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١٣","segs":[["matn","٥.النَّوم"],["ctx",": وهو فترةٌ طبعيّةٌ تَحْدُثُ للإنسان بلا اختيار."]]},{"id":"u99_14","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١٤","segs":[["ctx","وحكمه: أنَّه عجزٌ عن استعمال القدرة يوجب تأخير الخطاب، ولا يمنع الوجوب، فإن انتبه في الوقت يُؤدِّى وإلا يقضي، قال ﷺ: «مَن نام عن صلاة أو نسيها فليصلها إذا ذكرها»، فإنَّها لو لم تكن واجبةً لَمَا أمر بقضائها."]]},{"id":"u99_15","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١٥","segs":[["ctx","ونومُه يُنافي الاختيار أصلاً؛ لأنَّ الاختيارَ بالتَّمييز، ولا تمييز مع النَّوم حتى بطلت عبارتُه في الطَّلاق والعتاق والإسلام والردَّة والبيع والشِّراء."]]},{"id":"u99_16","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١٦","segs":[["matn","٦.الإغماء"],["ctx",": وهو نوعُ مرض يُضْعِفُ القوى ولا يُزيل العقل."]]},{"id":"u99_17","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١٧","segs":[["ctx","وحكمه: كالنَّوم حتى بطلت عباراتُه، بل الإغماء أشدُّ من النَّوم في فوت الاختيار؛ لأنَّ النَّوم يُمكن إزالته بالتَّنبيه بخلاف الإغماء، فكان الإغماءُ حدثاً في الصَّلاة بكلّ حال مضطجعاً أو قائماً أو ساجداً، بخلاف النَّوم ليس بحدث في بعض الأحوال."]]},{"id":"u99_18","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١٨","segs":[["ctx","وإن امتدّ الإغماء يسقط به الأداء؛ للحرج، وإذا بطل الأداء بطل الوجوب، فلا يلزمه قضاء الصَّلاة إذا زاد عن يوم وليلة، وأمّا في الصَّوم فامتداده نادرٌ فلا يُعتبر؛ لأنَّ أحكام الشَّرع تبتنى على ما عَمَّ وغَلَب لا على ما شَذَّ ونَدَر."]]},{"id":"u99_19","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ١٩","segs":[["matn","٧.المرض"],["ctx",": وهو حالةٌ للبدن يزول بها اعتدال الطَّبيعة."]]},{"id":"u99_20","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢٠","segs":[["ctx","وحكمُه: أنَّه سبب للتَّخفيف في الأحكام الشَّرعية إن خشي المرض أو زيادة المرض أو تأخر برء المرض عند القيام بالتَّكليف الشَّرعي، فيتأخر التَّكليف عليه إلى وقت القدرة: كتأخير صيام رمضان، أو يؤدى التَّكليف بقدر الإمكان: كالصَّلاة قاعداً أو مومئاً."]]},{"id":"u99_21","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢١","segs":[["ctx","وأمّا مرضُ الموت فيتعلَّق بالأمور الماليّة، فيكون سبباً لتعلّق حقّ الورثة بثلثي التَّركة، حفاظاً على حقّهم خشية من تضييع المورِّث لها بطريق من الطُّرق، ويتعلَّق حقّ الغريم بكلّ التَّركة، ولا يؤثِّر مرض الموت فيما لا يتعلّق به حقّ غريم ووارث: كنكاح بمهر المثل، فإنَّه يصحّ من حين صدوره، وكذلك يصحّ كلّ تصرّف من المورِّث يحتمل الفسخ: كالهبة، ثمّ يُنقض إن احتيج إلى النَّقض."]]},{"id":"u99_22","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢٢","segs":[["matn","٨.الحيض والنِّفاس"],["ctx",": وهما سواء في الأحكام؛ إذ لا يعدمان أَهلية الوجوب ولا الأداء، لكن الطَّهارة عنهما لصلاةٍ شرطٌ، وفي فواتِ الشَّرطِ فوات الأداء، وقد جُعِلت الطَّهارة عنهما نصّاً، قال ﷺ: «المستحاضة تدع الصَّلاة أيام أقرائها التي كانت تحيض فيها، ثم تغتسل وتتوضَّأ عند كلِّ صلاةٍ وتصوم وتُصلِّي»، بخلاف الصِّيام فيصحُّ من الجُنُب."]]},{"id":"u99_23","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢٣","segs":[["ctx","ويُقْضَى الصَّوم؛ لعدم الحرج في قضائه، بخلاف الصَّلاة، فإنَّها لا تُقْضَى لكثرتها؛ فعن عائشة رضي الله عنها: «كان يُصيبنا ذلك فنؤمر بقضاءِ الصَّوم، ولا نؤمر بقضاء الصَّلاة»."]]},{"id":"u99_24","kind":"def","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢٤","segs":[["matn","٩.الموت"],["ctx",": وهو عرض لا يصحّ معه إحساسٌ معقب للحياة."]]},{"id":"u99_25","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢٥","segs":[["ctx","وحكمه:"]]},{"id":"u99_26","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢٦","segs":[["ctx","ففي حقوق الله تعالى، فالموت ينافي الأهلية في أحكام الدُّنيا ممَّا فيه تكليف، فلم تبق الزَّكاة وسائر القُرب مستحقّة في ماله ما لم يوص، فإن لم يوص أثم."]]},{"id":"u99_27","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢٧","segs":[["ctx","وفي حقوق العباد، فله حالان:"]]},{"id":"u99_28","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢٨","segs":[["ctx","أ.إن كان حقّاً لغير الميت عند الميت من الأعيان: كرهن ومستأجر، فيأخذها صاحب الحقّ أولاً من غير أن تَدخل في التَّركة."]]},{"id":"u99_29","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٢٩","segs":[["ctx","وإن كان لغير الميت على الميت دين، فيلزم أداؤه له إن ترك الميت مالاً أو كفيلاً، وإن لم يترك فلا يطلبه الغريم من أولاده، وإنَّما يأخذه في الآخرة."]]},{"id":"u99_30","kind":"text","label":"المطلب الثَّاني: عوارض الأهلية · الفقرة ٣٠","segs":[["ctx","ب.إن كان حَقّاً للميت، فيبقى للميت من أمواله ما تقضى به الحاجة من التَّكفين والدَّفن؛ لأنَّ حاجتَه إلى التَّجهيز أَقوى من جميع الحوائج، ثم ديونه؛ لأنَّ الحاجةَ إليها أَمس لإبراء ذمّته، ثمّ وصاياه من ثلثه؛ لأنَّ الحاجةَ إليه أقوى من حقّ الورثة."]]}],"sup":"المبحث الرَّابع المحكوم عليه"},{"id":"u100","title":"الثَّاني: العارض المكتسب","group":"الباب الخامس الأحكام","units":[{"id":"u100_1","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ١","segs":[["ctx","وهي التي تكون لكسبِ العبادِ مدخل فيها بمباشرة الأسباب كالسُّكر، أو بالتَّقاعد عن المُزيل: كالجهل، وهو إمّا أن يكون من ذلك المكلَّف الذي يبحث عن تعلّق الحكم به: كالسُّكر، والجهل، وإمّا أن يكون من غيره عليه: كالإكراه،"],["matn","وهي سبعة أنواع:"]]},{"id":"u100_2","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ٢","segs":[["matn","١.الجهل:"],["ctx","وله حالتان:"]]},{"id":"u100_3","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ٣","segs":[["matn","أ.بسيط"],["ctx",": وهو عدمُ العلم عمّا من شأنه أن يكون عالماً، وهو بهذا المعنى ليس بعيب؛ لأنَّه فطري يمكن إزالته بالتَّعلم، وإنَّما العيب في عدم إزالته."]]},{"id":"u100_4","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ٤","segs":[["matn","ب.مركب"],["ctx",": وهو اعتقادُ جازم غير مطابق للواقع مع اعتقاد مطابقته، وهو عيبٌ لا يمكن إزالته بالتَّعلم؛ لأنَّ صاحبه يعتقد أنَّه عالم فلا يشتغل بالتَّعلم."]]},{"id":"u100_5","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ٥","segs":[["matn","وللجهل ثلاثة أنواع:"],["matn","أ.جهل لا يصلح عذراً في الآخرة"],["ctx","، وهو:"]]},{"id":"u100_6","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ٦","segs":[["ctx","ـ جهل الكفار بعد وضوح الدَّلائل على وحدانية الله جل جلاله ورسالة الرُّسل، وهذا أقوى أنواع الجهل؛ لأنَّه مكابرة وعناد بعد وضوح الدَّليل."]]},{"id":"u100_7","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ٧","segs":[["ctx","ـ جهل الفرق الضَّالة من أصحاب الهوى في صفات الله جل جلاله وأحكام الآخرة، بإنكار الصِّفات وعذاب القبر والشَّفاعة والرُّؤية؛ لوضوح الأدلّة من الكتاب والسُّنة، لكن لا تكفر هذه الفرق؛ لما لديهم من تأويل للنُّصوص الشَّرعية، وللنَّهي عن تكفير أهل القبلة؛ فعن أنس رضي الله عنه قال ﷺ: «مَن صلَّى صلاتنا، واستقبل قبلتنا، وأكل ذبيحتنا، فذلك المسلم الذي له ذمة الله وذمة رسوله، فلا تحقروا الله تعالى في ذمته»."]]},{"id":"u100_8","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ٨","segs":[["ctx","ـ جهل البغاة في الخروج على الإمام الحق؛ لدليل فاسد، فيضمنوا ما يُتلفوا من أموال وأنفُس لأتباع الحاكم العادل إذا أتلفه إذا لم يكن للبغاة منعة وقوّة؛ لأنَّه يمكن إلزامه بالدَّليل والجبر على الضَّمان، وأمَّا إذا كان للبغاة منعة وقوّة فلا يضمنوا ما أتلفوه بعد التَّوبة كما لا يؤخذ أهل الحرب بعد الإسلام، قال تعالى: ﴿فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ﴾ [الحجرات:٩]."]]},{"id":"u100_9","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ٩","segs":[["ctx","ـ جهل مَن خالف في اجتهاده للإجماع للصَّحابة والمذاهب الفقهية الأربعة المعتمدة: كالاجتهاد بجواز نكاح المتعة، فإنَّه خالف القرآن في قوله تعالى: ﴿وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ﴾ [المؤمنون:٦]، إذ حرَّم الله تعالى الجماع إلا بأحد شيئين: الزَّواج وملك اليمين، والمتعةُ ليست بنكاحٍ ولا بملك يمين، فيبقى التَّحريم، والدَّليل على أنَّها ليست بنكاح أنَّها ترتفع من غيرِ طلاقٍ ولا فرقةٍ ولا يَجري التَّوارث بينهما، وعن عليٍّ رضي الله عنه أنَّه سمع ابن عبَّاس رضي الله عنهم يلين في متعة النِّساء، فقال: «مهلاً يا ابن عبَّاس، فإنَّ رسول الله ﷺ نهى عنها يوم خيبر وعن لحوم الحمر»."]]},{"id":"u100_10","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ١٠","segs":[["matn","ب.جهل يصلح شبهة"],["ctx",": كالجهل في مواضع الاجتهاد الصَّحيح أو في موضع الشُّبهة، إذ هو دارئ للحدّ والكفَّارة: كالمحتجم الصَّائم إذا أفطر عمداً بعد الحجامة على ظنّ أنَّ الحجامة فطّرته؛ إذ لا تلزمه الكفَّارة؛ لأنَّه جهل في موضع الاجتهاد الصَّحيح؛ لأنَّ الحجامة عند الأوزاعي تُفَطِّر الصائم؛ لقوله ﷺ: «أفطر الحاجم والمحجوم»، قال شيخ الإسلام خُواهَر زاده: «لو لم يستفت فقيهاً ولم يبلغه الحديث أو بلغه وعرفَ تأويله تجب عليه الكفَّارة؛ لأنَّ ظنّه حصلَ في غير موضعه، وأما إذا استفتى فقيهاً يعتمد على فتواه فأفتاه بالفساد فأفطر بعده عمداً لا تجب الكفَّارة»."]]},{"id":"u100_11","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ١١","segs":[["matn","ج.جهل يصلح عذراً"],["ctx","؛ كالجهل في دار الحرب من مسلم لم يهاجر إلينا، وهو عذر حتى لو لم يُصَل ولم يَصم مدّة لم تبلغه الدَّعوة، ولا يجب قضاؤهما؛ لأنَّ دارَ الحرب ليس بمحلٍّ لشهرةِ أحكام الإسلام، بخلاف الذِّميّ إذا أَسلم في دارِ الإسلام، فإنَّ جهلَه بالشَّرائع لا يكون عذراً؛ إذ ربما يُمكنه السُّؤال عن أَحكام الإسلام فيجب عليه قضاء الصَّلاة والصَّوم من وقت الإسلام."]]},{"id":"u100_12","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ١٢","segs":[["matn","٢.السُّكر"],["ctx",": وهو سرورٌ يغلبُ على العقل بمباشرةِ بعض الأسبابِ الموجبةِ له، فيمنع الإنسان عن العمل بموجب عقله من غير أن يزيلَه."]]},{"id":"u100_13","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ١٣","segs":[["ctx","والسُّكر الموجب للحدّ: كونه لا يميز بين الأشياء، ولا يعرف الأرض من السَّماء؛ إذ لو ميَّز ففيه نقصان، وهو شبهةُ العدم، فيندرئ به الحدّ، وأمّا في غير وجوب الحدّ من الأحكام كنقض الوضوء، فالمعتبرُ اختلاطُ الكلام."]]},{"id":"u100_14","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ١٤","segs":[["ctx","والسُّكر حرام إجماعاً إلا أن يكون الطَّريق المفضي إليه مباحاً كتناول البنج للعلاج."]]},{"id":"u100_15","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ١٥","segs":[["matn","٣.السَّفه"],["ctx",": وهو العملُ بخلاف مقتضى العقل والشَّرع، وإن كان الفعل في أصله مشروعاً، وهو السّرفُ والتَّبذير."]]},{"id":"u100_16","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ١٦","segs":[["ctx","وحكمُه: أَنَّه لا يوجب خللاً في الأهلية، ولا يمنع شيئاً من أحكامِ الشَّرعِ من الوجوبِ له وعليه، فيكون مُطالباً بالأحكام كلِّها، ويكون سبباً للحجر عليه عند أبي يوسف ومحمد رضي الله عنهم، ولا يحجر عليه عند أبي حنيفة رضي الله عنه، ولكنَّ يمنع مال السَّفيه عنه في أول ما يبلغ بالنَّصّ، قال جل جلاله: ﴿وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ﴾ [النساء:٥]، فإذا بلغ خمساً وعشرين سنة يُدفع إليه المال وإن لم يؤنس منه الرُّشد؛ لأَنَّه يصير المرء فيه هذه المدّة جَداً؛ إذ أدنى مدّة البلوغ اثنتا عشرة سنة، وأدنى مدة الحمل ستة أشهر، فيصير حينئذ أباً، وإذا ضوعف ذلك يصير جَداً، فلا يفيد منع المال بعده."]]},{"id":"u100_17","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ١٧","segs":[["matn","٤.السَّفر"],["ctx",": وهو الخروج المديد عن موضع الإقامة على قصد السَّير، وأدناه ثلاثة أيام."]]},{"id":"u100_18","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ١٨","segs":[["ctx","وحكمه: أنَّه لا ينافي أهلية الخطاب؛ لبقاء العقل والقدرة البدنية، لكنَّه من أسباب التَّخفيف بنفسه مطلقاً، فتُقصر الصَّلاة الرُّباعية فيه، ويؤخر الصَّوم إلى عدَّة من أيام أُخر ﴿فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ﴾ [البقرة:١٨٤]، وتثبت أحكام السَّفر بمفارقة العمران من المصر."]]},{"id":"u100_19","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ١٩","segs":[["matn","٥.الخطأ"],["ctx",": وهو وقوع الشَّيء على خلاف ما أُريد."]]},{"id":"u100_20","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ٢٠","segs":[["ctx","ومن أحكامه:"]]},{"id":"u100_21","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ٢١","segs":[["ctx","أ.يُسقط حقّ الله جل جلاله إذا حصل عن اجتهاد؛ لعدم قصده، فلو أخطأ المجتهد في الفتوى بعد استفراغ وسعه لا يكون آثماً، ويستحق أجراً واحداً؛ فعن عمرو بن العاص رضي الله عنه، قال ﷺ: «إذا حكم الحاكم فاجتهد ثم أصاب فله أجران، وإذا حكم فاجتهد ثم أخطأ فله أجر»."]]},{"id":"u100_22","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ٢٢","segs":[["ctx","ب. يَدرأ الكفَّارة والحدّ والقصاص، فمَن أخطأ في الصِّيام تسقط عنه الكفَّارة، ومن زُفَّت إليه غير امرأته فظنَّها امرأتُه فوطئها لا حَدّ عليه ولا يصير آثماً إثم الزِّنا، ومن رأى خيالاً من بعيد فظنه صيداً فرمى وقتله لم يقتص منه؛ لأنَّه قتل خطأ، ويلزمه الدِّيَة."]]},{"id":"u100_23","kind":"text","label":"الثَّاني: العارض المكتسب · الفقرة ٢٣","segs":[["ctx","ج. يوجب الضَّمان في حقوق العباد، فمن أتلف مال إنسان خطأً؛ بأن رأى خيالاً من بعيد فظنه صيداً فقتله وكان شاة لإنسان، فيجب عليه ضمانها."]]},{"id":"u100_24","kind":"def","label":"الثَّاني: العارض المكتسب · الفقرة ٢٤","segs":[["matn","٥.الإكراه"],["ctx",": وهو حملُ الغير على ما لا يرضاه."]]}],"sup":"المبحث الرَّابع المحكوم عليه"},{"id":"u100a","title":"وأنواع الإكراه","group":"الباب الخامس الأحكام","units":[{"id":"u100a_1","kind":"def","label":"وأنواع الإكراه · الفقرة ١","segs":[["matn","وأنواع الإكراه:"],["ctx","أ.أن يعدم الرِّضا ويفسد الاختيار، ويكون في الإكراه الملجئ بما يخاف على نفسه أو عضو من أعضائه، بأن يقول: إن لم تفعل كذا لأقتلنك، أو لأقطعن يدك، فحينئذ ينعدم رضاه ويفسد اختياره ألبتة."]]},{"id":"u100a_2","kind":"text","label":"وأنواع الإكراه · الفقرة ٢","segs":[["ctx","ب.أن يعدم الرِّضا ولا يفسد الاختيار، وهو الإكراه بالقيد أو الحبس مدّة مديدة، أو بالضَّرب الذي يخاف على نفسه التَّلف، فإنَّه يبقى اختياره حينئذٍ، ولكن لا يرضى به."]]},{"id":"u100a_3","kind":"text","label":"وأنواع الإكراه · الفقرة ٣","segs":[["ctx","ج.أن لا يعدم الرِّضا ولا يفسد الاختيار، وهو أن يغتمَّ بحبس أبيه أو ابنه أو زوجته أو نحوه، فإنَّ الرِّضا والاختيار كلاهما باق."]]},{"id":"u100a_4","kind":"def","label":"وأنواع الإكراه · الفقرة ٤","segs":[["matn","وحكمه:"],["ctx","أنَّه لا ينافي الخطاب والأهلية بجميع أنواعه؛ لبقاء العقل والبلوغ الذي عليه مدار الخطاب والأهلية، فهو مترددٌ بين فرض وحظر وإباحة ورخصة، إذ في بعض المقام العمل به فرض: كأكل الميتة إذا أكره عليه بما يوجب الإلجاء، ولو صبر حتى يموت عوقب عليه؛ لأنَّه ألقى نفسه إلى التَّهلكة، وفي بعضه العمل به حرام: كالزِّنا وقتل النَّفس المعصومة، فإنَّه يَحرم فعلهما عند الإكراه الملجئ، وفي بعضه العمل به مباح: كالإفطار في الصَّوم، فإنَّه إذا أكره عليه يباح له الفطر، وفي بعضه العمل به رخصة: كإجراء كلمة الكفر على لسانه إذا أُكرِه عليه يرخص له ذلك بشرط أن يكون القلب مطمئناً بالتَّصديق."]]},{"id":"u100a_5","kind":"def","label":"وأنواع الإكراه · الفقرة ٥","segs":[["matn","٦.الهزل"],["ctx",": وهو أن يرادَ بالشَّيءِ غيرُ ما وُضع له ولا مناسبة بينهما؛ بأن يذكر اللفظ قصداً ولا يراد به معناه الحقيقي ولا المجازي."]]},{"id":"u100a_6","kind":"text","label":"وأنواع الإكراه · الفقرة ٦","segs":[["ctx","والهازل لا يختار الحكم ولا يرضى به، ولكنَّه يرضى بمباشرة السَّبب، إذ التَّلفُّظ إنَّما هو عن رضا واختيار صحيح، لكنَّه غيرُ قاصد ولا راض للحكم."]]},{"id":"u100a_7","kind":"text","label":"وأنواع الإكراه · الفقرة ٧","segs":[["ctx","وشرط الهزل المعتبر أن يكون صريحاً مشروطاً باللسان؛ بأن يذكر العاقدان قبل العقد أَنَّهما يهزلان في العقد، فلا يثبت ذلك بدلالة الحال فقط."]]}],"sup":"الثَّاني: العارض المكتسب"},{"id":"u100b","title":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع","group":"الباب الخامس الأحكام","units":[{"id":"u100b_1","kind":"def","label":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع · الفقرة ١","segs":[["matn","التَّصرفات التي يجري فيها الهزل ثلاثة أنواع:"],["matn","أ.في العقائد، والهزل فيها باطل"],["ctx","، وإنَّما قالوا: الهزل بالرِّدة كفرٌ؛ لما فيه من الاستخفاف بالدِّين، وهو من أمارات تَبدُّل الاعتقاد؛ بدليل قوله تعالى حكاية عن الكفار: ﴿إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ﴾ [التوبة:٦٥]."]]},{"id":"u100b_2","kind":"def","label":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع · الفقرة ٢","segs":[["matn","ب. في الإخبارات، والهزل يبطلُها مطلقاً"],["ctx","، سواء كان إخبار عمّا يحتمل الفسخ: كالبيع، أو إخبار عما لا يحتمل الفسخ: كالطَّلاق، كما إذا تواضع شخصان على أن يقرّا بأنَّ بينهما نكاحاً، أو بأنَّهما تبايعا في هذا الشَّيء بكذا؛ لأنَّ الإخبارَ يعتمد فيه صحة المُخبَرِ به وصدقه، والهزل يدلُّ على عدمه؛ لأنَّه دليلُ الكذب كالإكراه، حتى لو أَجاز الهازلُ إخباره لم يجز؛ لأنَّ الإجازة إنَّما تلحق شيئاً منعقداً يحتمل الصِّحة والبُطلان، وبالإجازة لا يصير الكذب صِدقاً."]]},{"id":"u100b_3","kind":"def","label":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع · الفقرة ٣","segs":[["matn","ج.في الإنشاءات"],["ctx","، والهزل في له أحوال:"]]},{"id":"u100b_4","kind":"def","label":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع · الفقرة ٤","segs":[["matn","ـ إن كان الهزل فيما يحتمل الفسخ: كالبيع والإجارة"],["ctx","، فله ثلاثة صور: إما أن يكون في أصل العقد؛ بأن يتفقا في السرّ على أن يظهر البيع بحضور النَّاس، أو في مقدار الثَّمن؛ بأن يتفقا على أصل العقد ويتواضعا أن يذكرا أمام النَّاس الثَّمن ألفين وهو في الحقيقة ألف، أو في جنس الثَّمن؛ بأن يتفقا على أصل العقد ويتواضعا على أن يعقدا بحضور النَّاس على مئةِ دينار، والعقد مئة دولار."]]},{"id":"u100b_5","kind":"text","label":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع · الفقرة ٥","segs":[["ctx","ولا بد في الهزل من ثلاثة مجالس: مجلس للتَّواضع، ومجلس للعقد، ومجلس للتَّوافق على أي المجلسين السَّابقين."]]},{"id":"u100b_6","kind":"text","label":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع · الفقرة ٦","segs":[["ctx","ويكون أربعة حالات لكلّ صورةٍ مما سبق، ففي حالةٍ يتوافقا على إرادةِ مجلس التَّواضع، وفي حالةٍ يتوافقا على إرادة مجلس العقد، وفي حالةٍ يتوافقا على أَنَّه لم يتذكرا ما قالاه في مجلس التَّواضع أثناء كلامهم في مجلس العقد، وفي حالة يختلفا يقول أحدهما: أردنا مجلس التَّواضع ويقول الآخر: أردنا مجلس العقد، فيكون اثنا عشرة صورة يعتبر فيها ما تمّ الاتفاق عليه في مجلس العقد، إلا في صورتين وهما: إن اتفقا على البناء على مجلس المواضعة سواء في أصل العقد أو مقدار الثَّمن، فيفسد البيع حينئذ؛ لوجود شرط مفسد، وهو تعلّقه بمجلس آخر."]]},{"id":"u100b_7","kind":"def","label":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع · الفقرة ٧","segs":[["matn","ـ أن يكون الهزلُ فيما لا مال فيه"],["ctx",": كالطَّلاق واليمين، فذلك صحيح، والهزل باطل للحديث، قال ﷺ: «ثلاثةٌ جدهنّ جد، وهزلهن جدّ: النِّكاح والطَّلاق والرَّجعة»، والمراد باليمين التَّعليق؛ بأن يتواضع الرَّجل مع امرأته بأن يُعَلِّق طلاقها علانيةً، ولا يكون في الواقع: كإن دخلت دار فلان فأنت طالق، فيقع الطَّلاق ولا يعتبر الهزل، وليس المراد به اليمين بالله تعالى؛ إذ لا تتصوّر فيها."]]},{"id":"u100b_8","kind":"def","label":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع · الفقرة ٨","segs":[["matn","ـ أن يكون الهزلُ فيما يكون المالُ فيه تبعاً"],["ctx",": كالنِّكاح، فإنَّ المهر فيه ليس بمقصود، وإنَّما المقصود ابتغاء البِضع، وله صور البيع من وجود الهزل في أصل النِّكاح، ومقدار المهر، وجنس المهر، ولا بد فيه من ثلاثة مجالس: تواضع، وعقد، وتوافق، ولكل صورة أربع حالات ـ كما سبق ـ."]]},{"id":"u100b_9","kind":"text","label":"التَّصرفات التي يجري فيها الهزل ثلاثة أنواع · الفقرة ٩","segs":[["ctx","فيكون اثنا عشرة صورة نعتبر في ثمانية منها ما تم الاتفاق عليه في مجلس العقد، ويعتبر في صورة ما تم الاتفاق في مجلس المواضعة في اعتبار قدر المهر، ولا يفسد كالبيع؛ لأنَّ الشُّروط الفاسدة لا تُفسد النِّكاح بخلاف البيع، ويعتبر مهر المثل في ثلاثة صور: وهي إن اتفقا في البناء على مجلس المواضعة أو اتفقا على أَنَّه لم يتذكرا مجلس المواضعة أثناء الكلام في مجلس العقد، أو اختلفا بأن قال أحدهما: أردنا مجلس المواضعة، وقال الآخر: أردنا مجلس العقد."]]}],"sup":"الثَّاني: العارض المكتسب"},{"id":"u103","title":"المبحث الأول الاجتهاد","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u103_1","kind":"def","label":"المبحث الأول الاجتهاد · الفقرة ١","segs":[["matn","أولاً: تعريفه:"],["matn","لغةً"],["ctx",": قيل: تحمُّل الجَهَد ـ بالفتح ـ: أي المشقّة، وقيل: استفراغُ الجُهد ـ بالضم ـ: أي الطَّاقة."]]},{"id":"u103_2","kind":"def","label":"المبحث الأول الاجتهاد · الفقرة ٢","segs":[["matn","واصطلاحاً"],["ctx",": استفراغُ الفقيه الوسعَ لتحصيل ظنٍّ بحكم شرعيٍّ فرعيٍّ."]]},{"id":"u103_3","kind":"text","label":"المبحث الأول الاجتهاد · الفقرة ٣","segs":[["ctx","فلا بدّ أن يكون مجتهداً، ويكون الحكمُ شرعيّاً فقهيّاً ظنيّاً، لا قطعيّاً ولا كلاميّاً ولا أصوليّاً."]]},{"id":"u103_4","kind":"def","label":"المبحث الأول الاجتهاد · الفقرة ٤","segs":[["matn","ثانياً: شرط المجتهد المطلق"],["ctx",": أن يحوي علوماً ثلاثة:"]]},{"id":"u103_5","kind":"text","label":"المبحث الأول الاجتهاد · الفقرة ٥","segs":[["ctx","١.أن يعرف آيات القرآن المتعلِّقة بمعرفة الأحكام لغةً أي إفراداً وتركيباً، فيحتاج إلى اللّغة والصَّرف والنَّحو والمعاني والبيان سليقةً أو تعلّمًا وشريعةً: أي مناطات الأحكام وأقسامه من أنَّ هذا خاصٌّ أو عامٌّ أو مجملٌ أو مبيّنٌ أو ناسخٌ أو منسوخٌ أو غيرُهما."]]},{"id":"u103_6","kind":"text","label":"المبحث الأول الاجتهاد · الفقرة ٦","segs":[["ctx","وضابطه: أن يتمكّن من العلم بالقدر الواجب من هذه العلوم عند الرُّجوع لها للاستنباط."]]},{"id":"u103_7","kind":"text","label":"المبحث الأول الاجتهاد · الفقرة ٧","segs":[["ctx","٢.معرفةُ السُّنّة المتعلِّقة بالأحكام وطريق وصولها إلينا من تواتر وغيره، ويتضمَّن معرفة حال الرُّواة، والجَّرح والتَّعديل والتَّصحيح والتَّسقيم وغيرها، وطريقه في زماننا الاكتفاء بتعديل الأئمّة الموثوق بهم؛ لتعذُّر حقيقة حال الرُّواة اليوم."]]},{"id":"u103_8","kind":"text","label":"المبحث الأول الاجتهاد · الفقرة ٨","segs":[["ctx","٣. معرفةُ القياسِ بشرائطِه وأركانِه وأقسامِه المقبولة والمردودة، ويستلزمُ معرفة المسائل المجمع عليها؛ لئلا يخالفها."]]},{"id":"u103_9","kind":"text","label":"المبحث الأول الاجتهاد · الفقرة ٩","segs":[["ctx","قال ابنُ الحسين المالكيّ: «الجمهورُ على أنَّ شروط الاجتهاد المطلق المذكورة لم تتحقَّق في شخصٍ من علماء القرن الرَّابع فما بعده، وأنَّ مَن ادّعى بلوغها منهم لا تُسلَّم له دعواه ضرورة أنّ بلوغَها لا يثبت بمجرد الدَّعوى...»."]]}]},{"id":"u103a","title":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u103a_1","kind":"def","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ١","segs":[["matn","ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد:"],["ctx","إنَّ جُلَّ القائمين على الفقه في المؤسسات الأكاديميّة وعامّة الطَّلبة الدَّارسين له سلكوا مذهب المعتزلة القائلين بتعدّد الحقّ، حتى صارت نظرتُهم إلى أقوال الفقهاء المختلفة أَنَّها محلّ اختيار كلّ واحد منهم، فيحقُّ له أخذ ما شاء منها، وترك ما شاء؛ لأَنَّها كلُّها حقّ، ففي كلّ مسألةٍ يدرسونها يأخذون فيها عدّة آراء فقهيّة: منها: مَن يقول: بالحلّ، ومنها: مَن يقول: بالحرمة، ومنها: مَن يقول: بالكراهة، وهكذا، دون بيانٍ للرَّاجح منها في الغالب، فيكون هذا الطَّالب المبتدئ هو المختار لما يُريد بما تمليه عليه نفسه على حسب حاجته، فيوماً يقول: بالحرمة، ويوماً يقول: بالإباحة، وغيرها على حسب المصلحة العقليّة."]]},{"id":"u103a_2","kind":"def","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ٢","segs":[["matn","أقوال العلماء في الحق عند الله تعالى:"],["ctx","١.قالت المعتزلة وبعض المتكلّمين: كلُّ مجتهد مصيب، والحقُّ عند الله متعدّد؛ لأنَّ الحكم ما أدّى إليه اجتهاد كلّ مجتهد، فإذا اجتهدوا في حادثة فالحكم عند الله تعالى في حقّ كلّ واحد ما اجتهد به."]]},{"id":"u103a_3","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ٣","segs":[["ctx","٢.إنَّ عامّة الفقهاء قالوا: المجتهدُ يُخطِئ ويُصيب، والحقُّ عند الله واحد، وإن لم يتعيَّن لنا فهو عند الله متعيِّن؛ لأنَّ حكم الاجتهاد الإصابة بغالب الرأي، وليس القطع بالوصول إلى الحقّ؛ لأنَّ الحقّ في موضع الخلاف واحد، بدليل:"]]},{"id":"u103a_4","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ٤","segs":[["ctx","أ.قال تعالى: ﴿فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمٗا وَعِلۡمٗاۚ﴾ [الأنبياء:٧٩]، وإذا اختصَّ سليمان ﷺ بالفهم، وهو إصابة الحقّ بالنّظر فيه كان الآخر خطأً."]]},{"id":"u103a_5","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ٥","segs":[["ctx","ب.وعن عبد الله بن عمرو رضي الله عنه: «إنَّ رجلين اختصما إلى النَّبيّ ﷺ، فقال لعمرو: اقض بينهما، فقال: أقضي بينهما وأنت حاضر يا رسول الله، قال: نعم، على أنَّك إن أصبت فلك عشر أجور، وإن اجتهدت فأخطأت فلك أجر»."]]},{"id":"u103a_6","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ٦","segs":[["ctx","ج.وعن عمرو بن العاص رضي الله عنه قال ﷺ: «إذا حكم الحاكم فاجتهد ثم أصاب فله أجران، وإذا حكم فاجتهد ثمّ أخطأ فله أجر»."]]},{"id":"u103a_7","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ٧","segs":[["ctx","د.وعن أبي بكر الصِّديق رضي الله عنه حين سئل عن الكلالة قال: «إنّي سأقول فيها برأيي، فإن كان صواباً فمن الله، وإن كان خطأً فمنّي ومن الشيطان، أراه ما خلا الوالد والولد، فلمّا استخلف عمر رضي الله عنه، قال: إنّي لأستحيي الله أن أردّ شيئاً قاله أبو بكر»."]]},{"id":"u103a_8","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ٨","segs":[["ctx","هـ.وعن عمر بن الخطاب رضي الله عنه: «إذا حاصرتم أهل حصن فأرادوكم على أن تنزلوهم على حكم الله فلا تنزلوهم على حكم الله، فإنَّكم لا تدرون ما حكم الله فيهم، ولكن أنزلوهم على حكمكم ثم احكموا فيهم ما شئتم...»."]]},{"id":"u103a_9","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ٩","segs":[["ctx","وجه الدَّلالة: وجود حكم واحد لله تعالى، وليس كلُّ ما يقول المجتهد حكم الله تعالى؛ لأَنَّه لا يدري حكم الله يقيناً، وبالتَّالي لا يُسلِّموا لهم أنَّ ما قالوه حكم الله تعالى، ويدعون غيره."]]},{"id":"u103a_10","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ١٠","segs":[["ctx","قال التَّفتازانيُّ: «وأمّا السُّنّة والأثر فالأحاديث والآثار الدَّالة على ترديد الاجتهاد بين الصَّواب والخطأ، وهي وإن كانت من قبيل الآحاد، إلا أنَّها متواترة من جهة المعنى، وإلا لم تصلح للاستدلال على الأصول»."]]},{"id":"u103a_11","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ١١","segs":[["ctx","و. والإجماع، قال علاء الدّين السمرقنديّ: «إنَّ الصَّحابة رضي الله عنهم أجمعوا على جواز القياس مع مخالفة البعض في جواب المسائل والتَّخطئة، حتى شدّدوا على عبد الله بن عبّاس رضي الله عنهم في جواز ربا النّقد... فالصَّحابةُ الذين جوَّزوا القياس أجمعوا على جواز الخطأ على القياس، وإجماع الصّحابة رضي الله عنهم حجّة قاطعة»."]]},{"id":"u103a_12","kind":"text","label":"ثالثاً: الحقُّ واحدُ عند الله تعالى لا متعدِّد · الفقرة ١٢","segs":[["ctx","ونَقل الإجماع أيضاً شيخ الإسلام شمس الدين الفناريّ."]]}],"sup":"المبحث الأول الاجتهاد"},{"id":"u103b","title":"وأدلَّة المصوِّبة ومناقشتها","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u103b_1","kind":"def","label":"وأدلَّة المصوِّبة ومناقشتها · الفقرة ١","segs":[["matn","وأدلَّة المصوِّبة ومناقشتها:"],["matn","أ."],["ctx","إنَّ المجتهدين في القِبلةِ جُعلوا مصيبين، حتى تأدّى الفرض عنهم جميعاً، ولا يتأدّى الفرض عنهم إلا بإصابة المأمور به مع إحاطة العلم بخطأ من استدبر الكعبة."]]},{"id":"u103b_2","kind":"text","label":"وأدلَّة المصوِّبة ومناقشتها · الفقرة ٢","segs":[["ctx","والجواب عنه: إنَّ المتحرّي يخطئ ويصيب أيضاً كغيره من المجتهدين؛ إذ لو صلّى جماعة وتحرّوا القبلة واختلفوا، فمَن علم منهم حال إمامه وهو مخالفه فسدت صلاته؛ لأَنَّه مخطئ للقبلة عنده، ولو كان الكلُّ صواباً والجهات قبلة لَما فسدت."]]},{"id":"u103b_3","kind":"def","label":"وأدلَّة المصوِّبة ومناقشتها · الفقرة ٣","segs":[["matn","ب."],["ctx","إنَّ الأحكام تختلف عند اختلاف الرُّسل بين قومين في زمان واحد: كإبراهيم عليه السلام ولوط عليه السلام."]]},{"id":"u103b_4","kind":"text","label":"وأدلَّة المصوِّبة ومناقشتها · الفقرة ٤","segs":[["ctx","والجواب عليه: إنَّ الشَّيءَ الواحد جاز أن يكون حراماً لشخص حلالاً لشخص آخر: كأم المرأة حرام على زوج ابنتها حلال لغيره، وكذلك سائر المحرّمات من الأمّ والبنت وغيرها، وكذلك المال لمالكه حلال ولغيره حرام، فكذلك يجوز أن تثبت الحرمة في حقّ أُمّةٍ، والحلّ في حقّ أمّةٍ أُخرى."]]},{"id":"u103b_5","kind":"text","label":"وأدلَّة المصوِّبة ومناقشتها · الفقرة ٥","segs":[["ctx","قال الكوثريّ: «والرَّأي الذي يُنسب إلى المعتزلة، يبيح لغير المجتهدِ الأخذُ بما يروقه من الآراء للمجتهدين، لكن أقلّ ما يجب على غير المجتهد في باب الاجتهاد أن يتخيَّر لدينه مجتهداً يراه الأعلم والأورع، فينصاع لفتياه."]]},{"id":"u103b_6","kind":"text","label":"وأدلَّة المصوِّبة ومناقشتها · الفقرة ٦","segs":[["ctx","وأمّا تتبّعه الرُّخص من أقوال كلِّ إمام، والأخذ بما يوافق الهوى من آراء الأئمّة، فليسا إلا تشهّياً محضاً، وليس عليهما مسحة من الدّين أصلاً، كائناً من كان مبيح ذلك؛ ولذلك يقول الأُستاذ أبو إسحاق الإسفرايينيّ الإمام عن تصويب المجتهدين مطلقاً: «أوله سفسطة وآخره زندقة»؛ لأنَّ أقوالهم تدور بين النفي والإثبات، فأنى يكون الصواب في النفي والإثبات معاً...؟"]]},{"id":"u103b_7","kind":"text","label":"وأدلَّة المصوِّبة ومناقشتها · الفقرة ٧","segs":[["ctx","نعم إنَّ من تابع هذا المجتهد في جميع آرائه، فقد خرج من العهدة، أصاب المجتهد أم أخطأ، وكذا المجتهدون الآخرون؛ لأنَّ الحاكم إذا اجتهد وأصاب فله أجران، وإذا اجتهد وأخطأ فله أجر واحد»."]]}],"sup":"المبحث الأول الاجتهاد"},{"id":"u104","title":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u104_1","kind":"text","label":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج · الفقرة ١","segs":[["ctx","إنَّ هذه الشَّريعةَ الغراءَ صادرةٌ عن إلهٍ واحدٍ ونبيٍّ واحدٍ، فلا شَكَّ في خلوها عن التَّعارضِ والتَّناقضِ في نفسِ الأمر، وإنَّما هو أَمْرٌ في الظَّاهر، قال ملا جيون: «وقد يقع التَّعارض بين الحجج فيما بيننا لجهلنا بالنَّاسخ والمنسوخ، وإلا فلا تعارض في نفس الأمر؛ لأنّ أحدَهما يكون منسوخاً والآخرُ ناسخاً، وكيف يقع التَّعارض في كلامه تعالى؛ لأنَّ ذلك من أمارات العجز تعالى الله عن ذلك علواً كبيراً»."]]},{"id":"u104_2","kind":"text","label":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج · الفقرة ٢","segs":[["ctx","فالتَّعارضُ لغةً: التَّمانع والتَّدافع والتَّنافر، وتعارضت البينات؛ لأنَّ كلَّ واحدةٍ تعتَرض الأخرى وتمنع نفوذها، وعَرَضَ إليَّ بكذا: أي استقبلني بصَدٍّ ومَنْعٍ."]]},{"id":"u104_3","kind":"def","label":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج · الفقرة ٣","segs":[["matn","واصطلاحاً: وهو تقابلُ المتساويين قوّةً حقيقة مع اتحاد النِّسبة بين الحجج"],["ctx","، أو اقتضاء كل من دليلين عدمُ مقتضى الآخرى."]]},{"id":"u104_4","kind":"text","label":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج · الفقرة ٤","segs":[["ctx","والتَّرجيح لغة: جعلُ الشَّيءِ راجحاً: أي فاضلاً زائداً، والاسم الرّجحان: إذا زاد وزونُه."]]},{"id":"u104_5","kind":"text","label":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج · الفقرة ٥","segs":[["ctx","واصطلاحاً: بيانُ الرُّجحان: أي القوّة التي لأحد المتعارضين على الآخر."]]},{"id":"u104_6","kind":"def","label":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج · الفقرة ٦","segs":[["matn","ويثبت التَّعارض عند وجود ركنه وشرطه:"],["matn","فركنه: هو المماثلةُ والمساواةُ بين الدَّليلين في الثُّبوت والقوة"],["ctx","؛ لاستوائهما في الطَّريق نحو النَّصّين من الكتاب والخبرين المتواترين ونحوهما."]]},{"id":"u104_7","kind":"def","label":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج · الفقرة ٧","segs":[["matn","وشرطُه: هو المخالفةُ بين حكميهما، إمّا من حيث تضاد الحكم: كالحلّ والحرمة، أو من حيث التَّنافي: كالنَّفي والإثبات، لكن التَّضاد والتَّنافي لا يثبت إلا عند اتحاد المحلّ والزَّمان والجهة"],["ctx","؛ وذلك لأنَّ التَّضاد لا يقع في محلين لجواز اجتماعهما، مثل: النِّكاح يوجب الحلَّ في محلٍّ والحرمةَ في غيره، وكذلك في وقتين لجواز اجتماعهما في محلٍّ واحدٍ في وقتين، مثل: حرمةُ الخمر بعد حلِّها."]]}]},{"id":"u105","title":"المطلب الأول: الحكم عند وقوع التَّعارض","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u105_1","kind":"def","label":"المطلب الأول: الحكم عند وقوع التَّعارض · الفقرة ١","segs":[["matn","أوّلاً: إن وقع بين الآيتين يصار إلى السُّنة"],["ctx",": كقوله تعالى: ﴿فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ﴾ [المزمل:٢٠] يوجب بعمومِه القراءة على المقتدي، وقوله تعالى: ﴿وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُواْ لَهُۥ﴾ [الأعراف:٢٠٤] ينفي وجوبها؛ إذ كلاهما وَرَدَ في الصَّلاة كما بيَّنه الطَّحاوي رضي الله عنه في «الأحكام»، فصير إلى الحديث: وهو ما رواه ابنُ منيع بسند «الصَّحيحين» عن جابر رضي الله عنه أنَّ النَّبيَّ ﷺ قال: «مَن كان له إمامٌ فقراءةُ الإمام له قراءة» ولا يعارضه قوله ﷺ: «لا صلاة إلا بفاتحة الكتاب»؛ لأنَّه محتملٌ لإرادة نفي الفضيلة."]]},{"id":"u105_2","kind":"def","label":"المطلب الأول: الحكم عند وقوع التَّعارض · الفقرة ٢","segs":[["matn","ثانياً: إذا وقع بين السُّنتين يصار إلى أَقوال علماءِ الصَّحابة رضي الله عنهم"],["ctx",": أي قُدِّم على القياس مُطلقاً، كما قال فخرُ الإسلام، وفيما لم يدرك بالقياس، كما قال الكَرْخيّ."]]},{"id":"u105_3","kind":"def","label":"المطلب الأول: الحكم عند وقوع التَّعارض · الفقرة ٣","segs":[["matn","وإن لم نقف على قول للصَّحابة رضي الله عنهم ننتقل إلى القياس، فيرجح به"],["ctx","، ومُثِّلَ لهذا بما روى النُّعمانُ بنُ بشير رضي الله عنه: «إنَّ النَّبيَّ ﷺ صلَّى صلاة الكسوف كما تصلون بركعةٍ وسجدتين» مع ما روت عائشة رضي الله عنها: «إنَّ النَّبيَّ ﷺ صلاها ركعتين بأَربع ركوعات وأربع سجدات» فصير إلى القياس، وهو اعتبار صلاة الكسوف بسائر الصَّلوات."]]},{"id":"u105_4","kind":"def","label":"المطلب الأول: الحكم عند وقوع التَّعارض · الفقرة ٤","segs":[["matn","ثالثاً: إذا وقع بين قياسين، فإن أَمكن ترجيح أحدهما عُمِل به، وإن لم يمكن ترجيح أحدهما على الآخر فيَعمل المجتهدُ بأيِّهما شاء بشهادةِ قلبه"],["ctx","؛ لأنَّ أَحَدَ القياسين حَقّ، ولا يتساقطان؛ لأنَّه لم يبق بعدهما دليلٌ يُصار إليه."]]},{"id":"u105_5","kind":"text","label":"المطلب الأول: الحكم عند وقوع التَّعارض · الفقرة ٥","segs":[["ctx","وعند العجز عن المصير إلى دليل، يجب تقرير الأصول، وهو إبقاء ما كان على ما كان ."]]},{"id":"u105_6","kind":"text","label":"المطلب الأول: الحكم عند وقوع التَّعارض · الفقرة ٦","segs":[["ctx","هذا بيانُ المعارضة الحقيقيّة التي حكمها التَّساقط، فالآن أوان الشُّروع في بيان معارضة صورية حكمها التَّرجيح أو التَّوفيق:"]]}],"sup":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج"},{"id":"u106","title":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u106_1","kind":"def","label":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة · الفقرة ١","segs":[["matn","١.بيانُ عدم وجودِ ركن المعارضة أو شرطها لعدم معادلة المعارض"],["ctx","، كما في الظَّاهر والنَّصّ ـ على ما تقدَّم ـ، كما لو عارض حديث: «البينة على المُدَّعِي واليمين على من أنكر» بحديثِ القضاء بشاهد ويمين فنقول: هذا حديث صحيح مشهور، فلا يعادله هذا؛ لأَنَّه خبر واحد، أو لم يستكمل شروط الصِّحَّة."]]},{"id":"u106_2","kind":"def","label":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة · الفقرة ٢","segs":[["matn","٢.اختلاف الحكم بأن يكون أحدُهما حكم الدُّنيا والآخرُ حكم الآخرة"],["ctx",": كآيتي اليمين، فالتي في سورة البقرة على حكم الآخرة؛ قال تعالى: ﴿لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ﴾ [البقرة:٢٢٥]، والتي في المائدة على حكم الدُّنيا: ﴿لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ﴾ [المائدة:٨٩]، فلا كفَّارة في الغموس؛ لأنَّها غير منعقدة."]]},{"id":"u106_3","kind":"def","label":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة · الفقرة ٣","segs":[["matn","٣.اختلاف الحال بحمل أَحدِهما على حال والآخر على أُخرى"],["ctx",": كقراءة التَّخفيفِ والتَّشديدِ في قوله تعالى: ﴿حَتَّىٰ يَطۡهُرۡنَ﴾ [البقرة:٢٢٢] بحمل التَّخفيف على الانقطاع لأكثر الحيض، والتَّشديد على ما دون ذلك."]]},{"id":"u106_4","kind":"def","label":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة · الفقرة ٤","segs":[["matn","٤ .اختلاف الزَّمان، وله وجهان:"]]},{"id":"u106_5","kind":"def","label":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة · الفقرة ٥","segs":[["matn","أ.صريحاً"],["ctx",": كآيتي العدَّة، قال تعالى: ﴿وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ﴾ [الطلاق:٤] نزلت بعد قوله تعالى: ﴿وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ﴾ [البقرة:٢٣٤] قال ابنُ مسعود رضي الله عنه: «من شاء لاعنته نزلت سورة النِّساء القصرى بعد ﴿أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗا﴾ [البقرة:٢٣٤]». وفي البخاري بدون «لاعنته»."]]},{"id":"u106_6","kind":"def","label":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة · الفقرة ٦","segs":[["matn","ب.دلالة"],["ctx",": كما في تعارض الحاظر والمبيح، نحو ما روي: «أنَّه ﷺ نهى عن أكل الضب». وروي «أنَّه ﷺ أَقرَّ على أكله»، فيجعل الحاظر متأخراً؛ تقليلاً لتغيير الأمر الأصلي."]]},{"id":"u106_7","kind":"text","label":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة · الفقرة ٧","segs":[["ctx","ولا ترجيح بكثرةِ الرُّواةِ ولا بالذُّكورةِ ولا بالحرية، فإنَّ عائشة رضي الله عنها أفضل من أكثر الرِّجال، وبلالاً كان أفضل من أكثر الأحرار، والجماعةُ القليلة العادلة أَفضل من الكثيرةِ العاصية، وبذلك لا يترجَّح عددٌ على عددٍ بعد أن كان في درجةِ الآحاد، وفائدة هذا القيد: أنَّ الخبر إذا وَصَلَ درجةَ التَّواتر فله ترجيحٌ على غيره."]]},{"id":"u106_8","kind":"text","label":"المطلب الثَّاني: وجوهُ التَّخلص من المعارضة · الفقرة ٨","segs":[["ctx","واختلف في تعارض المثبت والنافي، فعند الكرخيّ رضي الله عنه يُقَدَّمُ المثبت، وعند عيسى بن أبان رضي الله عنه يتعارضان إن كان النَّافي اعتمد دليلاً، وإن كان بُني على الظَّاهر فالمثبت مُقَدَّم."]]}],"sup":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج"},{"id":"u107","title":"المطلب الثَّالث: التَّعارضُ بين قياسين","group":"الباب السادس الاجتهاد والتَّرجيح","units":[{"id":"u107_1","kind":"def","label":"المطلب الثَّالث: التَّعارضُ بين قياسين · الفقرة ١","segs":[["matn","١.التَّرجيحُ بقوّةِ أَثَر الوَصْف"],["ctx",": كالاستحسان في معارضةِ القياس."]]},{"id":"u107_2","kind":"def","label":"المطلب الثَّالث: التَّعارضُ بين قياسين · الفقرة ٢","segs":[["matn","٢. التَّرجيح بقُوّة ثبات الوصفِ على الحكم الذي يَشْهَد الوصف بثبوته"],["ctx","، كقولنا في صوم رمضان: إنَّه متعيِّنٌ فلا يجب تعيينه، أَولى من قول غيرنا: إنَّه صومُ فرض فيجب تعيينه، فوصف الفرضيّة قاصرٌ على الصَّوم، ووصف التعيين مؤثِّر في عدم وجوبِ التَّعيين على الإطلاق، فيكون أثبت."]]},{"id":"u107_3","kind":"def","label":"المطلب الثَّالث: التَّعارضُ بين قياسين · الفقرة ٣","segs":[["matn","٣.التَّرجيحُ بكثرةِ أُصول الوصف"],["ctx",": كقولنا: في مسح الرَّأس فلا يُسَنُّ تكرارُه كمسح الخُفّ والتَّيمم ومسح الجبيرة، وهذا أَولى من قولهم: إنَّه ركن فيُسَنُّ تكرارُه كالغَسل."]]},{"id":"u107_4","kind":"def","label":"المطلب الثَّالث: التَّعارضُ بين قياسين · الفقرة ٤","segs":[["matn","٤ .التَّرجيحُ بعدم الحكم عند عدم الوصف، ووجوده عند وجوده"],["ctx","، كما قلنا في المثال السَّابق."]]},{"id":"u107_5","kind":"def","label":"المطلب الثَّالث: التَّعارضُ بين قياسين · الفقرة ٥","segs":[["matn","٥.إذا تعارض ضَربا ترجيح، فالرّجحانُ بما هو في الذَّات أَولى بالاعتبار من الرُّجحان بما هو في الحال"],["ctx",": كابن ابن ابن أخ وبنت بنت بنت أخ، الأول راجح بالذَّات وهو الذُّكورة من الآخَر بالحال وهو القُرب من الميت."]]},{"id":"u107_6","kind":"text","label":"المطلب الثَّالث: التَّعارضُ بين قياسين · الفقرة ٦","segs":[["ctx","وإذا كان في أحدِ الخبرين زيادةٌ لم تكن في الآخر، والرَّاوي واحدٌ، يؤخذ بالمُثبت للزِّيادة مثل ما روى ابنُ مسعود رضي الله عنه: «إذا اختلف المتبايعان والسِّلعةُ قائمةٌ تحالفا وترادّا»، وفي روايةٍ لم يذكر «والسِّلعةُ قائمةٌ» فأَخَذَ بالمثبتِ للزِّيادة، فلا يجري التَّحالف إلا عند قيام السِّلعة."]]},{"id":"u107_7","kind":"text","label":"المطلب الثَّالث: التَّعارضُ بين قياسين · الفقرة ٧","segs":[["ctx","وإذا اختلف الرَّاوي جُعِل الخبر كالخبرين وعُمِل بهما؛ لأنَّ الظَّاهرَ أَنَّ النَّبيَّ ﷺ قاله في وقتين، فيَجب العملُ بهما بحسبِ الإمكان، عَمَلاً بأنَّ المطلقَ لا يُحْمَلُ على المقيَّدِ في حكمين."]]},{"id":"u107_8","kind":"text","label":"المطلب الثَّالث: التَّعارضُ بين قياسين · الفقرة ٨","segs":[["ctx","وَمُثِّلَ له بما رُوي: «أنّه ﷺ نَهَى عن بيع الطَّعام قبل قبضه» رواه ابنُ عباس رضي الله عنه، ورُوي: «أنَّه ﷺ نهى عن بيع ما لم يقبض». فقلنا: لا يجوز بيع الطَّعام قبل القبض، ولا بيع سائر العروض قبل القبض."]]}],"sup":"المبحث الثَّاني التَّعارض والتَّرجيح بين الحجج"}]};
